INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Jr', 52, 'pt', '[{"numero": 1, "texto": "Zedequias era de idade de vinte e um anos quando começou a reinar, e reinou onze anos em Jerusalém. Sua mãe se chamava Hamutal, filha de Jeremias, de Libna."}, {"numero": 2, "texto": "E ele fez o que era mal aos olhos do SENHOR, conforme tudo o que Jeoaquim fizera."}, {"numero": 3, "texto": "E por isso a ira do SENHOR foi contra Jerusalém e Judá, até que ele os expulsou de sua presença; assim Zedequias se rebelou contra o rei da Babilônia."}, {"numero": 4, "texto": "E aconteceu no nono ano de seu reinado, no decimo mês, aos dez dias do mês, que veio Nabucodonosor rei da Babilônia, ele e todo seu exército, contra Jerusalém, e contra ela montaram um acampamento, e ao redor por todos os lados levantaram cercos contra ela."}, {"numero": 5, "texto": "Assim a cidade esteve cercada até o décimo primeiro ano do rei Zedequias."}, {"numero": 6, "texto": "No quarto mês, aos nove do mês, quando a fome havia dominado a cidade, até não haver pão para o povo da terra;"}, {"numero": 7, "texto": "Então a cidade foi arrombada, e todos os homens de guerra fugiram, e saíram da cidade de noite, pelo caminho de porta de entre os dois muros, que era perto do jardim do rei, e foram-se pelo caminho de Arabá, enquanto os caldeus estavam ao redor da cidade."}, {"numero": 8, "texto": "Porém o exército dos caldeus perseguiu o rei, e alcançaram a Zedequias nas planícies de Jericó; e todo o seu exército se dispersou dele."}, {"numero": 9, "texto": "Então prenderam ao rei, e fizeram-lhe vir ao rei de Babilônia, a Ribla na terra de Hamate, onde pronunciou sentença contra ele."}, {"numero": 10, "texto": "E o rei da Babilônia degolou os filhos de Zedequias diante de seus olhos; e também degolou a todos os príncipes de Judá em Ribla."}, {"numero": 11, "texto": "Mas Zedequias porém cegou os olhos, e o acorrentou com grilhões de bronze; e o rei da Babilônia o levou à Babilônia, e o pôs na casa do cárcere até o dia de sua morte."}, {"numero": 12, "texto": "E no quinto mês, aos dez do mês (que era o décimo nono ano do reinado de Nabucodonosor, rei de Babilônia), Nebuzaradã, capitão da guarda, que servia diante do rei de Babilônia, veio a Jerusalém;"}, {"numero": 13, "texto": "E queimou a casa do SENHOR, a casa do rei, e todas as casas de Jerusalém; e queimou com fogo todo grande edifício."}, {"numero": 14, "texto": "E todo o exército dos caldeus que estava com o capitão da guarda derrubou todos os muros que estavam ao redor de Jerusalém."}, {"numero": 15, "texto": "E Nebuzaradã, capitão da guarda, levou presos os pobres do povo, e ao demais do povo, que restaram na cidade, e os rebeldes que se haviam se rendido ao rei de Babilônia, e todo o resto dos artesãos."}, {"numero": 16, "texto": "Mas Nebuzaradã, capitão da guarda, deixou dos mais pobres daquela terra para serem cultivadores de vinhas e lavradores."}, {"numero": 17, "texto": "E os caldeus quebraram as colunas de bronze que estavam na casa do SENHOR, as bases, e o mar de bronze que estavam na casa do SENHOR, e levaram todo o bronze à Babilônia."}, {"numero": 18, "texto": "Tomaram também os caldeirões, as pás, os cortadores de pavios, as bacias, os pratos, e todos os vasos de bronze com que faziam o serviço [no templo] ;"}, {"numero": 19, "texto": "E o capitão da guarda tomou os copos, os incensários, as bacias, as panelas, os castiçais, os pratos, e vasos de ofertas de líquidos: tudo o que era de ouro ou de prata."}, {"numero": 20, "texto": "As duas colunas, o mar, e os doze bois de bronze que estavam debaixo das bases, que o rei Salomão tinha feito na casa do SENHOR. não se podia pesar o bronze de todos estes vasos."}, {"numero": 21, "texto": "Quanto às colunas, a altura de cada coluna era de dezoito côvados, e um fio de doze côvados a rodeava; e sua espessura era de quatro dedos, [e] era oca."}, {"numero": 22, "texto": "E [tinha] sobre si um capitel de bronze, e a altura do capitel era de cinco côvados, com uma rede e romãs ao redor do capitel, tudo de bronze; e semelhante a esta era o da segunda coluna, com [suas] romãs."}, {"numero": 23, "texto": "E havia noventa e seis romãs em cada lado; ao todo elas eram cem sobre a rede ao redor."}, {"numero": 24, "texto": "O capitão da guarda também tomou a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta."}, {"numero": 25, "texto": "E da cidade tomou a um eunuco que era comandante sobre os homens de guerra, e a sete homens que serviam na presença do rei, que se acharam na cidade; e também ao principal escrivão do exército, que registrava o povo da terra para a guerra; e a sessenta homens do povo da terra, que se acharam no meio da cidade."}, {"numero": 26, "texto": "Então Nebuzaradã, capitão da guarda, os tomou, e os levou ao rei de Babilônia, a Ribla."}, {"numero": 27, "texto": "E o rei de Babilônia os feriu e os matou em Ribla na terra de Hamate. Assim Judá foi levado cativo de sua terra."}, {"numero": 28, "texto": "Este é o povo que Nabucodonosor levou cativo; no sétimo ano, três mil e vinte e três judeus:"}, {"numero": 29, "texto": "No décimo oitavo ano Nabucodonosor, levou cativas de Jerusalém oitocentas e trinta e duas pessoas;"}, {"numero": 30, "texto": "No vigésimo terceiro ano de Nabucodonosor, Nebuzaradã capitão da guarda levou cativas setecentas e quarenta e cinco pessoas dos judeus; no total foram quatro mil e seiscentas pessoas."}, {"numero": 31, "texto": "Sucedeu, pois, no trigésimo sétimo ano de cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e cinco do mês, que Evil-Merodaque, rei da Babilônia, no [primeiro] ano de seu reinado, concedeu perdão a Joaquim rei de Judá, e o tirou da casa de prisão;"}, {"numero": 32, "texto": "E falou com ele benignamente; e pôs sua cadeira com mais honra do que as cadeiras dos reis que estavam com ele em Babilônia."}, {"numero": 33, "texto": "E mudou-lhe também as roupas de sua prisão, e continuamente comeu pão diante dele, todos os dias de sua vida."}, {"numero": 34, "texto": "E continuamente foi-lhe dada provisão pelo rei da Babilônia, uma porção diária, até o dia de sua morte, por todos os dias de sua vida."}]'::jsonb, 'Almeida Livre'),
  ('Jr', 52, 'en', '[{"numero": 1, "texto": "Zedekiah was one and twenty years old when he began to reign, and he reigned eleven years in Jerusalem. And his mother''s name was Hamutal the daughter of Jeremiah of Libnah."}, {"numero": 2, "texto": "And he did that which was evil in the eyes of the Lord, according to all that Jehoiakim had done."}, {"numero": 3, "texto": "For through the anger of the Lord it came to pass in Jerusalem and Judah, till he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon."}, {"numero": 4, "texto": "And it came to pass in the ninth year of his reign, in the tenth month, in the tenth day of the month, that Nebuchadrezzar king of Babylon came, he and all his army, against Jerusalem, and pitched against it, and built forts against it round about."}, {"numero": 5, "texto": "So the city was besieged unto the eleventh year of king Zedekiah."}, {"numero": 6, "texto": "And in the fourth month, in the ninth day of the month, the famine was sore in the city, so that there was no bread for the people of the land."}, {"numero": 7, "texto": "Then the city was broken up, and all the men of war fled, and went forth out of the city by night by the way of the gate between the two walls, which was by the king''s garden; (now the Chaldeans were by the city round about:) and they went by the way of the plain."}, {"numero": 8, "texto": "But the army of the Chaldeans pursued after the king, and overtook Zedekiah in the plains of Jericho; and all his army was scattered from him."}, {"numero": 9, "texto": "Then they took the king, and carried him up unto the king of Babylon to Riblah in the land of Hamath; where he gave judgment upon him."}, {"numero": 10, "texto": "And the king of Babylon slew the sons of Zedekiah before his eyes: he slew also all the princes of Judah in Riblah."}, {"numero": 11, "texto": "Then he put out the eyes of Zedekiah; and the king of Babylon bound him in chains, and carried him to Babylon, and put him in prison till the day of his death."}, {"numero": 12, "texto": "Now in the fifth month, in the tenth day of the month, which was the nineteenth year of Nebuchadrezzar king of Babylon, came Nebuzaradan, captain of the guard, which served the king of Babylon, into Jerusalem,"}, {"numero": 13, "texto": "And burned the house of the Lord, and the king''s house; and all the houses of Jerusalem, and all the houses of the great men, burned he with fire:"}, {"numero": 14, "texto": "And all the army of the Chaldeans, that were with the captain of the guard, brake down all the walls of Jerusalem round about."}, {"numero": 15, "texto": "Then Nebuzaradan the captain of the guard carried away captive certain of the poor of the people, and the residue of the people that remained in the city, and those that fell away, that fell to the king of Babylon, and the rest of the multitude."}, {"numero": 16, "texto": "But Nebuzaradan the captain of the guard left certain of the poor of the land for vinedressers and for husbandmen."}, {"numero": 17, "texto": "Also the pillars of brass that were in the house of the Lord, and the bases, and the brasen sea that was in the house of the Lord, the Chaldeans brake, and carried all the brass of them to Babylon."}, {"numero": 18, "texto": "The caldrons also, and the shovels, and the snuffers, and the bowls, and the spoons, and all the vessels of brass wherewith they ministered, took they away."}, {"numero": 19, "texto": "And the basons, and the firepans, and the bowls, and the caldrons, and the candlesticks, and the spoons, and the cups; that which was of gold in gold, and that which was of silver in silver, took the captain of the guard away."}, {"numero": 20, "texto": "The two pillars, one sea, and twelve brasen bulls that were under the bases, which king Solomon had made in the house of the Lord: the brass of all these vessels was without weight."}, {"numero": 21, "texto": "And concerning the pillars, the height of one pillar was eighteen cubits; and a fillet of twelve cubits did compass it; and the thickness thereof was four fingers: it was hollow."}, {"numero": 22, "texto": "And a chapiter of brass was upon it; and the height of one chapiter was five cubits, with network and pomegranates upon the chapiters round about, all of brass. The second pillar also and the pomegranates were like unto these."}, {"numero": 23, "texto": "And there were ninety and six pomegranates on a side; and all the pomegranates upon the network were an hundred round about."}, {"numero": 24, "texto": "And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door:"}, {"numero": 25, "texto": "He took also out of the city an eunuch, which had the charge of the men of war; and seven men of them that were near the king''s person, which were found in the city; and the principal scribe of the host, who mustered the people of the land; and threescore men of the people of the land, that were found in the midst of the city."}, {"numero": 26, "texto": "So Nebuzaradan the captain of the guard took them, and brought them to the king of Babylon to Riblah."}, {"numero": 27, "texto": "And the king of Babylon smote them, and put them to death in Riblah in the land of Hamath. Thus Judah was carried away captive out of his own land."}, {"numero": 28, "texto": "This is the people whom Nebuchadrezzar carried away captive: in the seventh year three thousand Jews and three and twenty:"}, {"numero": 29, "texto": "In the eighteenth year of Nebuchadrezzar he carried away captive from Jerusalem eight hundred thirty and two persons:"}, {"numero": 30, "texto": "In the three and twentieth year of Nebuchadrezzar Nebuzaradan the captain of the guard carried away captive of the Jews seven hundred forty and five persons: all the persons were four thousand and six hundred."}, {"numero": 31, "texto": "And it came to pass in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, in the five and twentieth day of the month, that Evilmerodach king of Babylon in the first year of his reign lifted up the head of Jehoiachin king of Judah, and brought him forth out of prison."}, {"numero": 32, "texto": "And spake kindly unto him, and set his throne above the throne of the kings that were with him in Babylon,"}, {"numero": 33, "texto": "And changed his prison garments: and he did continually eat bread before him all the days of his life."}, {"numero": 34, "texto": "And for his diet, there was a continual diet given him of the king of Babylon, every day a portion until the day of his death, all the days of his life."}]'::jsonb, 'King James Version'),
  ('Jr', 52, 'fr', '[{"numero": 1, "texto": "Sédécias avait vingt et un ans lorsqu''''il devint roi, et il régna onze ans à Jérusalem. Sa mère s''''appelait Hamuthal, fille de Jérémie, de Libna."}, {"numero": 2, "texto": "Il fit ce qui est mal aux yeux de l''''Eternel, entièrement comme avait fait Jojakim."}, {"numero": 3, "texto": "Et cela arriva à cause de la colère de l''''Eternel contre Jérusalem et contre Juda, qu''''il voulait rejeter de devant sa face. Et Sédécias se révolta contre le roi de Babylone."}, {"numero": 4, "texto": "La neuvième année du règne de Sédécias, le dixième jour du dixième mois, Nebucadnetsar, roi de Babylone, vint avec toute son armée contre Jérusalem; ils campèrent devant elle, et élevèrent des retranchements tout autour."}, {"numero": 5, "texto": "La ville fut assiégée jusqu''''à la onzième année du roi Sédécias."}, {"numero": 6, "texto": "Le neuvième jour du quatrième mois, la famine était forte dans la ville, et il n''''y avait pas de pain pour le peuple du pays."}, {"numero": 7, "texto": "Alors la brèche fut faite à la ville; et tous les gens de guerre s''''enfuirent, et sortirent de la ville pendant la nuit par le chemin de la porte entre les deux murs près du jardin du roi, tandis que les Chaldéens environnaient la ville. Les fuyards prirent le chemin de la plaine."}, {"numero": 8, "texto": "Mais l''''armée des Chaldéens poursuivit le roi, et ils atteignirent Sédécias dans les plaines de Jéricho; et toute son armée se dispersa loin de lui."}, {"numero": 9, "texto": "Ils saisirent le roi, et le firent monter vers le roi de Babylone à Ribla, dans le pays de Hamath; et il prononça contre lui une sentence."}, {"numero": 10, "texto": "Le roi de Babylone fit égorger les fils de Sédécias en sa présence; il fit aussi égorger tous les chefs de Juda à Ribla."}, {"numero": 11, "texto": "Puis il fit crever les yeux à Sédécias, et le fit lier avec des chaînes d''''airain; le roi de Babylone l''''emmena à Babylone, et il le tint en prison jusqu''''au jour de sa mort."}, {"numero": 12, "texto": "Le dixième jour du cinquième mois, -c''''était la dix-neuvième année du règne de Nebucadnetsar, roi de Babylone, -Nebuzaradan, chef des gardes, au service du roi de Babylone, vint à Jérusalem."}, {"numero": 13, "texto": "Il brûla la maison de l''''Eternel, la maison du roi, et toutes les maisons de Jérusalem; il livra au feu toutes les maisons de quelque importance."}, {"numero": 14, "texto": "Toute l''''armée des Chaldéens, qui était avec le chef des gardes, démolit toutes les murailles formant l''''enceinte de Jérusalem."}, {"numero": 15, "texto": "Nebuzaradan, chef des gardes, emmena captifs une partie des plus pauvres du peuple, ceux du peuple qui étaient demeurés dans la ville, ceux qui s''''étaient rendus au roi de Babylone, et le reste de la multitude."}, {"numero": 16, "texto": "Cependant Nebuzaradan, chef des gardes, laissa comme vignerons et comme laboureurs quelques-uns des plus pauvres du pays."}, {"numero": 17, "texto": "Les Chaldéens brisèrent les colonnes d''''airain qui étaient dans la maison de l''''Eternel, les bases, la mer d''''airain qui était dans la maison de l''''Eternel, et ils en emportèrent tout l''''airain à Babylone."}, {"numero": 18, "texto": "Ils prirent les cendriers, les pelles, les couteaux, les coupes, les tasses, et tous les ustensiles d''''airain avec lesquels on faisait le service."}, {"numero": 19, "texto": "Le chef des gardes prit encore les bassins, les brasiers, les coupes, les cendriers, les chandeliers, les tasses et les calices, ce qui était d''''or et ce qui était d''''argent."}, {"numero": 20, "texto": "Les deux colonnes, la mer, et les douze boeufs d''''airain qui servaient de base, et que le roi Salomon avait faits pour la maison de l''''Eternel, tous ces ustensiles d''''airain avaient un poids inconnu."}, {"numero": 21, "texto": "La hauteur de l''''une des colonnes était de dix-huit coudées, et un cordon de douze coudées l''''entourait; elle était creuse, et son épaisseur avait quatre doigts;"}, {"numero": 22, "texto": "il y avait au-dessus un chapiteau d''''airain, et la hauteur d''''un chapiteau était de cinq coudées; autour du chapiteau il y avait un treillis et des grenades, le tout d''''airain; il en était de même pour la seconde colonne avec des grenades."}, {"numero": 23, "texto": "Il y avait quatre-vingt-seize grenades de chaque côté, et toutes les grenades autour du treillis étaient au nombre de cent."}, {"numero": 24, "texto": "Le chef des gardes prit Seraja, le souverain sacrificateur, Sophonie, le second sacrificateur, et les trois gardiens du seuil."}, {"numero": 25, "texto": "Et dans la ville il prit un eunuque qui avait sous son commandement les gens de guerre, sept hommes qui faisaient partie des conseillers du roi et qui furent trouvés dans la ville, le secrétaire du chef de l''''armée qui était chargé d''''enrôler le peuple du pays, et soixante hommes du peuple du pays qui se trouvèrent dans la ville."}, {"numero": 26, "texto": "Nebuzaradan, chef des gardes, les prit, et les conduisit vers le roi de Babylone à Ribla."}, {"numero": 27, "texto": "Le roi de Babylone les frappa et les fit mourir à Ribla, dans le pays de Hamath. Ainsi Juda fut emmené captif loin de son pays."}, {"numero": 28, "texto": "Voici le peuple que Nebucadnetsar emmena en captivité: la septième année, trois mille vingt-trois Juifs;"}, {"numero": 29, "texto": "la dix-huitième année de Nebucadnetsar, il emmena de Jérusalem huit cent trente-deux personnes;"}, {"numero": 30, "texto": "la vingt-troisième année de Nebucadnetsar, Nebuzaradan, chef des gardes, emmena sept cent quarante-cinq Juifs; en tout quatre mille six cents personnes."}, {"numero": 31, "texto": "La trente-septième année de la captivité de Jojakin, roi de Juda, le vingt-cinquième jour du douzième mois, Evil-Merodac, roi de Babylone, dans la première année de son règne, releva la tête de Jojakin, roi de Juda, et le fit sortir de prison."}, {"numero": 32, "texto": "Il lui parla avec bonté, et il mit son trône au-dessus du trône des rois qui étaient avec lui à Babylone."}, {"numero": 33, "texto": "Il lui fit changer ses vêtements de prison, et Jojakin mangea toujours à sa table tout le temps de sa vie."}, {"numero": 34, "texto": "Le roi de Babylone pourvut constamment à son entretien journalier jusqu''''au jour de sa mort, tout le temps de sa vie."}]'::jsonb, 'Louis Segond 1910'),
  ('Jr', 52, 'es', '[{"numero": 1, "texto": "ERA Sedechîas de edad de veintiún años cuando comenzó á reinar, y reinó once años en Jerusalem. Su madre se llamaba Hamutal, hija de Jeremías, de Libna."}, {"numero": 2, "texto": "E hizo lo malo en los ojos de Jehová, conforme á todo lo que hizo Joacim."}, {"numero": 3, "texto": "Y á causa de la ira de Jehová contra Jerusalem y Judá, fué el llegar á echarlos de su presencia: y rebelóse Sedechîas contra el rey de Babilonia."}, {"numero": 4, "texto": "Aconteció por tanto á los nueve años de su reinado, en el mes décimo, á los diez días del mes, que vino Nabucodonosor rey de Babilonia, él y todo su ejército, contra Jerusalem, y contra ella asentaron campo, y de todas partes edificaron contra ella baluartes."}, {"numero": 5, "texto": "Y estuvo cercada la ciudad hasta el undécimo año del rey Sedechîas."}, {"numero": 6, "texto": "En el mes cuarto, á los nueve del mes, prevaleció el hambre en la ciudad, hasta no haber pan para el pueblo de la tierra."}, {"numero": 7, "texto": "Y fué entrada la ciudad, y todos los hombres de guerra huyeron, y saliéronse de la ciudad de noche por el camino del postigo de entre los dos muros, que había cerca del jardín del rey, y fuéronse por el camino del desierto, estando aún los Caldeos junto á la ciudad alrededor."}, {"numero": 8, "texto": "Y el ejército de los Caldeos siguió al rey, y alcanzaron á Sedechîas en los llanos de Jericó; y esparcióse de él todo su ejército."}, {"numero": 9, "texto": "Entonces prendieron al rey, é hiciéronle venir al rey de Babilonia, á Ribla en tierra de Hamath, donde pronunció contra él sentencia."}, {"numero": 10, "texto": "Y degolló el rey de Babilonia á los hijos de Sedechîas delante de sus ojos, y también degolló á todos los príncipes de Judá en Ribla."}, {"numero": 11, "texto": "A Sedechîas empero sacó los ojos, y le aprisionó con grillos, é hízolo el rey de Babilonia llevar á Babilonia; y púsolo en la casa de la cárcel hasta el día en que murió."}, {"numero": 12, "texto": "Y en el mes quinto, á los diez del mes, que era el año diecinueve del reinado de Nabucodonosor, rey de Babilonia, vino á Jerusalem Nabuzaradán, capitán de la guardia, que solía estar delante del rey de Babilonia."}, {"numero": 13, "texto": "Y quemó la casa de Jehová, y la casa del rey, y todas las casas de Jerusalem; y abrasó con fuego todo grande edificio."}, {"numero": 14, "texto": "Y todo el ejército de los Caldeos, que venía con el capitán de la guardia, destruyó todos los muros de Jerusalem en derredor."}, {"numero": 15, "texto": "E hizo trasportar Nabuzaradán, capitán de la guardia, los pobres del pueblo, y toda la otra gente vulgar que en la ciudad habían quedado, y los fugitivos que se habían huído al rey de Babilonia, y todo el resto de la multitud vulgar."}, {"numero": 16, "texto": "Mas de los pobres del país dejó Nabuzaradán, capitán de la guardia, para viñadores y labradores."}, {"numero": 17, "texto": "Y los Caldeos quebraron las columnas de bronce que estaban en la casa de Jehová, y las basas, y el mar de bronce que estaba en la casa de Jehová, y llevaron todo el metal á Babilonia."}, {"numero": 18, "texto": "Lleváronse también los calderos, y los badiles, y los salterios, y las bacías, y los cazos, y todos los vasos de metal con que se servían."}, {"numero": 19, "texto": "Y las copas, é incensarios, y tazones, y ollas, y candeleros, y escudillas, y tazas: lo que de oro de oro, y lo que de plata de plata, se llevó el capitán de la guardia."}, {"numero": 20, "texto": "Las dos columnas, un mar, y doce bueyes de bronce que estaban debajo de las basas, que había hecho el rey Salomón en la casa de Jehová: no se podía pesar el metal de todos estos vasos."}, {"numero": 21, "texto": "Cuanto á las columnas, la altura de la columna era de dieciocho codos, y un hilo de doce codos la rodeaba: y su grueso era de cuatro dedos, y hueca."}, {"numero": 22, "texto": "Y el capitel de bronce que había sobre ella, era de altura de cinco codos, con una red y granadas en el capitel alrededor, todo de bronce; y lo mismo era lo de la segunda columna con sus granadas."}, {"numero": 23, "texto": "Había noventa y seis granadas en cada orden: todas ellas eran ciento sobre la red alrededor."}, {"numero": 24, "texto": "Tomó también el capitán de la guardia á Seraías principal sacerdote, y á Sophonías segundo sacerdote, y tres guardas del atrio."}, {"numero": 25, "texto": "Y de la ciudad tomó un eunuco que era capitán sobre los hombres de guerra, y siete hombres de los continuos del rey, que se hallaron en la ciudad; y al principal secretario de la milicia, que revistaba el pueblo de la tierra para la guerra; y sesenta hombres del vulgo del país, que se hallaron dentro de la ciudad."}, {"numero": 26, "texto": "Tomólos pues Nabuzaradán, capitán de la guardia, y llevólos al rey de Babilonia á Ribla."}, {"numero": 27, "texto": "Y el rey de Babilonia los hirió, y los mató en Ribla en tierra de Hamath. Así fué Judá trasportado de su tierra."}, {"numero": 28, "texto": "Este es el pueblo que Nabucodonosor hizo trasportar: En el año séptimo, tres mil veintitrés Judíos:"}, {"numero": 29, "texto": "En el año dieciocho hizo Nabucodonosor trasportar de Jerusalem ochocientas treinta y dos personas:"}, {"numero": 30, "texto": "El año veintitrés de Nabucodonosor, trasportó Nabuzaradán capitán de la guardia, setecientas cuarenta y cinco personas de los Judíos: todas las personas fueron cuatro mil seiscientas."}, {"numero": 31, "texto": "Y acaeció que en el año treinta y siete de la cautividad de Joachîn rey de Judá, en el mes duodécimo, á los veinticinco del mes, Evil-merodach, rey de Babilonia, en el año primero de su reinado, alzó la cabeza de Joachîn rey de Judá y sacólo de la casa de la cárcel;"}, {"numero": 32, "texto": "Y habló con él amigablemente, é hizo poner su silla sobre las sillas de los reyes que estaban con él en Babilonia."}, {"numero": 33, "texto": "Hízole mudar también los vestidos de su prisión, y comía pan delante de él siempre todos los días de su vida."}, {"numero": 34, "texto": "Y continuamente se le daba ración por el rey de Babilonia, cada cosa en su día por todos los de su vida, hasta el día de su muerte."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 1, 'pt', '[{"numero": 1, "texto": "E aconteceu depois da morte de Moisés servo do SENHOR, que o SENHOR falou a Josué filho de Num, assistente de Moisés, dizendo:"}, {"numero": 2, "texto": "Meu servo Moisés é morto: levanta-te, pois, agora, e passa este Jordão, tu e todo este povo, à terra que eu lhes dou aos filhos de Israel."}, {"numero": 3, "texto": "Eu vos entreguei, como o disse a Moisés, todo lugar que pisar a planta de vosso pé."}, {"numero": 4, "texto": "Desde o deserto e este Líbano até o grande rio Eufrates, toda a terra dos heteus até o grande mar do ocidente, será vosso termo."}, {"numero": 5, "texto": "Ninguém poderá resistir a ti em todos os dias de tua vida: como eu fui com Moisés, serei contigo; não te deixarei, nem te desampararei."}, {"numero": 6, "texto": "Esforça-te e sê valente: porque tu repartirás a este povo por herança a terra, da qual jurei a seus pais que a daria a eles."}, {"numero": 7, "texto": "Somente te esforces, e sejas muito valente, para cuidar de fazer conforme toda a lei que meu servo Moisés te mandou: não te apartes dela nem à direita nem à esquerda, para que sejas próspero em todas as coisas que empreenderes."}, {"numero": 8, "texto": "O livro desta lei nunca se apartará de tua boca: antes de dia e de noite meditarás nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem."}, {"numero": 9, "texto": "Olha que te mando que te esforces e sejas valente: não temas nem desmaies, porque o SENHOR teu Deus será contigo onde quer que fores."}, {"numero": 10, "texto": "E Josué mandou aos oficiais do povo, dizendo:"}, {"numero": 11, "texto": "Passai por meio do acampamento, e mandai ao povo, dizendo: Abastecei-vos de comida; porque dentro de três dias passareis o Jordão, para que entreis a possuir a terra que o SENHOR vosso Deus vos dá para que a possuais."}, {"numero": 12, "texto": "Também falou Josué aos rubenitas e gaditas, e à meia tribo de Manassés, dizendo:"}, {"numero": 13, "texto": "Lembrai-vos da palavra que Moisés, servo do SENHOR, vos mandou dizendo: o SENHOR vosso Deus vos deu repouso, e vos deu esta terra."}, {"numero": 14, "texto": "Vossas mulheres e vossos meninos e vossas animais, ficarão na terra que Moisés vos deu desta parte do Jordão; mas vós, todos os valentes e fortes, passareis armados diante de vossos irmãos, e lhes ajudareis;"}, {"numero": 15, "texto": "Até tanto que o SENHOR tenha dado repouso a vossos irmãos como a vós, e que eles também possuam a terra que o SENHOR vosso Deus lhes dá: e depois voltareis vós à terra de vossa herança, a qual Moisés servo do SENHOR vos deu, desta parte do Jordão até o oriente; e a possuireis."}, {"numero": 16, "texto": "Então responderam a Josué, dizendo: Nós faremos todas as coisas que nos mandaste, e iremos aonde quer que nos mandares."}, {"numero": 17, "texto": "Da maneira que obedecemos a Moisés em todas as coisas, assim obedeceremos a ti: somente o SENHOR teu Deus seja contigo, como foi com Moisés."}, {"numero": 18, "texto": "Qualquer um que for rebelde ao teu mandamento, e não obedecer às tuas palavras em todas as coisas que lhe mandares, que morra; somente que te esforces, e sejas valente."}]'::jsonb, 'Almeida Livre'),
  ('Js', 1, 'en', '[{"numero": 1, "texto": "Now after the death of Moses the servant of the Lord it came to pass, that the Lord spake unto Joshua the son of Nun, Moses'' minister, saying,"}, {"numero": 2, "texto": "Moses my servant is dead; now therefore arise, go over this Jordan, thou, and all this people, unto the land which I do give to them, even to the children of Israel."}, {"numero": 3, "texto": "Every place that the sole of your foot shall tread upon, that have I given unto you, as I said unto Moses."}, {"numero": 4, "texto": "From the wilderness and this Lebanon even unto the great river, the river Euphrates, all the land of the Hittites, and unto the great sea toward the going down of the sun, shall be your coast."}, {"numero": 5, "texto": "There shall not any man be able to stand before thee all the days of thy life: as I was with Moses, so I will be with thee: I will not fail thee, nor forsake thee."}, {"numero": 6, "texto": "Be strong and of a good courage: for unto this people shalt thou divide for an inheritance the land, which I sware unto their fathers to give them."}, {"numero": 7, "texto": "Only be thou strong and very courageous, that thou mayest observe to do according to all the law, which Moses my servant commanded thee: turn not from it to the right hand or to the left, that thou mayest prosper withersoever thou goest."}, {"numero": 8, "texto": "This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success."}, {"numero": 9, "texto": "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the Lord thy God is with thee whithersoever thou goest."}, {"numero": 10, "texto": "Then Joshua commanded the officers of the people, saying,"}, {"numero": 11, "texto": "Pass through the host, and command the people, saying, Prepare you victuals; for within three days ye shall pass over this Jordan, to go in to possess the land, which the Lord your God giveth you to possess it."}, {"numero": 12, "texto": "And to the Reubenites, and to the Gadites, and to half the tribe of Manasseh, spake Joshua, saying,"}, {"numero": 13, "texto": "Remember the word which Moses the servant of the Lord commanded you, saying, The Lord your God hath given you rest, and hath given you this land."}, {"numero": 14, "texto": "Your wives, your little ones, and your cattle, shall remain in the land which Moses gave you on this side Jordan; but ye shall pass before your brethren armed, all the mighty men of valour, and help them;"}, {"numero": 15, "texto": "Until the Lord have given your brethren rest, as he hath given you, and they also have possessed the land which the Lord your God giveth them: then ye shall return unto the land of your possession, and enjoy it, which Moses the Lord''s servant gave you on this side Jordan toward the sunrising."}, {"numero": 16, "texto": "And they answered Joshua, saying, All that thou commandest us we will do, and whithersoever thou sendest us, we will go."}, {"numero": 17, "texto": "According as we hearkened unto Moses in all things, so will we hearken unto thee: only the Lord thy God be with thee, as he was with Moses."}, {"numero": 18, "texto": "Whosoever he be that doth rebel against thy commandment, and will not hearken unto thy words in all that thou commandest him, he shall be put to death: only be strong and of a good courage."}]'::jsonb, 'King James Version'),
  ('Js', 1, 'fr', '[{"numero": 1, "texto": "Après la mort de Moïse, serviteur de l''''Eternel, l''''Eternel dit à Josué, fils de Nun, serviteur de Moïse:"}, {"numero": 2, "texto": "Moïse, mon serviteur, est mort; maintenant, lève-toi, passe ce Jourdain, toi et tout ce peuple, pour entrer dans le pays que je donne aux enfants d''''Israël."}, {"numero": 3, "texto": "Tout lieu que foulera la plante de votre pied, je vous le donne, comme je l''''ai dit à Moïse."}, {"numero": 4, "texto": "Vous aurez pour territoire depuis le désert et le Liban jusqu''''au grand fleuve, le fleuve de l''''Euphrate, tout le pays des Héthiens, et jusqu''''à la grande mer vers le soleil couchant."}, {"numero": 5, "texto": "Nul ne tiendra devant toi, tant que tu vivras. Je serai avec toi, comme j''''ai été avec Moïse; je ne te délaisserai point, je ne t''''abandonnerai point."}, {"numero": 6, "texto": "Fortifie-toi et prends courage, car c''''est toi qui mettras ce peuple en possession du pays que j''''ai juré à leurs pères de leur donner."}, {"numero": 7, "texto": "Fortifie-toi seulement et aie bon courage, en agissant fidèlement selon toute la loi que Moïse, mon serviteur, t''''a prescrite; ne t''''en détourne ni à droite ni à gauche, afin de réussir dans tout ce que tu entreprendras."}, {"numero": 8, "texto": "Que ce livre de la loi ne s''''éloigne point de ta bouche; médite-le jour et nuit, pour agir fidèlement selon tout ce qui y est écrit; car c''''est alors que tu auras du succès dans tes entreprises, c''''est alors que tu réussiras."}, {"numero": 9, "texto": "Ne t''''ai-je pas donné cet ordre: Fortifie-toi et prends courage? Ne t''''effraie point et ne t''''épouvante point, car l''''Eternel, ton Dieu, est avec toi dans tout ce que tu entreprendras."}, {"numero": 10, "texto": "Josué donna cet ordre aux officiers du peuple:"}, {"numero": 11, "texto": "Parcourez le camp, et voici ce que vous commanderez au peuple: Préparez-vous des provisions, car dans trois jours vous passerez ce Jourdain pour aller conquérir le pays dont l''''Eternel, votre Dieu, vous donne la possession."}, {"numero": 12, "texto": "Josué dit aux Rubénites, aux Gadites et à la demi-tribu de Manassé:"}, {"numero": 13, "texto": "Rappelez-vous ce que vous a prescrit Moïse, serviteur de l''''Eternel, quand il a dit: L''''Eternel, votre Dieu, vous a accordé du repos, et vous a donné ce pays."}, {"numero": 14, "texto": "Vos femmes, vos petits enfants et vos troupeaux resteront dans le pays que vous a donné Moïse de ce côté-ci du Jourdain; mais vous tous, hommes vaillants, vous passerez en armes devant vos frères, et vous les aiderez,"}, {"numero": 15, "texto": "jusqu''''à ce que l''''Eternel ait accordé du repos à vos frères comme à vous, et qu''''ils soient aussi en possession du pays que l''''Eternel, votre Dieu, leur donne. Puis vous reviendrez prendre possession du pays qui est votre propriété, et que vous a donné Moïse, serviteur de l''''Eternel, de ce côté-ci du Jourdain, vers le soleil levant."}, {"numero": 16, "texto": "Ils répondirent à Josué, en disant: Nous ferons tout ce que tu nous as ordonné, et nous irons partout où tu nous enverras."}, {"numero": 17, "texto": "Nous t''''obéirons entièrement, comme nous avons obéi à Moïse. Veuille seulement l''''Eternel, ton Dieu, être avec toi, comme il a été avec Moïse!"}, {"numero": 18, "texto": "Tout homme qui sera rebelle à ton ordre, et qui n''''obéira pas à tout ce que tu lui commanderas, sera puni de mort. Fortifie-toi seulement, et prends courage!"}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 1, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después de la muerte de Moisés siervo de Jehová, que Jehová habló á Josué hijo de Nun, ministro de Moisés, diciendo:"}, {"numero": 2, "texto": "Mi siervo Moisés es muerto: levántate pues ahora, y pasa este Jordán, tú y todo este pueblo, á la tierra que yo les doy á los hijos de Israel."}, {"numero": 3, "texto": "Yo os he entregado, como lo había dicho á Moisés, todo lugar que pisare la planta de vuestro pie."}, {"numero": 4, "texto": "Desde el desierto y este Líbano hasta el gran río Eufrates, toda la tierra de los Hetheos hasta la gran mar del poniente del sol, será vuestro término."}, {"numero": 5, "texto": "Nadie te podrá hacer frente en todos los días de tu vida: como yo fuí con Moisés, seré contigo; no te dejaré, ni te desampararé."}, {"numero": 6, "texto": "Esfuérzate y sé valiente: porque tú repartirás á este pueblo por heredad la tierra, de la cual juré á sus padres que la daría á ellos."}, {"numero": 7, "texto": "Solamente te esfuerces, y seas muy valiente, para cuidar de hacer conforme á toda la ley que mi siervo Moisés te mandó: no te apartes de ella ni á diestra ni á siniestra, para que seas prosperado en todas las cosas que emprendieres."}, {"numero": 8, "texto": "El libro de aquesta ley nunca se apartará de tu boca: antes de día y de noche meditarás en él, para que guardes y hagas conforme á todo lo que en él está escrito: porque entonces harás prosperar tu camino, y todo te saldrá bien."}, {"numero": 9, "texto": "Mira que te mando que te esfuerces y seas valiente: no temas ni desmayes, porque Jehová tu Dios será contigo en donde quiera que fueres."}, {"numero": 10, "texto": "Y Josué mandó á los oficiales del pueblo, diciendo:"}, {"numero": 11, "texto": "Pasad por medio del campo, y mandad al pueblo, diciendo: Preveníos de comida; porque dentro de tres días pasaréis el Jordán, para que entréis á poseer la tierra que Jehová vuestro Dios os da para que la poseáis."}, {"numero": 12, "texto": "También habló Josué á los Rubenitas y Gaditas, y á la media tribu de Manasés, diciendo:"}, {"numero": 13, "texto": "Acordaos de la palabra que Moisés, siervo de Jehová, os mandó diciendo: Jehová vuestro Dios os ha dado reposo, y os ha dado esta tierra."}, {"numero": 14, "texto": "Vuestras mujeres y vuestros niños y vuestras bestias, quedarán en la tierra que Moisés os ha dado de esta parte del Jordán; mas vosotros, todos los valientes y fuertes, pasaréis armados delante de vuestros hermanos, y les ayudaréis;"}, {"numero": 15, "texto": "Hasta tanto que Jehová haya dado reposo á vuestros hermanos como á vosotros, y que ellos también posean la tierra que Jehová vuestro Dios les da: y después volveréis vosotros á la tierra de vuestra herencia, la cual Moisés siervo de Jehová os ha dado, de esta parte del Jordán hacia donde nace el sol; y la poseeréis."}, {"numero": 16, "texto": "Entonces respondieron á Josué, diciendo: Nosotros haremos todas las cosas que nos has mandado, é iremos adonde quiera que nos mandares."}, {"numero": 17, "texto": "De la manera que obedecimos á Moisés en todas las cosas, así te obedeceremos á ti: solamente Jehová tu Dios sea contigo, como fué con Moisés."}, {"numero": 18, "texto": "Cualquiera que fuere rebelde á tu mandamiento, y no obedeciere á tus palabras en todas las cosas que le mandares, que muera; solamente que te esfuerces, y seas valiente."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 2, 'pt', '[{"numero": 1, "texto": "E Josué, filho de Num, enviou desde Sitim dois espias secretamente, dizendo-lhes: Andai, reconhecei a terra, e a Jericó. Os quais foram, e entraram em casa de uma mulher prostituta que se chamava Raabe, e passaram a noite ali."}, {"numero": 2, "texto": "E foi dado aviso ao rei de Jericó, dizendo: Eis que homens dos filhos de Israel vieram aqui esta noite a espiar a terra."}, {"numero": 3, "texto": "Então o rei de Jericó, enviou a dizer a Raabe: Tira fora os homens que vieram a ti, e entraram em tua casa; porque vieram a espiar toda a terra."}, {"numero": 4, "texto": "Mas a mulher havia tomado os dois homens, e os havia escondido; e disse: Verdade que homens vieram a mim, mas não soube de onde eram:"}, {"numero": 5, "texto": "E ao fechar-se a porta, sendo já escuro, esses homens saíram, e não sei para onde se foram: segui-os depressa, que os alcançareis."}, {"numero": 6, "texto": "Mas ela os havia feito subir ao terraço, e havia os escondido entre talos de linho que naquele terraço tinha posto."}, {"numero": 7, "texto": "E os homens foram atrás eles pelo caminho do Jordão, até os vaus: e a porta foi fechada depois que saíram os que atrás eles iam."}, {"numero": 8, "texto": "Mas antes que eles dormissem, ela subiu a eles ao terraço, e disse-lhes:"}, {"numero": 9, "texto": "Eu sei que o SENHOR vos deu esta terra; porque o temor de vós caiu sobre nós, e todos os moradores desta terra estão apavorados por causa de vós;"}, {"numero": 10, "texto": "Porque ouvimos que o SENHOR fez secar as águas do mar Vermelho diante de vós, quando saístes do Egito, e o que fizestes aos dois reis pelos amorreus que estavam da parte dali do Jordão, a Seom e a Ogue, aos quais destruístes."}, {"numero": 11, "texto": "Ouvindo isto, desmaiou nosso coração; nem restou mais espírito em alguém por causa de vós: porque o SENHOR vosso Deus é Deus acima nos céus e abaixo na terra."}, {"numero": 12, "texto": "Rogo-vos, pois, agora, me jureis pelo SENHOR, que como fiz misericórdia convosco, assim a fareis vós com a casa de meu pai, do qual me dareis um sinal certo;"}, {"numero": 13, "texto": "E que salvareis a vida a meu pai e a minha mãe, e a meus irmãos e irmãs, e a todo o que for seu; e que livrareis nossas vidas da morte."}, {"numero": 14, "texto": "E eles lhe responderam: Nossa vida esteja pela vossa até a morte, se não denunciardes este nosso negócio; e quando o SENHOR houver nos dado a terra, nós a trataremos com misericórdia e fidelidade."}, {"numero": 15, "texto": "Então ela os fez descer com uma corda pela janela; porque sua casa estava à parede do muro, e ela vivia no muro."}, {"numero": 16, "texto": "E disse-lhes: Marchai-vos ao monte, porque os que foram atrás vós não vos encontrem; e estai escondidos ali três dias, até que os que vos seguem tenham voltado; e depois vos ireis vosso caminho."}, {"numero": 17, "texto": "E eles lhe disseram: Nós seremos desobrigados deste juramento com que nos hás conjurado."}, {"numero": 18, "texto": "Eis que, quando nós entrarmos na terra, tu atarás este cordão de escarlate à janela pela qual nos fizeste descer: e tu juntarás em tua casa teu pai e tua mãe, teus irmãos e toda a família de teu pai."}, {"numero": 19, "texto": "Qualquer um que sair fora das portas de tua casa, seu sangue será sobre sua cabeça, e nós sem culpa. Mas qualquer um que estiver em casa contigo, seu sangue será sobre nossa cabeça, se mão o tocar."}, {"numero": 20, "texto": "E se tu denunciares este nosso negócio, nós seremos desobrigados deste teu juramento com que nos fizeste jurar."}, {"numero": 21, "texto": "E ela respondeu: Seja assim como dissestes. Logo os despediu, e se foram: e ela atou o cordão de escarlate à janela."}, {"numero": 22, "texto": "E caminhando eles, chegaram ao monte, e estiveram ali três dias, até que os que os seguiam se houvessem voltado: e os que os seguiram, buscaram por todo aquele caminho, mas não os acharam."}, {"numero": 23, "texto": "E voltando-se os dois homens, desceram do monte, e passaram, e vieram a Josué filho de Num, e contaram-lhe todas as coisas que lhes haviam acontecido."}, {"numero": 24, "texto": "E disseram a Josué: O SENHOR entregou toda esta terra em nossas mãos; e também todos os moradores desta terra estão apavorados por nossa causa."}]'::jsonb, 'Almeida Livre'),
  ('Js', 2, 'en', '[{"numero": 1, "texto": "And Joshua the son of Nun sent out of Shittim two men to spy secretly, saying, Go view the land, even Jericho. And they went, and came into an harlot''s house, named Rahab, and lodged there."}, {"numero": 2, "texto": "And it was told the king of Jericho, saying, Behold, there came men in hither to night of the children of Israel to search out the country."}, {"numero": 3, "texto": "And the king of Jericho sent unto Rahab, saying, Bring forth the men that are come to thee, which are entered into thine house: for they be come to search out all the country."}, {"numero": 4, "texto": "And the woman took the two men, and hid them, and said thus, There came men unto me, but I wist not whence they were:"}, {"numero": 5, "texto": "And it came to pass about the time of shutting of the gate, when it was dark, that the men went out: whither the men went I wot not: pursue after them quickly; for ye shall overtake them."}, {"numero": 6, "texto": "But she had brought them up to the roof of the house, and hid them with the stalks of flax, which she had laid in order upon the roof."}, {"numero": 7, "texto": "And the men pursued after them the way to Jordan unto the fords: and as soon as they which pursued after them were gone out, they shut the gate."}, {"numero": 8, "texto": "And before they were laid down, she came up unto them upon the roof;"}, {"numero": 9, "texto": "And she said unto the men, I know that the Lord hath given you the land, and that your terror is fallen upon us, and that all the inhabitants of the land faint because of you."}, {"numero": 10, "texto": "For we have heard how the Lord dried up the water of the Red sea for you, when ye came out of Egypt; and what ye did unto the two kings of the Amorites, that were on the other side Jordan, Sihon and Og, whom ye utterly destroyed."}, {"numero": 11, "texto": "And as soon as we had heard these things, our hearts did melt, neither did there remain any more courage in any man, because of you: for the Lord your God, he is God in heaven above, and in earth beneath."}, {"numero": 12, "texto": "Now therefore, I pray you, swear unto me by the Lord, since I have shewed you kindness, that ye will also shew kindness unto my father''s house, and give me a true token:"}, {"numero": 13, "texto": "And that ye will save alive my father, and my mother, and my brethren, and my sisters, and all that they have, and deliver our lives from death."}, {"numero": 14, "texto": "And the men answered her, Our life for yours, if ye utter not this our business. And it shall be, when the Lord hath given us the land, that we will deal kindly and truly with thee."}, {"numero": 15, "texto": "Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."}, {"numero": 16, "texto": "And she said unto them, Get you to the mountain, lest the pursuers meet you; and hide yourselves there three days, until the pursuers be returned: and afterward may ye go your way."}, {"numero": 17, "texto": "And the men said unto her, We will be blameless of this thine oath which thou hast made us swear."}, {"numero": 18, "texto": "Behold, when we come into the land, thou shalt bind this line of scarlet thread in the window which thou didst let us down by: and thou shalt bring thy father, and thy mother, and thy brethren, and all thy father''s household, home unto thee."}, {"numero": 19, "texto": "And it shall be, that whosoever shall go out of the doors of thy house into the street, his blood shall be upon his head, and we will be guiltless: and whosoever shall be with thee in the house, his blood shall be on our head, if any hand be upon him."}, {"numero": 20, "texto": "And if thou utter this our business, then we will be quit of thine oath which thou hast made us to swear."}, {"numero": 21, "texto": "And she said, According unto your words, so be it. And she sent them away, and they departed: and she bound the scarlet line in the window."}, {"numero": 22, "texto": "And they went, and came unto the mountain, and abode there three days, until the pursuers were returned: and the pursuers sought them throughout all the way, but found them not."}, {"numero": 23, "texto": "So the two men returned, and descended from the mountain, and passed over, and came to Joshua the son of Nun, and told him all things that befell them:"}, {"numero": 24, "texto": "And they said unto Joshua, Truly the Lord hath delivered into our hands all the land; for even all the inhabitants of the country do faint because of us."}]'::jsonb, 'King James Version'),
  ('Js', 2, 'fr', '[{"numero": 1, "texto": "Josué, fils de Nun, fit partir secrètement de Sittim deux espions, en leur disant: Allez, examinez le pays, et en particulier Jéricho. Ils partirent, et ils arrivèrent dans la maison d''''une prostituée, qui se nommait Rahab, et ils y couchèrent."}, {"numero": 2, "texto": "On dit au roi de Jéricho: Voici, des hommes d''''entre les enfants d''''Israël sont arrivés ici, cette nuit, pour explorer le pays."}, {"numero": 3, "texto": "Le roi de Jéricho envoya dire à Rahab: Fais sortir les hommes qui sont venus chez toi, qui sont entrés dans ta maison; car c''''est pour explorer tout le pays qu''''ils sont venus."}, {"numero": 4, "texto": "La femme prit les deux hommes, et les cacha; et elle dit: Il est vrai que ces hommes sont arrivés chez moi, mais je ne savais pas d''''où ils étaient;"}, {"numero": 5, "texto": "et, comme la porte a dû se fermer de nuit, ces hommes sont sortis; j''''ignore où ils sont allés: hâtez-vous de les poursuivre et vous les atteindrez."}, {"numero": 6, "texto": "Elle les avait fait monter sur le toit, et les avait cachés sous des tiges de lin, qu''''elle avait arrangées sur le toit."}, {"numero": 7, "texto": "Ces gens les poursuivirent par le chemin qui mène au gué du Jourdain, et l''''on ferma la porte après qu''''ils furent sortis."}, {"numero": 8, "texto": "Avant que les espions se couchassent, Rahab monta vers eux sur le toit"}, {"numero": 9, "texto": "et leur dit: L''''Eternel, je le sais, vous a donné ce pays, la terreur que vous inspirez nous a saisis, et tous les habitants du pays tremblent devant vous."}, {"numero": 10, "texto": "Car nous avons appris comment, à votre sortie d''''Egypte, l''''Eternel a mis à sec devant vous les eaux de la mer Rouge, et comment vous avez traité les deux rois des Amoréens au delà du Jourdain, Sihon et Og, que vous avez dévoués par interdit."}, {"numero": 11, "texto": "Nous l''''avons appris, et nous avons perdu courage, et tous nos esprits sont abattus à votre aspect; car c''''est l''''Eternel, votre Dieu, qui est Dieu en haut dans les cieux et en bas sur la terre."}, {"numero": 12, "texto": "Et maintenant, je vous prie, jurez-moi par l''''Eternel que vous aurez pour la maison de mon père la même bonté que j''''ai eue pour vous. Donnez-moi l''''assurance"}, {"numero": 13, "texto": "que vous laisserez vivre mon père, ma mère, mes frères, mes soeurs, et tous ceux qui leur appartiennent, et que vous nous sauverez de la mort."}, {"numero": 14, "texto": "Ces hommes lui répondirent: Nous sommes prêts à mourir pour vous, si vous ne divulguez pas ce qui nous concerne; et quand l''''Eternel nous donnera le pays, nous agirons envers toi avec bonté et fidélité."}, {"numero": 15, "texto": "Elle les fit descendre avec une corde par la fenêtre, car la maison qu''''elle habitait était sur la muraille de la ville."}, {"numero": 16, "texto": "Elle leur dit: Allez du côté de la montagne, de peur que ceux qui vous poursuivent ne vous rencontrent; cachez-vous là pendant trois jours, jusqu''''à ce qu''''ils soient de retour; après cela, vous suivrez votre chemin."}, {"numero": 17, "texto": "Ces hommes lui dirent: Voici de quelle manière nous serons quittes du serment que tu nous as fait faire."}, {"numero": 18, "texto": "A notre entrée dans le pays, attache ce cordon de fil cramoisi à la fenêtre par laquelle tu nous fais descendre, et recueille auprès de toi dans la maison ton père, ta mère, tes frères, et toute la famille de ton père."}, {"numero": 19, "texto": "Si quelqu''''un d''''eux sort de la porte de ta maison pour aller dehors, son sang retombera sur sa tête, et nous en serons innocents; mais si on met la main sur l''''un quelconque de ceux qui seront avec toi dans la maison, son sang retombera sur notre tête."}, {"numero": 20, "texto": "Et si tu divulgues ce qui nous concerne, nous serons quittes du serment que tu nous as fait faire."}, {"numero": 21, "texto": "Elle répondit: Qu''''il en soit selon vos paroles. Elle prit ainsi congé d''''eux, et ils s''''en allèrent. Et elle attacha le cordon de cramoisi à la fenêtre."}, {"numero": 22, "texto": "Ils partirent, et arrivèrent à la montagne, où ils restèrent trois jours, jusqu''''à ce que ceux qui les poursuivaient fussent de retour. Ceux qui les poursuivaient les cherchèrent par tout le chemin, mais ils ne les trouvèrent pas."}, {"numero": 23, "texto": "Les deux hommes s''''en retournèrent, descendirent de la montagne, et passèrent le Jourdain. Ils vinrent auprès de Josué, fils de Nun, et lui racontèrent tout ce qui leur était arrivé."}, {"numero": 24, "texto": "Ils dirent à Josué: Certainement, l''''Eternel a livré tout le pays entre nos mains, et même tous les habitants du pays tremblent devant nous."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 2, 'es', '[{"numero": 1, "texto": "Y JOSUÉ, hijo de Nun, envió desde Sittim dos espías secretamente, diciéndoles: Andad, reconoced la tierra, y á Jericó. Los cuales fueron, y entráronse en casa de una mujer ramera que se llamaba Rahab, y posaron allí."}, {"numero": 2, "texto": "Y fué dado aviso al rey de Jericó, diciendo: He aquí que hombres de los hijos de Israel han venido aquí esta noche á espiar la tierra."}, {"numero": 3, "texto": "Entonces el rey de Jericó envió á decir á Rahab: Saca fuera los hombres que han venido á ti, y han entrado en tu casa; porque han venido á espiar toda la tierra."}, {"numero": 4, "texto": "Mas la mujer había tomado los dos hombres, y los había escondido; y dijo: Verdad que hombres vinieron á mí, mas no supe de dónde eran:"}, {"numero": 5, "texto": "Y al cerrarse la puerta, siendo ya oscuro, esos hombres se salieron, y no sé á dónde se han ido: seguidlos apriesa, que los alcanzaréis."}, {"numero": 6, "texto": "Mas ella los había hecho subir al terrado, y habíalos escondido entre tascos de lino que en aquel terrado tenía puestos."}, {"numero": 7, "texto": "Y los hombres fueron tras ellos por el camino del Jordán, hasta los vados: y la puerta fué cerrada después que salieron los que tras ellos iban."}, {"numero": 8, "texto": "Mas antes que ellos durmiesen, ella subió á ellos al terrado, y díjoles:"}, {"numero": 9, "texto": "Sé que Jehová os ha dado esta tierra; porque el temor de vosotros ha caído sobre nosotros, y todos los moradores del país están desmayados por causa de vosotros;"}, {"numero": 10, "texto": "Porque hemos oído que Jehová hizo secar las aguas del mar Bermejo delante de vosotros, cuando salisteis de Egipto, y lo que habéis hecho á los dos reyes de los Amorrheos que estaban de la parte allá del Jordán, á Sehón y á Og, á los cuales habéis destruído."}, {"numero": 11, "texto": "Oyendo esto, ha desmayado nuestro corazón; ni ha quedado más espíritu en alguno por causa de vosotros: porque Jehová vuestro Dios es Dios arriba en los cielos y abajo en la tierra."}, {"numero": 12, "texto": "Ruégoos pues ahora, me juréis por Jehová, que como he hecho misericordia con vosotros, así la haréis vosotros con la casa de mi padre, de lo cual me daréis una señal cierta;"}, {"numero": 13, "texto": "Y que salvaréis la vida á mi padre y á mi madre, y á mis hermanos y hermanas, y á todo lo que es suyo; y que libraréis nuestras vidas de la muerte."}, {"numero": 14, "texto": "Y ellos le respondieron: Nuestra alma por vosotros hasta la muerte, si no denunciareis este nuestro negocio: y cuando Jehová nos hubiere dado la tierra, nosotros haremos contigo misericordia y verdad."}, {"numero": 15, "texto": "Entonces ella los hizo descender con una cuerda por la ventana; porque su casa estaba á la pared del muro, y ella vivía en el muro."}, {"numero": 16, "texto": "Y díjoles: Marchaos al monte, porque los que fueron tras vosotros no os encuentren; y estad escondidos allí tres días, hasta que los que os siguen hayan vuelto; y después os iréis vuestro camino."}, {"numero": 17, "texto": "Y ellos le dijeron: Nosotros seremos desobligados de este juramento con que nos has conjurado."}, {"numero": 18, "texto": "He aquí, cuando nosotros entráremos en la tierra, tú atarás este cordón de grana á la ventana por la cual nos descolgaste: y tú juntarás en tu casa tu padre y tu madre, tus hermanos y toda la familia de tu padre."}, {"numero": 19, "texto": "Cualquiera que saliere fuera de las puertas de tu casa, su sangre será sobre su cabeza, y nosotros sin culpa. Mas cualquiera que se estuviere en casa contigo, su sangre será sobre nuestra cabeza, si mano le tocare."}, {"numero": 20, "texto": "Y si tú denunciares este nuestro negocio, nosotros seremos desobligados de este tu juramento con que nos has juramentado."}, {"numero": 21, "texto": "Y ella respondió: Sea así como habéis dicho. Luego los despidió, y se fueron: y ella ató el cordón de grana á la ventana."}, {"numero": 22, "texto": "Y caminando ellos, llegaron al monte, y estuvieron allí tres días, hasta que los que los seguían se hubiesen vuelto: y los que los siguieron, buscaron por todo el camino, mas no los hallaron."}, {"numero": 23, "texto": "Y tornándose los dos varones, descendieron del monte, y pasaron, y vinieron á Josué hijo de Nun, y contáronle todas las cosas que les habían acontecido."}, {"numero": 24, "texto": "Y dijeron á Josué: Jehová ha entregado toda la tierra en nuestras manos; y también todos los moradores del país están desmayados delante de nosotros."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 3, 'pt', '[{"numero": 1, "texto": "E levantou-se Josué de manhã, e partiram de Sitim, e vieram até o Jordão, ele e todos os filhos de Israel, e repousaram ali antes que passassem."}, {"numero": 2, "texto": "E passados três dias, os oficiais atravessaram por meio do acampamento,"}, {"numero": 3, "texto": "E mandaram ao povo, dizendo: Quando virdes a arca do pacto do SENHOR vosso Deus, e os sacerdotes e levitas que a levam, vós partireis de vosso lugar, e marchareis atrás dela."}, {"numero": 4, "texto": "Porém entre vós e ela haja distância como da medida de dois mil côvados: e não vos aproximareis dela, a fim de que saibais o caminho por onde haveis de ir: porquanto vós não passastes antes de agora por este caminho."}, {"numero": 5, "texto": "E Josué disse ao povo: Santificai-vos, porque o SENHOR fará amanhã entre vós maravilhas."}, {"numero": 6, "texto": "E falou Josué aos sacerdotes, dizendo: Tomai a arca do pacto, e passai diante do povo. E eles tomaram a arca do pacto, e foram diante do povo."}, {"numero": 7, "texto": "Então o SENHOR disse a Josué: Desde este dia começarei a fazer-te grande diante dos olhos de todo Israel, para que entendam que como fui com Moisés, assim serei contigo."}, {"numero": 8, "texto": "Tu, pois, mandarás aos sacerdotes que levam a arca do pacto, dizendo: Quando houverdes entrado até a borda da água do Jordão, parareis no Jordão."}, {"numero": 9, "texto": "E Josué disse aos filhos de Israel: Achegai-vos aqui, e escutai as palavras do SENHOR vosso Deus."}, {"numero": 10, "texto": "E acrescentou Josué: Em isto conhecereis que o Deus vivente está em meio de vós, e que ele lançará de diante de vós aos cananeus, e aos heteus, e aos heveus, e aos perizeus, e aos gergeseus, e aos amorreus, e aos jebuseus."}, {"numero": 11, "texto": "Eis que, a arca do pacto do Dominador de toda a terra passa o Jordão diante de vós."}, {"numero": 12, "texto": "Tomai, pois, agora doze homens das tribos de Israel, de cada tribo um."}, {"numero": 13, "texto": "E quando as plantas dos pés dos sacerdotes que levam a arca do SENHOR Dominador de toda a terra, forem assentadas sobre as águas do Jordão, as águas do Jordão se partirão: porque as águas que vem de acima se deterão em um amontoado."}, {"numero": 14, "texto": "E aconteceu que, partindo o povo de suas tendas para passar o Jordão, e os sacerdotes diante do povo levando a arca do pacto,"}, {"numero": 15, "texto": "Quando os que levavam a arca chegaram no Jordão, assim como os pés dos sacerdotes que levavam a arca foram molhados à beira da água, (porque o Jordão costuma transbordar sobre todas as suas margens todo aquele tempo da colheita,)"}, {"numero": 16, "texto": "As águas que vinham de cima pararam, e amontoaram-se bem longe, na cidade de Adã, que está ao lado de Zaretã; e as que desciam ao mar das planícies, ao mar Salgado, esgotaram-se e foram totalmente interrompidas; e o povo passou em frente de Jericó."}, {"numero": 17, "texto": "Mas os sacerdotes que levavam a arca do pacto do SENHOR, ficaram firmes em seco, no meio do Jordão, e todo Israel passou em seco, até que todo o povo acabou de passar o Jordão."}]'::jsonb, 'Almeida Livre'),
  ('Js', 3, 'en', '[{"numero": 1, "texto": "And Joshua rose early in the morning; and they removed from Shittim, and came to Jordan, he and all the children of Israel, and lodged there before they passed over."}, {"numero": 2, "texto": "And it came to pass after three days, that the officers went through the host;"}, {"numero": 3, "texto": "And they commanded the people, saying, When ye see the ark of the covenant of the Lord your God, and the priests the Levites bearing it, then ye shall remove from your place, and go after it."}, {"numero": 4, "texto": "Yet there shall be a space between you and it, about two thousand cubits by measure: come not near unto it, that ye may know the way by which ye must go: for ye have not passed this way heretofore."}, {"numero": 5, "texto": "And Joshua said unto the people, Sanctify yourselves: for to morrow the Lord will do wonders among you."}, {"numero": 6, "texto": "And Joshua spake unto the priests, saying, Take up the ark of the covenant, and pass over before the people. And they took up the ark of the covenant, and went before the people."}, {"numero": 7, "texto": "And the Lord said unto Joshua, This day will I begin to magnify thee in the sight of all Israel, that they may know that, as I was with Moses, so I will be with thee."}, {"numero": 8, "texto": "And thou shalt command the priests that bear the ark of the covenant, saying, When ye are come to the brink of the water of Jordan, ye shall stand still in Jordan."}, {"numero": 9, "texto": "And Joshua said unto the children of Israel, Come hither, and hear the words of the Lord your God."}, {"numero": 10, "texto": "And Joshua said, Hereby ye shall know that the living God is among you, and that he will without fail drive out from before you the Canaanites, and the Hittites, and the Hivites, and the Perizzites, and the Girgashites, and the Amorites, and the Jebusites."}, {"numero": 11, "texto": "Behold, the ark of the covenant of the Lord of all the earth passeth over before you into Jordan."}, {"numero": 12, "texto": "Now therefore take you twelve men out of the tribes of Israel, out of every tribe a man."}, {"numero": 13, "texto": "And it shall come to pass, as soon as the soles of the feet of the priests that bear the ark of the Lord, the Lord of all the earth, shall rest in the waters of Jordan, that the waters of Jordan shall be cut off from the waters that come down from above; and they shall stand upon an heap."}, {"numero": 14, "texto": "And it came to pass, when the people removed from their tents, to pass over Jordan, and the priests bearing the ark of the covenant before the people;"}, {"numero": 15, "texto": "And as they that bare the ark were come unto Jordan, and the feet of the priests that bare the ark were dipped in the brim of the water, (for Jordan overfloweth all his banks all the time of harvest,)"}, {"numero": 16, "texto": "That the waters which came down from above stood and rose up upon an heap very far from the city Adam, that is beside Zaretan: and those that came down toward the sea of the plain, even the salt sea, failed, and were cut off: and the people passed over right against Jericho."}, {"numero": 17, "texto": "And the priests that bare the ark of the covenant of the Lord stood firm on dry ground in the midst of Jordan, and all the Israelites passed over on dry ground, until all the people were passed clean over Jordan."}]'::jsonb, 'King James Version'),
  ('Js', 3, 'fr', '[{"numero": 1, "texto": "Josué, s''''étant levé de bon matin, partit de Sittim avec tous les enfants d''''Israël. Ils arrivèrent au Jourdain; et là, ils passèrent la nuit, avant de le traverser."}, {"numero": 2, "texto": "Au bout de trois jours, les officiers parcoururent le camp,"}, {"numero": 3, "texto": "et donnèrent cet ordre au peuple: Lorsque vous verrez l''''arche de l''''alliance de l''''Eternel, votre Dieu, portée par les sacrificateurs, les Lévites, vous partirez du lieu où vous êtes, et vous vous mettrez en marche après elle."}, {"numero": 4, "texto": "Mais il y aura entre vous et elle une distance d''''environ deux mille coudées: n''''en approchez pas. Elle vous montrera le chemin que vous devez suivre, car vous n''''avez point encore passé par ce chemin."}, {"numero": 5, "texto": "Josué dit au peuple: Sanctifiez-vous, car demain l''''Eternel fera des prodiges au milieu de vous."}, {"numero": 6, "texto": "Et Josué dit aux sacrificateurs: Portez l''''arche de l''''alliance, et passez devant le peuple. Ils portèrent l''''arche de l''''alliance, et ils marchèrent devant le peuple."}, {"numero": 7, "texto": "L''''Eternel dit à Josué: Aujourd''''hui, je commencerai à t''''élever aux yeux de tout Israël, afin qu''''ils sachent que je serai avec toi comme j''''ai été avec Moïse."}, {"numero": 8, "texto": "Tu donneras cet ordre aux sacrificateurs qui portent l''''arche de l''''alliance: Lorsque vous arriverez au bord des eaux du Jourdain, vous vous arrêterez dans le Jourdain."}, {"numero": 9, "texto": "Josué dit aux enfants d''''Israël: Approchez, et écoutez les paroles de l''''Eternel, votre Dieu."}, {"numero": 10, "texto": "Josué dit: A ceci vous reconnaîtrez que le Dieu vivant est au milieu de vous, et qu''''il chassera devant vous les Cananéens, les Héthiens, les Héviens, les Phéréziens, les Guirgasiens, les Amoréens et les Jébusiens:"}, {"numero": 11, "texto": "voici, l''''arche de l''''alliance du Seigneur de toute la terre va passer devant vous dans le Jourdain."}, {"numero": 12, "texto": "Maintenant, prenez douze hommes parmi les tribus d''''Israël, un homme de chaque tribu."}, {"numero": 13, "texto": "Et dès que les sacrificateurs qui portent l''''arche de l''''Eternel, le Seigneur de toute la terre, poseront la plante des pieds dans les eaux du Jourdain, les eaux du Jourdain seront coupées, les eaux qui descendent d''''en haut, et elles s''''arrêteront en un monceau."}, {"numero": 14, "texto": "Le peuple sortit de ses tentes pour passer le Jourdain, et les sacrificateurs qui portaient l''''arche de l''''alliance marchèrent devant le peuple."}, {"numero": 15, "texto": "Quand les sacrificateurs qui portaient l''''arche furent arrivés au Jourdain, et que leurs pieds se furent mouillés au bord de l''''eau, -le Jourdain regorge par-dessus toutes ses rives tout le temps de la moisson,"}, {"numero": 16, "texto": "les eaux qui descendent d''''en haut s''''arrêtèrent, et s''''élevèrent en un monceau, à une très grande distance, près de la ville d''''Adam, qui est à côté de Tsarthan; et celles qui descendaient vers la mer de la plaine, la mer Salée, furent complètement coupées. Le peuple passa vis-à-vis de Jéricho."}, {"numero": 17, "texto": "Les sacrificateurs qui portaient l''''arche de l''''alliance de l''''Eternel s''''arrêtèrent de pied ferme sur le sec, au milieu du Jourdain, pendant que tout Israël passait à sec, jusqu''''à ce que toute la nation eût achevé de passer le Jourdain."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 3, 'es', '[{"numero": 1, "texto": "Y LEVANTÓSE Josué de mañana, y partieron de Sittim, y vinieron hasta el Jordán, él y todos los hijos de Israel, y reposaron allí antes que pasasen."}, {"numero": 2, "texto": "Y pasados tres días, los oficiales atravesaron por medio del campo,"}, {"numero": 3, "texto": "Y mandaron al pueblo, diciendo: Cuando viereis el arca del pacto de Jehová vuestro Dios, y los sacerdotes y Levitas que la llevan, vosotros partiréis de vuestro lugar, y marcharéis en pos de ella."}, {"numero": 4, "texto": "Empero entre vosotros y ella haya distancia como de la medida de dos mil codos: y no os acercaréis á ella, á fin de que sepáis el camino por donde habéis de ir: por cuanto vosotros no habéis pasado antes de ahora por este camino."}, {"numero": 5, "texto": "Y Josué dijo al pueblo: Santificaos, porque Jehová hará mañana entre vosotros maravillas."}, {"numero": 6, "texto": "Y habló Josué á los sacerdotes, diciendo: Tomad el arca del pacto, y pasad delante del pueblo. Y ellos tomaron el arca del pacto, y fueron delante del pueblo."}, {"numero": 7, "texto": "Entonces Jehová dijo á Josué: Desde aqueste día comenzaré á hacerte grande delante de los ojos de todo Israel, para que entiendan que como fuí con Moisés, así seré contigo."}, {"numero": 8, "texto": "Tú, pues, mandarás á los sacerdotes que llevan el arca del pacto, diciendo: Cuando hubiereis entrado hasta el borde del agua del Jordán, pararéis en el Jordán."}, {"numero": 9, "texto": "Y Josué dijo á los hijos de Israel: Llegaos acá, y escuchad las palabras de Jehová vuestro Dios."}, {"numero": 10, "texto": "Y añadió Josué: En esto conoceréis que el Dios viviente está en medio de vosotros, y que él echará de delante de vosotros al Cananeo, y al Heteo, y al Heveo, y al Pherezeo, y al Gergeseo, y al Amorrheo, y al Jebuseo."}, {"numero": 11, "texto": "He aquí, el arca del pacto del Señoreador de toda la tierra pasa el Jordán delante de vosotros."}, {"numero": 12, "texto": "Tomad, pues, ahora doce hombres de las tribus de Israel, de cada tribu uno."}, {"numero": 13, "texto": "Y cuando las plantas de los pies de los sacerdotes que llevan el arca de Jehová Señoreador de toda la tierra, fueren asentadas sobre las aguas del Jordán, las aguas del Jordán se partirán: porque las aguas que vienen de arriba se detendrán en un montón."}, {"numero": 14, "texto": "Y aconteció, que partiendo el pueblo de sus tiendas para pasar el Jordán, y los sacerdotes delante del pueblo llevando el arca del pacto,"}, {"numero": 15, "texto": "Cuando los que llevaban el arca entraron en el Jordán, así como los pies de los sacerdotes que llevaban el arca fueron mojados á la orilla del agua, (porque el Jordán suele reverter sobre todos sus bordes todo el tiempo de la siega,)"}, {"numero": 16, "texto": "Las aguas que venían de arriba, se pararon como en un montón bien lejos de la ciudad de Adam, que está al lado de Sarethan; y las que descendían á la mar de los llanos, al mar Salado, se acabaron y fueron partidas; y el pueblo pasó en derecho de Jericó."}, {"numero": 17, "texto": "Mas los sacerdotes que llevaban el arca del pacto de Jehová, estuvieron en seco, firmes en medio del Jordán, hasta que todo el pueblo hubo acabado de pasar el Jordán; y todo Israel pasó en seco."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 4, 'pt', '[{"numero": 1, "texto": "E quando toda a nação acabou de passar o Jordão, o SENHOR falou a Josué, dizendo:"}, {"numero": 2, "texto": "Tomai do povo doze homens, de cada tribo um,"}, {"numero": 3, "texto": "E mandai-lhes, dizendo: Tomai-vos daqui do meio do Jordão, do lugar de onde estão firmes os pés dos sacerdotes, doze pedras, as quais passareis convosco, e as assentareis no alojamento de onde haveis de passar a noite."}, {"numero": 4, "texto": "Então Josué chamou aos doze homens, os quais ele havia ordenado dentre os filhos de Israel, de cada tribo um;"}, {"numero": 5, "texto": "E disse-lhes Josué: Passai diante da arca do SENHOR vosso Deus ao meio do Jordão; e cada um de vós tome uma pedra sobre seu ombro, conforme ao número das tribos dos filhos de Israel;"}, {"numero": 6, "texto": "Para que isto seja sinal entre vós; e quando vossos filhos perguntarem a seus pais amanhã, dizendo: “Que vos significam estas pedras?”"}, {"numero": 7, "texto": "Então vós lhes respondereis: “As águas do Jordão foram interrompidas diante da arca do pacto do SENHOR; quando ela passou pelo Jordão, as águas do Jordão se separaram; e estas pedras serão por memorial aos filhos de Israel para sempre."}, {"numero": 8, "texto": "E os filhos de Israel o fizeram assim como Josué havia lhes mandado, e levantaram doze pedras do meio do Jordão, como o SENHOR havia dito a Josué, conforme o número das tribos dos filhos de Israel; e levaram-nas consigo ao alojamento, e ali as puseram."}, {"numero": 9, "texto": "Josué também levantou doze pedras no meio do Jordão, no lugar onde estiveram os pés dos sacerdotes que levavam a arca do pacto; e ali estão até hoje."}, {"numero": 10, "texto": "Pois os sacerdotes que levavam a arca ficaram parados no meio do Jordão, até que se cumpriu tudo o que o SENHOR havia mandado a Josué dizer ao povo, conforme tudo quanto Moisés havia ordenado a Josué; e o povo apressou-se e passou."}, {"numero": 11, "texto": "E sucedeu quando todo o povo acabou de passar, então passaram a arca do SENHOR, e os sacerdotes, na presença do povo."}, {"numero": 12, "texto": "Também os filhos de Rúben, os filhos de Gade, e a meia tribo de Manassés, passaram armados diante dos filhos de Israel, como Moisés havia lhes dito;"}, {"numero": 13, "texto": "cerca de quarenta mil homens prontamente armados passaram ó diante do SENHOR para a batalha, às campina de Jericó."}, {"numero": 14, "texto": "Naquele dia o SENHOR engrandeceu Josué à vista de todo Israel; e temeram-no, como haviam temido a Moisés, todos os dias de sua vida."}, {"numero": 15, "texto": "E o SENHOR falou a Josué, dizendo:"}, {"numero": 16, "texto": "“Manda os sacerdotes que levam a arca do testemunho, que subam do Jordão”."}, {"numero": 17, "texto": "E Josué mandou os sacerdotes, dizendo: “Subi do Jordão”."}, {"numero": 18, "texto": "E aconteceu que quando os sacerdotes que levavam a arca do pacto do SENHOR subiram do meio do Jordão, e as plantas dos pés dos sacerdotes estiveram em seco, as águas do Jordão voltaram ao seu lugar, correndo como antes sobre todas as suas margens."}, {"numero": 19, "texto": "E o povo subiu do Jordão no dia dez do mês primeiro, e assentaram o acampamento em Gilgal, ao lado oriental de Jericó."}, {"numero": 20, "texto": "E Josué erigiu em Gilgal as doze pedras que haviam trazido do Jordão."}, {"numero": 21, "texto": "E falou aos filhos de Israel, dizendo: Quando amanhã perguntarem vossos filhos a seus pais, e disserem: Que vos significam estas pedras?"}, {"numero": 22, "texto": "Declarareis a vossos filhos, dizendo: Israel passou em seco por este Jordão."}, {"numero": 23, "texto": "Porque o SENHOR vosso Deus secou as águas do Jordão diante de vós, até que havíeis passado, à maneira que o SENHOR vosso Deus o havia feito no mar Vermelho, ao qual secou diante de nós até que passamos:"}, {"numero": 24, "texto": "Para que todos os povos da terra conheçam a mão do SENHOR, que é forte; para que temais ao SENHOR vosso Deus todos os dias."}]'::jsonb, 'Almeida Livre'),
  ('Js', 4, 'en', '[{"numero": 1, "texto": "And it came to pass, when all the people were clean passed over Jordan, that the Lord spake unto Joshua, saying,"}, {"numero": 2, "texto": "Take you twelve men out of the people, out of every tribe a man,"}, {"numero": 3, "texto": "And command ye them, saying, Take you hence out of the midst of Jordan, out of the place where the priests'' feet stood firm, twelve stones, and ye shall carry them over with you, and leave them in the lodging place, where ye shall lodge this night."}, {"numero": 4, "texto": "Then Joshua called the twelve men, whom he had prepared of the children of Israel, out of every tribe a man:"}, {"numero": 5, "texto": "And Joshua said unto them, Pass over before the ark of the Lord your God into the midst of Jordan, and take you up every man of you a stone upon his shoulder, according unto the number of the tribes of the children of Israel:"}, {"numero": 6, "texto": "That this may be a sign among you, that when your children ask their fathers in time to come, saying, What mean ye by these stones?"}, {"numero": 7, "texto": "Then ye shall answer them, That the waters of Jordan were cut off before the ark of the covenant of the Lord; when it passed over Jordan, the waters of Jordan were cut off: and these stones shall be for a memorial unto the children of Israel for ever."}, {"numero": 8, "texto": "And the children of Israel did so as Joshua commanded, and took up twelve stones out of the midst of Jordan, as the Lord spake unto Joshua, according to the number of the tribes of the children of Israel, and carried them over with them unto the place where they lodged, and laid them down there."}, {"numero": 9, "texto": "And Joshua set up twelve stones in the midst of Jordan, in the place where the feet of the priests which bare the ark of the covenant stood: and they are there unto this day."}, {"numero": 10, "texto": "For the priests which bare the ark stood in the midst of Jordan, until everything was finished that the Lord commanded Joshua to speak unto the people, according to all that Moses commanded Joshua: and the people hasted and passed over."}, {"numero": 11, "texto": "And it came to pass, when all the people were clean passed over, that the ark of the Lord passed over, and the priests, in the presence of the people."}, {"numero": 12, "texto": "And the children of Reuben, and the children of Gad, and half the tribe of Manasseh, passed over armed before the children of Israel, as Moses spake unto them:"}, {"numero": 13, "texto": "About forty thousand prepared for war passed over before the Lord unto battle, to the plains of Jericho."}, {"numero": 14, "texto": "On that day the Lord magnified Joshua in the sight of all Israel; and they feared him, as they feared Moses, all the days of his life."}, {"numero": 15, "texto": "And the Lord spake unto Joshua, saying,"}, {"numero": 16, "texto": "Command the priests that bear the ark of the testimony, that they come up out of Jordan."}, {"numero": 17, "texto": "Joshua therefore commanded the priests, saying, Come ye up out of Jordan."}, {"numero": 18, "texto": "And it came to pass, when the priests that bare the ark of the covenant of the Lord were come up out of the midst of Jordan, and the soles of the priests'' feet were lifted up unto the dry land, that the waters of Jordan returned unto their place, and flowed over all his banks, as they did before."}, {"numero": 19, "texto": "And the people came up out of Jordan on the tenth day of the first month, and encamped in Gilgal, in the east border of Jericho."}, {"numero": 20, "texto": "And those twelve stones, which they took out of Jordan, did Joshua pitch in Gilgal."}, {"numero": 21, "texto": "And he spake unto the children of Israel, saying, When your children shall ask their fathers in time to come, saying, What mean these stones?"}, {"numero": 22, "texto": "Then ye shall let your children know, saying, Israel came over this Jordan on dry land."}, {"numero": 23, "texto": "For the Lord your God dried up the waters of Jordan from before you, until ye were passed over, as the Lord your God did to the Red sea, which he dried up from before us, until we were gone over:"}, {"numero": 24, "texto": "That all the people of the earth might know the hand of the Lord, that it is mighty: that ye might fear the Lord your God for ever."}]'::jsonb, 'King James Version'),
  ('Js', 4, 'fr', '[{"numero": 1, "texto": "Lorsque toute la nation eut achevé de passer le Jourdain, l''''Eternel dit à Josué:"}, {"numero": 2, "texto": "Prenez douze hommes parmi le peuple, un homme de chaque tribu."}, {"numero": 3, "texto": "Donnez-leur cet ordre: Enlevez d''''ici, du milieu du Jourdain, de la place où les sacrificateurs se sont arrêtés de pied ferme, douze pierres, que vous emporterez avec vous, et que vous déposerez dans le lieu où vous passerez cette nuit."}, {"numero": 4, "texto": "Josué appela les douze hommes qu''''il choisit parmi les enfants d''''Israël, un homme de chaque tribu."}, {"numero": 5, "texto": "Il leur dit: Passez devant l''''arche de l''''Eternel, votre Dieu, au milieu du Jourdain, et que chacun de vous charge une pierre sur son épaule, selon le nombre des tribus des enfants d''''Israël,"}, {"numero": 6, "texto": "afin que cela soit un signe au milieu de vous. Lorsque vos enfants demanderont un jour: Que signifient pour vous ces pierres?"}, {"numero": 7, "texto": "vous leur direz: Les eaux du Jourdain ont été coupées devant l''''arche de l''''alliance de l''''Eternel; lorsqu''''elle passa le Jourdain, les eaux du Jourdain ont été coupées, et ces pierres seront à jamais un souvenir pour les enfants d''''Israël."}, {"numero": 8, "texto": "Les enfants d''''Israël firent ce que Josué leur avait ordonné. Ils enlevèrent douze pierres du milieu du Jourdain, comme l''''Eternel l''''avait dit à Josué, selon le nombre des tribus des enfants d''''Israël, ils les emportèrent avec eux, et les déposèrent dans le lieu où ils devaient passer la nuit."}, {"numero": 9, "texto": "Josué dressa aussi douze pierres au milieu du Jourdain, à la place où s''''étaient arrêtés les pieds des sacrificateurs qui portaient l''''arche de l''''alliance; et elles y sont restées jusqu''''à ce jour."}, {"numero": 10, "texto": "Les sacrificateurs qui portaient l''''arche se tinrent au milieu du Jourdain jusqu''''à l''''entière exécution de ce que l''''Eternel avait ordonné à Josué de dire au peuple, selon tout ce que Moïse avait prescrit à Josué. Et le peuple se hâta de passer."}, {"numero": 11, "texto": "Lorsque tout le peuple eut achevé de passer, l''''arche de l''''Eternel et les sacrificateurs passèrent devant le peuple."}, {"numero": 12, "texto": "Les fils de Ruben, les fils de Gad, et la demi-tribu de Manassé, passèrent en armes devant les enfants d''''Israël, comme Moïse le leur avait dit."}, {"numero": 13, "texto": "Environ quarante mille hommes, équipés pour la guerre et prêts à combattre, passèrent devant l''''Eternel dans les plaines de Jéricho."}, {"numero": 14, "texto": "En ce jour-là, l''''Eternel éleva Josué aux yeux de tout Israël; et ils le craignirent, comme ils avaient craint Moïse, tous les jours de sa vie."}, {"numero": 15, "texto": "L''''Eternel dit à Josué:"}, {"numero": 16, "texto": "Ordonne aux sacrificateurs qui portent l''''arche du témoignage de sortir du Jourdain."}, {"numero": 17, "texto": "Et Josué donna cet ordre aux sacrificateurs: Sortez du Jourdain."}, {"numero": 18, "texto": "Lorsque les sacrificateurs qui portaient l''''arche de l''''alliance de l''''Eternel furent sortis du milieu du Jourdain, et que la plante de leurs pieds se posa sur le sec, les eaux du Jourdain retournèrent à leur place, et se répandirent comme auparavant sur tous ses bords."}, {"numero": 19, "texto": "Le peuple sortit du Jourdain le dixième jour du premier mois, et il campa à Guilgal, à l''''extrémité orientale de Jéricho."}, {"numero": 20, "texto": "Josué dressa à Guilgal les douze pierres qu''''ils avaient prises du Jourdain."}, {"numero": 21, "texto": "Il dit aux enfants d''''Israël: Lorsque vos enfants demanderont un jour à leurs pères: Que signifient ces pierres?"}, {"numero": 22, "texto": "vous en instruirez vos enfants, et vous direz: Israël a passé ce Jourdain à sec."}, {"numero": 23, "texto": "Car l''''Eternel, votre Dieu, a mis à sec devant vous les eaux du Jourdain jusqu''''à ce que vous eussiez passé, comme l''''Eternel, votre Dieu, l''''avait fait à la mer Rouge, qu''''il mit à sec devant nous jusqu''''à ce que nous eussions passé,"}, {"numero": 24, "texto": "afin que tous les peuples de la terre sachent que la main de l''''Eternel est puissante, et afin que vous ayez toujours la crainte de l''''Eternel, votre Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 4, 'es', '[{"numero": 1, "texto": "Y CUANDO toda la gente hubo acabado de pasar el Jordán, Jehová habló á Josué, diciendo:"}, {"numero": 2, "texto": "Tomad del pueblo doce hombres, de cada tribu uno,"}, {"numero": 3, "texto": "Y mandadles, diciendo: Tomaos de aquí del medio del Jordán, del lugar donde están firmes los pies de los sacerdotes, doce piedras, las cuales pasaréis con vosotros, y las asentaréis en el alojamiento donde habéis de tener la noche."}, {"numero": 4, "texto": "Entonces Josué llamó á los doce hombres, los cuales había él ordenado de entre los hijos de Israel, de cada tribu uno;"}, {"numero": 5, "texto": "Y díjoles Josué: Pasad delante del arca de Jehová vuestro Dios al medio del Jordán; y cada uno de vosotros tome una piedra sobre su hombro, conforme al número de las tribus de los hijos de Israel;"}, {"numero": 6, "texto": "Para que esto sea señal entre vosotros; y cuando vuestros hijos preguntaren á sus padres mañana, diciendo: ¿Qué os significan estas piedras?"}, {"numero": 7, "texto": "Les responderéis: Que las aguas del Jordán fueron partidas delante del arca del pacto de Jehová; cuando ella pasó el Jordán, las aguas del Jordán se partieron: y estas piedras serán por memoria á los hijos de Israel para siempre."}, {"numero": 8, "texto": "Y los hijos de Israel lo hicieron así como Josué les mandó: que levantaron doce piedras del medio del Jordán, como Jehová lo había dicho á Josué, conforme al número de las tribus de los hijos de Israel, y pasáronlas consigo al alojamiento, y las asentaron allí."}, {"numero": 9, "texto": "Josué también levantó doce piedras en medio del Jordán, en el lugar donde estuvieron los pies de los sacerdotes que llevaban el arca del pacto; y han estado allí hasta hoy."}, {"numero": 10, "texto": "Y los sacerdotes que llevaban el arca se pararon en medio del Jordán, hasta tanto que se acabó todo lo que Jehová había mandado á Josué que hablase al pueblo, conforme á todas las cosas que Moisés había á Josué mandado: y el pueblo se dió priesa y pasó."}, {"numero": 11, "texto": "Y cuando todo el pueblo acabó de pasar, pasó también el arca de Jehová, y los sacerdotes, en presencia del pueblo."}, {"numero": 12, "texto": "También los hijos de Rubén y los hijos de Gad, y la media tribu de Manasés, pasaron armados delante de los hijos de Israel, según Moisés les había dicho:"}, {"numero": 13, "texto": "Como cuarenta mil hombres armados á punto pasaron hacia la campiña de Jericó delante de Jehová á la guerra."}, {"numero": 14, "texto": "En aquel día Jehová engrandeció á Josué en ojos de todo Israel: y temiéronle, como habían temido á Moisés, todos los días de su vida."}, {"numero": 15, "texto": "Y Jehová habló á Josué, diciendo:"}, {"numero": 16, "texto": "Manda á los sacerdotes que llevan el arca del testimonio, que suban del Jordán."}, {"numero": 17, "texto": "Y Josué mandó á los sacerdotes, diciendo: Subid del Jordán."}, {"numero": 18, "texto": "Y aconteció que como los sacerdotes que llevaban el arca del pacto de Jehová, subieron del medio del Jordán, y las plantas de los pies de los sacerdotes estuvieron en seco, las aguas del Jordán se volvieron á su lugar, corriendo como antes sobre todos sus bordes."}, {"numero": 19, "texto": "Y el pueblo subió del Jordán el diez del mes primero, y asentaron el campo en Gilgal, al lado oriental de Jericó."}, {"numero": 20, "texto": "Y Josué erigió en Gilgal las doce piedras que habían traído del Jordán."}, {"numero": 21, "texto": "Y habló á los hijos de Israel, diciendo: Cuando mañana preguntaren vuestros hijos á sus padres, y dijeren: ¿Qué os significan estas piedras?"}, {"numero": 22, "texto": "Declararéis á vuestros hijos, diciendo: Israel pasó en seco por este Jordán."}, {"numero": 23, "texto": "Porque Jehová vuestro Dios secó las aguas del Jordán delante de vosotros, hasta que habíais pasado, á la manera que Jehová vuestro Dios lo había hecho en el mar Bermejo, al cual secó delante de nosotros hasta que pasamos:"}, {"numero": 24, "texto": "Para que todos los pueblos de la tierra conozcan la mano de Jehová, que es fuerte; para que temáis á Jehová vuestro Dios todos los días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 5, 'pt', '[{"numero": 1, "texto": "E quando todos os reis dos amorreus, que estavam da outra parte do Jordão ao ocidente, e todos os reis dos cananeus, que estavam próximos do mar, ouviram como o SENHOR havia secado as águas do Jordão diante dos filhos de Israel até que passaram, desfaleceu seu coração, e não houve mais espírito neles diante dos filhos de Israel."}, {"numero": 2, "texto": "Naquele tempo o SENHOR disse a Josué: Faze-te facas afiadas, e volta a circuncidar a segunda vez aos filhos de Israel."}, {"numero": 3, "texto": "E Josué se fez facas afiadas, e circuncidou aos filhos de Israel no monte dos prepúcios."}, {"numero": 4, "texto": "Esta é a causa pela qual Josué os circuncidou: todo aquele povo que havia saído do Egito, os homens, todos os homens de guerra, haviam morrido no deserto pelo caminho, depois que saíram do Egito."}, {"numero": 5, "texto": "Porque todos os do povo que haviam saído, estavam circuncidados: mas todo aquele povo que havia nascido no deserto pelo caminho, depois que saíram do Egito, não estavam circuncidados."}, {"numero": 6, "texto": "Porque os filhos de Israel andaram pelo deserto por quarenta anos, até que toda a gente dos homens de guerra que haviam saído do Egito foi consumida, porquanto não obedeceram à voz do SENHOR; pelo qual o SENHOR lhes jurou que não lhes deixaria ver a terra, da qual o SENHOR havia jurado a seus pais que não as daria, terra que flui leite e mel."}, {"numero": 7, "texto": "E os filhos deles, que ele havia feito suceder em seu lugar, Josué os circuncidou; pois eram incircuncisos, porque não haviam sido circuncidados pelo caminho."}, {"numero": 8, "texto": "E quando acabaram de circuncidar toda a gente, ficaram no mesmo lugar no acampamento, até que sararam."}, {"numero": 9, "texto": "E o SENHOR disse a Josué: Hoje tirei de vós a humilhação do Egito: pelo qual o nome daquele lugar foi chamado Gilgal, até hoje."}, {"numero": 10, "texto": "E os filhos de Israel assentaram o acampamento em Gilgal, e celebraram a páscoa aos catorze dias do mês, pela tarde, nas planícies de Jericó."}, {"numero": 11, "texto": "E ao outro dia da páscoa comeram do fruto da terra os pães sem levedura, e no mesmo dia espigas novas tostadas."}, {"numero": 12, "texto": "E o maná cessou o dia seguinte, desde que começaram a comer do fruto da terra: e os filhos de Israel nunca mais tiveram maná, mas sim que comeram dos frutos da terra de Canaã aquele ano."}, {"numero": 13, "texto": "E estando Josué próximo de Jericó, levantou seus olhos, e viu um homem que estava diante dele, o qual tinha uma espada nua em sua mão. E Josué indo até ele, lhe disse: És dos nossos, ou de nossos inimigos?"}, {"numero": 14, "texto": "E ele respondeu: Não; mas sim Príncipe do exército do SENHOR, agora vim. Então Josué prostrando-se sobre seu rosto em terra o adorou; e disse-lhe: Que diz meu Senhor a seu servo?"}, {"numero": 15, "texto": "E o Príncipe do exército do SENHOR respondeu a Josué: Tira teus sapatos de teus pés; porque o lugar onde estás é santo. E Josué o fez assim."}]'::jsonb, 'Almeida Livre'),
  ('Js', 5, 'en', '[{"numero": 1, "texto": "And it came to pass, when all the kings of the Amorites, which were on the side of Jordan westward, and all the kings of the Canaanites, which were by the sea, heard that the Lord had dried up the waters of Jordan from before the children of Israel, until we were passed over, that their heart melted, neither was there spirit in them any more, because of the children of Israel."}, {"numero": 2, "texto": "At that time the Lord said unto Joshua, Make thee sharp knives, and circumcise again the children of Israel the second time."}, {"numero": 3, "texto": "And Joshua made him sharp knives, and circumcised the children of Israel at the hill of the foreskins."}, {"numero": 4, "texto": "And this is the cause why Joshua did circumcise: All the people that came out of Egypt, that were males, even all the men of war, died in the wilderness by the way, after they came out of Egypt."}, {"numero": 5, "texto": "Now all the people that came out were circumcised: but all the people that were born in the wilderness by the way as they came forth out of Egypt, them they had not circumcised."}, {"numero": 6, "texto": "For the children of Israel walked forty years in the wilderness, till all the people that were men of war, which came out of Egypt, were consumed, because they obeyed not the voice of the Lord: unto whom the Lord sware that he would not shew them the land, which the Lord sware unto their fathers that he would give us, a land that floweth with milk and honey."}, {"numero": 7, "texto": "And their children, whom he raised up in their stead, them Joshua circumcised: for they were uncircumcised, because they had not circumcised them by the way."}, {"numero": 8, "texto": "And it came to pass, when they had done circumcising all the people, that they abode in their places in the camp, till they were whole."}, {"numero": 9, "texto": "And the Lord said unto Joshua, This day have I rolled away the reproach of Egypt from off you. Wherefore the name of the place is called Gilgal unto this day."}, {"numero": 10, "texto": "And the children of Israel encamped in Gilgal, and kept the passover on the fourteenth day of the month at even in the plains of Jericho."}, {"numero": 11, "texto": "And they did eat of the old corn of the land on the morrow after the passover, unleavened cakes, and parched corn in the selfsame day."}, {"numero": 12, "texto": "And the manna ceased on the morrow after they had eaten of the old corn of the land; neither had the children of Israel manna any more; but they did eat of the fruit of the land of Canaan that year."}, {"numero": 13, "texto": "And it came to pass, when Joshua was by Jericho, that he lifted up his eyes and looked, and, behold, there stood a man over against him with his sword drawn in his hand: and Joshua went unto him, and said unto him, Art thou for us, or for our adversaries?"}, {"numero": 14, "texto": "And he said, Nay; but as captain of the host of the Lord am I now come. And Joshua fell on his face to the earth, and did worship, and said unto him, What saith my Lord unto his servant?"}, {"numero": 15, "texto": "And the captain of the Lord''s host said unto Joshua, Loose thy shoe from off thy foot; for the place whereon thou standest is holy. And Joshua did so."}]'::jsonb, 'King James Version'),
  ('Js', 5, 'fr', '[{"numero": 1, "texto": "Lorsque tous les rois des Amoréens à l''''occident du Jourdain et tous les rois des Cananéens près de la mer apprirent que l''''Eternel avait mis à sec les eaux du Jourdain devant les enfants d''''Israël jusqu''''à ce que nous eussions passé, ils perdirent courage et furent consternés à l''''aspect des enfants d''''Israël."}, {"numero": 2, "texto": "En ce temps-là, l''''Eternel dit à Josué: Fais-toi des couteaux de pierre, et circoncis de nouveau les enfants d''''Israël, une seconde fois."}, {"numero": 3, "texto": "Josué se fit des couteaux de pierre, et il circoncit les enfants d''''Israël sur la colline d''''Araloth."}, {"numero": 4, "texto": "Voici la raison pour laquelle Josué les circoncit. Tout le peuple sorti d''''Egypte, les mâles, tous les hommes de guerre, étaient morts dans le désert, pendant la route, après leur sortie d''''Egypte."}, {"numero": 5, "texto": "Tout ce peuple sorti d''''Egypte était circoncis; mais tout le peuple né dans le désert, pendant la route, après la sortie d''''Egypte, n''''avait point été circoncis."}, {"numero": 6, "texto": "Car les enfants d''''Israël avaient marché quarante ans dans le désert jusqu''''à la destruction de toute la nation des hommes de guerre qui étaient sortis d''''Egypte et qui n''''avaient point écouté la voix de l''''Eternel; l''''Eternel leur jura de ne pas leur faire voir le pays qu''''il avait juré à leurs pères de nous donner, pays où coulent le lait et le miel."}, {"numero": 7, "texto": "Ce sont leurs enfants qu''''il établit à leur place; et Josué les circoncit, car ils étaient incirconcis, parce qu''''on ne les avait point circoncis pendant la route."}, {"numero": 8, "texto": "Lorsqu''''on eut achevé de circoncire toute la nation, ils restèrent à leur place dans le camp jusqu''''à leur guérison."}, {"numero": 9, "texto": "L''''Eternel dit à Josué: Aujourd''''hui, j''''ai roulé de dessus vous l''''opprobre de l''''Egypte. Et ce lieu fut appelé du nom de Guilgal jusqu''''à ce jour."}, {"numero": 10, "texto": "Les enfants d''''Israël campèrent à Guilgal; et ils célébrèrent la Pâque le quatorzième jour du mois, sur le soir, dans les plaines de Jéricho."}, {"numero": 11, "texto": "Ils mangèrent du blé du pays le lendemain de la Pâque, des pains sans levain et du grain rôti; ils en mangèrent ce même jour."}, {"numero": 12, "texto": "La manne cessa le lendemain de la Pâque, quand ils mangèrent du blé du pays; les enfants d''''Israël n''''eurent plus de manne, et ils mangèrent des produits du pays de Canaan cette année-là."}, {"numero": 13, "texto": "Comme Josué était près de Jéricho, il leva les yeux, et regarda. Voici, un homme se tenait debout devant lui, son épée nue dans la main. Il alla vers lui, et lui dit: Es-tu des nôtres ou de nos ennemis?"}, {"numero": 14, "texto": "Il répondit: Non, mais je suis le chef de l''''armée de l''''Eternel, j''''arrive maintenant. Josué tomba le visage contre terre, se prosterna, et lui dit: Qu''''est-ce que mon seigneur dit à son serviteur?"}, {"numero": 15, "texto": "Et le chef de l''''armée de l''''Eternel dit à Josué: Ote tes souliers de tes pieds, car le lieu sur lequel tu te tiens est saint. Et Josué fit ainsi."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 5, 'es', '[{"numero": 1, "texto": "Y CUANDO todos los reyes de los Amorrheos, que estaban de la otra parte del Jordán al occidente, y todos los reyes de los Cananeos, que estaban cerca de la mar, oyeron como Jehová había secado las aguas del Jordán delante de los hijos de Israel hasta que hubieron pasado, desfalleció su corazón, y no hubo más espíritu en ellos delante de los hijos de Israel."}, {"numero": 2, "texto": "En aquel tiempo Jehová dijo á Josué: Hazte cuchillos afilados, y vuelve á circuncidar la segunda vez á los hijos de Israel."}, {"numero": 3, "texto": "Y Josué se hizo cuchillos afilados, y circuncidó á los hijos de Israel en el monte de los prepucios."}, {"numero": 4, "texto": "Esta es la causa por la cual Josué los circuncidó: todo el pueblo que había salido de Egipto, los varones, todos los hombres de guerra, habían muerto en el desierto por el camino, después que salieron de Egipto."}, {"numero": 5, "texto": "Porque todos los del pueblo que habían salido, estaban circuncidados: mas todo el pueblo que había nacido en el desierto por el camino, después que salieron de Egipto, no estaban circuncidados."}, {"numero": 6, "texto": "Porque los hijos de Israel anduvieron por el desierto cuarenta años, hasta que toda la gente de los hombres de guerra que habían salido de Egipto, fué consumida, por cuanto no obedecieron á la voz de Jehová; por lo cual Jehová les juró que no les dejaría ver la tierra, de la cual Jehová había jurado á sus padres que nos la daría, tierra que fluye leche y miel."}, {"numero": 7, "texto": "Y los hijos de ellos, que él había hecho suceder en su lugar, Josué los circuncidó; pues eran incircuncisos, porque no habían sido circuncidados por el camino."}, {"numero": 8, "texto": "Y cuando hubieron acabado de circuncidar toda la gente, quedáronse en el mismo lugar en el campo, hasta que sanaron."}, {"numero": 9, "texto": "Y Jehová dijo á Josué: Hoy he quitado de vosotros el oprobio de Egipto: por lo cual el nombre de aquel lugar fué llamado Gilgal, hasta hoy."}, {"numero": 10, "texto": "Y los hijos de Israel asentaron el campo en Gilgal, y celebraron la pascua á los catorce días del mes, por la tarde, en los llanos de Jericó."}, {"numero": 11, "texto": "Y al otro día de la pascua comieron del fruto de la tierra los panes sin levadura, y en el mismo día espigas nuevas tostadas."}, {"numero": 12, "texto": "Y el maná cesó el día siguiente, desde que comenzaron á comer del fruto de la tierra: y los hijos de Israel nunca más tuvieron maná, sino que comieron de los frutos de la tierra de Canaán aquel año."}, {"numero": 13, "texto": "Y estando Josué cerca de Jericó, alzó sus ojos, y vió un varón que estaba delante de él, el cual tenía una espada desnuda en su mano. Y Josué yéndose hacia él, le dijo: ¿Eres de los nuestros, ó de nuestros enemigos?"}, {"numero": 14, "texto": "Y él respondió: No; mas Príncipe del ejército de Jehová, ahora he venido. Entonces Josué postrándose sobre su rostro en tierra le adoró; y díjole: ¿Qué dice mi Señor á su siervo?"}, {"numero": 15, "texto": "Y el Príncipe del ejército de Jehová respondió á Josué: Quita tus zapatos de tus pies; porque el lugar donde estás es santo. Y Josué lo hizo así."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 6, 'pt', '[{"numero": 1, "texto": "Porém Jericó estava fechada, bem fechada, por causa dos filhos de Israel: ninguém entrava, nem saía."}, {"numero": 2, "texto": "Mas o SENHOR disse a Josué: Olha, eu entreguei em tua mão a Jericó e a seu rei, com seus homens de guerra."}, {"numero": 3, "texto": "Cercareis, pois, a cidade todos os homens de guerra, indo ao redor da cidade uma vez: e isto fareis seis dias."}, {"numero": 4, "texto": "E sete sacerdotes levarão sete trombetas de chifres de carneiros diante da arca; e ao sétimo dia dareis sete voltas à cidade, e os sacerdotes tocarão as trombetas."}, {"numero": 5, "texto": "E quando tocarem prolongadamente a trombeta de carneiro, assim que ouvirdes o som da trombeta, todo aquele povo gritará a grande voz, e o muro da cidade cairá debaixo de si: então o povo subirá cada um em frente de si."}, {"numero": 6, "texto": "E chamando Josué filho de Num aos sacerdotes, lhes disse: Levai a arca do pacto, e sete sacerdotes levem trombetas de chifres de carneiros diante da arca do SENHOR."}, {"numero": 7, "texto": "E disse ao povo: Passai, e rodeai a cidade; e os que estão armados passarão diante da arca do SENHOR."}, {"numero": 8, "texto": "E assim que Josué falou ao povo, os sete sacerdotes, levando as sete trombetas de chifres de carneiros, passaram diante da arca do SENHOR, e tocaram as trombetas: e a arca do pacto do SENHOR os seguia."}, {"numero": 9, "texto": "E os homens armados iam diante dos sacerdotes que tocavam as trombetas, e a gente reunida ia detrás da arca, andando e tocando trombetas."}, {"numero": 10, "texto": "E Josué mandou ao povo, dizendo: Vós não dareis grito, nem se ouvirá vossa voz, nem sairá palavra de vossa boca, até o dia que eu vos diga: Gritai: então dareis grito."}, {"numero": 11, "texto": "Então a arca do SENHOR deu uma volta ao redor da cidade, e vieram-se ao acampamento, no qual tiveram a noite."}, {"numero": 12, "texto": "E Josué se levantou de manhã, e os sacerdotes tomaram a arca do SENHOR."}, {"numero": 13, "texto": "E os sete sacerdotes, levando as sete trombetas de chifres de carneiros, foram diante da arca do SENHOR, andando sempre e tocando as trombetas; e os armados iam diante deles, e a gente reunida ia detrás da arca do SENHOR, andando e tocando l"}, {"numero": 14, "texto": "Assim deram outra volta à cidade o segundo dia, e voltaram ao acampamento: desta maneira fizeram por seis dias."}, {"numero": 15, "texto": "E ao sétimo dia levantaram-se quando subia a alva, e deram volta à cidade da mesma maneira sete vezes: somente este dia deram volta ao redor dela sete vezes."}, {"numero": 16, "texto": "E quando os sacerdotes tocaram as trombetas pela sétima vez, Josué disse ao povo: Dai grito, porque o SENHOR vos entregou a cidade."}, {"numero": 17, "texto": "Mas a cidade será anátema ao SENHOR, ela com todas as coisas que estão nela: somente Raabe a prostituta viverá, com todos os que estiverem em casa com ela, porquanto escondeu os mensageiros que enviamos."}, {"numero": 18, "texto": "Porém guardai-vos vós do anátema, que nem toqueis, nem tomeis alguma coisa do anátema, porque não façais anátema o acampamento de Israel, e o perturbeis."}, {"numero": 19, "texto": "Mas toda a prata, e o ouro, e vasos de bronze e de ferro, seja consagrado ao SENHOR, e venha ao tesouro do SENHOR."}, {"numero": 20, "texto": "Então o povo deu grito, e os sacerdotes tocaram as trombetas: e aconteceu que quando o povo ouviu o som da trombeta, deu o povo grito com grande barulho, e o muro caiu verticalmente. O povo subiu logo à cidade, cada um em frente de si, e tomaram-na."}, {"numero": 21, "texto": "E destruíram tudo o que na cidade havia; homens e mulheres, moços e anciãos, até os bois, e ovelhas, e asnos, a fio de espada."}, {"numero": 22, "texto": "Mas Josué disse aos dois homens que haviam reconhecido a terra: Entrai em casa da mulher prostituta, e fazei sair dali à mulher, e a tudo o que for seu, como o jurastes."}, {"numero": 23, "texto": "E os rapazes espias entraram, e tiraram a Raabe, e a seu pai, e a sua mãe, e a seus irmãos, e todo o que era seu; e também tiraram a toda sua parentela, e puseram-nos fora do acampamento de Israel."}, {"numero": 24, "texto": "E consumiram com fogo a cidade, e tudo o que nela havia: somente puseram no tesouro da casa do SENHOR a prata, e o ouro, e os vasos de bronze e de ferro."}, {"numero": 25, "texto": "Mas Josué salvou a vida a Raabe a prostituta, e à casa de seu pai, e a tudo o que ela tinha: e habitou ela entre os israelitas até hoje; porquanto escondeu os mensageiros que Josué enviou a reconhecer a Jericó."}, {"numero": 26, "texto": "E naquele tempo Josué lhes juramentou dizendo: Maldito diante do SENHOR o homem que se levantar e reedificar esta cidade de Jericó. Em seu primogênito lance seus alicerces, e em seu menor assente suas portas."}, {"numero": 27, "texto": "Foi, pois, o SENHOR com Josué, e seu nome se divulgou por toda a terra."}]'::jsonb, 'Almeida Livre'),
  ('Js', 6, 'en', '[{"numero": 1, "texto": "Now Jericho was straitly shut up because of the children of Israel: none went out, and none came in."}, {"numero": 2, "texto": "And the Lord said unto Joshua, See, I have given into thine hand Jericho, and the king thereof, and the mighty men of valour."}, {"numero": 3, "texto": "And ye shall compass the city, all ye men of war, and go round about the city once. Thus shalt thou do six days."}, {"numero": 4, "texto": "And seven priests shall bear before the ark seven trumpets of rams'' horns: and the seventh day ye shall compass the city seven times, and the priests shall blow with the trumpets."}, {"numero": 5, "texto": "And it shall come to pass, that when they make a long blast with the ram''s horn, and when ye hear the sound of the trumpet, all the people shall shout with a great shout; and the wall of the city shall fall down flat, and the people shall ascend up every man straight before him."}, {"numero": 6, "texto": "And Joshua the son of Nun called the priests, and said unto them, Take up the ark of the covenant, and let seven priests bear seven trumpets of rams'' horns before the ark of the Lord."}, {"numero": 7, "texto": "And he said unto the people, Pass on, and compass the city, and let him that is armed pass on before the ark of the Lord."}, {"numero": 8, "texto": "And it came to pass, when Joshua had spoken unto the people, that the seven priests bearing the seven trumpets of rams'' horns passed on before the Lord, and blew with the trumpets: and the ark of the covenant of the Lord followed them."}, {"numero": 9, "texto": "And the armed men went before the priests that blew with the trumpets, and the rereward came after the ark, the priests going on, and blowing with the trumpets."}, {"numero": 10, "texto": "And Joshua had commanded the people, saying, Ye shall not shout, nor make any noise with your voice, neither shall any word proceed out of your mouth, until the day I bid you shout; then shall ye shout."}, {"numero": 11, "texto": "So the ark of the Lord compassed the city, going about it once: and they came into the camp, and lodged in the camp."}, {"numero": 12, "texto": "And Joshua rose early in the morning, and the priests took up the ark of the Lord."}, {"numero": 13, "texto": "And seven priests bearing seven trumpets of rams'' horns before the ark of the Lord went on continually, and blew with the trumpets: and the armed men went before them; but the rereward came after the ark of the Lord, the priests going on, and blowing with the trumpets."}, {"numero": 14, "texto": "And the second day they compassed the city once, and returned into the camp: so they did six days."}, {"numero": 15, "texto": "And it came to pass on the seventh day, that they rose early about the dawning of the day, and compassed the city after the same manner seven times: only on that day they compassed the city seven times."}, {"numero": 16, "texto": "And it came to pass at the seventh time, when the priests blew with the trumpets, Joshua said unto the people, Shout; for the Lord hath given you the city."}, {"numero": 17, "texto": "And the city shall be accursed, even it, and all that are therein, to the Lord: only Rahab the harlot shall live, she and all that are with her in the house, because she hid the messengers that we sent."}, {"numero": 18, "texto": "And ye, in any wise keep yourselves from the accursed thing, lest ye make yourselves accursed, when ye take of the accursed thing, and make the camp of Israel a curse, and trouble it."}, {"numero": 19, "texto": "But all the silver, and gold, and vessels of brass and iron, are consecrated unto the Lord: they shall come into the treasury of the Lord."}, {"numero": 20, "texto": "So the people shouted when the priests blew with the trumpets: and it came to pass, when the people heard the sound of the trumpet, and the people shouted with a great shout, that the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city."}, {"numero": 21, "texto": "And they utterly destroyed all that was in the city, both man and woman, young and old, and ox, and sheep, and ass, with the edge of the sword."}, {"numero": 22, "texto": "But Joshua had said unto the two men that had spied out the country, Go into the harlot''s house, and bring out thence the woman, and all that she hath, as ye sware unto her."}, {"numero": 23, "texto": "And the young men that were spies went in, and brought out Rahab, and her father, and her mother, and her brethren, and all that she had; and they brought out all her kindred, and left them without the camp of Israel."}, {"numero": 24, "texto": "And they burnt the city with fire, and all that was therein: only the silver, and the gold, and the vessels of brass and of iron, they put into the treasury of the house of the Lord."}, {"numero": 25, "texto": "And Joshua saved Rahab the harlot alive, and her father''s household, and all that she had; and she dwelleth in Israel even unto this day; because she hid the messengers, which Joshua sent to spy out Jericho."}, {"numero": 26, "texto": "And Joshua adjured them at that time, saying, Cursed be the man before the Lord, that riseth up and buildeth this city Jericho: he shall lay the foundation thereof in his firstborn, and in his youngest son shall he set up the gates of it."}, {"numero": 27, "texto": "So the Lord was with Joshua; and his fame was noised throughout all the country."}]'::jsonb, 'King James Version'),
  ('Js', 6, 'fr', '[{"numero": 1, "texto": "Jéricho était fermée et barricadée devant les enfants d''''Israël. Personne ne sortait, et personne n''''entrait."}, {"numero": 2, "texto": "L''''Eternel dit à Josué: Vois, je livre entre tes mains Jéricho et son roi, ses vaillants soldats."}, {"numero": 3, "texto": "Faites le tour de la ville, vous tous les hommes de guerre, faites une fois le tour de la ville. Tu feras ainsi pendant six jours."}, {"numero": 4, "texto": "Sept sacrificateurs porteront devant l''''arche sept trompettes retentissantes; le septième jour, vous ferez sept fois le tour de la ville; et les sacrificateurs sonneront des trompettes."}, {"numero": 5, "texto": "Quand ils sonneront de la corne retentissante, quand vous entendrez le son de la trompette, tout le peuple poussera de grands cris. Alors la muraille de la ville s''''écroulera, et le peuple montera, chacun devant soi."}, {"numero": 6, "texto": "Josué, fils de Nun, appela les sacrificateurs, et leur dit: Portez l''''arche de l''''alliance, et que sept sacrificateurs portent sept trompettes retentissantes devant l''''arche de l''''Eternel."}, {"numero": 7, "texto": "Et il dit au peuple: Marchez, faites le tour de la ville, et que les hommes armés passent devant l''''arche de l''''Eternel."}, {"numero": 8, "texto": "Lorsque Josué eut parlé au peuple, les sept sacrificateurs qui portaient devant l''''Eternel les sept trompettes retentissantes se mirent en marche et sonnèrent des trompettes. L''''arche de l''''alliance de l''''Eternel allait derrière eux."}, {"numero": 9, "texto": "Les hommes armés marchaient devant les sacrificateurs qui sonnaient des trompettes, et l''''arrière-garde suivait l''''arche; pendant la marche, on sonnait des trompettes."}, {"numero": 10, "texto": "Josué avait donné cet ordre au peuple: Vous ne crierez point, vous ne ferez point entendre votre voix, et il ne sortira pas un mot de votre bouche jusqu''''au jour où je vous dirai: Poussez des cris! Alors vous pousserez des cris."}, {"numero": 11, "texto": "L''''arche de l''''Eternel fit le tour de la ville, elle fit une fois le tour; puis on rentra dans le camp, et l''''on y passa la nuit."}, {"numero": 12, "texto": "Josué se leva de bon matin, et les sacrificateurs portèrent l''''arche de l''''Eternel."}, {"numero": 13, "texto": "Les sept sacrificateurs qui portaient les sept trompettes retentissantes devant l''''arche de l''''Eternel se mirent en marche et sonnèrent des trompettes. Les hommes armés marchaient devant eux, et l''''arrière-garde suivait l''''arche de l''''Eternel; pendant la marche, on sonnait des trompettes."}, {"numero": 14, "texto": "Ils firent une fois le tour de la ville, le second jour; puis ils retournèrent dans le camp. Ils firent de même pendant six jours."}, {"numero": 15, "texto": "Le septième jour, ils se levèrent de bon matin, dès l''''aurore, et ils firent de la même manière sept fois le tour de la ville; ce fut le seul jour où ils firent sept fois le tour de la ville."}, {"numero": 16, "texto": "A la septième fois, comme les sacrificateurs sonnaient des trompettes, Josué dit au peuple: Poussez des cris, car l''''Eternel vous a livré la ville!"}, {"numero": 17, "texto": "La ville sera dévouée à l''''Eternel par interdit, elle et tout ce qui s''''y trouve; mais on laissera la vie à Rahab la prostituée et à tous ceux qui seront avec elle dans la maison, parce qu''''elle a caché les messagers que nous avions envoyés."}, {"numero": 18, "texto": "Gardez-vous seulement de ce qui sera dévoué par interdit; car si vous preniez de ce que vous aurez dévoué par interdit, vous mettriez le camp d''''Israël en interdit et vous y jetteriez le trouble."}, {"numero": 19, "texto": "Tout l''''argent et tout l''''or, tous les objets d''''airain et de fer, seront consacrés à l''''Eternel, et entreront dans le trésor de l''''Eternel."}, {"numero": 20, "texto": "Le peuple poussa des cris, et les sacrificateurs sonnèrent des trompettes. Lorsque le peuple entendit le son de la trompette, il poussa de grands cris, et la muraille s''''écroula; le peuple monta dans la ville, chacun devant soi. Ils s''''emparèrent de la ville,"}, {"numero": 21, "texto": "et ils dévouèrent par interdit, au fil de l''''épée, tout ce qui était dans la ville, hommes et femmes, enfants et vieillards, jusqu''''aux boeufs, aux brebis et aux ânes."}, {"numero": 22, "texto": "Josué dit aux deux hommes qui avaient exploré le pays: Entrez dans la maison de la femme prostituée, et faites-en sortir cette femme et tous ceux qui lui appartiennent, comme vous le lui avez juré."}, {"numero": 23, "texto": "Les jeunes gens, les espions, entrèrent et firent sortir Rahab, son père, sa mère, ses frères, et tous ceux qui lui appartenaient; ils firent sortir tous les gens de sa famille, et ils les déposèrent hors du camp d''''Israël."}, {"numero": 24, "texto": "Ils brûlèrent la ville et tout ce qui s''''y trouvait; seulement ils mirent dans le trésor de la maison de l''''Eternel l''''argent, l''''or et tous les objets d''''airain et de fer."}, {"numero": 25, "texto": "Josué laissa la vie à Rahab la prostituée, à la maison de son père, et à tous ceux qui lui appartenaient; elle a habité au milieu d''''Israël jusqu''''à ce jour, parce qu''''elle avait caché les messagers que Josué avait envoyés pour explorer Jéricho."}, {"numero": 26, "texto": "Ce fut alors que Josué jura, en disant: Maudit soit devant l''''Eternel l''''homme qui se lèvera pour rebâtir cette ville de Jéricho! Il en jettera les fondements au prix de son premier-né, et il en posera les portes au prix de son plus jeune fils."}, {"numero": 27, "texto": "L''''Eternel fut avec Josué, dont la renommée se répandit dans tout le pays."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 6, 'es', '[{"numero": 1, "texto": "EMPERO Jericó estaba cerrada, bien cerrada, á causa de los hijos de Israel: nadie entraba, ni salía."}, {"numero": 2, "texto": "Mas Jehová dijo á Josué: Mira, yo he entregado en tu mano á Jericó y á su rey, con sus varones de guerra."}, {"numero": 3, "texto": "Cercaréis pues la ciudad todos los hombres de guerra, yendo alrededor de la ciudad una vez: y esto haréis seis días."}, {"numero": 4, "texto": "Y siete sacerdotes llevarán siete bocinas de cuernos de carneros delante del arca; y al séptimo día daréis siete vueltas á la ciudad, y los sacerdotes tocarán las bocinas."}, {"numero": 5, "texto": "Y cuando tocaren prolongadamente el cuerno de carnero, así que oyereis el sonido de la bocina, todo el pueblo gritará á gran voz, y el muro de la ciudad caerá debajo de sí: entonces el pueblo subirá cada uno en derecho de sí."}, {"numero": 6, "texto": "Y llamando Josué hijo de Nun á los sacerdotes, les dijo: Llevad el arca del pacto, y siete sacerdotes lleven bocinas de cuernos de carneros delante del arca de Jehová."}, {"numero": 7, "texto": "Y dijo al pueblo: Pasad, y rodead la ciudad; y los que están armados pasarán delante del arca de Jehová."}, {"numero": 8, "texto": "Y así que Josué hubo hablado al pueblo, los siete sacerdotes, llevando las siete bocinas de cuernos de carneros, pasaron delante del arca de Jehová, y tocaron las bocinas: y el arca del pacto de Jehová los seguía."}, {"numero": 9, "texto": "Y los armados iban delante de los sacerdotes que tocaban las bocinas, y la gente reunida iba detrás del arca, andando y tocando bocinas."}, {"numero": 10, "texto": "Y Josué mandó al pueblo, diciendo: Vosotros no daréis grita, ni se oirá vuestra voz, ni saldrá palabra de vuestra boca, hasta el día que yo os diga: Gritad: entonces daréis grita."}, {"numero": 11, "texto": "El arca pues de Jehová dió una vuelta alrededor de la ciudad, y viniéronse al real, en el cual tuvieron la noche."}, {"numero": 12, "texto": "Y Josué se levantó de mañana, y los sacerdotes tomaron el arca de Jehová."}, {"numero": 13, "texto": "Y los siete sacerdotes, llevando las siete bocinas de cuernos de carneros, fueron delante del arca de Jehová, andando siempre y tocando las bocinas; y los armados iban delante de ellos, y la gente reunida iba detrás del arca de Jehová, andando y tocando las bocinas."}, {"numero": 14, "texto": "Así dieron otra vuelta á la ciudad el segundo día, y volviéronse al real: de esta manera hicieron por seis días."}, {"numero": 15, "texto": "Y al séptimo día levantáronse cuando subía el alba, y dieron vuelta á la ciudad de la misma manera siete veces: solamente este día dieron vuelta alrededor de ella siete veces."}, {"numero": 16, "texto": "Y como los sacerdotes hubieron tocado las bocinas la séptima vez, Josué dijo al pueblo: Dad grita, porque Jehová os ha entregado la ciudad."}, {"numero": 17, "texto": "Mas la ciudad será anatema á Jehová, ella con todas las cosas que están en ella: solamente Rahab la ramera vivirá, con todos los que estuvieren en casa con ella, por cuanto escondió los mensajeros que enviamos."}, {"numero": 18, "texto": "Empero guardaos vosotros del anatema, que ni toquéis, ni toméis alguna cosa del anatema, porque no hagáis anatema el campo de Israel, y lo turbéis."}, {"numero": 19, "texto": "Mas toda la plata, y el oro, y vasos de metal y de hierro, sea consagrado á Jehová, y venga al tesoro de Jehová."}, {"numero": 20, "texto": "Entonces el pueblo dió grita, y los sacerdotes tocaron las bocinas: y aconteció que como el pueblo hubo oído el sonido de la bocina, dió el pueblo grita con gran vocerío, y el muro cayó á plomo. El pueblo subió luego á la ciudad, cada uno en derecho de sí, y tomáronla."}, {"numero": 21, "texto": "Y destruyeron todo lo que en la ciudad había; hombres y mujeres, mozos y viejos, hasta los bueyes, y ovejas, y asnos, á filo de espada."}, {"numero": 22, "texto": "Mas Josué dijo á los dos hombres que habían reconocido la tierra: Entrad en casa de la mujer ramera, y haced salir de allá á la mujer, y á todo lo que fuere suyo, como lo jurasteis."}, {"numero": 23, "texto": "Y los mancebos espías entraron, y sacaron á Rahab, y á su padre, y á su madre, y á sus hermanos, y todo lo que era suyo; y también sacaron á toda su parentela, y pusiéronlos fuera del campo de Israel."}, {"numero": 24, "texto": "Y consumieron con fuego la ciudad, y todo lo que en ella había: solamente pusieron en el tesoro de la casa de Jehová la plata, y el oro, y los vasos de metal y de hierro."}, {"numero": 25, "texto": "Mas Josué salvó la vida á Rahab la ramera, y á la casa de su padre, y á todo lo que ella tenía: y habitó ella entre los Israelitas hasta hoy; por cuanto escondió los mensajeros que Josué envió á reconocer á Jericó."}, {"numero": 26, "texto": "Y en aquel tiempo Josué les juramentó diciendo: Maldito delante de Jehová el hombre que se levantare y reedificare esta ciudad de Jericó. En su primogénito eche sus cimientos, y en su menor asiente sus puertas."}, {"numero": 27, "texto": "Fué pues Jehová con Josué, y su nombre se divulgó por toda la tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 7, 'pt', '[{"numero": 1, "texto": "Porém os filhos de Israel cometeram transgressão no anátema: porque Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá, tomou do anátema; e a ira do SENHOR se acendeu contra os filhos de Israel."}, {"numero": 2, "texto": "E Josué enviou homens desde Jericó a Ai, que estava junto a Bete-Áven até o oriente de Betel; e falou-lhes dizendo: Subi, e reconhecei a terra. E eles subiram, e reconheceram a Ai."}, {"numero": 3, "texto": "E voltando a Josué, disseram-lhe: Não suba todo aquele povo, mas subam como dois mil ou como três mil homens, e tomarão a Ai: não canses a todo aquele povo ali, porque são poucos."}, {"numero": 4, "texto": "E subiram ali do povo como três mil homens, os quais fugiram diante dos de Ai."}, {"numero": 5, "texto": "E os de Ai feriram deles como trinta e seis homens, e seguiram-nos desde a porta até Sebarim, e os feriram na descida: pelo que se dissolveu o coração do povo, e veio a ser como água."}, {"numero": 6, "texto": "Então Josué rasgou suas roupas, e prostrou-se em terra sobre seu rosto diante da arca do SENHOR até à tarde, ele e os anciãos de Israel; e lançaram pó sobre suas cabeças."}, {"numero": 7, "texto": "E Josué disse: Ah, Senhor DEUS! Por que fizeste passar a este povo o Jordão, para entregar-nos nas mãos dos amorreus, que nos destruam? Antes nos tivéssemos ficado da outra parte do Jordão!"}, {"numero": 8, "texto": "Ai Senhor! Que direi, já que Israel virou as costas diante de seus inimigos?"}, {"numero": 9, "texto": "Porque os cananeus e todos os moradores da terra ouvirão, e nos cercarão, e apagarão nosso nome de sobre a terra: então que farás tu a teu grande nome?"}, {"numero": 10, "texto": "E o SENHOR disse a Josué: Levanta-te; por que te prostras assim sobre teu rosto?"}, {"numero": 11, "texto": "Israel pecou, e ainda quebrantou meu pacto que eu lhes havia mandado; pois ainda tomaram do anátema, e até furtaram, e também mentiram, e ainda o guardaram entre seus utensílios."}, {"numero": 12, "texto": "Por isto os filhos de Israel não poderão estar diante de seus inimigos, mas sim que diante de seus inimigos virarão as costas; porquanto vieram a ser anátema: nem serei mais convosco, se não destruirdes o anátema do meio de vós."}, {"numero": 13, "texto": "Levanta-te, santifica ao povo, e dize: Santificai-vos para amanhã, porque o SENHOR o Deus de Israel diz assim: Anátema há em meio de ti, Israel; não poderás estar diante de teus inimigos, até tanto que tenhais tirado o anátema do meio de vós."}, {"numero": 14, "texto": "Vós vos achegareis, pois, amanhã por vossas tribos; e a tribo que o SENHOR tomar, se achegará por suas famílias; e a família que o SENHOR tomar, se achegará por suas casas; e a casa que o SENHOR tomar, se achegará pelos homens;"}, {"numero": 15, "texto": "E o que for colhido no anátema, será queimado a fogo, ele e tudo o que tem, porquanto quebrantou o pacto do SENHOR, e cometeu maldade em Israel."}, {"numero": 16, "texto": "Josué, pois, levantando-se de manhã, fez achegar a Israel por suas tribos; e foi tomada a tribo de Judá;"}, {"numero": 17, "texto": "E fazendo achegar a tribo de Judá, foi tomada a família dos de Zerá; fazendo logo achegar a família dos de Zerá pelos homens, foi tomado Zabdi;"}, {"numero": 18, "texto": "E fez achegar sua casa pelos homens, e foi tomado Acã, filho de Carmi, filho de Zabdi, filho de zerá, da tribo de Judá."}, {"numero": 19, "texto": "Então Josué disse a Acã: Filho meu, dá glória agora ao SENHOR o Deus de Israel, e dá-lhe louvor, e declara-me agora o que fizeste; não me o encubras."}, {"numero": 20, "texto": "E Acã respondeu a Josué, dizendo: Verdadeiramente eu pequei contra o SENHOR o Deus de Israel, e fiz assim e assim:"}, {"numero": 21, "texto": "Que vi entre os despojos um manto babilônico muito bom, e duzentos siclos de prata, e uma barra de ouro de peso de cinquenta siclos; o qual cobicei, e tomei: e eis que está escondido debaixo da terra no meio de minha tenda, e o dinheiro debaixo dele."}, {"numero": 22, "texto": "Josué então enviou mensageiros, os quais foram correndo à tenda; e eis que estava escondido em sua tenda, e o dinheiro debaixo disso:"}, {"numero": 23, "texto": "E tomando-o do meio da tenda, trouxeram-no a Josué e a todos os filhos de Israel, e puseram-no diante do SENHOR."}, {"numero": 24, "texto": "Então Josué, e todo Israel com ele, tomou a Acã filho de zerá, e o dinheiro, e o manto, e a barra de ouro, e seus filhos, e suas filhas, e seus bois, e seus asnos, e suas ovelhas, e sua tenda, e tudo quanto tinha, e levaram-no tudo ao vale de Acor;"}, {"numero": 25, "texto": "E disse Josué: Por que nos perturbaste? Perturbe-te o SENHOR neste dia. E todos os israelitas os apedrejaram, e os queimaram a fogo, depois de apedrejá-los com pedras;"}, {"numero": 26, "texto": "E levantaram sobre ele um grande amontoado de pedras, até hoje. E o SENHOR se apaziguou da ira de seu furor. E por isto foi chamado aquele lugar o Vale de Acor, até hoje."}]'::jsonb, 'Almeida Livre'),
  ('Js', 7, 'en', '[{"numero": 1, "texto": "But the children of Israel committed a trespass in the accursed thing: for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took of the accursed thing: and the anger of the Lord was kindled against the children of Israel."}, {"numero": 2, "texto": "And Joshua sent men from Jericho to Ai, which is beside Bethaven, on the east of Bethel, and spake unto them, saying, Go up and view the country. And the men went up and viewed Ai."}, {"numero": 3, "texto": "And they returned to Joshua, and said unto him, Let not all the people go up; but let about two or three thousand men go up and smite Ai; and make not all the people to labour thither; for they are but few."}, {"numero": 4, "texto": "So there went up thither of the people about three thousand men: and they fled before the men of Ai."}, {"numero": 5, "texto": "And the men of Ai smote of them about thirty and six men: for they chased them from before the gate even unto Shebarim, and smote them in the going down: wherefore the hearts of the people melted, and became as water."}, {"numero": 6, "texto": "And Joshua rent his clothes, and fell to the earth upon his face before the ark of the Lord until the eventide, he and the elders of Israel, and put dust upon their heads."}, {"numero": 7, "texto": "And Joshua said, Alas, O Lord God, wherefore hast thou at all brought this people over Jordan, to deliver us into the hand of the Amorites, to destroy us? would to God we had been content, and dwelt on the other side Jordan!"}, {"numero": 8, "texto": "O Lord, what shall I say, when Israel turneth their backs before their enemies!"}, {"numero": 9, "texto": "For the Canaanites and all the inhabitants of the land shall hear of it, and shall environ us round, and cut off our name from the earth: and what wilt thou do unto thy great name?"}, {"numero": 10, "texto": "And the Lord said unto Joshua, Get thee up; wherefore liest thou thus upon thy face?"}, {"numero": 11, "texto": "Israel hath sinned, and they have also transgressed my covenant which I commanded them: for they have even taken of the accursed thing, and have also stolen, and dissembled also, and they have put it even among their own stuff."}, {"numero": 12, "texto": "Therefore the children of Israel could not stand before their enemies, but turned their backs before their enemies, because they were accursed: neither will I be with you any more, except ye destroy the accursed from among you."}, {"numero": 13, "texto": "Up, sanctify the people, and say, Sanctify yourselves against to morrow: for thus saith the Lord God of Israel, There is an accursed thing in the midst of thee, O Israel: thou canst not stand before thine enemies, until ye take away the accursed thing from among you."}, {"numero": 14, "texto": "In the morning therefore ye shall be brought according to your tribes: and it shall be, that the tribe which the Lord taketh shall come according to the families thereof; and the family which the Lord shall take shall come by households; and the household which the Lord shall take shall come man by man."}, {"numero": 15, "texto": "And it shall be, that he that is taken with the accursed thing shall be burnt with fire, he and all that he hath: because he hath transgressed the covenant of the Lord, and because he hath wrought folly in Israel."}, {"numero": 16, "texto": "So Joshua rose up early in the morning, and brought Israel by their tribes; and the tribe of Judah was taken:"}, {"numero": 17, "texto": "And he brought the family of Judah; and he took the family of the Zarhites: and he brought the family of the Zarhites man by man; and Zabdi was taken:"}, {"numero": 18, "texto": "And he brought his household man by man; and Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, was taken."}, {"numero": 19, "texto": "And Joshua said unto Achan, My son, give, I pray thee, glory to the Lord God of Israel, and make confession unto him; and tell me now what thou hast done; hide it not from me."}, {"numero": 20, "texto": "And Achan answered Joshua, and said, Indeed I have sinned against the Lord God of Israel, and thus and thus have I done:"}, {"numero": 21, "texto": "When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."}, {"numero": 22, "texto": "So Joshua sent messengers, and they ran unto the tent; and, behold, it was hid in his tent, and the silver under it."}, {"numero": 23, "texto": "And they took them out of the midst of the tent, and brought them unto Joshua, and unto all the children of Israel, and laid them out before the Lord."}, {"numero": 24, "texto": "And Joshua, and all Israel with him, took Achan the son of Zerah, and the silver, and the garment, and the wedge of gold, and his sons, and his daughters, and his oxen, and his asses, and his sheep, and his tent, and all that he had: and they brought them unto the valley of Achor."}, {"numero": 25, "texto": "And Joshua said, Why hast thou troubled us? the Lord shall trouble thee this day. And all Israel stoned him with stones, and burned them with fire, after they had stoned them with stones."}, {"numero": 26, "texto": "And they raised over him a great heap of stones unto this day. So the Lord turned from the fierceness of his anger. Wherefore the name of that place was called, The valley of Achor, unto this day."}]'::jsonb, 'King James Version'),
  ('Js', 7, 'fr', '[{"numero": 1, "texto": "Les enfants d''''Israël commirent une infidélité au sujet des choses dévouées par interdit. Acan, fils de Carmi, fils de Zabdi, fils de Zérach, de la tribu de Juda, prit des choses dévouées. Et la colère de l''''Eternel s''''enflamma contre les enfants d''''Israël."}, {"numero": 2, "texto": "Josué envoya de Jéricho des hommes vers Aï, qui est près de Beth-Aven, à l''''orient de Béthel. Il leur dit: Montez, et explorez le pays. Et ces hommes montèrent, et explorèrent Aï."}, {"numero": 3, "texto": "Ils revinrent auprès de Josué, et lui dirent: Il est inutile de faire marcher tout le peuple; deux ou trois mille hommes suffiront pour battre Aï; ne donne pas cette fatigue à tout le peuple, car ils sont en petit nombre."}, {"numero": 4, "texto": "Trois mille hommes environ se mirent en marche, mais ils prirent la fuite devant les gens d''''Aï."}, {"numero": 5, "texto": "Les gens d''''Aï leur tuèrent environ trente-six hommes; ils les poursuivirent depuis la porte jusqu''''à Schebarim, et les battirent à la descente. Le peuple fut consterné et perdit courage."}, {"numero": 6, "texto": "Josué déchira ses vêtements, et se prosterna jusqu''''au soir le visage contre terre devant l''''arche de l''''Eternel, lui et les anciens d''''Israël, et ils se couvrirent la tête de poussière."}, {"numero": 7, "texto": "Josué dit: Ah! Seigneur Eternel, pourquoi as-tu fait passer le Jourdain à ce peuple, pour nous livrer entre les mains des Amoréens et nous faire périr? Oh! si nous eussions su rester de l''''autre côté du Jourdain!"}, {"numero": 8, "texto": "De grâce, Seigneur, que dirai-je, après qu''''Israël a tourné le dos devant ses ennemis?"}, {"numero": 9, "texto": "Les Cananéens et tous les habitants du pays l''''apprendront; ils nous envelopperont, et ils feront disparaître notre nom de la terre. Et que feras-tu pour ton grand nom?"}, {"numero": 10, "texto": "L''''Eternel dit à Josué: Lève-toi! Pourquoi restes-tu ainsi couché sur ton visage?"}, {"numero": 11, "texto": "Israël a péché; ils ont transgressé mon alliance que je leur ai prescrite, ils ont pris des choses dévouées par interdit, ils les ont dérobées et ont dissimulé, et ils les ont cachées parmi leurs bagages."}, {"numero": 12, "texto": "Aussi les enfants d''''Israël ne peuvent-ils résister à leurs ennemis; ils tourneront le dos devant leurs ennemis, car ils sont sous l''''interdit; je ne serai plus avec vous, si vous ne détruisez pas l''''interdit du milieu de vous."}, {"numero": 13, "texto": "Lève-toi, sanctifie le peuple. Tu diras: Sanctifiez-vous pour demain; car ainsi parle l''''Eternel, le Dieu d''''Israël: Il y a de l''''interdit au milieu de toi, Israël; tu ne pourras résister à tes ennemis, jusqu''''à ce que vous ayez ôté l''''interdit du milieu de vous."}, {"numero": 14, "texto": "Vous vous approcherez le matin selon vos tribus; et la tribu que désignera l''''Eternel s''''approchera par famille, et la famille que désignera l''''Eternel s''''approchera par maisons, et la maison que désignera l''''Eternel s''''approchera par hommes."}, {"numero": 15, "texto": "Celui qui sera désigné comme ayant pris de ce qui était dévoué par interdit sera brûlé au feu, lui et tout ce qui lui appartient, pour avoir transgressé l''''alliance de l''''Eternel et commis une infamie en Israël."}, {"numero": 16, "texto": "Josué se leva de bon matin, et il fit approcher Israël selon ses tribus, et la tribu de Juda fut désignée."}, {"numero": 17, "texto": "Il fit approcher les familles de Juda, et la famille de Zérach fut désignée. Il fit approcher la famille de Zérach par maisons, et Zabdi fut désigné."}, {"numero": 18, "texto": "Il fit approcher la maison de Zabdi par hommes, et Acan, fils de Carmi, fils de Zabdi, fils de Zérach, de la tribu de Juda, fut désigné."}, {"numero": 19, "texto": "Josué dit à Acan: Mon fils, donne gloire à l''''Eternel, le Dieu d''''Israël, et rends-lui hommage. Dis-moi donc ce que tu as fait, ne me le cache point."}, {"numero": 20, "texto": "Acan répondit à Josué, et dit: Il est vrai que j''''ai péché contre l''''Eternel, le Dieu d''''Israël, et voici ce que j''''ai fait."}, {"numero": 21, "texto": "J''''ai vu dans le butin un beau manteau de Schinear, deux cents sicles d''''argent, et un lingot d''''or du poids de cinquante sicles; je les ai convoités, et je les ai pris; ils sont cachés dans la terre au milieu de ma tente, et l''''argent est dessous."}, {"numero": 22, "texto": "Josué envoya des gens, qui coururent à la tente; et voici, les objets étaient cachés dans la tente d''''Acan, et l''''argent était dessous."}, {"numero": 23, "texto": "Ils les prirent du milieu de la tente, les apportèrent à Josué et à tous les enfants d''''Israël, et les déposèrent devant l''''Eternel."}, {"numero": 24, "texto": "Josué et tout Israël avec lui prirent Acan, fils de Zérach, l''''argent, le manteau, le lingot d''''or, les fils et les filles d''''Acan, ses boeufs, ses ânes, ses brebis, sa tente, et tout ce qui lui appartenait; et ils les firent monter dans la vallée d''''Acor."}, {"numero": 25, "texto": "Josué dit: Pourquoi nous as-tu troublés? L''''Eternel te troublera aujourd''''hui. Et tout Israël le lapida. On les brûla au feu, on les lapida,"}, {"numero": 26, "texto": "et l''''on éleva sur Acan un grand monceau de pierres, qui subsiste encore aujourd''''hui. Et l''''Eternel revint de l''''ardeur de sa colère. C''''est à cause de cet événement qu''''on a donné jusqu''''à ce jour à ce lieu le nom de vallée d''''Acor."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 7, 'es', '[{"numero": 1, "texto": "EMPERO los hijos de Israel cometieron prevaricación en el anatema: porque Achân, hijo de Carmi, hijo de Zabdi, hijo de Zera, de la tribu de Judá, tomó del anatema; y la ira de Jehová se encendió contra los hijos de Israel."}, {"numero": 2, "texto": "Y Josué envió hombres desde Jericó á Hai, que estaba junto á Beth-aven hacia el oriente de Beth-el; y hablóles diciendo: Subid, y reconoced la tierra. Y ellos subieron, y reconocieron á Hai."}, {"numero": 3, "texto": "Y volviendo á Josué, dijéronle: No suba todo el pueblo, mas suban como dos mil ó como tres mil hombres, y tomarán á Hai: no fatigues á todo el pueblo allí, porque son pocos."}, {"numero": 4, "texto": "Y subieron allá del pueblo como tres mil hombres, los cuales huyeron delante de los de Hai."}, {"numero": 5, "texto": "Y los de Hai hirieron de ellos como treinta y seis hombres, y siguiéronlos desde la puerta hasta Sebarim, y los rompieron en la bajada: por lo que se disolvió el corazón del pueblo, y vino á ser como agua."}, {"numero": 6, "texto": "Entonces Josué rompió sus vestidos, y postróse en tierra sobre su rostro delante del arca de Jehová hasta la tarde, él y los ancianos de Israel; y echaron polvo sobre sus cabezas."}, {"numero": 7, "texto": "Y Josué dijo: ¡Ah, Señor Jehová! ¿Por qué hiciste pasar á este pueblo el Jordán, para entregarnos en las manos de los Amorrheos, que nos destruyan? ¡Ojalá nos hubiéramos quedado de la otra parte del Jordán!"}, {"numero": 8, "texto": "¡Ay Señor! ¿qué diré, ya que Israel ha vuelto las espaldas delante de sus enemigos?"}, {"numero": 9, "texto": "Porque los Cananeos y todos los moradores de la tierra oirán, y nos cercarán, y raerán nuestro nombre de sobre la tierra: entonces ¿qué harás tú á tu grande nombre?"}, {"numero": 10, "texto": "Y Jehová dijo á Josué: Levántate; ¿por qué te postras así sobre tu rostro?"}, {"numero": 11, "texto": "Israel ha pecado, y aun han quebrantado mi pacto que yo les había mandado; pues aun han tomado del anatema, y hasta han hurtado, y también han mentido, y aun lo han guardado entre sus enseres."}, {"numero": 12, "texto": "Por esto los hijos de Israel no podrán estar delante de sus enemigos, sino que delante de sus enemigos volverán las espaldas; por cuanto han venido á ser anatema: ni seré más con vosotros, si no destruyereis el anatema de en medio de vosotros."}, {"numero": 13, "texto": "Levántate, santifica al pueblo, y di: Santificaos para mañana; porque Jehová el Dios de Israel dice así: Anatema hay en medio de ti, Israel; no podrás estar delante de tus enemigos, hasta tanto que hayáis quitado el anatema de en medio de vosotros."}, {"numero": 14, "texto": "Os allegaréis, pues, mañana por vuestras tribus; y la tribu que Jehová tomare, se allegará por sus familias; y la familia que Jehová tomare, se allegará por sus casas; y la casa que Jehová tomare, allegaráse por los varones;"}, {"numero": 15, "texto": "Y el que fuere cogido en el anatema, será quemado á fuego, él y todo lo que tiene, por cuanto ha quebrantado el pacto de Jehová, y ha cometido maldad en Israel."}, {"numero": 16, "texto": "Josué, pues, levantándose de mañana, hizo allegar á Israel por sus tribus; y fué tomada la tribu de Judá;"}, {"numero": 17, "texto": "Y haciendo allegar la tribu de Judá, fué tomada la familia de los de Zera; haciendo luego allegar la familia de los de Zera por los varones, fué tomado Zabdi;"}, {"numero": 18, "texto": "E hizo allegar su casa por los varones, y fué tomado Achân, hijo de Carmi, hijo de Zabdi, hijo de Zera, de la tribu de Judá."}, {"numero": 19, "texto": "Entonces Josué dijo á Achân: Hijo mío, da gloria ahora á Jehová el Dios de Israel, y dale alabanza, y declárame ahora lo que has hecho; no me lo encubras."}, {"numero": 20, "texto": "Y Achân respondió á Josué, diciendo: Verdaderamente yo he pecado contra Jehová el Dios de Israel, y he hecho así y así:"}, {"numero": 21, "texto": "Que vi entre los despojos un manto babilónico muy bueno, y doscientos siclos de plata, y un changote de oro de peso de cincuenta siclos; lo cual codicié, y tomé: y he aquí que está escondido debajo de tierra en el medio de mi tienda, y el dinero debajo de ello."}, {"numero": 22, "texto": "Josué entonces envió mensajeros, los cuales fueron corriendo á la tienda; y he aquí estaba escondido en su tienda, y el dinero debajo de ello:"}, {"numero": 23, "texto": "Y tomándolo de en medio de la tienda, trajéronlo á Josué y á todos los hijos de Israel, y pusiéronlo delante de Jehová."}, {"numero": 24, "texto": "Entonces Josué, y todo Israel con él, tomó á Achân hijo de Zera, y el dinero, y el manto, y el changote de oro, y sus hijos, y sus hijas, y sus bueyes, y sus asnos, y sus ovejas, y su tienda, y todo cuanto tenía, y lleváronlo todo al valle de Achôr;"}, {"numero": 25, "texto": "Y dijo Josué: ¿Por qué nos has turbado? Túrbete Jehová en este día. Y todos los Israelitas los apedrearon, y los quemaron á fuego, después de apedrearlos con piedras;"}, {"numero": 26, "texto": "Y levantaron sobre él un gran montón de piedras, hasta hoy. Y Jehová se tornó de la ira de su furor. Y por esto fué llamado aquel lugar el Valle de Achôr, hasta hoy."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 8, 'pt', '[{"numero": 1, "texto": "E o SENHOR disse a Josué: Não temas, nem desmaies; toma contigo toda a gente de guerra, e levanta-te e sobe a Ai. Olha, eu entreguei em tua mão ao rei de Ai, e a seu povo, a sua cidade, e a sua terra."}, {"numero": 2, "texto": "E farás a Ai e a seu rei como fizeste a Jericó e a seu rei: somente que seus despojos e seus animais tomareis para vós. Porás, pois, emboscadas à cidade detrás dela."}, {"numero": 3, "texto": "E levantou-se Josué, e toda a gente de guerra, para subir contra Ai: e escolheu Josué trinta mil homens fortes, os quais enviou de noite."}, {"numero": 4, "texto": "E mandou-lhes, dizendo: Olhai, poreis emboscada à cidade detrás dela: não vos afastareis muito da cidade, e estareis todos prontos."}, {"numero": 5, "texto": "E eu, e todo aquele povo que está comigo, nos aproximaremos da cidade; e quando saírem eles contra nós, como fizeram antes, fugiremos diante deles."}, {"numero": 6, "texto": "E eles sairão atrás de nós, até que os tiremos da cidade; porque eles dirão: Fogem de nós como a primeira vez. Fugiremos, pois, diante deles."}, {"numero": 7, "texto": "Então vós vos levantareis da emboscada, e vos lançareis sobre a cidade; pois o SENHOR vosso Deus a entregará em vossas mãos."}, {"numero": 8, "texto": "E quando a houverdes tomado, poreis fogo nela. Fareis conforme a palavra do SENHOR. Olhai que vos o mandei."}, {"numero": 9, "texto": "Então Josué os enviou; e eles se foram à emboscada, e puseram-se entre Betel e Ai, ao ocidente de Ai: e Josué ficou aquela noite em meio do povo."}, {"numero": 10, "texto": "E levantando-se Josué muito de manhã, revistou ao povo, e subiu ele, com os anciãos de Israel, diante do povo contra Ai."}, {"numero": 11, "texto": "E toda a gente de guerra que com ele estava, subiu, e aproximou-se, e chegaram diante da cidade, e assentaram o campo à parte do norte de Ai: e o vale estava entre ele e Ai."}, {"numero": 12, "texto": "E tomou como cinco mil homens, e os pôs em emboscada entre Betel e Ai, à parte ocidental da cidade."}, {"numero": 13, "texto": "E o povo, todo aquele acampamento que estava à parte do norte da cidade, colocado já próximo, e sua emboscada ao ocidente da cidade, veio Josué aquela noite ao meio do vale."}, {"numero": 14, "texto": "O qual quando o rei de Ai viu, levantou-se prontamente de manhã, e saiu com a gente da cidade contra Israel, ele e todo seu povo, para combater pela planície ao tempo assinalado, não sabendo que lhe estava posta emboscada atrás da cidade."}, {"numero": 15, "texto": "Então Josué e todo Israel, fazendo-se de vencidos, fugiram diante deles pelo caminho do deserto."}, {"numero": 16, "texto": "E todo aquele povo que estava em Ai se juntou para segui-los: e seguiram a Josué, sendo assim tirados da cidade."}, {"numero": 17, "texto": "E não ficou homem em Ai e Betel, que não tivesse saído atrás de Israel; e por perseguir a Israel deixaram a cidade aberta."}, {"numero": 18, "texto": "Então o SENHOR disse a Josué: Levanta a lança que tens em tua mão até Ai, porque eu a entregarei em tua mão. E Josué levantou até a cidade a lança que em sua mão tinha."}, {"numero": 19, "texto": "E levantando-se prontamente de seu lugar os que estavam na emboscada, correram logo que ele levantou sua mão, e vieram à cidade, e a tomaram, e apressaram-se a por-lhe fogo."}, {"numero": 20, "texto": "E quando os da cidade olharam atrás, observaram, e eis que a fumaça da cidade que subia ao céu, e não puderam fugir nem a uma parte nem à outra: e o povo que ia fugindo até o deserto, se voltou contra os que o seguiam."}, {"numero": 21, "texto": "Josué e todo Israel, vendo que os da emboscada tomaram a cidade, e que a fumaça da cidade subia, voltaram, e feriram aos de Ai."}, {"numero": 22, "texto": "E os outros saíram da cidade a seu encontro: e assim foram cercados em meio de Israel, os uns da uma parte, e os outros da outra. E os feriram até que não restou nenhum deles que escapasse."}, {"numero": 23, "texto": "E tomaram vivo ao rei de Ai, e trouxeram-lhe a Josué."}, {"numero": 24, "texto": "E quando os israelitas acabaram de matar a todos os moradores de Ai no campo, no deserto, onde eles os haviam perseguido, e que todos haviam caído a fio de espada até serem consumidos, todos os israelitas se voltaram a Ai, e também a feriram à espada."}, {"numero": 25, "texto": "E o número dos que caíram aquele dia, homens e mulheres, foi doze mil, todos os de Ai."}, {"numero": 26, "texto": "E Josué não retraiu sua mão que havia estendido com a lança, até que destruiu a todos os moradores de Ai."}, {"numero": 27, "texto": "Porém os israelitas tomaram para si os animais e os despojos da cidade, conforme a palavra do SENHOR que ele havia mandado a Josué."}, {"numero": 28, "texto": "E Josué queimou a Ai e reduziu-a a um amontoado perpétuo, assolado até hoje."}, {"numero": 29, "texto": "Mas ao rei de Ai enforcou de um madeiro até à tarde: e quando o sol se pôs, mandou Josué que tirassem do madeiro seu corpo, e o lançassem à porta da cidade: e levantaram sobre ele um grande amontoado de pedras, até hoje."}, {"numero": 30, "texto": "Então Josué edificou um altar ao SENHOR Deus de Israel no monte de Ebal,"}, {"numero": 31, "texto": "Como Moisés, servo do SENHOR, o havia mandado aos filhos de Israel, como está escrito no livro da lei de Moisés, um altar de pedras inteiras sobre as quais ninguém levantou ferro: e ofereceram sobre ele holocaustos ao SENHOR, e sacrificaram ofertas pacíficas."}, {"numero": 32, "texto": "Também escreveu ali em pedras a repetição da lei de Moisés, a qual ele havia escrito diante dos filhos de Israel."}, {"numero": 33, "texto": "E todo Israel, e seus anciãos, oficiais, e juízes, estavam da uma e da outra parte junto à arca, diante dos sacerdotes levitas que levam a arca do pacto do SENHOR; tanto estrangeiros como naturais, a metade deles estava até o monte de Gerizim, e a outra metade até o monte de Ebal; da maneira que Moisés, servo do SENHOR, havia lhe mandado antes, para que abençoassem primeiramente ao povo de Israel."}, {"numero": 34, "texto": "Depois disto, leu todas as palavras da lei, as bênçãos e as maldições, conforme tudo o que está escrito no livro da lei."}, {"numero": 35, "texto": "Não houve palavra alguma de todas as coisas que mandou Moisés, que Josué não fizesse ler diante de toda a congregação de Israel, mulheres e meninos, e estrangeiros que andavam entre eles."}]'::jsonb, 'Almeida Livre'),
  ('Js', 8, 'en', '[{"numero": 1, "texto": "And the Lord said unto Joshua, Fear not, neither be thou dismayed: take all the people of war with thee, and arise, go up to Ai: see, I have given into thy hand the king of Ai, and his people, and his city, and his land:"}, {"numero": 2, "texto": "And thou shalt do to Ai and her king as thou didst unto Jericho and her king: only the spoil thereof, and the cattle thereof, shall ye take for a prey unto yourselves: lay thee an ambush for the city behind it."}, {"numero": 3, "texto": "So Joshua arose, and all the people of war, to go up against Ai: and Joshua chose out thirty thousand mighty men of valour, and sent them away by night."}, {"numero": 4, "texto": "And he commanded them, saying, Behold, ye shall lie in wait against the city, even behind the city: go not very far from the city, but be ye all ready:"}, {"numero": 5, "texto": "And I, and all the people that are with me, will approach unto the city: and it shall come to pass, when they come out against us, as at the first, that we will flee before them,"}, {"numero": 6, "texto": "(For they will come out after us) till we have drawn them from the city; for they will say, They flee before us, as at the first: therefore we will flee before them."}, {"numero": 7, "texto": "Then ye shall rise up from the ambush, and seize upon the city: for the Lord your God will deliver it into your hand."}, {"numero": 8, "texto": "And it shall be, when ye have taken the city, that ye shall set the city on fire: according to the commandment of the Lord shall ye do. See, I have commanded you."}, {"numero": 9, "texto": "Joshua therefore sent them forth: and they went to lie in ambush, and abode between Bethel and Ai, on the west side of Ai: but Joshua lodged that night among the people."}, {"numero": 10, "texto": "And Joshua rose up early in the morning, and numbered the people, and went up, he and the elders of Israel, before the people to Ai."}, {"numero": 11, "texto": "And all the people, even the people of war that were with him, went up, and drew nigh, and came before the city, and pitched on the north side of Ai: now there was a valley between them and Ai."}, {"numero": 12, "texto": "And he took about five thousand men, and set them to lie in ambush between Bethel and Ai, on the west side of the city."}, {"numero": 13, "texto": "And when they had set the people, even all the host that was on the north of the city, and their liers in wait on the west of the city, Joshua went that night into the midst of the valley."}, {"numero": 14, "texto": "And it came to pass, when the king of Ai saw it, that they hasted and rose up early, and the men of the city went out against Israel to battle, he and all his people, at a time appointed, before the plain; but he wist not that there were liers in ambush against him behind the city."}, {"numero": 15, "texto": "And Joshua and all Israel made as if they were beaten before them, and fled by the way of the wilderness."}, {"numero": 16, "texto": "And all the people that were in Ai were called together to pursue after them: and they pursued after Joshua, and were drawn away from the city."}, {"numero": 17, "texto": "And there was not a man left in Ai or Bethel, that went not out after Israel: and they left the city open, and pursued after Israel."}, {"numero": 18, "texto": "And the Lord said unto Joshua, Stretch out the spear that is in thy hand toward Ai; for I will give it into thine hand. And Joshua stretched out the spear that he had in his hand toward the city."}, {"numero": 19, "texto": "And the ambush arose quickly out of their place, and they ran as soon as he had stretched out his hand: and they entered into the city, and took it, and hasted and set the city on fire."}, {"numero": 20, "texto": "And when the men of Ai looked behind them, they saw, and, behold, the smoke of the city ascended up to heaven, and they had no power to flee this way or that way: and the people that fled to the wilderness turned back upon the pursuers."}, {"numero": 21, "texto": "And when Joshua and all Israel saw that the ambush had taken the city, and that the smoke of the city ascended, then they turned again, and slew the men of Ai."}, {"numero": 22, "texto": "And the other issued out of the city against them; so they were in the midst of Israel, some on this side, and some on that side: and they smote them, so that they let none of them remain or escape."}, {"numero": 23, "texto": "And the king of Ai they took alive, and brought him to Joshua."}, {"numero": 24, "texto": "And it came to pass, when Israel had made an end of slaying all the inhabitants of Ai in the field, in the wilderness wherein they chased them, and when they were all fallen on the edge of the sword, until they were consumed, that all the Israelites returned unto Ai, and smote it with the edge of the sword."}, {"numero": 25, "texto": "And so it was, that all that fell that day, both of men and women, were twelve thousand, even all the men of Ai."}, {"numero": 26, "texto": "For Joshua drew not his hand back, wherewith he stretched out the spear, until he had utterly destroyed all the inhabitants of Ai."}, {"numero": 27, "texto": "Only the cattle and the spoil of that city Israel took for a prey unto themselves, according unto the word of the Lord which he commanded Joshua."}, {"numero": 28, "texto": "And Joshua burnt Ai, and made it an heap for ever, even a desolation unto this day."}, {"numero": 29, "texto": "And the king of Ai he hanged on a tree until eventide: and as soon as the sun was down, Joshua commanded that they should take his carcase down from the tree, and cast it at the entering of the gate of the city, and raise thereon a great heap of stones, that remaineth unto this day."}, {"numero": 30, "texto": "Then Joshua built an altar unto the Lord God of Israel in mount Ebal,"}, {"numero": 31, "texto": "As Moses the servant of the Lord commanded the children of Israel, as it is written in the book of the law of Moses, an altar of whole stones, over which no man hath lift up any iron: and they offered thereon burnt offerings unto the Lord, and sacrificed peace offerings."}, {"numero": 32, "texto": "And he wrote there upon the stones a copy of the law of Moses, which he wrote in the presence of the children of Israel."}, {"numero": 33, "texto": "And all Israel, and their elders, and officers, and their judges, stood on this side the ark and on that side before the priests the Levites, which bare the ark of the covenant of the Lord, as well the stranger, as he that was born among them; half of them over against mount Gerizim, and half of them over against mount Ebal; as Moses the servant of the Lord had commanded before, that they should bless the people of Israel."}, {"numero": 34, "texto": "And afterward he read all the words of the law, the blessings and cursings, according to all that is written in the book of the law."}, {"numero": 35, "texto": "There was not a word of all that Moses commanded, which Joshua read not before all the congregation of Israel, with the women, and the little ones, and the strangers that were conversant among them."}]'::jsonb, 'King James Version'),
  ('Js', 8, 'fr', '[{"numero": 1, "texto": "L''''Eternel dit à Josué: Ne crains point, et ne t''''effraie point! Prends avec toi tous les gens de guerre, lève-toi, monte contre Aï. Vois, je livre entre tes mains le roi d''''Aï et son peuple, sa ville et son pays."}, {"numero": 2, "texto": "Tu traiteras Aï et son roi comme tu as traité Jéricho et son roi; seulement vous garderez pour vous le butin et le bétail. Place une embuscade derrière la ville."}, {"numero": 3, "texto": "Josué se leva avec tous les gens de guerre, pour monter contre Aï. Il choisit trente mille vaillants hommes, qu''''il fit partir de nuit,"}, {"numero": 4, "texto": "et auxquels il donna cet ordre: Ecoutez, vous vous mettrez en embuscade derrière la ville; ne vous éloignez pas beaucoup de la ville, et soyez tous prêts."}, {"numero": 5, "texto": "Mais moi et tout le peuple qui est avec moi, nous nous approcherons de la ville. Et quand ils sortiront à notre rencontre, comme la première fois, nous prendrons la fuite devant eux."}, {"numero": 6, "texto": "Ils nous poursuivront jusqu''''à ce que nous les ayons attirés loin de la ville, car ils diront: Ils fuient devant nous, comme la première fois! Et nous fuirons devant eux."}, {"numero": 7, "texto": "Vous sortirez alors de l''''embuscade, et vous vous emparerez de la ville, et l''''Eternel, votre Dieu, la livrera entre vos mains."}, {"numero": 8, "texto": "Quand vous aurez pris la ville, vous y mettrez le feu, vous agirez comme l''''Eternel l''''a dit: c''''est l''''ordre que je vous donne."}, {"numero": 9, "texto": "Josué les fit partir, et ils allèrent se placer en embuscade entre Béthel et Aï, à l''''occident d''''Aï. Mais Josué passa cette nuit-là au milieu du peuple."}, {"numero": 10, "texto": "Josué se leva de bon matin, passa le peuple en revue, et marcha contre Aï, à la tête du peuple, lui et les anciens d''''Israël."}, {"numero": 11, "texto": "Tous les gens de guerre qui étaient avec lui montèrent et s''''approchèrent; lorsqu''''ils furent arrivés en face de la ville, ils campèrent au nord d''''Aï, dont ils étaient séparés par la vallée."}, {"numero": 12, "texto": "Josué prit environ cinq mille hommes, et les mit en embuscade entre Béthel et Aï, à l''''occident de la ville."}, {"numero": 13, "texto": "Après que tout le camp eut pris position au nord de la ville, et l''''embuscade à l''''occident de la ville, Josué s''''avança cette nuit-là au milieu de la vallée."}, {"numero": 14, "texto": "Lorsque le roi d''''Aï vit cela, les gens d''''Aï se levèrent en hâte de bon matin, et sortirent à la rencontre d''''Israël, pour le combattre. Le roi se dirigea, avec tout son peuple, vers un lieu fixé, du côté de la plaine, et il ne savait pas qu''''il y avait derrière la ville une embuscade contre lui."}, {"numero": 15, "texto": "Josué et tout Israël feignirent d''''être battus devant eux, et ils s''''enfuirent par le chemin du désert."}, {"numero": 16, "texto": "Alors tout le peuple qui était dans la ville s''''assembla pour se mettre à leur poursuite. Ils poursuivirent Josué, et ils furent attirés loin de la ville."}, {"numero": 17, "texto": "Il n''''y eut dans Aï et dans Béthel pas un homme qui ne sortît contre Israël. Ils laissèrent la ville ouverte, et poursuivirent Israël."}, {"numero": 18, "texto": "L''''Eternel dit à Josué: Etends vers Aï le javelot que tu as à la main, car je vais la livrer en ton pouvoir. Et Josué étendit vers la ville le javelot qu''''il avait à la main."}, {"numero": 19, "texto": "Aussitôt qu''''il eut étendu sa main, les hommes en embuscade sortirent précipitamment du lieu où ils étaient; ils pénétrèrent dans la ville, la prirent, et se hâtèrent d''''y mettre le feu."}, {"numero": 20, "texto": "Les gens d''''Aï, ayant regardé derrière eux, virent la fumée de la ville monter vers le ciel, et ils ne purent se sauver d''''aucun côté. Le peuple qui fuyait vers le désert se retourna contre ceux qui le poursuivaient;"}, {"numero": 21, "texto": "car Josué et tout Israël, voyant la ville prise par les hommes de l''''embuscade, et la fumée de la ville qui montait, se retournèrent et battirent les gens d''''Aï."}, {"numero": 22, "texto": "Les autres sortirent de la ville à leur rencontre, et les gens d''''Aï furent enveloppés par Israël de toutes parts. Israël les battit, sans leur laisser un survivant ni un fuyard;"}, {"numero": 23, "texto": "ils prirent vivant le roi d''''Aï, et l''''amenèrent à Josué."}, {"numero": 24, "texto": "Lorsqu''''Israël eut achevé de tuer tous les habitants d''''Aï dans la campagne, dans le désert, où ils l''''avaient poursuivi, et que tous furent entièrement passés au fil de l''''épée, tout Israël revint vers Aï et la frappa du tranchant de l''''épée."}, {"numero": 25, "texto": "Il y eut au total douze mille personnes tuées ce jour-là, hommes et femmes, tous gens d''''Aï."}, {"numero": 26, "texto": "Josué ne retira point sa main qu''''il tenait étendue avec le javelot, jusqu''''à ce que tous les habitants eussent été dévoués par interdit."}, {"numero": 27, "texto": "Seulement Israël garda pour lui le bétail et le butin de cette ville, selon l''''ordre que l''''Eternel avait prescrit à Josué."}, {"numero": 28, "texto": "Josué brûla Aï, et en fit à jamais un monceau de ruines, qui subsiste encore aujourd''''hui."}, {"numero": 29, "texto": "Il fit pendre à un bois le roi d''''Aï, et l''''y laissa jusqu''''au soir. Au coucher du soleil, Josué ordonna qu''''on descendît son cadavre du bois; on le jeta à l''''entrée de la porte de la ville, et l''''on éleva sur lui un grand monceau de pierres, qui subsiste encore aujourd''''hui."}, {"numero": 30, "texto": "Alors Josué bâtit un autel à l''''Eternel, le Dieu d''''Israël, sur le mont Ebal,"}, {"numero": 31, "texto": "comme Moïse, serviteur de l''''Eternel, l''''avait ordonné aux enfants d''''Israël, et comme il est écrit dans le livre de la loi de Moïse: c''''était un autel de pierres brutes, sur lesquelles on ne porta point le fer. Ils offrirent sur cet autel des holocaustes à l''''Eternel, et ils présentèrent des sacrifices d''''actions de grâces."}, {"numero": 32, "texto": "Et là Josué écrivit sur les pierres une copie de la loi que Moïse avait écrite devant les enfants d''''Israël."}, {"numero": 33, "texto": "Tout Israël, ses anciens, ses officiers et ses juges, se tenaient des deux côtés de l''''arche, devant les sacrificateurs, les Lévites, qui portaient l''''arche de l''''alliance de l''''Eternel; les étrangers comme les enfants d''''Israël étaient là, moitié du côté du mont Garizim, moitié du côté du mont Ebal, selon l''''ordre qu''''avait précédemment donné Moïse, serviteur de l''''Eternel, de bénir le peuple d''''Israël."}, {"numero": 34, "texto": "Josué lut ensuite toutes les paroles de la loi, les bénédictions et les malédictions, suivant ce qui est écrit dans le livre de la loi."}, {"numero": 35, "texto": "Il n''''y eut rien de tout ce que Moïse avait prescrit, que Josué ne lût en présence de toute l''''assemblée d''''Israël, des femmes et des enfants, et des étrangers qui marchaient au milieu d''''eux."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 8, 'es', '[{"numero": 1, "texto": "Y JEHOVÁ dijo á Josué: No temas, ni desmayes; toma contigo toda la gente de guerra, y levántate y sube á Hai. Mira, yo he entregado en tu mano al rey de Hai, y á su pueblo, á su ciudad, y á su tierra."}, {"numero": 2, "texto": "Y harás á Hai y á su rey como hiciste á Jericó y á su rey: sólo que sus despojos y sus bestias tomaréis para vosotros. Pondrás, pues, emboscadas á la ciudad detrás de ella."}, {"numero": 3, "texto": "Y levantóse Josué, y toda la gente de guerra, para subir contra Hai: y escogió Josué treinta mil hombres fuertes, los cuales envió de noche."}, {"numero": 4, "texto": "Y mandóles, diciendo: Mirad, pondréis emboscada á la ciudad detrás de ella: no os alejaréis mucho de la ciudad, y estaréis todos apercibidos."}, {"numero": 5, "texto": "Y yo, y todo el pueblo que está conmigo, nos acercaremos á la ciudad; y cuando saldrán ellos contra nosotros, como hicieron antes, huiremos delante de ellos."}, {"numero": 6, "texto": "Y ellos saldrán tras nosotros, hasta que los arranquemos de la ciudad; porque ellos dirán: Huyen de nosotros como la primera vez. Huiremos, pues, delante de ellos."}, {"numero": 7, "texto": "Entonces vosotros os levantaréis de la emboscada, y os echaréis sobre la ciudad; pues Jehová vuestro Dios la entregará en vuestras manos."}, {"numero": 8, "texto": "Y cuando la hubiereis tomado, le prenderéis fuego. Haréis conforme á la palabra de Jehová. Mirad que os lo he mandado."}, {"numero": 9, "texto": "Entonces Josué los envió; y ellos se fueron á la emboscada, y pusiéronse entre Beth-el y Hai, al occidente de Hai: y Josué se quedó aquella noche en medio del pueblo."}, {"numero": 10, "texto": "Y levantándose Josué muy de mañana, revistó al pueblo, y subió él, con los ancianos de Israel, delante del pueblo contra Hai."}, {"numero": 11, "texto": "Y toda la gente de guerra que con él estaba, subió, y acercóse, y llegaron delante de la ciudad, y asentaron el campo á la parte del norte de Hai: y el valle estaba entre él y Hai."}, {"numero": 12, "texto": "Y tomó como cinco mil hombres, y púsolos en emboscada entre Beth-el y Hai, á la parte occidental de la ciudad."}, {"numero": 13, "texto": "Y el pueblo, todo el campo que estaba á la parte del norte de la ciudad, colocado ya cerca, y su emboscada al occidente de la ciudad, vínose Josué aquella noche al medio del valle."}, {"numero": 14, "texto": "Lo cual como viese el rey de Hai, levantóse prestamente de mañana, y salió con la gente de la ciudad contra Israel, él y todo su pueblo, para combatir por el llano al tiempo señalado, no sabiendo que le estaba puesta emboscada á las espaldas de la ciudad."}, {"numero": 15, "texto": "Entonces Josué y todo Israel, haciéndose vencidos, huyeron delante de ellos por el camino del desierto."}, {"numero": 16, "texto": "Y todo el pueblo que estaba en Hai se juntó para seguirlos: y siguieron á Josué, siendo así arrancados de la ciudad."}, {"numero": 17, "texto": "Y no quedó hombre en Hai y Beth-el, que no saliera tras de Israel; y por seguir á Israel dejaron la ciudad abierta."}, {"numero": 18, "texto": "Entonces Jehová dijo á Josué: Levanta la lanza que tienes en tu mano hacia Hai, porque yo la entregaré en tu mano. Y Josué levantó hacia la ciudad la lanza que en su mano tenía."}, {"numero": 19, "texto": "Y levantándose prestamente de su lugar los que estaban en la emboscada, corrieron luego que él alzó su mano, y vinieron á la ciudad, y la tomaron, y apresuráronse á prenderle fuego."}, {"numero": 20, "texto": "Y como los de la ciudad miraron atrás, observaron, y he aquí el humo de la ciudad que subía al cielo, y no tuvieron arbitrio para huir ni á una parte ni á otra: y el pueblo que iba huyendo hacia el desierto, se volvió contra los que le seguían."}, {"numero": 21, "texto": "Josué y todo Israel, viendo que los de la emboscada habían tomado la ciudad, y que el humo de la ciudad subía, tornaron, é hirieron á los de Hai."}, {"numero": 22, "texto": "Y los otros salieron de la ciudad á su encuentro: y así fueron encerrados en medio de Israel, los unos de la una parte, y los otros de la otra. Y los hirieron hasta que no quedó ninguno de ellos que escapase."}, {"numero": 23, "texto": "Y tomaron vivo al rey de Hai, y trajéronle á Josué."}, {"numero": 24, "texto": "Y cuando los Israelitas acabaron de matar á todos los moradores de Hai en el campo, en el desierto, donde ellos los habían perseguido, y que todos habían caído á filo de espada hasta ser consumidos, todos los Israelitas se tornaron á Hai, y también la pusieron á cuchillo."}, {"numero": 25, "texto": "Y el número de los que cayeron aquel día, hombres y mujeres, fué doce mil, todos los de Hai."}, {"numero": 26, "texto": "Y Josué no retrajo su mano que había extendido con la lanza, hasta que hubo destruído á todos los moradores de Hai."}, {"numero": 27, "texto": "Empero los Israelitas tomaron para sí las bestias y los despojos de la ciudad, conforme á la palabra de Jehová que él había mandado á Josué."}, {"numero": 28, "texto": "Y Josué quemó á Hai y redújola á un montón perpetuo, asolado hasta hoy."}, {"numero": 29, "texto": "Mas al rey de Hai colgó de un madero hasta la tarde: y como el sol se puso, mandó Josué que quitasen del madero su cuerpo, y lo echasen á la puerta de la ciudad: y levantaron sobre él un gran montón de piedras, hasta hoy."}, {"numero": 30, "texto": "Entonces Josué edificó un altar á Jehová Dios de Israel en el monte de Ebal,"}, {"numero": 31, "texto": "Como Moisés, siervo de Jehová, lo había mandado á los hijos de Israel, como está escrito en el libro de la ley de Moisés, un altar de piedras enteras sobre las cuales nadie alzó hierro: y ofrecieron sobre él holocaustos á Jehová, y sacrificaron víctimas pacíficas."}, {"numero": 32, "texto": "También escribió allí en piedras la repetición de la ley de Moisés, la cual él había escrito delante de los hijos de Israel."}, {"numero": 33, "texto": "Y todo Israel, y sus ancianos, oficiales, y jueces, estaban de la una y de la otra parte junto al arca, delante de los sacerdotes Levitas que llevan el arca del pacto de Jehová; así extranjeros como naturales, la mitad de ellos estaba hacia el monte de Gerizim, y la otra mitad hacia el monte de Ebal; de la manera que Moisés, siervo de Jehová, lo había mandado antes, para que bendijesen primeramente al pueblo de Israel."}, {"numero": 34, "texto": "Después de esto, leyó todas las palabras de la ley, las bendiciones y las maldiciones, conforme á todo lo que está escrito en el libro de la ley."}, {"numero": 35, "texto": "No hubo palabra alguna de todas las cosas que mandó Moisés, que Josué no hiciese leer delante de toda la congregación de Israel, mujeres y niños, y extranjeros que andaban entre ellos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 10, 'pt', '[{"numero": 1, "texto": "E quando Adoni-Zedeque rei de Jerusalém ouviu que Josué havia tomado a Ai, e que a haviam assolado, (como havia feito a Jericó e a seu rei, assim fez a Ai e a seu rei;) e que os moradores de Gibeão fizeram paz com os israelitas, e que estavam entre eles;"}, {"numero": 2, "texto": "Tiveram muito grande temor; porque Gibeão era uma grande cidade, como uma das cidades reais, e maior que Ai, e todos os seus homens fortes."}, {"numero": 3, "texto": "Enviou, pois, a dizer Adoni-Zedeque rei de Jerusalém, a Hoão rei de Hebrom, e a Pirã rei de Jeremote, e a Jafia rei de Laquis, e a Debir rei de Eglom:"}, {"numero": 4, "texto": "Subi a mim, e ajudai-me, e combatamos a Gibeão: porque fez paz com Josué e com os filhos de Israel."}, {"numero": 5, "texto": "E cinco reis dos amorreus, o rei de Jerusalém, o rei de Hebrom, o rei de Jeremote, o rei de Laquis, o rei de Eglom, se juntaram e subiram, eles com todos os seus exércitos, e assentaram acampamento sobre Gibeão, e lutaram contra ela."}, {"numero": 6, "texto": "E os moradores de Gibeão enviaram a dizer a Josué ao acampamento em Gilgal: Não encolhas tuas mãos de teus servos; sobe prontamente a nós para guardar-nos e ajudar-nos: porque todos os reis dos amorreus que habitam nas montanhas, se juntaram contra nós."}, {"numero": 7, "texto": "E subiu Josué de Gilgal, ele e todo aquele povo de guerra com ele, e todos os homens valentes."}, {"numero": 8, "texto": "E o SENHOR disse a Josué: Não tenhas medo deles: porque eu os entreguei em tua mão, e nenhum deles resistirá diante de ti."}, {"numero": 9, "texto": "E Josué veio a eles de repente, toda a noite subiu desde Gilgal."}, {"numero": 10, "texto": "E o SENHOR os perturbou diante de Israel, e feriu-os com grande mortandade em Gibeão: e seguiu-os pelo caminho que sobe a Bete-Horom, e feriu-os até Azeca e Maceda."}, {"numero": 11, "texto": "E quando iam fugindo dos israelitas, à descida de Bete-Horom, o SENHOR lançou sobre eles do céu grandes pedras até Azeca, e morreram: muitos mais morreram das pedras do granizo, que os que os filhos de Israel haviam matado à espada."}, {"numero": 12, "texto": "Então Josué falou ao SENHOR o dia que o SENHOR entregou aos amorreus diante dos filhos de Israel, e disse em presença dos israelitas: Sol, detém-te em Gibeão; E tu, Lua, no vale de Aijalom."}, {"numero": 13, "texto": "E o sol se deteve e a lua se parou, Até tanto que a gente se havia vingado de seus inimigos. Não está este escrito no livro de Jasar? E o sol se parou em meio do céu, e não se apressou a se pôr quase um dia inteiro."}, {"numero": 14, "texto": "E nunca foi tal dia antes nem depois daquele, havendo atendido o SENHOR à voz de um homem: porque o SENHOR lutava por Israel."}, {"numero": 15, "texto": "E Josué, e todo Israel com ele, voltava-se ao acampamento em Gilgal."}, {"numero": 16, "texto": "Porém os cinco reis fugiram, e se esconderam em uma cova em Maquedá."}, {"numero": 17, "texto": "E foi dito a Josué que os cinco reis haviam sido achados em uma cova em Maquedá."}, {"numero": 18, "texto": "Então Josué disse: Rolai grandes pedras à boca da cova, e ponde homens junto a ela que os guardem;"}, {"numero": 19, "texto": "E vós não vos pareis, mas sim segui a vossos inimigos, e feri-lhes a retaguarda, sem deixar-lhes entrar em suas cidades; porque o SENHOR vosso Deus os entregou em vossa mão."}, {"numero": 20, "texto": "E aconteceu que quando Josué e os filhos de Israel acabaram de feri-los com mortandade muito grande, até destruí-los, os que restaram deles se meteram nas cidades fortes."}, {"numero": 21, "texto": "E todo aquele povo se voltou salvo ao acampamento a Josué em Maquedá; que não houve quem movesse sua língua contra os filhos de Israel."}, {"numero": 22, "texto": "Então disse Josué: Abri a boca da cova, e tirai-me dela a estes cinco reis."}, {"numero": 23, "texto": "E fizeram-no assim, e tiraram-lhe da cova aqueles cinco reis: ao rei de Jerusalém, ao rei de Hebrom, ao rei de Jeremote, ao rei de Laquis, ao rei de Eglom."}, {"numero": 24, "texto": "E quando tiraram estes reis a Josué, chamou Josué a todos os homens de Israel, e disse aos principais da gente de guerra que haviam vindo com ele: Chegai e ponde vossos pés sobre os pescoços destes reis. E eles se aproximaram, e puseram seus pés sobre os pescoços deles."}, {"numero": 25, "texto": "E Josué lhes disse: Não temais, nem vos atemorizeis; sede fortes e valentes: porque assim fará o SENHOR a todos vossos inimigos contra os quais lutai."}, {"numero": 26, "texto": "E depois disto Josué os feriu e os matou, e os fez enforcar em cinco madeiros: e restaram enforcados nos madeiros até à tarde."}, {"numero": 27, "texto": "E quando o sol se ia a pôr, mandou Josué que os tirassem dos madeiros, e os lançassem na cova de onde se haviam escondido: e puseram grandes pedras à boca da cova, até hoje."}, {"numero": 28, "texto": "Naquele mesmo dia tomou Josué a Maquedá, e a pôs à espada, e matou a seu rei; a eles e a tudo o que nela tinha vida, sem restar nada: mas ao rei de Maquedá fez como havia feito ao rei de Jericó."}, {"numero": 29, "texto": "E de Maquedá passou Josué, e todo Israel com ele, a Libna; e lutou contra Libna:"}, {"numero": 30, "texto": "E o SENHOR a entregou também a ela, e a seu rei, em mãos de Israel; e feriu-a a fio de espada, com tudo o que nela havia vivo, sem restar nada: mas a seu rei fez da maneira que havia feito ao rei de Jericó."}, {"numero": 31, "texto": "E Josué, e todo Israel com ele, passou de Libna a Laquis, e pôs acampamento contra ela, e combateu-a:"}, {"numero": 32, "texto": "E o SENHOR entregou a Laquis em mão de Israel, e tomou-a ao dia seguinte, e feriu-a à espada, com tudo o que nela havia vivo, como havia feito em Libna."}, {"numero": 33, "texto": "Então Horão, rei de Gezer, subiu em ajuda de Laquis; mas a ele e a seu povo feriu Josué, até não restar nenhum deles."}, {"numero": 34, "texto": "De Laquis passou Josué, e todo Israel com ele, a Eglom: e puseram acampamento contra ela, e combateram-na:"}, {"numero": 35, "texto": "E a tomaram no mesmo dia, e meteram-na à espada; e aquele dia matou a todo o que nela havia vivo, como havia feito em Laquis."}, {"numero": 36, "texto": "Subiu logo Josué, e todo Israel com ele, de Eglom a Hebrom, e combateram-na;"}, {"numero": 37, "texto": "E tomando-a, feriram-na à espada, a seu rei e a todas as suas cidades, com tudo o que nela havia vivo, sem restar nada: como fizeram a Eglom, assim a destruíram com tudo o que nela havia vivo."}, {"numero": 38, "texto": "E voltando-se Josué, e todo Israel com ele, sobre Debir, combateu-a;"}, {"numero": 39, "texto": "E tomou-a, e a seu rei, e a todas as suas vilas; e feriram-nos à espada, e destruíram tudo o que ali dentro havia vivo, sem restar nada; como havia feito a Hebrom, assim fez a Debir e a seu rei; e como havia feito a Libna e a seu rei."}, {"numero": 40, "texto": "Feriu pois Josué toda a região das montanhas, e do sul, e das planícies, e das costas, e a todos os seus reis, sem restar nada; tudo o que tinha vida matou, ao modo que o SENHOR Deus de Israel o havia mandado."}, {"numero": 41, "texto": "E feriu-os Josué desde Cades-Barneia até Gaza, e toda a terra de Gósen até Gibeão."}, {"numero": 42, "texto": "Todos estes reis e suas terras tomou Josué de uma vez; porque o SENHOR o Deus de Israel lutava por Israel."}, {"numero": 43, "texto": "E voltou Josué, e todo Israel com ele, ao acampamento em Gilgal."}]'::jsonb, 'Almeida Livre'),
  ('Js', 10, 'en', '[{"numero": 1, "texto": "Now it came to pass, when Adonizedec king of Jerusalem had heard how Joshua had taken Ai, and had utterly destroyed it; as he had done to Jericho and her king, so he had done to Ai and her king; and how the inhabitants of Gibeon had made peace with Israel, and were among them;"}, {"numero": 2, "texto": "That they feared greatly, because Gibeon was a great city, as one of the royal cities, and because it was greater than Ai, and all the men thereof were mighty."}, {"numero": 3, "texto": "Wherefore Adonizedec king of Jerusalem, sent unto Hoham king of Hebron, and unto Piram king of Jarmuth, and unto Japhia king of Lachish, and unto Debir king of Eglon, saying,"}, {"numero": 4, "texto": "Come up unto me, and help me, that we may smite Gibeon: for it hath made peace with Joshua and with the children of Israel."}, {"numero": 5, "texto": "Therefore the five kings of the Amorites, the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, the king of Eglon, gathered themselves together, and went up, they and all their hosts, and encamped before Gibeon, and made war against it."}, {"numero": 6, "texto": "And the men of Gibeon sent unto Joshua to the camp to Gilgal, saying, Slack not thy hand from thy servants; come up to us quickly, and save us, and help us: for all the kings of the Amorites that dwell in the mountains are gathered together against us."}, {"numero": 7, "texto": "So Joshua ascended from Gilgal, he, and all the people of war with him, and all the mighty men of valour."}, {"numero": 8, "texto": "And the Lord said unto Joshua, Fear them not: for I have delivered them into thine hand; there shall not a man of them stand before thee."}, {"numero": 9, "texto": "Joshua therefore came unto them suddenly, and went up from Gilgal all night."}, {"numero": 10, "texto": "And the Lord discomfited them before Israel, and slew them with a great slaughter at Gibeon, and chased them along the way that goeth up to Bethhoron, and smote them to Azekah, and unto Makkedah."}, {"numero": 11, "texto": "And it came to pass, as they fled from before Israel, and were in the going down to Bethhoron, that the Lord cast down great stones from heaven upon them unto Azekah, and they died: they were more which died with hailstones than they whom the children of Israel slew with the sword."}, {"numero": 12, "texto": "Then spake Joshua to the Lord in the day when the Lord delivered up the Amorites before the children of Israel, and he said in the sight of Israel, Sun, stand thou still upon Gibeon; and thou, Moon, in the valley of Ajalon."}, {"numero": 13, "texto": "And the sun stood still, and the moon stayed, until the people had avenged themselves upon their enemies. Is not this written in the book of Jasher? So the sun stood still in the midst of heaven, and hasted not to go down about a whole day."}, {"numero": 14, "texto": "And there was no day like that before it or after it, that the Lord hearkened unto the voice of a man: for the Lord fought for Israel."}, {"numero": 15, "texto": "And Joshua returned, and all Israel with him, unto the camp to Gilgal."}, {"numero": 16, "texto": "But these five kings fled, and hid themselves in a cave at Makkedah."}, {"numero": 17, "texto": "And it was told Joshua, saying, The five kings are found hid in a cave at Makkedah."}, {"numero": 18, "texto": "And Joshua said, Roll great stones upon the mouth of the cave, and set men by it for to keep them:"}, {"numero": 19, "texto": "And stay ye not, but pursue after your enemies, and smite the hindmost of them; suffer them not to enter into their cities: for the Lord your God hath delivered them into your hand."}, {"numero": 20, "texto": "And it came to pass, when Joshua and the children of Israel had made an end of slaying them with a very great slaughter, till they were consumed, that the rest which remained of them entered into fenced cities."}, {"numero": 21, "texto": "And all the people returned to the camp to Joshua at Makkedah in peace: none moved his tongue against any of the children of Israel."}, {"numero": 22, "texto": "Then said Joshua, Open the mouth of the cave, and bring out those five kings unto me out of the cave."}, {"numero": 23, "texto": "And they did so, and brought forth those five kings unto him out of the cave, the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, and the king of Eglon."}, {"numero": 24, "texto": "And it came to pass, when they brought out those kings unto Joshua, that Joshua called for all the men of Israel, and said unto the captains of the men of war which went with him, Come near, put your feet upon the necks of these kings. And they came near, and put their feet upon the necks of them."}, {"numero": 25, "texto": "And Joshua said unto them, Fear not, nor be dismayed, be strong and of good courage: for thus shall the Lord do to all your enemies against whom ye fight."}, {"numero": 26, "texto": "And afterward Joshua smote them, and slew them, and hanged them on five trees: and they were hanging upon the trees until the evening."}, {"numero": 27, "texto": "And it came to pass at the time of the going down of the sun, that Joshua commanded, and they took them down off the trees, and cast them into the cave wherein they had been hid, and laid great stones in the cave''s mouth, which remain until this very day."}, {"numero": 28, "texto": "And that day Joshua took Makkedah, and smote it with the edge of the sword, and the king thereof he utterly destroyed, them, and all the souls that were therein; he let none remain: and he did to the king of Makkedah as he did unto the king of Jericho."}, {"numero": 29, "texto": "Then Joshua passed from Makkedah, and all Israel with him, unto Libnah, and fought against Libnah:"}, {"numero": 30, "texto": "And the Lord delivered it also, and the king thereof, into the hand of Israel; and he smote it with the edge of the sword, and all the souls that were therein; he let none remain in it; but did unto the king thereof as he did unto the king of Jericho."}, {"numero": 31, "texto": "And Joshua passed from Libnah, and all Israel with him, unto Lachish, and encamped against it, and fought against it:"}, {"numero": 32, "texto": "And the Lord delivered Lachish into the hand of Israel, which took it on the second day, and smote it with the edge of the sword, and all the souls that were therein, according to all that he had done to Libnah."}, {"numero": 33, "texto": "Then Horam king of Gezer came up to help Lachish; and Joshua smote him and his people, until he had left him none remaining."}, {"numero": 34, "texto": "And from Lachish Joshua passed unto Eglon, and all Israel with him; and they encamped against it, and fought against it:"}, {"numero": 35, "texto": "And they took it on that day, and smote it with the edge of the sword, and all the souls that were therein he utterly destroyed that day, according to all that he had done to Lachish."}, {"numero": 36, "texto": "And Joshua went up from Eglon, and all Israel with him, unto Hebron; and they fought against it:"}, {"numero": 37, "texto": "And they took it, and smote it with the edge of the sword, and the king thereof, and all the cities thereof, and all the souls that were therein; he left none remaining, according to all that he had done to Eglon; but destroyed it utterly, and all the souls that were therein."}, {"numero": 38, "texto": "And Joshua returned, and all Israel with him, to Debir; and fought against it:"}, {"numero": 39, "texto": "And he took it, and the king thereof, and all the cities thereof; and they smote them with the edge of the sword, and utterly destroyed all the souls that were therein; he left none remaining: as he had done to Hebron, so he did to Debir, and to the king thereof; as he had done also to Libnah, and to her king."}, {"numero": 40, "texto": "So Joshua smote all the country of the hills, and of the south, and of the vale, and of the springs, and all their kings: he left none remaining, but utterly destroyed all that breathed, as the Lord God of Israel commanded."}, {"numero": 41, "texto": "And Joshua smote them from Kadeshbarnea even unto Gaza, and all the country of Goshen, even unto Gibeon."}, {"numero": 42, "texto": "And all these kings and their land did Joshua take at one time, because the Lord God of Israel fought for Israel."}, {"numero": 43, "texto": "And Joshua returned, and all Israel with him, unto the camp to Gilgal."}]'::jsonb, 'King James Version'),
  ('Js', 10, 'fr', '[{"numero": 1, "texto": "Adoni-Tsédek, roi de Jérusalem, apprit que Josué s''''était emparé d''''Aï et l''''avait dévouée par interdit, qu''''il avait traité Aï et son roi comme il avait traité Jéricho et son roi, et que les habitants de Gabaon avaient fait la paix avec Israël et étaient au milieu d''''eux."}, {"numero": 2, "texto": "Il eut alors une forte crainte; car Gabaon était une grande ville, comme une des villes royales, plus grande même qu''''Aï, et tous ses hommes étaient vaillants."}, {"numero": 3, "texto": "Adoni-Tsédek, roi de Jérusalem, fit dire à Hoham, roi d''''Hébron, à Piream, roi de Jarmuth, à Japhia, roi de Lakis, et à Debir, roi d''''Eglon:"}, {"numero": 4, "texto": "Montez vers moi, et aidez-moi, afin que nous frappions Gabaon, car elle a fait la paix avec Josué et avec les enfants d''''Israël."}, {"numero": 5, "texto": "Cinq rois des Amoréens, le roi de Jérusalem, le roi d''''Hébron, le roi de Jarmuth, le roi de Lakis, le roi d''''Eglon, se réunirent ainsi et montèrent avec toutes leurs armées; ils vinrent camper près de Gabaon, et l''''attaquèrent."}, {"numero": 6, "texto": "Les gens de Gabaon envoyèrent dire à Josué, au camp de Guilgal: N''''abandonne pas tes serviteurs, monte vers nous en hâte, délivre-nous, donne-nous du secours; car tous les rois des Amoréens, qui habitent la montagne, se sont réunis contre nous."}, {"numero": 7, "texto": "Josué monta de Guilgal, lui et tous les gens de guerre avec lui, et tous les vaillants hommes."}, {"numero": 8, "texto": "L''''Eternel dit à Josué: Ne les crains point, car je les livre entre tes mains, et aucun d''''eux ne tiendra devant toi."}, {"numero": 9, "texto": "Josué arriva subitement sur eux, après avoir marché toute la nuit depuis Guilgal."}, {"numero": 10, "texto": "L''''Eternel les mit en déroute devant Israël; et Israël leur fit éprouver une grande défaite près de Gabaon, les poursuivit sur le chemin qui monte à Beth-Horon, et les battit jusqu''''à Azéka et à Makkéda."}, {"numero": 11, "texto": "Comme ils fuyaient devant Israël, et qu''''ils étaient à la descente de Beth-Horon, l''''Eternel fit tomber du ciel sur eux de grosses pierres jusqu''''à Azéka, et ils périrent; ceux qui moururent par les pierres de grêle furent plus nombreux que ceux qui furent tués avec l''''épée par les enfants d''''Israël."}, {"numero": 12, "texto": "Alors Josué parla à l''''Eternel, le jour où l''''Eternel livra les Amoréens aux enfants d''''Israël, et il dit en présence d''''Israël: Soleil, arrête-toi sur Gabaon, Et toi, lune, sur la vallée d''''Ajalon!"}, {"numero": 13, "texto": "Et le soleil s''''arrêta, et la lune suspendit sa course, Jusqu''''à ce que la nation eût tiré vengeance de ses ennemis. Cela n''''est-il pas écrit dans le livre du Juste? Le soleil s''''arrêta au milieu du ciel, Et ne se hâta point de se coucher, presque tout un jour."}, {"numero": 14, "texto": "Il n''''y a point eu de jour comme celui-là, ni avant ni après, où l''''Eternel ait écouté la voix d''''un homme; car l''''Eternel combattait pour Israël."}, {"numero": 15, "texto": "Et Josué, et tout Israël avec lui, retourna au camp à Guilgal."}, {"numero": 16, "texto": "Les cinq rois s''''enfuirent, et se cachèrent dans une caverne à Makkéda."}, {"numero": 17, "texto": "On le rapporta à Josué, en disant: Les cinq rois se trouvent cachés dans une caverne à Makkéda."}, {"numero": 18, "texto": "Josué dit: Roulez de grosses pierres à l''''entrée de la caverne, et mettez-y des hommes pour les garder."}, {"numero": 19, "texto": "Et vous, ne vous arrêtez pas, poursuivez vos ennemis, et attaquez-les par derrière; ne les laissez pas entrer dans leurs villes, car l''''Eternel, votre Dieu, les a livrés entre vos mains."}, {"numero": 20, "texto": "Après que Josué et les enfants d''''Israël leur eurent fait éprouver une très grande défaite, et les eurent complètement battus, ceux qui purent échapper se sauvèrent dans les villes fortifiées,"}, {"numero": 21, "texto": "et tout le peuple revint tranquillement au camp vers Josué à Makkéda, sans que personne remuât sa langue contre les enfants d''''Israël."}, {"numero": 22, "texto": "Josué dit alors: Ouvrez l''''entrée de la caverne, faites-en sortir ces cinq rois, et amenez-les-moi."}, {"numero": 23, "texto": "Ils firent ainsi, et lui amenèrent les cinq rois qu''''ils avaient fait sortir de la caverne, le roi de Jérusalem, le roi d''''Hébron, le roi de Jarmuth, le roi de Lakis, le roi d''''Eglon."}, {"numero": 24, "texto": "Lorsqu''''ils eurent amené ces rois devant Josué, Josué appela tous les hommes d''''Israël, et dit aux chefs des gens de guerre qui avaient marché avec lui: Approchez-vous, mettez vos pieds sur les cous de ces rois. Ils s''''approchèrent, et ils mirent les pieds sur leurs cous."}, {"numero": 25, "texto": "Josué leur dit: Ne craignez point et ne vous effrayez point, fortifiez-vous et ayez du courage, car c''''est ainsi que l''''Eternel traitera tous vos ennemis contre lesquels vous combattez."}, {"numero": 26, "texto": "Après cela, Josué les frappa et les fit mourir; il les pendit à cinq arbres, et ils restèrent pendus aux arbres jusqu''''au soir."}, {"numero": 27, "texto": "Vers le coucher du soleil, Josué ordonna qu''''on les descendît des arbres, on les jeta dans la caverne où ils s''''étaient cachés, et l''''on mit à l''''entrée de la caverne de grosses pierres, qui y sont demeurées jusqu''''à ce jour."}, {"numero": 28, "texto": "Josué prit Makkéda le même jour, et la frappa du tranchant de l''''épée; il dévoua par interdit le roi, la ville et tous ceux qui s''''y trouvaient; il n''''en laissa échapper aucun, et il traita le roi de Makkéda comme il avait traité le roi de Jéricho."}, {"numero": 29, "texto": "Josué, et tout Israël avec lui, passa de Makkéda à Libna, et il attaqua Libna."}, {"numero": 30, "texto": "L''''Eternel la livra aussi, avec son roi, entre les mains d''''Israël, et la frappa du tranchant de l''''épée, elle et tous ceux qui s''''y trouvaient; il n''''en laissa échapper aucun, et il traita son roi comme il avait traité le roi de Jéricho."}, {"numero": 31, "texto": "Josué, et tout Israël avec lui, passa de Libna à Lakis; il campa devant elle, et il l''''attaqua."}, {"numero": 32, "texto": "L''''Eternel livra Lakis entre les mains d''''Israël, qui la prit le second jour, et la frappa du tranchant de l''''épée, elle et tous ceux qui s''''y trouvaient, comme il avait traité Libna."}, {"numero": 33, "texto": "Alors Horam, roi de Guézer, monta pour secourir Lakis. Josué le battit, lui et son peuple, sans laisser échapper personne."}, {"numero": 34, "texto": "Josué, et tout Israël avec lui, passa de Lakis à Eglon; ils campèrent devant elle, et ils l''''attaquèrent."}, {"numero": 35, "texto": "Ils la prirent le même jour, et la frappèrent du tranchant de l''''épée, elle et tous ceux qui s''''y trouvaient; Josué la dévoua par interdit le jour même, comme il avait traité Lakis."}, {"numero": 36, "texto": "Josué, et tout Israël avec lui, monta d''''Eglon à Hébron, et ils l''''attaquèrent."}, {"numero": 37, "texto": "Ils la prirent, et la frappèrent du tranchant de l''''épée, elle, son roi, toutes les villes qui en dépendaient, et tous ceux qui s''''y trouvaient; Josué n''''en laissa échapper aucun, comme il avait fait à Eglon, et il la dévoua par interdit avec tous ceux qui s''''y trouvaient."}, {"numero": 38, "texto": "Josué, et tout Israël avec lui, se dirigea sur Debir, et il l''''attaqua."}, {"numero": 39, "texto": "Il la prit, elle, son roi, et toutes les villes qui en dépendaient; ils les frappèrent du tranchant de l''''épée, et ils dévouèrent par interdit tous ceux qui s''''y trouvaient, sans en laisser échapper aucun; Josué traita Debir et son roi comme il avait traité Hébron et comme il avait traité Libna et son roi."}, {"numero": 40, "texto": "Josué battit tout le pays, la montagne, le midi, la plaine et les coteaux, et il en battit tous les rois; il ne laissa échapper personne, et il dévoua par interdit tout ce qui respirait, comme l''''avait ordonné l''''Eternel, le Dieu d''''Israël."}, {"numero": 41, "texto": "Josué les battit de Kadès-Barnéa à Gaza, il battit tout le pays de Gosen jusqu''''à Gabaon."}, {"numero": 42, "texto": "Josué prit en même temps tous ces rois et leur pays, car l''''Eternel, le Dieu d''''Israël, combattait pour Israël."}, {"numero": 43, "texto": "Et Josué, et tout Israël avec lui, retourna au camp à Guilgal."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 10, 'es', '[{"numero": 1, "texto": "Y COMO Adonisedec rey de Jerusalem oyó que Josué había tomado á Hai, y que la había asolado, (como había hecho á Jericó y á su rey, así hizo á Hai y á su rey;) y que los moradores de Gabaón habían hecho paz con los Israelitas, y que estaban entre ellos;"}, {"numero": 2, "texto": "Tuvieron muy gran temor; porque Gabaón era una gran ciudad, como una de las ciudades reales, y mayor que Hai, y todos sus hombres fuertes."}, {"numero": 3, "texto": "Envió pues á decir Adonisedec rey de Jerusalem, á Oham rey de Hebrón, y á Phiream rey de Jerimoth, y á Japhia rey de Lachîs, y á Debir rey de Eglón:"}, {"numero": 4, "texto": "Subid á mí, y ayudadme, y combatamos á Gabaón: porque ha hecho paz con Josué y con los hijos de Israel."}, {"numero": 5, "texto": "Y cinco reyes de los Amorrheos, el rey de Jerusalem, el rey de Hebrón, el rey de Jerimoth, el rey de Lachîs, el rey de Eglón, se juntaron y subieron, ellos con todos sus ejércitos, y asentaron campo sobre Gabaón, y pelearon contra ella."}, {"numero": 6, "texto": "Y los moradores de Gabaón enviaron á decir á Josué al campo en Gilgal: No encojas tus manos de tus siervos; sube prestamente á nosotros para guardarnos y ayudarnos: porque todos los reyes de los Amorrheos que habitan en las montañas, se han juntado contra nosotros."}, {"numero": 7, "texto": "Y subió Josué de Gilgal, él y todo el pueblo de guerra con él, y todos los hombres valientes."}, {"numero": 8, "texto": "Y Jehová dijo á Josué: No tengas temor de ellos: porque yo los he entregado en tu mano, y ninguno de ellos parará delante de ti."}, {"numero": 9, "texto": "Y Josué vino á ellos de repente, toda la noche subió desde Gilgal."}, {"numero": 10, "texto": "Y Jehová los turbó delante de Israel, é hiriólos con gran mortandad en Gabaón: y siguiólos por el camino que sube á Beth-oron, é hiriólos hasta Azeca y Maceda."}, {"numero": 11, "texto": "Y como iban huyendo de los Israelitas, á la bajada de Beth-oron, Jehová echó sobre ellos del cielo grandes piedras hasta Azeca, y murieron: muchos más murieron de las piedras del granizo, que los que los hijos de Israel habían muerto á cuchillo."}, {"numero": 12, "texto": "Entonces Josué habló á Jehová el día que Jehová entregó al Amorrheo delante de los hijos de Israel, y dijo en presencia de los Israelitas: Sol, detente en Gabaón; y tú, Luna, en el valle de Ajalón."}, {"numero": 13, "texto": "Y el sol se detuvo y la luna se paró, hasta tanto que la gente se hubo vengado de sus enemigos. ¿No está aquesto escrito en el libro de Jasher? Y el sol se paró en medio del cielo, y no se apresuró á ponerse casi un día entero."}, {"numero": 14, "texto": "Y nunca fué tal día antes ni después de aquél, habiendo atendido Jehová á la voz de un hombre: porque Jehová peleaba por Israel."}, {"numero": 15, "texto": "Y Josué, y todo Israel con él, volvíase al campo en Gilgal."}, {"numero": 16, "texto": "Pero los cinco reyes huyeron, y se escondieron en una cueva en Maceda."}, {"numero": 17, "texto": "Y fué dicho á Josué que los cinco reyes habían sido hallados en una cueva en Maceda."}, {"numero": 18, "texto": "Entonces Josué dijo: Rodad grandes piedras á la boca de la cueva, y poned hombres junto á ella que los guarden;"}, {"numero": 19, "texto": "Y vosotros no os paréis, sino seguid á vuestros enemigos, y heridles la retaguardia, sin dejarles entrar en sus ciudades; porque Jehová vuestro Dios los ha entregado en vuestra mano."}, {"numero": 20, "texto": "Y aconteció que como Josué y los hijos de Israel hubieron acabado de herirlos con mortandad muy grande, hasta destruirlos, los que quedaron de ellos se metieron en las ciudades fuertes."}, {"numero": 21, "texto": "Y todo el pueblo se volvió salvo al campo á Josué en Maceda; que no hubo quien moviese su lengua contra los hijos de Israel."}, {"numero": 22, "texto": "Entonces dijo Josué: Abrid la boca de la cueva, y sacadme de ella á estos cinco reyes."}, {"numero": 23, "texto": "E hiciéronlo así, y sacáronle de la cueva aquellos cinco reyes: al rey de Jerusalem, al rey de Hebrón, al rey de Jerimoth, al rey de Lachîs, al rey de Eglón."}, {"numero": 24, "texto": "Y cuando hubieron sacado estos reyes á Josué, llamó Josué á todos los varones de Israel, y dijo á los principales de la gente de guerra que habían venido con él: Llegad y poned vuestros pies sobre los pescuezos de aquestos reyes. Y ellos se llegaron, y pusieron sus pies sobre los pescuezos de ellos."}, {"numero": 25, "texto": "Y Josué les dijo: No temáis, ni os atemoricéis; sed fuertes y valientes: porque así hará Jehová á todos vuestros enemigos contra los cuales peleáis."}, {"numero": 26, "texto": "Y después de esto Josué los hirió y los mató, é hízolos colgar en cinco maderos: y quedaron colgados en los maderos hasta la tarde."}, {"numero": 27, "texto": "Y cuando el sol se iba á poner, mandó Josué que los quitasen de los maderos, y los echasen en la cueva donde se habían escondido: y pusieron grandes piedras á la boca de la cueva, hasta hoy."}, {"numero": 28, "texto": "En aquel mismo día tomó Josué á Maceda, y la puso á cuchillo, y mató á su rey; á ellos y á todo lo que en ella tenía vida, sin quedar nada: mas al rey de Maceda hizo como había hecho al rey de Jericó."}, {"numero": 29, "texto": "Y de Maceda pasó Josué, y todo Israel con él, á Libna; y peleó contra Libna:"}, {"numero": 30, "texto": "Y Jehová la entregó también á ella, y á su rey, en manos de Israel; y metióla á filo de espada, con todo lo que en ella había vivo, sin quedar nada: mas á su rey hizo de la manera que había hecho al rey de Jericó."}, {"numero": 31, "texto": "Y Josué, y todo Israel con él, pasó de Libna á Lachîs, y puso campo contra ella, y combatióla:"}, {"numero": 32, "texto": "Y Jehová entregó á Lachîs en mano de Israel, y tomóla al día siguiente, y metióla á cuchillo, con todo lo que en ella había vivo, como había hecho en Libna."}, {"numero": 33, "texto": "Entonces Horam, rey de Gezer, subió en ayuda de Lachîs; mas á él y á su pueblo hirió Josué, hasta no quedar ninguno de ellos."}, {"numero": 34, "texto": "De Lachîs pasó Josué, y todo Israel con él, á Eglón: y pusieron campo contra ella, y combatiéronla:"}, {"numero": 35, "texto": "Y la tomaron el mismo día, y metiéronla á cuchillo; y aquel día mató á todo lo que en ella había vivo, como había hecho en Lachîs."}, {"numero": 36, "texto": "Subió luego Josué, y todo Israel con él, de Eglón á Hebrón, y combatiéronla;"}, {"numero": 37, "texto": "Y tomándola, la metieron á cuchillo, á su rey y á todas sus ciudades, con todo lo que en ella había vivo, sin quedar nada: como habían hecho á Eglón, así la destruyeron con todo lo que en ella había vivo."}, {"numero": 38, "texto": "Y volviéndose Josué, y todo Israel con él, sobre Debir, combatióla;"}, {"numero": 39, "texto": "Y tomóla, y á su rey, y á todas sus villas; y metiéronlos á cuchillo, y destruyeron todo lo que allí dentro había vivo, sin quedar nada: como había hecho á Hebrón, así hizo á Debir y á su rey; y como había hecho á Libna y á su rey."}, {"numero": 40, "texto": "Hirió pues Josué toda la región de las montañas, y del mediodía, y de los llanos, y de las cuestas, y á todos sus reyes, sin quedar nada; todo lo que tenía vida mató, al modo que Jehová Dios de Israel lo había mandado."}, {"numero": 41, "texto": "E hiriólos Josué desde Cades-barnea hasta Gaza, y toda la tierra de Gosén hasta Gabaón."}, {"numero": 42, "texto": "Todos estos reyes y sus tierras tomó Josué de una vez; porque Jehová el Dios de Israel peleaba por Israel."}, {"numero": 43, "texto": "Y tornóse Josué, y todo Israel con él, al campo en Gilgal."}]'::jsonb, 'Reina-Valera 1909'),
  ('Js', 24, 'pt', '[{"numero": 1, "texto": "E juntando Josué todas as tribos de Israel em Siquém, chamou aos anciãos de Israel, e a seus príncipes, a seus juízes, e a seus oficiais; e apresentaram-se diante de Deus."}, {"numero": 2, "texto": "E disse Josué a todo o povo: Assim diz o SENHOR, Deus de Israel: Vossos pais habitaram antigamente da outra parte do rio, a saber, Terá, pai de Abraão e de Naor; e serviam a deuses estranhos."}, {"numero": 3, "texto": "E eu tomei a vosso pai Abraão da outra parte do rio, e trouxe-o por toda a terra de Canaã, e aumentei sua geração, e dei-lhe a Isaque."}, {"numero": 4, "texto": "E a Isaque dei a Jacó e a Esaú: e a Esaú dei o monte de Seir, que o possuísse: mas Jacó e seus filhos desceram ao Egito."}, {"numero": 5, "texto": "E eu enviei a Moisés e a Arão, e feri ao Egito, ao modo que o fiz em meio dele, e depois vos tirei."}, {"numero": 6, "texto": "E tirei a vossos pais do Egito: e quando chegaram ao mar, os egípcios seguiram a vossos pais até o mar Vermelho com carros e cavalaria."}, {"numero": 7, "texto": "E quando eles clamaram ao SENHOR, ele pôs escuridão entre vós e os egípcios, e fez vir sobre eles o mar, a qual os cobriu: e vossos olhos viram o que fiz em Egito. Depois estivestes muitos dias no deserto."}, {"numero": 8, "texto": "E vos introduzi na terra dos amorreus, que habitavam da outra parte do Jordão, os quais lutaram contra vós; mas eu os entreguei em vossas mãos, e possuístes sua terra, e os destruí de diante de vós."}, {"numero": 9, "texto": "E levantou-se depois Balaque filho de Zipor, rei dos moabitas, e lutou contra Israel; e mandou chamar a Balaão filho de Beor, para que vos amaldiçoasse."}, {"numero": 10, "texto": "Mas eu não quis escutar a Balaão, antes vos abençoou repetidamente, e vos livre de suas mãos."}, {"numero": 11, "texto": "E passado o Jordão, viestes a Jericó; e os moradores de Jericó lutaram contra vós: os amorreus, perizeus, cananeus, heteus, girgaseus, heveus, e jebuseus: e eu os entreguei em vossas mãos."}, {"numero": 12, "texto": "E enviei vespas diante de vós, os quais os expulsaram de diante de vós, a saber, aos dois reis dos amorreus; não com tua espada, nem com teu arco."}, {"numero": 13, "texto": "E vos dei a terra pela qual nada trabalhastes, e as cidades que não edificastes, nas quais morais; e das vinhas e olivais que não plantastes, comeis."}, {"numero": 14, "texto": "Agora, pois, temei ao SENHOR, e servi-o com integridade e em verdade; e tirai do meio os deuses aos quais serviram vossos pais da outra parte do rio, e em Egito; e servi ao SENHOR."}, {"numero": 15, "texto": "E se mal vos parece servir ao SENHOR, escolhei hoje a quem sirvais; se aos deuses a os quais serviram vossos pais, quando estiveram da outra parte do rio, ou aos deuses dos amorreus em cuja terra habitais: que eu e minha casa serviremos ao SENHOR."}, {"numero": 16, "texto": "Então o povo respondeu, e disse: Nunca tal aconteça que deixemos ao SENHOR para servir a outros deuses:"}, {"numero": 17, "texto": "Porque o SENHOR nosso Deus é o que tirou a nós e a nossos pais da terra do Egito, da casa de escravidão; o qual diante de nossos olhos fez estas grandes sinais, e nos guardou por todo o caminho por onde andamos, e em todos os povos por entre os quais passamos."}, {"numero": 18, "texto": "E o SENHOR expulsou de diante de nós a todos os povos, e aos amorreus que habitavam na terra: nós, pois, também serviremos ao SENHOR, porque ele é nosso Deus."}, {"numero": 19, "texto": "Então Josué disse ao povo: Não podereis servir ao SENHOR, porque ele é Deus santo, e Deus zeloso; não tolerará vossas rebeliões e vossos pecados."}, {"numero": 20, "texto": "Se deixardes ao SENHOR e servirdes a deuses alheios, se voltará, e vos maltratará, e vos consumirá, depois que vos fez bem."}, {"numero": 21, "texto": "O povo então disse a Josué: Não, antes ao SENHOR serviremos."}, {"numero": 22, "texto": "E Josué respondeu ao povo: Vós sois testemunhas contra vós mesmos, de que escolhestes para vós ao SENHOR para servir-lhe. E eles responderam: Testemunhas somos."}, {"numero": 23, "texto": "Tirai, pois, agora os deuses alheios que estão entre vós, e inclinai vosso coração ao SENHOR Deus de Israel."}, {"numero": 24, "texto": "E o povo respondeu a Josué: Ao SENHOR nosso Deus serviremos, e à sua voz obedeceremos."}, {"numero": 25, "texto": "Então Josué fez aliança com o povo o mesmo dia, e pôs-lhe ordenanças e leis em Siquém."}, {"numero": 26, "texto": "E escreveu Josué estas palavras no livro da lei de Deus; e tomando uma grande pedra, levantou-a ali debaixo de um carvalho que estava junto ao santuário do SENHOR."}, {"numero": 27, "texto": "E disse Josué a todo o povo: Eis que esta pedra será entre nós por testemunha, a qual ouviu todas as palavras do SENHOR que ele falou conosco: será, pois, testemunha contra vós, para que não mintais contra vosso Deus."}, {"numero": 28, "texto": "E enviou Josué ao povo, cada um à sua herança."}, {"numero": 29, "texto": "E depois destas coisas morreu Josué, filho de Num, servo do SENHOR sendo de cento e dez anos."}, {"numero": 30, "texto": "E enterraram-no no termo de sua possessão em Timnate-Sera, que está no monte de Efraim, ao norte do monte de Gaás."}, {"numero": 31, "texto": "E serviu Israel ao SENHOR todo o tempo de Josué, e todo o tempo dos anciãos que viveram depois de Josué, e que sabiam todas as obras do SENHOR, que havia feito por Israel."}, {"numero": 32, "texto": "E enterraram em Siquém os ossos de José que os filhos de Israel haviam trazido do Egito, na parte do campo que Jacó comprou dos filhos de Hamor, pai de Siquém, por cem peças de prata; e foi em possessão aos filhos de José."}, {"numero": 33, "texto": "Também morreu Eleazar, filho de Arão; ao qual enterraram no morro de Fineias seu filho, que lhe foi dado no monte de Efraim."}]'::jsonb, 'Almeida Livre'),
  ('Js', 24, 'en', '[{"numero": 1, "texto": "And Joshua gathered all the tribes of Israel to Shechem, and called for the elders of Israel, and for their heads, and for their judges, and for their officers; and they presented themselves before God."}, {"numero": 2, "texto": "And Joshua said unto all the people, Thus saith the Lord God of Israel, Your fathers dwelt on the other side of the flood in old time, even Terah, the father of Abraham, and the father of Nachor: and they served other gods."}, {"numero": 3, "texto": "And I took your father Abraham from the other side of the flood, and led him throughout all the land of Canaan, and multiplied his seed, and gave him Isaac."}, {"numero": 4, "texto": "And I gave unto Isaac Jacob and Esau: and I gave unto Esau mount Seir, to possess it; but Jacob and his children went down into Egypt."}, {"numero": 5, "texto": "I sent Moses also and Aaron, and I plagued Egypt, according to that which I did among them: and afterward I brought you out."}, {"numero": 6, "texto": "And I brought your fathers out of Egypt: and ye came unto the sea; and the Egyptians pursued after your fathers with chariots and horsemen unto the Red sea."}, {"numero": 7, "texto": "And when they cried unto the Lord, he put darkness between you and the Egyptians, and brought the sea upon them, and covered them; and your eyes have seen what I have done in Egypt: and ye dwelt in the wilderness a long season."}, {"numero": 8, "texto": "And I brought you into the land of the Amorites, which dwelt on the other side Jordan; and they fought with you: and I gave them into your hand, that ye might possess their land; and I destroyed them from before you."}, {"numero": 9, "texto": "Then Balak the son of Zippor, king of Moab, arose and warred against Israel, and sent and called Balaam the son of Beor to curse you:"}, {"numero": 10, "texto": "But I would not hearken unto Balaam; therefore he blessed you still: so I delivered you out of his hand."}, {"numero": 11, "texto": "And you went over Jordan, and came unto Jericho: and the men of Jericho fought against you, the Amorites, and the Perizzites, and the Canaanites, and the Hittites, and the Girgashites, the Hivites, and the Jebusites; and I delivered them into your hand."}, {"numero": 12, "texto": "And I sent the hornet before you, which drave them out from before you, even the two kings of the Amorites; but not with thy sword, nor with thy bow."}, {"numero": 13, "texto": "And I have given you a land for which ye did not labour, and cities which ye built not, and ye dwell in them; of the vineyards and oliveyards which ye planted not do ye eat."}, {"numero": 14, "texto": "Now therefore fear the Lord, and serve him in sincerity and in truth: and put away the gods which your fathers served on the other side of the flood, and in Egypt; and serve ye the Lord."}, {"numero": 15, "texto": "And if it seem evil unto you to serve the Lord, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the Lord."}, {"numero": 16, "texto": "And the people answered and said, God forbid that we should forsake the Lord, to serve other gods;"}, {"numero": 17, "texto": "For the Lord our God, he it is that brought us up and our fathers out of the land of Egypt, from the house of bondage, and which did those great signs in our sight, and preserved us in all the way wherein we went, and among all the people through whom we passed:"}, {"numero": 18, "texto": "And the Lord drave out from before us all the people, even the Amorites which dwelt in the land: therefore will we also serve the Lord; for he is our God."}, {"numero": 19, "texto": "And Joshua said unto the people, Ye cannot serve the Lord: for he is an holy God; he is a jealous God; he will not forgive your transgressions nor your sins."}, {"numero": 20, "texto": "If ye forsake the Lord, and serve strange gods, then he will turn and do you hurt, and consume you, after that he hath done you good."}, {"numero": 21, "texto": "And the people said unto Joshua, Nay; but we will serve the Lord."}, {"numero": 22, "texto": "And Joshua said unto the people, Ye are witnesses against yourselves that ye have chosen you the Lord, to serve him. And they said, We are witnesses."}, {"numero": 23, "texto": "Now therefore put away, said he, the strange gods which are among you, and incline your heart unto the Lord God of Israel."}, {"numero": 24, "texto": "And the people said unto Joshua, The Lord our God will we serve, and his voice will we obey."}, {"numero": 25, "texto": "So Joshua made a covenant with the people that day, and set them a statute and an ordinance in Shechem."}, {"numero": 26, "texto": "And Joshua wrote these words in the book of the law of God, and took a great stone, and set it up there under an oak, that was by the sanctuary of the Lord."}, {"numero": 27, "texto": "And Joshua said unto all the people, Behold, this stone shall be a witness unto us; for it hath heard all the words of the Lord which he spake unto us: it shall be therefore a witness unto you, lest ye deny your God."}, {"numero": 28, "texto": "So Joshua let the people depart, every man unto his inheritance."}, {"numero": 29, "texto": "And it came to pass after these things, that Joshua the son of Nun, the servant of the Lord, died, being an hundred and ten years old."}, {"numero": 30, "texto": "And they buried him in the border of his inheritance in Timnathserah, which is in mount Ephraim, on the north side of the hill of Gaash."}, {"numero": 31, "texto": "And Israel served the Lord all the days of Joshua, and all the days of the elders that overlived Joshua, and which had known all the works of the Lord, that he had done for Israel."}, {"numero": 32, "texto": "And the bones of Joseph, which the children of Israel brought up out of Egypt, buried they in Shechem, in a parcel of ground which Jacob bought of the sons of Hamor the father of Shechem for an hundred pieces of silver: and it became the inheritance of the children of Joseph."}, {"numero": 33, "texto": "And Eleazar the son of Aaron died; and they buried him in a hill that pertained to Phinehas his son, which was given him in mount Ephraim."}]'::jsonb, 'King James Version'),
  ('Js', 24, 'fr', '[{"numero": 1, "texto": "Josué assembla toutes les tribus d''''Israël à Sichem, et il convoqua les anciens d''''Israël, ses chefs, ses juges et ses officiers. Et ils se présentèrent devant Dieu."}, {"numero": 2, "texto": "Josué dit à tout le peuple: Ainsi parle l''''Eternel, le Dieu d''''Israël: Vos pères, Térach, père d''''Abraham et père de Nachor, habitaient anciennement de l''''autre côté du fleuve, et ils servaient d''''autres dieux."}, {"numero": 3, "texto": "Je pris votre père Abraham de l''''autre côté du fleuve, et je lui fis parcourir tout le pays de Canaan; je multipliai sa postérité, et je lui donnai Isaac."}, {"numero": 4, "texto": "Je donnai à Isaac Jacob et Esaü, et je donnai en propriété à Esaü la montagne de Séir, mais Jacob et ses fils descendirent en Egypte."}, {"numero": 5, "texto": "J''''envoyai Moïse et Aaron, et je frappai l''''Egypte par les prodiges que j''''opérai au milieu d''''elle; puis je vous en fis sortir."}, {"numero": 6, "texto": "Je fis sortir vos pères de l''''Egypte, et vous arrivâtes à la mer. Les Egyptiens poursuivirent vos pères jusqu''''à la mer Rouge, avec des chars et des cavaliers."}, {"numero": 7, "texto": "Vos pères crièrent à l''''Eternel. Et l''''Eternel mit des ténèbres entre vous et les Egyptiens, il ramena sur eux la mer, et elle les couvrit. Vos yeux ont vu ce que j''''ai fait aux Egyptiens. Et vous restâtes longtemps dans le désert."}, {"numero": 8, "texto": "Je vous conduisis dans le pays des Amoréens, qui habitaient de l''''autre côté du Jourdain, et ils combattirent contre vous. Je les livrai entre vos mains; vous prîtes possession de leur pays, et je les détruisis devant vous."}, {"numero": 9, "texto": "Balak, fils de Tsippor, roi de Moab, se leva et combattit Israël. Il fit appeler Balaam, fils de Beor, pour qu''''il vous maudît."}, {"numero": 10, "texto": "Mais je ne voulus point écouter Balaam; il vous bénit, et je vous délivrai de la main de Balak."}, {"numero": 11, "texto": "Vous passâtes le Jourdain, et vous arrivâtes à Jéricho. Les habitants de Jéricho combattirent contre vous, les Amoréens, les Phéréziens, les Cananéens, les Héthiens, les Guirgasiens, les Héviens et les Jébusiens. Je les livrai entre vos mains,"}, {"numero": 12, "texto": "et j''''envoyai devant vous les frelons, qui les chassèrent loin de votre face, comme les deux rois des Amoréens: ce ne fut ni par ton épée, ni par ton arc."}, {"numero": 13, "texto": "Je vous donnai un pays que vous n''''aviez point cultivé, des villes que vous n''''aviez point bâties et que vous habitez, des vignes et des oliviers que vous n''''aviez point plantés et qui vous servent de nourriture."}, {"numero": 14, "texto": "Maintenant, craignez l''''Eternel, et servez-le avec intégrité et fidélité. Faites disparaître les dieux qu''''ont servis vos pères de l''''autre côté du fleuve et en Egypte, et servez l''''Eternel."}, {"numero": 15, "texto": "Et si vous ne trouvez pas bon de servir l''''Eternel, choisissez aujourd''''hui qui vous voulez servir, ou les dieux que servaient vos pères au delà du fleuve, ou les dieux des Amoréens dans le pays desquels vous habitez. Moi et ma maison, nous servirons l''''Eternel."}, {"numero": 16, "texto": "Le peuple répondit, et dit: Loin de nous la pensée d''''abandonner l''''Eternel, et de servir d''''autres dieux!"}, {"numero": 17, "texto": "Car l''''Eternel est notre Dieu; c''''est lui qui nous a fait sortir du pays d''''Egypte, de la maison de servitude, nous et nos pères; c''''est lui qui a opéré sous nos yeux ces grands prodiges, et qui nous a gardés pendant toute la route que nous avons suivie et parmi tous les peuples au milieu desquels nous avons passé."}, {"numero": 18, "texto": "Il a chassé devant nous tous les peuples, et les Amoréens qui habitaient ce pays. Nous aussi, nous servirons l''''Eternel, car il est notre Dieu."}, {"numero": 19, "texto": "Josué dit au peuple: Vous n''''aurez pas la force de servir l''''Eternel, car c''''est un Dieu saint, c''''est un Dieu jaloux; il ne pardonnera point vos transgressions et vos péchés."}, {"numero": 20, "texto": "Lorsque vous abandonnerez l''''Eternel et que vous servirez des dieux étrangers, il reviendra vous faire du mal, et il vous consumera après vous avoir fait du bien."}, {"numero": 21, "texto": "Le peuple dit à Josué: Non! car nous servirons l''''Eternel."}, {"numero": 22, "texto": "Josué dit au peuple: Vous êtes témoins contre vous-mêmes que c''''est vous qui avez choisi l''''Eternel pour le servir. Ils répondirent: Nous en sommes témoins."}, {"numero": 23, "texto": "Otez donc les dieux étrangers qui sont au milieu de vous, et tournez votre coeur vers l''''Eternel, le Dieu d''''Israël."}, {"numero": 24, "texto": "Et le peuple dit à Josué: Nous servirons l''''Eternel, notre Dieu, et nous obéirons à sa voix."}, {"numero": 25, "texto": "Josué fit en ce jour une alliance avec le peuple, et lui donna des lois et des ordonnances, à Sichem."}, {"numero": 26, "texto": "Josué écrivit ces choses dans le livre de la loi de Dieu. Il prit une grande pierre, qu''''il dressa là sous le chêne qui était dans le lieu consacré à l''''Eternel."}, {"numero": 27, "texto": "Et Josué dit à tout le peuple: Voici, cette pierre servira de témoin contre nous, car elle a entendu toutes les paroles que l''''Eternel nous a dites; elle servira de témoin contre vous, afin que vous ne soyez pas infidèles à votre Dieu."}, {"numero": 28, "texto": "Puis Josué renvoya le peuple, chacun dans son héritage."}, {"numero": 29, "texto": "Après ces choses, Josué, fils de Nun, serviteur de l''''Eternel, mourut, âgé de cent dix ans."}, {"numero": 30, "texto": "On l''''ensevelit dans le territoire qu''''il avait eu en partage, à Thimnath-Sérach, dans la montagne d''''Ephraïm, au nord de la montagne de Gaasch."}, {"numero": 31, "texto": "Israël servit l''''Eternel pendant toute la vie de Josué, et pendant toute la vie des anciens qui survécurent à Josué et qui connaissaient tout ce que l''''Eternel avait fait en faveur d''''Israël."}, {"numero": 32, "texto": "Les os de Joseph, que les enfants d''''Israël avaient rapportés d''''Egypte, furent enterrés à Sichem, dans la portion du champ que Jacob avait achetée des fils de Hamor, père de Sichem, pour cent kesita, et qui appartint à l''''héritage des fils de Joseph."}, {"numero": 33, "texto": "Eléazar, fils d''''Aaron, mourut, et on l''''enterra à Guibeath-Phinées, qui avait été donnée à son fils Phinées, dans la montagne d''''Ephraïm."}]'::jsonb, 'Louis Segond 1910'),
  ('Js', 24, 'es', '[{"numero": 1, "texto": "Y JUNTANDO Josué todas las tribus de Israel en Sichêm, llamó á los ancianos de Israel, y á sus príncipes, á sus jueces, y á sus oficiales; y presentáronse delante de Dios."}, {"numero": 2, "texto": "Y dijo Josué á todo el pueblo: Así dice Jehová, Dios de Israel: Vuestros padres habitaron antiguamente de esotra parte del río, es á saber, Tharé, padre de Abraham y de Nachôr; y servían á dioses extraños."}, {"numero": 3, "texto": "Y yo tomé á vuestro padre Abraham de la otra parte del río, y trájelo por toda la tierra de Canaán, y aumenté su generación, y díle á Isaac."}, {"numero": 4, "texto": "Y á Isaac dí á Jacob y á Esaú: y á Esaú dí el monte de Seir, que lo poseyese: mas Jacob y sus hijos descendieron á Egipto."}, {"numero": 5, "texto": "Y yo envié á Moisés y á Aarón, y herí á Egipto, al modo que lo hice en medio de él, y después os saqué."}, {"numero": 6, "texto": "Y saqué á vuestros padres de Egipto: y como llegaron á la mar, los Egipcios siguieron á vuestros padres hasta el mar Bermejo con carros y caballería."}, {"numero": 7, "texto": "Y como ellos clamasen á Jehová, él puso oscuridad entre vosotros y los Egipcios, é hizo venir sobre ellos la mar, la cual los cubrió: y vuestros ojos vieron lo que hice en Egipto. Después estuvisteis muchos días en el desierto."}, {"numero": 8, "texto": "Y os introduje en la tierra de los Amorrheos, que habitaban de la otra parte del Jordán, los cuales pelearon contra vosotros; mas yo los entregué en vuestras manos, y poseísteis su tierra, y los destruí de delante de vosotros."}, {"numero": 9, "texto": "Y levantóse después Balac hijo de Sephor, rey de los Moabitas, y peleó contra Israel; y envió á llamar á Balaam hijo de Beor, para que os maldijese."}, {"numero": 10, "texto": "Mas yo no quise escuchar á Balaam, antes os bendijo repetidamente, y os libré de sus manos."}, {"numero": 11, "texto": "Y pasado el Jordán, vinisteis á Jericó; y los moradores de Jericó pelearon contra vosotros: los Amorrheos, Pherezeos, Cananeos, Hetheos, Gergeseos, Heveos, y Jebuseos: y yo los entregué en vuestras manos."}, {"numero": 12, "texto": "Y envié tábanos delante de vosotros, los cuales los echaron de delante de vosotros, á saber, á los dos reyes de los Amorrheos; no con tu espada, ni con tu arco."}, {"numero": 13, "texto": "Y os dí la tierra por la cual nada trabajasteis, y las ciudades que no edificasteis, en las cuales moráis; y de las viñas y olivares que no plantasteis, coméis."}, {"numero": 14, "texto": "Ahora pues, temed á Jehová, y servidle con integridad y en verdad; y quitad de en medio los dioses á los cuales sirvieron vuestros padres de esotra parte del río, y en Egipto; y servid á Jehová."}, {"numero": 15, "texto": "Y si mal os parece servir á Jehová, escogeos hoy á quién sirváis; si á los dioses á quienes sirvieron vuestros padres, cuando estuvieron de esotra parte del río, ó á los dioses de los Amorrheos en cuya tierra habitáis: que yo y mi casa serviremos á Jehová."}, {"numero": 16, "texto": "Entonces el pueblo respondió, y dijo: Nunca tal acontezca, que dejemos á Jehová por servir á otros dioses:"}, {"numero": 17, "texto": "Porque Jehová nuestro Dios es el que nos sacó á nosotros y á nuestros padres de la tierra de Egipto, de la casa de servidumbre; el cual delante de nuestros ojos ha hecho estas grandes señales, y nos ha guardado por todo el camino por donde hemos andado, y en todos los pueblos por entre los cuales pasamos."}, {"numero": 18, "texto": "Y Jehová echó de delante de nosotros á todos los pueblos, y al Amorrheo que habitaba en la tierra: nosotros, pues, también serviremos á Jehová, porque él es nuestro Dios."}, {"numero": 19, "texto": "Entonces Josué dijo al pueblo: No podréis servir á Jehová, porque él es Dios santo, y Dios celoso; no sufrirá vuestras rebeliones y vuestros pecados."}, {"numero": 20, "texto": "Si dejareis á Jehová y sirviereis á dioses ajenos, se volverá, y os maltratará, y os consumirá, después que os ha hecho bien."}, {"numero": 21, "texto": "El pueblo entonces dijo á Josué: No, antes á Jehová serviremos."}, {"numero": 22, "texto": "Y Josué respondió al pueblo: Vosotros sois testigos contra vosotros mismos, de que os habéis elegido á Jehová para servirle. Y ellos respondieron: Testigos somos."}, {"numero": 23, "texto": "Quitad, pues, ahora los dioses ajenos que están entre vosotros, é inclinad vuestro corazón á Jehová Dios de Israel."}, {"numero": 24, "texto": "Y el pueblo respondió á Josué: A Jehová nuestro Dios serviremos, y á su voz obedeceremos."}, {"numero": 25, "texto": "Entonces Josué hizo alianza con el pueblo el mismo día, y púsole ordenanzas y leyes en Sichêm."}, {"numero": 26, "texto": "Y escribió Josué estas palabras en el libro de la ley de Dios; y tomando una grande piedra, levantóla allí debajo de un alcornoque que estaba junto al santuario de Jehová."}, {"numero": 27, "texto": "Y dijo Josué á todo el pueblo: He aquí esta piedra será entre nosotros por testigo, la cual ha oído todas las palabras de Jehová que él ha hablado con nosotros: será, pues, testigo contra vosotros, porque no mintáis contra vuestro Dios."}, {"numero": 28, "texto": "Y envió Josué al pueblo, cada uno á su heredad."}, {"numero": 29, "texto": "Y después de estas cosas murió Josué, hijo de Nun, siervo de Jehová, siendo de ciento y diez años."}, {"numero": 30, "texto": "Y enterráronlo en el término de su posesión en Timnath-sera, que está en el monte de Ephraim, al norte del monte de Gaas."}, {"numero": 31, "texto": "Y sirvió Israel á Jehová todo el tiempo de Josué, y todo el tiempo de los ancianos que vivieron después de Josué, y que sabían todas las obras de Jehová, que había hecho por Israel."}, {"numero": 32, "texto": "Y enterraron en Sichêm los huesos de José que los hijos de Israel habían traído de Egipto, en la parte del campo que Jacob compró de los hijos de Hemor padre de Sichêm, por cien corderas; y fué en posesión á los hijos de José."}, {"numero": 33, "texto": "También murió Eleazar, hijo de Aarón; al cual enterraron en el collado de Phinees su hijo, que le fué dado en el monte de Ephraim."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 6, 'pt', '[{"numero": 1, "texto": "Mas os filhos de Israel fizeram o mal aos olhos do SENHOR; e o SENHOR os entregou nas mãos de Midiã por sete anos."}, {"numero": 2, "texto": "E a mão de Midiã prevaleceu contra Israel. E os filhos de Israel, por causa dos midianitas, se fizeram covas nos montes, e cavernas, e lugares fortes."}, {"numero": 3, "texto": "Pois quando os de Israel haviam semeado, subiam os midianitas, e amalequitas, e os orientais: subiam contra eles;"}, {"numero": 4, "texto": "E assentando acampamento contra eles destruíam os frutos da terra, até chegar a Gaza; e não deixavam o que comer em Israel, nem ovelhas, nem bois, nem asnos."}, {"numero": 5, "texto": "Porque subiam eles e seus gados, e vinham com suas tendas em grande multidão como gafanhotos, que não havia número neles nem em seus camelos: assim vinham à terra para devastá-la."}, {"numero": 6, "texto": "Era, pois, Israel em grande maneira empobrecido pelos midianitas; e os filhos de Israel clamaram ao SENHOR."}, {"numero": 7, "texto": "E quando os filhos de Israel clamaram ao SENHOR, por causa dos midianitas,"}, {"numero": 8, "texto": "O SENHOR enviou um homem profeta aos filhos de Israel, o qual lhes disse: Assim disse o SENHOR Deus de Israel: Eu vos fiz sair do Egito, e vos tirei da casa de servidão:"}, {"numero": 9, "texto": "Eu vos livrei da mão dos egípcios, e da mão de todos os que vos afligiram, aos quais expulsei de diante de vós, e vos dei sua terra;"}, {"numero": 10, "texto": "E disse-vos: Eu sou o SENHOR vosso Deus; não temais aos deuses dos amorreus, em cuja terra habitais; mas não obedecestes à minha voz."}, {"numero": 11, "texto": "E veio o anjo do SENHOR, e sentou-se debaixo do carvalho que está em Ofra, o qual era de Joás abiezrita; e seu filho Gideão estava malhando o trigo na prensa de uvas, para fazê-lo esconder dos midianitas."}, {"numero": 12, "texto": "E o anjo do SENHOR se lhe apareceu, e disse-lhe: O SENHOR é contigo, homem esforçado."}, {"numero": 13, "texto": "E Gideão lhe respondeu: Ah, Senhor meu, se o SENHOR é conosco, por que nos sobreveio tudo isto? E onde estão todas suas maravilhas, que nossos pais nos contaram, dizendo: Não nos tirou o SENHOR do Egito? E agora o SENHOR nos desamparou, e nos entregou nas mãos dos midianitas."}, {"numero": 14, "texto": "E olhando-lhe o SENHOR, disse-lhe: Vai com esta tua força, e salvarás a Israel da mão dos midianitas. Não te envio eu?"}, {"numero": 15, "texto": "Então lhe respondeu: Ah, Senhor meu, com que tenho de salvar a Israel? Eis que minha família é pobre em Manassés, e eu o menor na casa de meu pai."}, {"numero": 16, "texto": "E o SENHOR lhe disse: Porque eu serei contigo, e ferirás aos midianitas como a um só homem."}, {"numero": 17, "texto": "E ele respondeu: Eu te rogo que, se achei favor diante de ti, me dês sinal de que tu falaste comigo."}, {"numero": 18, "texto": "Rogo-te que não te vás daqui, até que eu volte a ti, e traga a minha oferta, e a ponha diante de ti. E ele respondeu: Eu esperarei até que voltes."}, {"numero": 19, "texto": "E entrando-se Gideão preparou um cabrito, e pães sem levedura de um efa de farinha; e pôs a carne em um cesto, e o caldo em uma caçarola, e tirando-o apresentou-lhe debaixo daquele carvalho."}, {"numero": 20, "texto": "E o anjo de Deus lhe disse: Toma a carne, e os pães sem levedura, e põe-o sobre esta penha, e derrama o caldo. E ele o fez assim."}, {"numero": 21, "texto": "E estendendo o anjo do SENHOR o bordão que tinha em sua mão, tocou com a ponta na carne e nos pães sem levedura; e subiu fogo da penha, o qual consumiu a carne e os pães sem levedura. E o anjo do SENHOR desapareceu de diante dele."}, {"numero": 22, "texto": "E vendo Gideão que era o anjo do SENHOR, disse: Ah, Senhor DEUS, que vi o anjo do SENHOR face a face."}, {"numero": 23, "texto": "E o SENHOR lhe disse: Paz seja contigo; não tenhas medo, não morrerás."}, {"numero": 24, "texto": "E edificou ali Gideão altar ao SENHOR, ao que chamou O SENHOR é paz: está até hoje em Ofra dos abiezritas."}, {"numero": 25, "texto": "E aconteceu que a mesma noite lhe disse o SENHOR: Toma um touro do rebanho de teu pai, e outro touro de sete anos, e derruba o altar de Baal que teu pai tem, e corta também o bosque que está junto a ele:"}, {"numero": 26, "texto": "E edifica altar ao SENHOR teu Deus no cume deste penhasco em lugar conveniente; e tomando o segundo touro, sacrifica-o em holocausto sobre a lenha do bosque que haverás cortado."}, {"numero": 27, "texto": "Então Gideão tomou dez homens de seus servos, e fez como o SENHOR lhe disse. Mas temendo fazê-lo de dia, pela família de seu pai e pelos homens da cidade, o fez de noite."}, {"numero": 28, "texto": "E à manhã, quando os da cidade se levantaram, eis que o altar de Baal estava derrubado, e cortado o bosque que junto a ele estava, e sacrificado aquele segundo touro em holocausto sobre o altar edificado."}, {"numero": 29, "texto": "E diziam-se uns aos outros: Quem fez isto? E buscando e investigando, disseram-lhes: Gideão filho de Joás o fez. Então os homens da cidade disseram a Joás:"}, {"numero": 30, "texto": "Tira fora teu filho para que morra, porquanto derrubou o altar de Baal e cortou o bosque que junto a ele estava."}, {"numero": 31, "texto": "E Joás respondeu a todos os que estavam junto a ele: Tomareis vós a demanda por Baal? Vós o salvareis? Qualquer um que tomar a demanda por ele, que morra amanhã. Se é Deus, contenda por si mesmo com o que derrubou seu altar."}, {"numero": 32, "texto": "E aquele dia ele chamou a Gideão Jerubaal; porque disse: Pleiteie Baal contra o que derrubou seu altar."}, {"numero": 33, "texto": "E todos os midianitas, e amalequitas, e orientais, se juntaram de uma vez, e passando assentaram acampamento no vale de Jezreel."}, {"numero": 34, "texto": "E o espírito do SENHOR se investiu em Gideão, e quando este tocou a a trombeta, Abiezer se juntou com ele."}, {"numero": 35, "texto": "E enviou mensageiros por todo Manassés, o qual também se juntou com ele: também enviou mensageiros a Aser, e a Zebulom, e a Naftali, os quais saíram a encontrar-lhes."}, {"numero": 36, "texto": "E Gideão disse a Deus: Se hás de salvar a Israel por minha mão, como disseste,"}, {"numero": 37, "texto": "Eis que eu porei um velo de lã na era; e se o orvalho estiver no velo somente, restando seca toda a outra terra, então entenderei que hás de salvar a Israel por minha mão, como o disseste."}, {"numero": 38, "texto": "E aconteceu assim: porque quando se levantou de manhã, espremendo o velo tirou dele o orvalho, um vaso cheio de água."}, {"numero": 39, "texto": "Mas Gideão disse a Deus: Não se acenda tua ira contra mim, se ainda falar esta vez: somente provarei agora outra vez com o velo. Rogo-te que a secura seja somente no velo, e o orvalho sobre a terra."}, {"numero": 40, "texto": "E aquela noite o fez Deus assim: porque a secura foi somente no velo, e em toda a terra esteve o orvalho."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 6, 'en', '[{"numero": 1, "texto": "And the children of Israel did evil in the sight of the Lord: and the Lord delivered them into the hand of Midian seven years."}, {"numero": 2, "texto": "And the hand of Midian prevailed against Israel: and because of the Midianites the children of Israel made them the dens which are in the mountains, and caves, and strong holds."}, {"numero": 3, "texto": "And so it was, when Israel had sown, that the Midianites came up, and the Amalekites, and the children of the east, even they came up against them;"}, {"numero": 4, "texto": "And they encamped against them, and destroyed the increase of the earth, till thou come unto Gaza, and left no sustenance for Israel, neither sheep, nor ox, nor ass."}, {"numero": 5, "texto": "For they came up with their cattle and their tents, and they came as grasshoppers for multitude; for both they and their camels were without number: and they entered into the land to destroy it."}, {"numero": 6, "texto": "And Israel was greatly impoverished because of the Midianites; and the children of Israel cried unto the Lord."}, {"numero": 7, "texto": "And it came to pass, when the children of Israel cried unto the Lord because of the Midianites,"}, {"numero": 8, "texto": "That the Lord sent a prophet unto the children of Israel, which said unto them, Thus saith the Lord God of Israel, I brought you up from Egypt, and brought you forth out of the house of bondage;"}, {"numero": 9, "texto": "And I delivered you out of the hand of the Egyptians, and out of the hand of all that oppressed you, and drave them out from before you, and gave you their land;"}, {"numero": 10, "texto": "And I said unto you, I am the Lord your God; fear not the gods of the Amorites, in whose land ye dwell: but ye have not obeyed my voice."}, {"numero": 11, "texto": "And there came an angel of the Lord, and sat under an oak which was in Ophrah, that pertained unto Joash the Abiezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites."}, {"numero": 12, "texto": "And the angel of the Lord appeared unto him, and said unto him, The Lord is with thee, thou mighty man of valour."}, {"numero": 13, "texto": "And Gideon said unto him, Oh my Lord, if the Lord be with us, why then is all this befallen us? and where be all his miracles which our fathers told us of, saying, Did not the Lord bring us up from Egypt? but now the Lord hath forsaken us, and delivered us into the hands of the Midianites."}, {"numero": 14, "texto": "And the Lord looked upon him, and said, Go in this thy might, and thou shalt save Israel from the hand of the Midianites: have not I sent thee?"}, {"numero": 15, "texto": "And he said unto him, Oh my Lord, wherewith shall I save Israel? behold, my family is poor in Manasseh, and I am the least in my father''s house."}, {"numero": 16, "texto": "And the Lord said unto him, Surely I will be with thee, and thou shalt smite the Midianites as one man."}, {"numero": 17, "texto": "And he said unto him, If now I have found grace in thy sight, then shew me a sign that thou talkest with me."}, {"numero": 18, "texto": "Depart not hence, I pray thee, until I come unto thee, and bring forth my present, and set it before thee. And he said, I will tarry until thou come again."}, {"numero": 19, "texto": "And Gideon went in, and made ready a kid, and unleavened cakes of an ephah of flour: the flesh he put in a basket, and he put the broth in a pot, and brought it out unto him under the oak, and presented it."}, {"numero": 20, "texto": "And the angel of God said unto him, Take the flesh and the unleavened cakes, and lay them upon this rock, and pour out the broth. And he did so."}, {"numero": 21, "texto": "Then the angel of the Lord put forth the end of the staff that was in his hand, and touched the flesh and the unleavened cakes; and there rose up fire out of the rock, and consumed the flesh and the unleavened cakes. Then the angel of the Lord departed out of his sight."}, {"numero": 22, "texto": "And when Gideon perceived that he was an angel of the Lord, Gideon said, Alas, O Lord God! for because I have seen an angel of the Lord face to face."}, {"numero": 23, "texto": "And the Lord said unto him, Peace be unto thee; fear not: thou shalt not die."}, {"numero": 24, "texto": "Then Gideon built an altar there unto the Lord, and called it Jehovahshalom: unto this day it is yet in Ophrah of the Abiezrites."}, {"numero": 25, "texto": "And it came to pass the same night, that the Lord said unto him, Take thy father''s young bullock, even the second bullock of seven years old, and throw down the altar of Baal that thy father hath, and cut down the grove that is by it:"}, {"numero": 26, "texto": "And build an altar unto the Lord thy God upon the top of this rock, in the ordered place, and take the second bullock, and offer a burnt sacrifice with the wood of the grove which thou shalt cut down."}, {"numero": 27, "texto": "Then Gideon took ten men of his servants, and did as the Lord had said unto him: and so it was, because he feared his father''s household, and the men of the city, that he could not do it by day, that he did it by night."}, {"numero": 28, "texto": "And when the men of the city arose early in the morning, behold, the altar of Baal was cast down, and the grove was cut down that was by it, and the second bullock was offered upon the altar that was built."}, {"numero": 29, "texto": "And they said one to another, Who hath done this thing? And when they enquired and asked, they said, Gideon the son of Joash hath done this thing."}, {"numero": 30, "texto": "Then the men of the city said unto Joash, Bring out thy son, that he may die: because he hath cast down the altar of Baal, and because he hath cut down the grove that was by it."}, {"numero": 31, "texto": "And Joash said unto all that stood against him, Will ye plead for Baal? will ye save him? he that will plead for him, let him be put to death whilst it is yet morning: if he be a god, let him plead for himself, because one hath cast down his altar."}, {"numero": 32, "texto": "Therefore on that day he called him Jerubbaal, saying, Let Baal plead against him, because he hath thrown down his altar."}, {"numero": 33, "texto": "Then all the Midianites and the Amalekites and the children of the east were gathered together, and went over, and pitched in the valley of Jezreel."}, {"numero": 34, "texto": "But the Spirit of the Lord came upon Gideon, and he blew a trumpet; and Abiezer was gathered after him."}, {"numero": 35, "texto": "And he sent messengers throughout all Manasseh; who also was gathered after him: and he sent messengers unto Asher, and unto Zebulun, and unto Naphtali; and they came up to meet them."}, {"numero": 36, "texto": "And Gideon said unto God, If thou wilt save Israel by mine hand, as thou hast said,"}, {"numero": 37, "texto": "Behold, I will put a fleece of wool in the floor; and if the dew be on the fleece only, and it be dry upon all the earth beside, then shall I know that thou wilt save Israel by mine hand, as thou hast said."}, {"numero": 38, "texto": "And it was so: for he rose up early on the morrow, and thrust the fleece together, and wringed the dew out of the fleece, a bowl full of water."}, {"numero": 39, "texto": "And Gideon said unto God, Let not thine anger be hot against me, and I will speak but this once: let me prove, I pray thee, but this once with the fleece; let it now be dry only upon the fleece, and upon all the ground let there be dew."}, {"numero": 40, "texto": "And God did so that night: for it was dry upon the fleece only, and there was dew on all the ground."}]'::jsonb, 'King James Version'),
  ('Jz', 6, 'fr', '[{"numero": 1, "texto": "Les enfants d''''Israël firent ce qui déplaît à l''''Eternel; et l''''Eternel les livra entre les mains de Madian, pendant sept ans."}, {"numero": 2, "texto": "La main de Madian fut puissante contre Israël. Pour échapper à Madian, les enfants d''''Israël se retiraient dans les ravins des montagnes, dans les cavernes et sur les rochers fortifiés."}, {"numero": 3, "texto": "Quand Israël avait semé, Madian montait avec Amalek et les fils de l''''Orient, et ils marchaient contre lui."}, {"numero": 4, "texto": "Ils campaient en face de lui, détruisaient les productions du pays jusque vers Gaza, et ne laissaient en Israël ni vivres, ni brebis, ni boeufs, ni ânes."}, {"numero": 5, "texto": "Car ils montaient avec leurs troupeaux et leurs tentes, ils arrivaient comme une multitude de sauterelles, ils étaient innombrables, eux et leurs chameaux, et ils venaient dans le pays pour le ravager."}, {"numero": 6, "texto": "Israël fut très malheureux à cause de Madian, et les enfants d''''Israël crièrent à l''''Eternel."}, {"numero": 7, "texto": "Lorsque les enfants d''''Israël crièrent à l''''Eternel au sujet de Madian,"}, {"numero": 8, "texto": "l''''Eternel envoya un prophète aux enfants d''''Israël. Il leur dit: Ainsi parle l''''Eternel, le Dieu d''''Israël: Je vous ai fait monter d''''Egypte, et je vous ai fait sortir de la maison de servitude."}, {"numero": 9, "texto": "Je vous ai délivrés de la main des Egyptiens et de la main de tous ceux qui vous opprimaient; je les ai chassés devant vous, et je vous ai donné leur pays."}, {"numero": 10, "texto": "Je vous ai dit: Je suis l''''Eternel, votre Dieu; vous ne craindrez point les dieux des Amoréens, dans le pays desquels vous habitez. Mais vous n''''avez point écouté ma voix."}, {"numero": 11, "texto": "Puis vint l''''ange de l''''Eternel, et il s''''assit sous le térébinthe d''''Ophra, qui appartenait à Joas, de la famille d''''Abiézer. Gédéon, son fils, battait du froment au pressoir, pour le mettre à l''''abri de Madian."}, {"numero": 12, "texto": "L''''ange de l''''Eternel lui apparut, et lui dit: L''''Eternel est avec toi, vaillant héros!"}, {"numero": 13, "texto": "Gédéon lui dit: Ah! mon seigneur, si l''''Eternel est avec nous, pourquoi toutes ces choses nous sont-elles arrivées? Et où sont tous ces prodiges que nos pères nous racontent, quand ils disent: L''''Eternel ne nous a-t-il pas fait monter hors d''''Egypte? Maintenant l''''Eternel nous abandonne, et il nous livre entre les mains de Madian!"}, {"numero": 14, "texto": "L''''Eternel se tourna vers lui, et dit: Va avec cette force que tu as, et délivre Israël de la main de Madian; n''''est-ce pas moi qui t''''envoie?"}, {"numero": 15, "texto": "Gédéon lui dit: Ah! mon seigneur, avec quoi délivrerai-je Israël? Voici, ma famille est la plus pauvre en Manassé, et je suis le plus petit dans la maison de mon père."}, {"numero": 16, "texto": "L''''Eternel lui dit: Mais je serai avec toi, et tu battras Madian comme un seul homme."}, {"numero": 17, "texto": "Gédéon lui dit: Si j''''ai trouvé grâce à tes yeux, donne-moi un signe pour montrer que c''''est toi qui me parles."}, {"numero": 18, "texto": "Ne t''''éloigne point d''''ici jusqu''''à ce que je revienne auprès de toi, que j''''apporte mon offrande, et que je la dépose devant toi. Et l''''Eternel dit: Je resterai jusqu''''à ce que tu reviennes."}, {"numero": 19, "texto": "Gédéon entra, prépara un chevreau, et fit avec un épha de farine des pains sans levain. Il mit la chair dans un panier et le jus dans un pot, les lui apporta sous le térébinthe, et les présenta."}, {"numero": 20, "texto": "L''''ange de Dieu lui dit: Prends la chair et les pains sans levain, pose-les sur ce rocher, et répands le jus. Et il fit ainsi."}, {"numero": 21, "texto": "L''''ange de l''''Eternel avança l''''extrémité du bâton qu''''il avait à la main, et toucha la chair et les pains sans levain. Alors il s''''éleva du rocher un feu qui consuma la chair et les pains sans levain. Et l''''ange de l''''Eternel disparut à ses yeux."}, {"numero": 22, "texto": "Gédéon, voyant que c''''était l''''ange de l''''Eternel, dit: Malheur à moi, Seigneur Eternel! car j''''ai vu l''''ange de l''''Eternel face à face."}, {"numero": 23, "texto": "Et l''''Eternel lui dit: Sois en paix, ne crains point, tu ne mourras pas."}, {"numero": 24, "texto": "Gédéon bâtit là un autel à l''''Eternel, et lui donna pour nom l''''Eternel paix: il existe encore aujourd''''hui à Ophra, qui appartenait à la famille d''''Abiézer."}, {"numero": 25, "texto": "Dans la même nuit, l''''Eternel dit à Gédéon: Prends le jeune taureau de ton père, et un second taureau de sept ans. Renverse l''''autel de Baal qui est à ton père, et abats le pieu sacré qui est dessus."}, {"numero": 26, "texto": "Tu bâtiras ensuite et tu disposeras, sur le haut de ce rocher, un autel à l''''Eternel ton Dieu. Tu prendras le second taureau, et tu offriras un holocauste, avec le bois de l''''idole que tu auras abattue."}, {"numero": 27, "texto": "Gédéon prit dix hommes parmi ses serviteurs, et fit ce que l''''Eternel avait dit; mais, comme il craignait la maison de son père et les gens de la ville, il l''''exécuta de nuit, et non de jour."}, {"numero": 28, "texto": "Lorsque les gens de la ville se furent levés de bon matin, voici, l''''autel de Baal était renversé, le pieu sacré placé dessus était abattu, et le second taureau était offert en holocauste sur l''''autel qui avait été bâti."}, {"numero": 29, "texto": "Ils se dirent l''''un à l''''autre: Qui a fait cela? Et ils s''''informèrent et firent des recherches. On leur dit: C''''est Gédéon, fils de Joas, qui a fait cela."}, {"numero": 30, "texto": "Alors les gens de la ville dirent à Joas: Fais sortir ton fils, et qu''''il meure, car il a renversé l''''autel de Baal et abattu le pieu sacré qui était dessus."}, {"numero": 31, "texto": "Joas répondit à tous ceux qui se présentèrent à lui: Est-ce à vous de prendre parti pour Baal? est-ce à vous de venir à son secours? Quiconque prendra parti pour Baal mourra avant que le matin vienne. Si Baal est un dieu, qu''''il plaide lui-même sa cause, puisqu''''on a renversé son autel."}, {"numero": 32, "texto": "Et en ce jour l''''on donna à Gédéon le nom de Jerubbaal, en disant: Que Baal plaide contre lui, puisqu''''il a renversé son autel."}, {"numero": 33, "texto": "Tout Madian, Amalek et les fils de l''''Orient, se rassemblèrent; ils passèrent le Jourdain, et campèrent dans la vallée de Jizréel."}, {"numero": 34, "texto": "Gédéon fut revêtu de l''''esprit de l''''Eternel; il sonna de la trompette, et Abiézer fut convoqué pour marcher à sa suite."}, {"numero": 35, "texto": "Il envoya des messagers dans tout Manassé, qui fut aussi convoqué pour marcher à sa suite. Il envoya des messagers dans Aser, dans Zabulon et dans Nephthali, qui montèrent à leur rencontre."}, {"numero": 36, "texto": "Gédéon dit à Dieu: Si tu veux délivrer Israël par ma main, comme tu l''''as dit,"}, {"numero": 37, "texto": "voici, je vais mettre une toison de laine dans l''''aire; si la toison seule se couvre de rosée et que tout le terrain reste sec, je connaîtrai que tu délivreras Israël par ma main, comme tu l''''as dit."}, {"numero": 38, "texto": "Et il arriva ainsi. Le jour suivant, il se leva de bon matin, pressa la toison, et en fit sortir la rosée, qui donna de l''''eau plein une coupe."}, {"numero": 39, "texto": "Gédéon dit à Dieu: Que ta colère ne s''''enflamme point contre moi, et je ne parlerai plus que cette fois: Je voudrais seulement faire encore une épreuve avec la toison: que la toison seule reste sèche, et que tout le terrain se couvre de rosée."}, {"numero": 40, "texto": "Et Dieu fit ainsi cette nuit-là. La toison seule resta sèche, et tout le terrain se couvrit de rosée."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 6, 'es', '[{"numero": 1, "texto": "MAS los hijos de Israel hicieron lo malo en los ojos de Jehová; y Jehová los entregó en las manos de Madián por siete años."}, {"numero": 2, "texto": "Y la mano de Madián prevaleció contra Israel. Y los hijos de Israel, por causa de los Madianitas, se hicieron cuevas en los montes, y cavernas, y lugares fuertes."}, {"numero": 3, "texto": "Pues como los de Israel habían sembrado, subían los Madianitas, y Amalecitas, y los orientales: subían contra ellos;"}, {"numero": 4, "texto": "Y asentando campo contra ellos destruían los frutos de la tierra, hasta llegar á Gaza; y no dejaban qué comer en Israel, ni ovejas, ni bueyes, ni asnos."}, {"numero": 5, "texto": "Porque subían ellos y sus ganados, y venían con sus tiendas en grande multitud como langosta, que no había número en ellos ni en sus camellos: así venían á la tierra para devastarla."}, {"numero": 6, "texto": "Era pues Israel en gran manera empobrecido por los Madianitas; y los hijos de Israel clamaron á Jehová."}, {"numero": 7, "texto": "Y cuando los hijos de Israel hubieron clamado á Jehová, á causa de los Madianitas,"}, {"numero": 8, "texto": "Jehová envió un varón profeta á los hijos de Israel, el cual les dijo: Así ha dicho Jehová Dios de Israel: Yo os hice salir de Egipto, y os saqué de la casa de servidumbre:"}, {"numero": 9, "texto": "Yo os libré de mano de los Egipcios, y de mano de todos los que os afligieron, á los cuales eché de delante de vosotros, y os dí su tierra;"}, {"numero": 10, "texto": "Y díjeos: Yo soy Jehová vuestro Dios; no temáis á los dioses de los Amorrheos, en cuya tierra habitáis: mas no habéis obedecido á mi voz."}, {"numero": 11, "texto": "Y vino el ángel de Jehová, y sentóse debajo del alcornoque que está en Ophra, el cual era de Joas Abiezerita; y su hijo Gedeón estaba sacudiendo el trigo en el lagar, para hacerlo esconder de los Madianitas."}, {"numero": 12, "texto": "Y el ángel de Jehová se le apareció, y díjole: Jehová es contigo, varón esforzado."}, {"numero": 13, "texto": "Y Gedeón le respondió: Ah, Señor mío, si Jehová es con nosotros, ¿por qué nos ha sobrevenido todo esto? ¿Y dónde están todas sus maravillas, que nuestros padres nos han contado, diciendo: ¿No nos sacó Jehová de Egipto? Y ahora Jehová nos ha desamparado, y nos ha entregado en mano de los Madianitas."}, {"numero": 14, "texto": "Y mirándole Jehová, díjole: Ve con esta tu fortaleza, y salvarás á Israel de la mano de los Madianitas. ¿No te envío yo?"}, {"numero": 15, "texto": "Entonces le respondió: Ah, Señor mío, ¿con qué tengo de salvar á Israel? He aquí que mi familia es pobre en Manasés, y yo el menor en la casa de mi padre."}, {"numero": 16, "texto": "Y Jehová le dijo: Porque yo seré contigo, y herirás á los Madianitas como á un solo hombre."}, {"numero": 17, "texto": "Y él respondió: Yo te ruego, que si he hallado gracia delante de ti, me des señal de que tú has hablado conmigo."}, {"numero": 18, "texto": "Ruégote que no te vayas de aquí, hasta que á ti vuelva, y saque mi presente, y lo ponga delante de ti. Y él respondió: Yo esperaré hasta que vuelvas."}, {"numero": 19, "texto": "Y entrándose Gedeón aderezó un cabrito, y panes sin levadura de un epha de harina; y puso la carne en un canastillo, y el caldo en una olla, y sacándolo presentóselo debajo de aquel alcornoque."}, {"numero": 20, "texto": "Y el ángel de Dios le dijo: Toma la carne, y los panes sin levadura, y ponlo sobre esta peña, y vierte el caldo. Y él lo hizo así."}, {"numero": 21, "texto": "Y extendiendo el ángel de Jehová el bordón que tenía en su mano, tocó con la punta en la carne y en los panes sin levadura; y subió fuego de la peña, el cual consumió la carne y los panes sin levadura. Y el ángel de Jehová desapareció de delante de él."}, {"numero": 22, "texto": "Y viendo Gedeón que era el ángel de Jehová, dijo: Ah, Señor Jehová, que he visto el ángel de Jehová cara á cara."}, {"numero": 23, "texto": "Y Jehová le dijo: Paz á ti; no tengas temor, no morirás."}, {"numero": 24, "texto": "Y edificó allí Gedeón altar á Jehová, al que llamó Jehová-salom: está hasta hoy en Ophra de los Abiezeritas."}, {"numero": 25, "texto": "Y aconteció que la misma noche le dijo Jehová: Toma un toro del hato de tu padre, y otro toro de siete años, y derriba el altar de Baal que tu padre tiene, y corta también el bosque que está junto á él:"}, {"numero": 26, "texto": "Y edifica altar á Jehová tu Dios en la cumbre de este peñasco en lugar conveniente; y tomando el segundo toro, sacrifícalo en holocausto sobre la leña del bosque que habrás cortado."}, {"numero": 27, "texto": "Entonces Gedeón tomó diez hombres de sus siervos, é hizo como Jehová le dijo. Mas temiendo hacerlo de día, por la familia de su padre y por los hombres de la ciudad, hízolo de noche."}, {"numero": 28, "texto": "Y á la mañana, cuando los de la ciudad se levantaron, he aquí que el altar de Baal estaba derribado, y cortado el bosque que junto á él estaba, y sacrificado aquel segundo toro en holocausto sobre el altar edificado."}, {"numero": 29, "texto": "Y decíanse unos á otros: ¿Quién ha hecho esto? Y buscando é inquiriendo, dijéronles: Gedeón hijo de Joas lo ha hecho. Entonces los hombres de la ciudad dijeron á Joas:"}, {"numero": 30, "texto": "Saca fuera tu hijo para que muera, por cuanto ha derribado el altar de Baal y ha cortado el bosque que junto á él estaba."}, {"numero": 31, "texto": "Y Joas respondió á todos los que estaban junto á él: ¿Tomaréis vosotros la demanda por Baal? ¿le salvaréis vosotros? Cualquiera que tomare la demanda por él, que muera mañana. Si es Dios, contienda por sí mismo con el que derribó su altar."}, {"numero": 32, "texto": "Y aquel día llamó él á Gedeón Jerobaal; porque dijo: Pleitee Baal contra el que derribó su altar."}, {"numero": 33, "texto": "Y todos los Madianitas, y Amalecitas, y orientales, se juntaron á una, y pasando asentaron campo en el valle de Jezreel."}, {"numero": 34, "texto": "Y el espíritu de Jehová se envistió en Gedeón, y como éste hubo tocado el cuerno, Abiezer se juntó con él."}, {"numero": 35, "texto": "Y envió mensajeros por todo Manasés, el cual también se juntó con él: asimismo envió mensajeros á Aser, y á Zabulón, y á Nephtalí, los cuales salieron á encontrarles."}, {"numero": 36, "texto": "Y Gedeón dijo á Dios: Si has de salvar á Israel por mi mano, como has dicho,"}, {"numero": 37, "texto": "He aquí que yo pondré un vellón de lana en la era; y si el rocío estuviere en el vellón solamente, quedando seca toda la otra tierra, entonces entenderé que has de salvar á Israel por mi mano, como lo has dicho."}, {"numero": 38, "texto": "Y aconteció así: porque como se levantó de mañana, exprimiendo el vellón sacó de él el rocío, un vaso lleno de agua."}, {"numero": 39, "texto": "Mas Gedeón dijo á Dios: No se encienda tu ira contra mí, si aun hablare esta vez: solamente probaré ahora otra vez con el vellón. Ruégote que la sequedad sea sólo en el vellón, y el rocío sobre la tierra."}, {"numero": 40, "texto": "Y aquella noche lo hizo Dios así: porque la sequedad fué sólo en el vellón, y en toda la tierra estuvo el rocío."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 7, 'pt', '[{"numero": 1, "texto": "Levantando-se, pois, de manhã Jerubaal, o qual é Gideão, e todo aquele povo que estava com ele, assentaram o acampamento junto à fonte de Harode: e tinha o acampamento dos midianitas ao norte, da outra parte do morro de Moré, no vale."}, {"numero": 2, "texto": "E o SENHOR disse a Gideão: O povo que está contigo é muito para que eu dê aos midianitas em sua mão: para que não se glorie Israel contra mim, dizendo: Minha mão me salvou."}, {"numero": 3, "texto": "Agora, pois, proclama aos ouvidos do povo, dizendo: Aquele que teme e se estremece, volte e retire-se do monte de Gileade. E do povo voltaram vinte e dois mil; e restaram dez mil."}, {"numero": 4, "texto": "E o SENHOR disse a Gideão: Ainda é muito o povo; leva-os às águas, e ali eu te os provarei; e do que eu te disser: Vá este contigo, vá contigo: mas de qualquer um que eu te disser: Este não vá contigo, o tal não vá."}, {"numero": 5, "texto": "Então levou o povo às águas: e o SENHOR disse a Gideão: Qualquer um que lamber as águas com sua língua como lambe o cão, aquele porás à parte; também qualquer um que se dobrar sobre seus joelhos para beber."}, {"numero": 6, "texto": "E foi o número dos que lamberam as águas, achegando-a com a mão à boca, trezentos homens: e todo aquele resto do povo se dobrou sobre seus joelhos para beber as águas."}, {"numero": 7, "texto": "Então o SENHOR disse a Gideão: Com estes trezentos homens que lamberam o água vos salvarei, e entregarei aos midianitas em tuas mãos; e vá-se todo o resto do povo cada um a seu lugar."}, {"numero": 8, "texto": "Depois de tomarem a provisão do povo e suas trombetas, ele enviou todos os israelitas cada um a sua tenda, mas manteve aqueles trezentos homens; e o campo de Midiã estava no vale abaixo dele."}, {"numero": 9, "texto": "E aconteceu que aquela noite o SENHOR lhe disse: Levanta-te, e desce ao acampamento; porque eu o entreguei em tuas mãos."}, {"numero": 10, "texto": "E se temes descer para atacar, desce apenas tu e o teu servo Pura ao acampamento,"}, {"numero": 11, "texto": "e ouvirás o que falam; e então tuas mãos se fortalecerão, e descerás para atacar o acampamento. E ele desceu com o seu servo Pura à extremidade dos homens armados que estavam no acampamento."}, {"numero": 12, "texto": "E Midiã, e Amaleque, e todos os orientais, estavam estendidos no vale como gafanhotos em multidão, e seus camelos eram inúmeros, como a areia que está à beira do mar em multidão."}, {"numero": 13, "texto": "E logo que chegou Gideão, eis que um homem estava contando a seu companheiro um sonho, dizendo: Eis que eu sonhei um sonho: que via um pão de cevada que rodava até o acampamento de Midiã, e chegava às tendas, e as feria de tal maneira que caíam, e as virava de cima abaixo, e as tendas caíam."}, {"numero": 14, "texto": "E seu companheiro respondeu, e disse: Isto não é outra coisa a não ser a espada de Gideão filho de Joás, homem de Israel: Deus entregou em suas mãos aos midianitas com todo o acampamento."}, {"numero": 15, "texto": "E quando Gideão ouviu a história do sonho e sua interpretação, adorou; e voltado ao acampamento de Israel, disse: Levantai-vos, que o SENHOR entregou o acampamento de Midiã em vossas mãos."}, {"numero": 16, "texto": "E repartindo os trezentos homens em três esquadrões, deu a cada um deles trombetas em suas mãos, e cântaros vazios com tochas ardendo dentro dos cântaros."}, {"numero": 17, "texto": "E disse-lhes: Olhai a mim, e fazei como eu fizer; eis que quando eu chegar ao princípio do acampamento, como eu fizer, assim fareis vós."}, {"numero": 18, "texto": "Eu tocarei a trombeta e todos os que estiverem comigo; e vós tocareis então as trombetas ao redor de todo aquele campo, e direis: Pelo SENHOR e Gideão!"}, {"numero": 19, "texto": "Chegou, pois, Gideão, e os cem homens que levava consigo, ao princípio do acampamento, à entrada da vigília do meio, quando acabavam de renovar as sentinelas; e tocaram as trombetas, e quebraram os cântaros que levavam em suas mãos:"}, {"numero": 20, "texto": "E os três esquadrões tocaram as trombetas, e quebrando os cântaros tomaram nas mãos esquerdas as tochas, e nas direitas as trombetas com que tocavam, e deram grito: A espada do SENHOR e de Gideão!"}, {"numero": 21, "texto": "E estiveram em seus lugares em derredor do acampamento: e todo aquele acampamento foi alvoroçado, e fugiram gritando."}, {"numero": 22, "texto": "Mas os trezentos tocavam as trombetas: e o SENHOR pôs a espada de cada um contra seu companheiro em todo aquele acampamento. E o exército fugiu até Bete-Sita, até Zererá, e até o termo de Abel-Meolá em Tabate."}, {"numero": 23, "texto": "E juntando-se os de Israel, de Naftali, e de Aser, e de todo Manassés, seguiram aos midianitas."}, {"numero": 24, "texto": "Gideão também enviou mensageiros a todo aquele monte de Efraim, dizendo: Descei ao encontro dos midianitas, e tomai-lhes as águas até Bete-Bara e o Jordão. E juntos todos os homens de Efraim, tomaram as águas de Bete-Bara e o Jordão."}, {"numero": 25, "texto": "E tomaram dois príncipes dos midianitas, Orebe e Zeebe: e mataram a Orebe na penha de Orebe, e a Zeebe o mataram na prensa de uvas de Zeebe; e depois que seguiram aos midianitas, trouxeram as cabeças de Orebe e de Zeebe a Gideão da outra parte do Jordão."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 7, 'en', '[{"numero": 1, "texto": "Then Jerubbaal, who is Gideon, and all the people that were with him, rose up early, and pitched beside the well of Harod: so that the host of the Midianites were on the north side of them, by the hill of Moreh, in the valley."}, {"numero": 2, "texto": "And the Lord said unto Gideon, The people that are with thee are too many for me to give the Midianites into their hands, lest Israel vaunt themselves against me, saying, Mine own hand hath saved me."}, {"numero": 3, "texto": "Now therefore go to, proclaim in the ears of the people, saying, Whosoever is fearful and afraid, let him return and depart early from mount Gilead. And there returned of the people twenty and two thousand; and there remained ten thousand."}, {"numero": 4, "texto": "And the Lord said unto Gideon, The people are yet too many; bring them down unto the water, and I will try them for thee there: and it shall be, that of whom I say unto thee, This shall go with thee, the same shall go with thee; and of whomsoever I say unto thee, This shall not go with thee, the same shall not go."}, {"numero": 5, "texto": "So he brought down the people unto the water: and the Lord said unto Gideon, Every one that lappeth of the water with his tongue, as a dog lappeth, him shalt thou set by himself; likewise every one that boweth down upon his knees to drink."}, {"numero": 6, "texto": "And the number of them that lapped, putting their hand to their mouth, were three hundred men: but all the rest of the people bowed down upon their knees to drink water."}, {"numero": 7, "texto": "And the Lord said unto Gideon, By the three hundred men that lapped will I save you, and deliver the Midianites into thine hand: and let all the other people go every man unto his place."}, {"numero": 8, "texto": "So the people took victuals in their hand, and their trumpets: and he sent all the rest of Israel every man unto his tent, and retained those three hundred men: and the host of Midian was beneath him in the valley."}, {"numero": 9, "texto": "And it came to pass the same night, that the Lord said unto him, Arise, get thee down unto the host; for I have delivered it into thine hand."}, {"numero": 10, "texto": "But if thou fear to go down, go thou with Phurah thy servant down to the host:"}, {"numero": 11, "texto": "And thou shalt hear what they say; and afterward shall thine hands be strengthened to go down unto the host. Then went he down with Phurah his servant unto the outside of the armed men that were in the host."}, {"numero": 12, "texto": "And the Midianites and the Amalekites and all the children of the east lay along in the valley like grasshoppers for multitude; and their camels were without number, as the sand by the sea side for multitude."}, {"numero": 13, "texto": "And when Gideon was come, behold, there was a man that told a dream unto his fellow, and said, Behold, I dreamed a dream, and, lo, a cake of barley bread tumbled into the host of Midian, and came unto a tent, and smote it that it fell, and overturned it, that the tent lay along."}, {"numero": 14, "texto": "And his fellow answered and said, This is nothing else save the sword of Gideon the son of Joash, a man of Israel: for into his hand hath God delivered Midian, and all the host."}, {"numero": 15, "texto": "And it was so, when Gideon heard the telling of the dream, and the interpretation thereof, that he worshipped, and returned into the host of Israel, and said, Arise; for the Lord hath delivered into your hand the host of Midian."}, {"numero": 16, "texto": "And he divided the three hundred men into three companies, and he put a trumpet in every man''s hand, with empty pitchers, and lamps within the pitchers."}, {"numero": 17, "texto": "And he said unto them, Look on me, and do likewise: and, behold, when I come to the outside of the camp, it shall be that, as I do, so shall ye do."}, {"numero": 18, "texto": "When I blow with a trumpet, I and all that are with me, then blow ye the trumpets also on every side of all the camp, and say, The sword of the Lord, and of Gideon."}, {"numero": 19, "texto": "So Gideon, and the hundred men that were with him, came unto the outside of the camp in the beginning of the middle watch; and they had but newly set the watch: and they blew the trumpets, and brake the pitchers that were in their hands."}, {"numero": 20, "texto": "And the three companies blew the trumpets, and brake the pitchers, and held the lamps in their left hands, and the trumpets in their right hands to blow withal: and they cried, The sword of the Lord, and of Gideon."}, {"numero": 21, "texto": "And they stood every man in his place round about the camp; and all the host ran, and cried, and fled."}, {"numero": 22, "texto": "And the three hundred blew the trumpets, and the Lord set every man''s sword against his fellow, even throughout all the host: and the host fled to Bethshittah in Zererath, and to the border of Abelmeholah, unto Tabbath."}, {"numero": 23, "texto": "And the men of Israel gathered themselves together out of Naphtali, and out of Asher, and out of all Manasseh, and pursued after the Midianites."}, {"numero": 24, "texto": "And Gideon sent messengers throughout all mount Ephraim, saying, come down against the Midianites, and take before them the waters unto Bethbarah and Jordan. Then all the men of Ephraim gathered themselves together, and took the waters unto Bethbarah and Jordan."}, {"numero": 25, "texto": "And they took two princes of the Midianites, Oreb and Zeeb; and they slew Oreb upon the rock Oreb, and Zeeb they slew at the winepress of Zeeb, and pursued Midian, and brought the heads of Oreb and Zeeb to Gideon on the other side Jordan."}]'::jsonb, 'King James Version'),
  ('Jz', 7, 'fr', '[{"numero": 1, "texto": "Jerubbaal, qui est Gédéon, et tout le peuple qui était avec lui, se levèrent de bon matin, et campèrent près de la source de Harod. Le camp de Madian était au nord de Gédéon, vers la colline de Moré, dans la vallée."}, {"numero": 2, "texto": "L''''Eternel dit à Gédéon: Le peuple que tu as avec toi est trop nombreux pour que je livre Madian entre ses mains; il pourrait en tirer gloire contre moi, et dire: C''''est ma main qui m''''a délivré."}, {"numero": 3, "texto": "Publie donc ceci aux oreilles du peuple: Que celui qui est craintif et qui a peur s''''en retourne et s''''éloigne de la montagne de Galaad. Vingt-deux mille hommes parmi le peuple s''''en retournèrent, et il en resta dix mille."}, {"numero": 4, "texto": "L''''Eternel dit à Gédéon: Le peuple est encore trop nombreux. Fais-les descendre vers l''''eau, et là je t''''en ferai le triage; celui dont je te dirai: Que celui-ci aille avec toi, ira avec toi; et celui dont je te dirai: Que celui-ci n''''aille pas avec toi, n''''ira pas avec toi."}, {"numero": 5, "texto": "Gédéon fit descendre le peuple vers l''''eau, et l''''Eternel dit à Gédéon: Tous ceux qui laperont l''''eau avec la langue comme lape le chien, tu les sépareras de tous ceux qui se mettront à genoux pour boire."}, {"numero": 6, "texto": "Ceux qui lapèrent l''''eau en la portant à la bouche avec leur main furent au nombre de trois cents hommes, et tout le reste du peuple se mit à genoux pour boire."}, {"numero": 7, "texto": "Et l''''Eternel dit à Gédéon: C''''est par les trois cents hommes qui ont lapé, que je vous sauverai et que je livrerai Madian entre tes mains. Que tout le reste du peuple s''''en aille chacun chez soi."}, {"numero": 8, "texto": "On prit les vivres du peuple et ses trompettes. Puis Gédéon renvoya tous les hommes d''''Israël chacun dans sa tente, et il retint les trois cents hommes. Le camp de Madian était au-dessous de lui dans la vallée."}, {"numero": 9, "texto": "L''''Eternel dit à Gédéon pendant la nuit: Lève-toi, descends au camp, car je l''''ai livré entre tes mains."}, {"numero": 10, "texto": "Si tu crains de descendre, descends-y avec Pura, ton serviteur."}, {"numero": 11, "texto": "Tu écouteras ce qu''''ils diront, et après cela tes mains seront fortifiées: descends donc au camp. Il descendit avec Pura, son serviteur, jusqu''''aux avant-postes du camp."}, {"numero": 12, "texto": "Madian, Amalek, et tous les fils de l''''Orient, étaient répandus dans la vallée comme une multitude de sauterelles, et leurs chameaux étaient innombrables comme le sable qui est sur le bord de la mer."}, {"numero": 13, "texto": "Gédéon arriva; et voici, un homme racontait à son camarade un songe. Il disait: J''''ai eu un songe; et voici, un gâteau de pain d''''orge roulait dans le camp de Madian; il est venu heurter jusqu''''à la tente, et elle est tombée; il l''''a retournée sens dessus dessous, et elle a été renversée."}, {"numero": 14, "texto": "Son camarade répondit, et dit: Ce n''''est pas autre chose que l''''épée de Gédéon, fils de Joas, homme d''''Israël; Dieu a livré entre ses mains Madian et tout le camp."}, {"numero": 15, "texto": "Lorsque Gédéon eut entendu le récit du songe et son explication, il se prosterna, revint au camp d''''Israël, et dit: Levez-vous, car l''''Eternel a livré entre vos mains le camp de Madian."}, {"numero": 16, "texto": "Il divisa en trois corps les trois cents hommes, et il leur remit à tous des trompettes et des cruches vides, avec des flambeaux dans les cruches."}, {"numero": 17, "texto": "Il leur dit: Vous me regarderez et vous ferez comme moi. Dès que j''''aborderai le camp, vous ferez ce que je ferai;"}, {"numero": 18, "texto": "et quand je sonnerai de la trompette, moi et tous ceux qui seront avec moi, vous sonnerez aussi de la trompette tout autour du camp, et vous direz: Pour l''''Eternel et pour Gédéon!"}, {"numero": 19, "texto": "Gédéon et les cent hommes qui étaient avec lui arrivèrent aux abords du camp au commencement de la veille du milieu, comme on venait de placer les gardes. Ils sonnèrent de la trompette, et brisèrent les cruches qu''''ils avaient à la main."}, {"numero": 20, "texto": "Les trois corps sonnèrent de la trompette, et brisèrent les cruches; ils saisirent de la main gauche les flambeaux et de la main droite les trompettes pour sonner, et ils s''''écrièrent: Epée pour l''''Eternel et pour Gédéon!"}, {"numero": 21, "texto": "Ils restèrent chacun à sa place autour du camp, et tout le camp se mit à courir, à pousser des cris, et à prendre la fuite."}, {"numero": 22, "texto": "Les trois cents hommes sonnèrent encore de la trompette; et, dans tout le camp, l''''Eternel leur fit tourner l''''épée les uns contre les autres. Le camp s''''enfuit jusqu''''à Beth-Schitta vers Tseréra, jusqu''''au bord d''''Abel-Mehola près de Tabbath."}, {"numero": 23, "texto": "Les hommes d''''Israël se rassemblèrent, ceux de Nephthali, d''''Aser et de tout Manassé, et ils poursuivirent Madian."}, {"numero": 24, "texto": "Gédéon envoya des messagers dans toute la montagne d''''Ephraïm, pour dire: Descendez à la rencontre de Madian, et coupez-leur le passage des eaux jusqu''''à Beth-Bara et celui du Jourdain. Tous les hommes d''''Ephraïm se rassemblèrent et ils s''''emparèrent du passage des eaux jusqu''''à Beth-Bara et de celui du Jourdain."}, {"numero": 25, "texto": "Ils saisirent deux chefs de Madian, Oreb et Zeeb; ils tuèrent Oreb au rocher d''''Oreb, et ils tuèrent Zeeb au pressoir de Zeeb. Ils poursuivirent Madian, et ils apportèrent les têtes d''''Oreb et de Zeeb à Gédéon de l''''autre côté du Jourdain."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 7, 'es', '[{"numero": 1, "texto": "LEVANTÁNDOSE pues de mañana Jerobaal, el cual es Gedeón, y todo el pueblo que estaba con él, asentaron el campo junto á la fuente de Harod: y tenía el campo de los Madianitas al norte, de la otra parte del collado de More, en el valle."}, {"numero": 2, "texto": "Y Jehová dijo á Gedeón: El pueblo que está contigo es mucho para que yo dé á los Madianitas en su mano: porque no se alabe Israel contra mí, diciendo: Mi mano me ha salvado."}, {"numero": 3, "texto": "Haz pues ahora pregonar, que lo oiga el pueblo, diciendo: El que teme y se estremece, madrugue y vuélvase desde el monte de Galaad. Y volviéronse de los del pueblo veintidós mil: y quedaron diez mil."}, {"numero": 4, "texto": "Y Jehová dijo á Gedeón: Aun es mucho el pueblo; llévalos á las aguas, y allí yo te los probaré; y del que yo te dijere: Vaya este contigo, vaya contigo: mas de cualquiera que yo te dijere: Este no vaya contigo, el tal no vaya."}, {"numero": 5, "texto": "Entonces llevó el pueblo á las aguas: y Jehová dijo á Gedeón: Cualquiera que lamiere las aguas con su lengua como lame el perro, aquél pondrás aparte; asimismo cualquiera que se doblare sobre sus rodillas para beber."}, {"numero": 6, "texto": "Y fué el número de los que lamieron las aguas, llegándola con la mano á la boca, trescientos hombres: y todo el resto del pueblo se dobló sobre sus rodillas para beber las aguas."}, {"numero": 7, "texto": "Entonces Jehová dijo á Gedeón: Con estos trescientos hombres que lamieron el agua os salvaré, y entregaré á los Madianitas en tus manos: y váyase toda la gente cada uno á su lugar."}, {"numero": 8, "texto": "Y tomada provisión para el pueblo en sus manos, y sus bocinas, envió á todos los Israelitas cada uno á su tienda, y retuvo á aquellos trescientos hombres: y tenía el campo de Madián abajo en el valle."}, {"numero": 9, "texto": "Y aconteció que aquella noche Jehová le dijo: Levántate, y desciende al campo; porque yo lo he entregado en tus manos."}, {"numero": 10, "texto": "Y si tienes temor de descender, baja tú con Phara tu criado al campo,"}, {"numero": 11, "texto": "Y oirás lo que hablan; y entonces tus manos se esforzarán, y descenderás al campo. Y él descendió con Phara su criado al principio de la gente de armas que estaba en el campo."}, {"numero": 12, "texto": "Y Madián, y Amalec, y todos los orientales, estaban tendidos en el valle como langostas en muchedumbre, y sus camellos eran innumerables, como la arena que está á la ribera de la mar en multitud."}, {"numero": 13, "texto": "Y luego que llegó Gedeón, he aquí que un hombre estaba contando á su compañero un sueño, diciendo: He aquí yo soñé un sueño: que veía un pan de cebada que rodaba hasta el campo de Madián, y llegaba á las tiendas, y las hería de tal manera que caían, y las trastornaba de arriba abajo, y las tiendas caían."}, {"numero": 14, "texto": "Y su compañero respondió, y dijo: Esto no es otra cosa sino la espada de Gedeón hijo de Joas, varón de Israel: Dios ha entregado en sus manos á los Madianitas con todo el campo."}, {"numero": 15, "texto": "Y como Gedeón oyó la historia del sueño y su interpretación, adoró; y vuelto al campo de Israel, dijo: Levantaos, que Jehová ha entregado el campo de Madián en vuestras manos."}, {"numero": 16, "texto": "Y repartiendo los trescientos hombres en tres escuadrones, dió á cada uno de ellos bocinas en sus manos, y cántaros vacíos con teas ardiendo dentro de los cántaros."}, {"numero": 17, "texto": "Y díjoles: Miradme á mí, y haced como yo hiciere; he aquí que cuando yo llegare al principio del campo, como yo hiciere, así haréis vosotros."}, {"numero": 18, "texto": "Yo tocaré la bocina y todos los que estarán conmigo; y vosotros tocaréis entonces las bocinas alrededor de todo el campo, y diréis: ¡Por Jehová y Gedeón!"}, {"numero": 19, "texto": "Llegó pues Gedeón, y los cien hombres que llevaba consigo, al principio del campo, á la entrada de la vela del medio, cuando acababan de renovar las centinelas; y tocaron las bocinas, y quebraron los cántaros que llevaban en sus manos:"}, {"numero": 20, "texto": "Y los tres escuadrones tocaron las bocinas, y quebrando los cántaros tomaron en las manos izquierdas las teas, y en las derechas los cuernos con que tañían, y dieron grita: ¡La espada de Jehová y de Gedeón!"}, {"numero": 21, "texto": "Y estuviéronse en sus lugares en derredor del campo: y todo el campo fué alborotado, y huyeron gritando."}, {"numero": 22, "texto": "Mas los trescientos tocaban las bocinas: y Jehová puso la espada de cada uno contra su compañero en todo el campo. Y el ejército huyó hasta Beth-sitta, hacia Cerera, y hasta el término de Abel-mehola en Tabbat."}, {"numero": 23, "texto": "Y juntándose los de Israel, de Nephtalí, y de Aser, y de todo Manasés, siguieron á los Madianitas."}, {"numero": 24, "texto": "Gedeón también envió mensajeros á todo el monte de Ephraim, diciendo: Descended al encuentro de los Madianitas, y tomadles las aguas hasta Beth-bara y el Jordán. Y juntos todos los hombres de Ephraim, tomaron las aguas de Beth-bara y el Jordán."}, {"numero": 25, "texto": "Y tomaron dos príncipes de los Madianitas, Oreb y Zeeb: y mataron á Oreb en la peña de Oreb, y á Zeeb lo mataron en el lagar de Zeeb: y después que siguieron á los Madianitas, trajeron las cabezas de Oreb y de Zeeb á Gedeón de la otra parte del Jordán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 13, 'pt', '[{"numero": 1, "texto": "E os filhos de Israel voltaram a fazer o mal aos olhos do SENHOR; e o SENHOR os entregou por mão dos filisteus, por quarenta anos."}, {"numero": 2, "texto": "E havia um homem de Zorá, da tribo de Dã, o qual se chamava Manoá; e sua mulher era estéril, que nunca havia dado à luz."}, {"numero": 3, "texto": "A esta mulher apareceu o anjo do SENHOR, e disse-lhe: Eis que tu és estéril, e não pariste: mas conceberás e darás à luz um filho."}, {"numero": 4, "texto": "Agora, pois, olha que agora não bebas vinho, nem bebida forte, nem comas coisa imunda."}, {"numero": 5, "texto": "Porque tu te farás grávida, e darás à luz um filho: e não subirá navalha sobre sua cabeça, porque aquele menino será nazireu a Deus desde o ventre, e ele começará a salvar a Israel da mão dos filisteus."}, {"numero": 6, "texto": "E a mulher veio e contou-o a seu marido, dizendo: Um homem de Deus veio a mim, cujo aspecto era como o aspecto de um anjo de Deus, terrível em grande maneira; e não lhe perguntei de onde nem quem era, nem tampouco ele me disse seu nome."}, {"numero": 7, "texto": "E disse-me: Eis que tu conceberás, e darás à luz um filho: portanto, agora não bebas vinho, nem bebida forte, nem comas coisa imunda; porque este menino desde o ventre será nazireu a Deus até o dia de sua morte."}, {"numero": 8, "texto": "Então orou Manoá ao SENHOR, e disse: Ah, Senhor meu, eu te rogo que aquele homem de Deus que enviaste, torne agora a vir a nós, e nos ensine o que havemos de fazer com o menino que há de nascer."}, {"numero": 9, "texto": "E Deus ouviu a voz de Manoá: e o anjo de Deus voltou outra vez à mulher, estando ela no campo; mas seu marido Manoá não estava com ela."}, {"numero": 10, "texto": "E a mulher correu prontamente, e noticiou-o a seu marido, dizendo-lhe: Olha que se me apareceu aquele homem que veio a mim o outro dia."}, {"numero": 11, "texto": "E levantou-se Manoá, e seguiu a sua mulher; e assim que chegou ao homem, disse-lhe: És tu aquele homem que falaste à mulher? E ele disse: Eu sou."}, {"numero": 12, "texto": "Então Manoá disse: Cumpra-se pois tua palavra. Que ordem se terá com o menino, e que deve?"}, {"numero": 13, "texto": "E o anjo do SENHOR respondeu a Manoá: A mulher se guardará de todas as coisas que eu lhe disse:"}, {"numero": 14, "texto": "Ela não comerá coisa que proceda da vide que dá vinho; não beberá vinho nem bebida forte, e não comerá coisa imunda: há de guardar tudo o que lhe mandei."}, {"numero": 15, "texto": "Então Manoá disse ao anjo do SENHOR: Rogo-te permitas que te detenhamos, e preparemos um cabrito que pôr diante de ti."}, {"numero": 16, "texto": "E o anjo do SENHOR respondeu a Manoá: Ainda que me detenhas não comerei de teu pão: mas se quiseres fazer holocausto, sacrifica-o ao SENHOR. E não sabia Manoá que aquele fosse anjo do SENHOR."}, {"numero": 17, "texto": "Então disse Manoá ao anjo do SENHOR: Como é teu nome, para que quando se cumprir tua palavra te honremos?"}, {"numero": 18, "texto": "E o anjo do SENHOR respondeu: Por que perguntas por meu nome, que é oculto?"}, {"numero": 19, "texto": "E Manoá tomou um cabrito das cabras e uma oferta de alimentos, e o sacrificou sobre uma rocha ao SENHOR; e o anjo fez algo sobrenatural à vista de Manoá e de sua mulher."}, {"numero": 20, "texto": "Porque aconteceu que, quando a chama subia do altar até o céu, o anjo do SENHOR subiu na chama do altar à vista de Manoá e de sua mulher, os quais se prostraram em terra sobre seus rostos."}, {"numero": 21, "texto": "E o anjo do SENHOR não voltou a aparecer a Manoá nem à sua mulher. Então conheceu Manoá que era o anjo do SENHOR."}, {"numero": 22, "texto": "E disse Manoá à sua mulher: Certamente morreremos, porque vimos a Deus."}, {"numero": 23, "texto": "E sua mulher lhe respondeu: Se o SENHOR nos quisesse matar, não tomaria de nossas mãos o holocausto e a oferta de alimentos, nem nos teria mostrado todas estas coisas, nem em tal tempo nos haveria anunciado isto."}, {"numero": 24, "texto": "E a mulher deu à luz um filho, e chamou-lhe por nome Sansão. E o menino creceu, e o SENHOR o abençoou."}, {"numero": 25, "texto": "E o espírito do SENHOR começou a manifestar-se nele nos acampamentos de Dã, entre Zorá e Estaol."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 13, 'en', '[{"numero": 1, "texto": "And the children of Israel did evil again in the sight of the Lord; and the Lord delivered them into the hand of the Philistines forty years."}, {"numero": 2, "texto": "And there was a certain man of Zorah, of the family of the Danites, whose name was Manoah; and his wife was barren, and bare not."}, {"numero": 3, "texto": "And the angel of the Lord appeared unto the woman, and said unto her, Behold now, thou art barren, and bearest not: but thou shalt conceive, and bear a son."}, {"numero": 4, "texto": "Now therefore beware, I pray thee, and drink not wine nor strong drink, and eat not any unclean thing:"}, {"numero": 5, "texto": "For, lo, thou shalt conceive, and bear a son; and no razor shall come on his head: for the child shall be a Nazarite unto God from the womb: and he shall begin to deliver Israel out of the hand of the Philistines."}, {"numero": 6, "texto": "Then the woman came and told her husband, saying, A man of God came unto me, and his countenance was like the countenance of an angel of God, very terrible: but I asked him not whence he was, neither told he me his name:"}, {"numero": 7, "texto": "But he said unto me, Behold, thou shalt conceive, and bear a son; and now drink no wine nor strong drink, neither eat any unclean thing: for the child shall be a Nazarite to God from the womb to the day of his death."}, {"numero": 8, "texto": "Then Manoah intreated the Lord, and said, O my Lord, let the man of God which thou didst send come again unto us, and teach us what we shall do unto the child that shall be born."}, {"numero": 9, "texto": "And God hearkened to the voice of Manoah; and the angel of God came again unto the woman as she sat in the field: but Manoah her husband was not with her."}, {"numero": 10, "texto": "And the woman made haste, and ran, and shewed her husband, and said unto him, Behold, the man hath appeared unto me, that came unto me the other day."}, {"numero": 11, "texto": "And Manoah arose, and went after his wife, and came to the man, and said unto him, Art thou the man that spakest unto the woman? And he said, I am."}, {"numero": 12, "texto": "And Manoah said, Now let thy words come to pass. How shall we order the child, and how shall we do unto him?"}, {"numero": 13, "texto": "And the angel of the Lord said unto Manoah, Of all that I said unto the woman let her beware."}, {"numero": 14, "texto": "She may not eat of any thing that cometh of the vine, neither let her drink wine or strong drink, nor eat any unclean thing: all that I commanded her let her observe."}, {"numero": 15, "texto": "And Manoah said unto the angel of the Lord, I pray thee, let us detain thee, until we shall have made ready a kid for thee."}, {"numero": 16, "texto": "And the angel of the Lord said unto Manoah, Though thou detain me, I will not eat of thy bread: and if thou wilt offer a burnt offering, thou must offer it unto the Lord. For Manoah knew not that he was an angel of the Lord."}, {"numero": 17, "texto": "And Manoah said unto the angel of the Lord, What is thy name, that when thy sayings come to pass we may do thee honour?"}, {"numero": 18, "texto": "And the angel of the Lord said unto him, Why askest thou thus after my name, seeing it is secret?"}, {"numero": 19, "texto": "So Manoah took a kid with a meat offering, and offered it upon a rock unto the Lord: and the angel did wonderously; and Manoah and his wife looked on."}, {"numero": 20, "texto": "For it came to pass, when the flame went up toward heaven from off the altar, that the angel of the Lord ascended in the flame of the altar. And Manoah and his wife looked on it, and fell on their faces to the ground."}, {"numero": 21, "texto": "But the angel of the Lord did no more appear to Manoah and to his wife. Then Manoah knew that he was an angel of the Lord."}, {"numero": 22, "texto": "And Manoah said unto his wife, We shall surely die, because we have seen God."}, {"numero": 23, "texto": "But his wife said unto him, If the Lord were pleased to kill us, he would not have received a burnt offering and a meat offering at our hands, neither would he have shewed us all these things, nor would as at this time have told us such things as these."}, {"numero": 24, "texto": "And the woman bare a son, and called his name Samson: and the child grew, and the Lord blessed him."}, {"numero": 25, "texto": "And the Spirit of the Lord began to move him at times in the camp of Dan between Zorah and Eshtaol."}]'::jsonb, 'King James Version'),
  ('Jz', 13, 'fr', '[{"numero": 1, "texto": "Les enfants d''''Israël firent encore ce qui déplaît à l''''Eternel; et l''''Eternel les livra entre les mains des Philistins, pendant quarante ans."}, {"numero": 2, "texto": "Il y avait un homme de Tsorea, de la famille des Danites, et qui s''''appelait Manoach. Sa femme était stérile, et n''''enfantait pas."}, {"numero": 3, "texto": "Un ange de l''''Eternel apparut à la femme, et lui dit: Voici, tu es stérile, et tu n''''as point d''''enfants; tu deviendras enceinte, et tu enfanteras un fils."}, {"numero": 4, "texto": "Maintenant prends bien garde, ne bois ni vin ni liqueur forte, et ne mange rien d''''impur."}, {"numero": 5, "texto": "Car tu vas devenir enceinte et tu enfanteras un fils. Le rasoir ne passera point sur sa tête, parce que cet enfant sera consacré à Dieu dès le ventre de sa mère; et ce sera lui qui commencera à délivrer Israël de la main des Philistins."}, {"numero": 6, "texto": "La femme alla dire à son mari; Un homme de Dieu est venu vers moi, et il avait l''''aspect d''''un ange de Dieu, un aspect redoutable. Je ne lui ai pas demandé d''''où il était, et il ne m''''a pas fait connaître son nom."}, {"numero": 7, "texto": "Mais il m''''a dit: Tu vas devenir enceinte, et tu enfanteras un fils; et maintenant ne bois ni vin ni liqueur forte, et ne mange rien d''''impur, parce que cet enfant sera consacré à Dieu dès le ventre de sa mère jusqu''''au jour de sa mort."}, {"numero": 8, "texto": "Manoach fit cette prière à l''''Eternel: Ah! Seigneur, que l''''homme de Dieu que tu as envoyé vienne encore vers nous, et qu''''il nous enseigne ce que nous devons faire pour l''''enfant qui naîtra!"}, {"numero": 9, "texto": "Dieu exauça la prière de Manoach, et l''''ange de Dieu vint encore vers la femme. Elle était assise dans un champ, et Manoach, son mari, n''''était pas avec elle."}, {"numero": 10, "texto": "Elle courut promptement donner cette nouvelle à son mari, et lui dit: Voici, l''''homme qui était venu l''''autre jour vers moi m''''est apparu."}, {"numero": 11, "texto": "Manoach se leva, suivit sa femme, alla vers l''''homme, et lui dit: Est-ce toi qui as parlé à cette femme? Il répondit: C''''est moi."}, {"numero": 12, "texto": "Manoach dit: Maintenant, si ta parole s''''accomplit, que faudra-t-il observer à l''''égard de l''''enfant, et qu''''y aura-t-il à faire?"}, {"numero": 13, "texto": "L''''ange de l''''Eternel répondit à Manoach: La femme s''''abstiendra de tout ce que je lui ai dit."}, {"numero": 14, "texto": "Elle ne goûtera d''''aucun produit de la vigne, elle ne boira ni vin ni liqueur forte, et elle ne mangera rien d''''impur; elle observera tout ce que je lui ai prescrit."}, {"numero": 15, "texto": "Manoach dit à l''''ange de l''''Eternel: Permets-nous de te retenir, et de t''''apprêter un chevreau."}, {"numero": 16, "texto": "L''''ange de l''''Eternel répondit à Manoach: Quand tu me retiendrais, je ne mangerais pas de ton mets; mais si tu veux faire un holocauste, tu l''''offriras à l''''Eternel. Manoach ne savait point que ce fût un ange de l''''Eternel."}, {"numero": 17, "texto": "Et Manoach dit à l''''ange de l''''Eternel: Quel est ton nom, afin que nous te rendions gloire, quand ta parole s''''accomplira?"}, {"numero": 18, "texto": "L''''ange de l''''Eternel lui répondit: Pourquoi demandes-tu mon nom? Il est merveilleux."}, {"numero": 19, "texto": "Manoach prit le chevreau et l''''offrande, et fit un sacrifice à l''''Eternel sur le rocher. Il s''''opéra un prodige, pendant que Manoach et sa femme regardaient."}, {"numero": 20, "texto": "Comme la flamme montait de dessus l''''autel vers le ciel, l''''ange de l''''Eternel monta dans la flamme de l''''autel. A cette vue, Manoach et sa femme tombèrent la face contre terre."}, {"numero": 21, "texto": "L''''ange de l''''Eternel n''''apparut plus à Manoach et à sa femme. Alors Manoach comprit que c''''était l''''ange de l''''Eternel,"}, {"numero": 22, "texto": "et il dit à sa femme: Nous allons mourir, car nous avons vu Dieu."}, {"numero": 23, "texto": "Sa femme lui répondit: Si l''''Eternel eût voulu nous faire mourir, il n''''aurait pas pris de nos mains l''''holocauste et l''''offrande, il ne nous aurait pas fait voir tout cela, et il ne nous aurait pas maintenant fait entendre pareilles choses."}, {"numero": 24, "texto": "La femme enfanta un fils, et lui donna le nom de Samson. L''''enfant grandit, et l''''Eternel le bénit."}, {"numero": 25, "texto": "Et l''''esprit de l''''Eternel commença à l''''agiter à Machané-Dan, entre Tsorea et Eschthaol."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 13, 'es', '[{"numero": 1, "texto": "Y LOS hijos de Israel tornaron á hacer lo malo en los ojos de Jehová; y Jehová los entregó en mano de los Filisteos, por cuarenta años."}, {"numero": 2, "texto": "Y había un hombre de Sora, de la tribu de Dan, el cual se llamaba Manoa; y su mujer era estéril, que nunca había parido."}, {"numero": 3, "texto": "A esta mujer apareció el ángel de Jehová, y díjole: He aquí que tú eres estéril, y no has parido; mas concebirás y parirás un hijo."}, {"numero": 4, "texto": "Ahora, pues, mira que ahora no bebas vino, ni sidra, ni comas cosa inmunda."}, {"numero": 5, "texto": "Porque tú te harás embarazada, y parirás un hijo: y no subirá navaja sobre su cabeza, porque aquel niño será Nazareo á Dios desde el vientre, y él comenzará á salvar á Israel de mano de los Filisteos."}, {"numero": 6, "texto": "Y la mujer vino y contólo á su marido, diciendo: Un varón de Dios vino á mí, cuyo aspecto era como el aspecto de un ángel de Dios, terrible en gran manera; y no le pregunté de dónde ni quién era, ni tampoco él me dijo su nombre."}, {"numero": 7, "texto": "Y díjome: He aquí que tú concebirás, y parirás un hijo: por tanto, ahora no bebas vino, ni sidra, ni comas cosa inmunda; porque este niño desde el vientre será Nazareo á Dios hasta el día de su muerte."}, {"numero": 8, "texto": "Entonces oró Manoa á Jehová, y dijo: Ah, Señor mío, yo te ruego que aquel varón de Dios que enviaste, torne ahora á venir á nosotros, y nos enseñe lo que hayamos de hacer con el niño que ha de nacer."}, {"numero": 9, "texto": "Y Dios oyó la voz de Manoa: y el ángel de Dios volvió otra vez á la mujer, estando ella en el campo; mas su marido Manoa no estaba con ella."}, {"numero": 10, "texto": "Y la mujer corrió prontamente, y noticiólo á su marido, diciéndole: Mira que se me ha aparecido aquel varón que vino á mí el otro día."}, {"numero": 11, "texto": "Y levantóse Manoa, y siguió á su mujer; y así que llegó al varón, díjole: ¿Eres tú aquel varón que hablaste á la mujer? Y él dijo: Yo soy."}, {"numero": 12, "texto": "Entonces Manoa dijo: Cúmplase pues tu palabra. ¿Qué orden se tendrá con el niño, y qué ha de hacer?"}, {"numero": 13, "texto": "Y el ángel de Jehová respondió á Manoa: La mujer se guardará de todas las cosas que yo le dije:"}, {"numero": 14, "texto": "Ella no comerá cosa que proceda de vid que da vino; no beberá vino ni sidra, y no comerá cosa inmunda: ha de guardar todo lo que le mandé."}, {"numero": 15, "texto": "Entonces Manoa dijo al ángel de Jehová: Ruégote permitas que te detengamos, y aderezaremos un cabrito que poner delante de ti."}, {"numero": 16, "texto": "Y el ángel de Jehová respondió á Manoa: Aunque me detengas no comeré de tu pan: mas si quisieres hacer holocausto, sacrifícalo á Jehová. Y no sabía Manoa que aquél fuese ángel de Jehová."}, {"numero": 17, "texto": "Entonces dijo Manoa al ángel de Jehová: ¿Cómo es tu nombre, para que cuando se cumpliere tu palabra te honremos?"}, {"numero": 18, "texto": "Y el ángel de Jehová respondió: ¿Por qué preguntas por mi nombre, que es oculto?"}, {"numero": 19, "texto": "Y Manoa tomó un cabrito de las cabras y un presente, y sacrificólo sobre una peña á Jehová: y el ángel hizo milagro á vista de Manoa y de su mujer."}, {"numero": 20, "texto": "Porque aconteció que como la llama subía del altar hacia el cielo, el ángel de Jehová subió en la llama del altar á vista de Manoa y de su mujer, los cuales se postraron en tierra sobre sus rostros."}, {"numero": 21, "texto": "Y el ángel de Jehová no tornó á aparecer á Manoa ni á su mujer. Entonces conoció Manoa que era el ángel de Jehová."}, {"numero": 22, "texto": "Y dijo Manoa á su mujer: Ciertamente moriremos, porque á Dios hemos visto."}, {"numero": 23, "texto": "Y su mujer le respondió: Si Jehová nos quisiera matar, no tomara de nuestras manos el holocausto y el presente, ni nos hubiera mostrado todas estas cosas, ni en tal tiempo nos habría anunciado esto."}, {"numero": 24, "texto": "Y la mujer parió un hijo, y llamóle por nombre Samsón. Y el niño creció, y Jehová lo bendijo."}, {"numero": 25, "texto": "Y el espíritu de Jehová comenzó á manifestarse en él en los campamentos de Dan, entre Sora y Esthaol."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 14, 'pt', '[{"numero": 1, "texto": "E descendo Sansão a Timna, viu em Timna uma mulher das filhas dos filisteus."}, {"numero": 2, "texto": "E subiu, e declarou-o a seu pai e a sua mãe, dizendo: Eu vi em Timna uma mulher das filhas dos filisteus: rogo-vos que a deis a mim por mulher."}, {"numero": 3, "texto": "E seu pai e sua mãe lhe disseram: Não há mulher entre as filhas de teus irmãos, nem em todo meu povo, para que vás tu a tomar mulher dos filisteus incircuncisos? E Sansão respondeu a seu pai: Toma-a a mim por mulher, porque esta agradou a meus olhos."}, {"numero": 4, "texto": "Mas seu pai e sua mãe não sabiam que isto vinha do SENHOR, e que ele buscava ocasião contra os filisteus: porque naquele tempo os filisteus dominavam sobre Israel."}, {"numero": 5, "texto": "E Sansão desceu com seu pai e com sua mãe a Timna: e quando chegaram às vinhas de Timna, eis que um leão jovem que vinha bramando até ele."}, {"numero": 6, "texto": "E o espírito do SENHOR caiu sobre ele, e despedaçou-o como quem despedaça um cabrito, sem ter nada em sua mão: e não deu a entender a seu pai nem a sua mãe o que havia feito."}, {"numero": 7, "texto": "Veio, pois, e falou à mulher que havia agradado a Sansão."}, {"numero": 8, "texto": "E voltando depois de alguns dias para tomá-la, apartou-se para ver o corpo morto do leão, e eis que no corpo do leão um enxame de abelhas, e um favo de mel."}, {"numero": 9, "texto": "E tomando-o em suas mãos, foi-se comendo-o pelo caminho: e chegado que houve a seu pai e a sua mãe, deu-lhes também a eles que comessem; mas não lhes revelou que havia tomado aquela mel do corpo do leão."}, {"numero": 10, "texto": "Veio, pois, seu pai à mulher, e Sansão fez ali banquete; porque assim costumavam fazer os rapazes."}, {"numero": 11, "texto": "E quando eles o viram, tomaram trinta companheiros que estivessem com ele;"}, {"numero": 12, "texto": "Aos quais Sansão disse: Eu vos proporei agora um enigma, o qual se nos sete dias do banquete vós me declarardes e descobrirdes, eu vos darei trinta sábanas e trinta mudas de vestidos."}, {"numero": 13, "texto": "Mas se não o souberes declarar a mim, vós me dareis as trinta mantas e as trinta mudas de vestidos. E eles responderam: Propõe-nos teu enigma, e o ouviremos."}, {"numero": 14, "texto": "Então lhes disse: Do comedor saiu comida, E do forte saiu doçura. E eles não puderam declarar-lhe o enigma em três dias."}, {"numero": 15, "texto": "E ao sétimo dia disseram à mulher de Sansão: Induz a teu marido a que nos declare este enigma, para que não te queimemos a ti e à casa de teu pai. Chamaste-nos aqui para possuir-nos?"}, {"numero": 16, "texto": "E chorou a mulher de Sansão diante dele, e disse: Somente me aborreces e não me amas, pois que não me declaras o enigma que propuseste aos filhos de meu povo. E ele respondeu: Eis que nem a meu pai nem a minha mãe o declarei; e havia eu de declará-lo a ti?"}, {"numero": 17, "texto": "E ela chorou diante dele os sete dias que eles tiveram banquete: mas ao sétimo dia ele o declarou a ela, porque lhe constrangeu; e ela o declarou aos filhos de seu povo."}, {"numero": 18, "texto": "E ao sétimo dia, antes que o sol se pusesse, os da cidade lhe disseram: Que coisa mais doce que o mel? E que coisa mais forte que o leão? Se não arásseis com minha novilha, Nunca teríeis descoberto meu enigma."}, {"numero": 19, "texto": "E o espírito do SENHOR caiu sobre ele, e desceu a Asquelom, e feriu trinta homens deles; e tomando seus despojos, deu as mudas de vestidos aos que haviam explicado o enigma: e acendido em ira foi-se à casa de seu pai."}, {"numero": 20, "texto": "E a mulher de Sansão foi dada a seu companheiro, com o qual ele antes se acompanhava."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 14, 'en', '[{"numero": 1, "texto": "And Samson went down to Timnath, and saw a woman in Timnath of the daughters of the Philistines."}, {"numero": 2, "texto": "And he came up, and told his father and his mother, and said, I have seen a woman in Timnath of the daughters of the Philistines: now therefore get her for me to wife."}, {"numero": 3, "texto": "Then his father and his mother said unto him, Is there never a woman among the daughters of thy brethren, or among all my people, that thou goest to take a wife of the uncircumcised Philistines? And Samson said unto his father, Get her for me; for she pleaseth me well."}, {"numero": 4, "texto": "But his father and his mother knew not that it was of the Lord, that he sought an occasion against the Philistines: for at that time the Philistines had dominion over Israel."}, {"numero": 5, "texto": "Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him."}, {"numero": 6, "texto": "And the Spirit of the Lord came mightily upon him, and he rent him as he would have rent a kid, and he had nothing in his hand: but he told not his father or his mother what he had done."}, {"numero": 7, "texto": "And he went down, and talked with the woman; and she pleased Samson well."}, {"numero": 8, "texto": "And after a time he returned to take her, and he turned aside to see the carcase of the lion: and, behold, there was a swarm of bees and honey in the carcase of the lion."}, {"numero": 9, "texto": "And he took thereof in his hands, and went on eating, and came to his father and mother, and he gave them, and they did eat: but he told not them that he had taken the honey out of the carcase of the lion."}, {"numero": 10, "texto": "So his father went down unto the woman: and Samson made there a feast; for so used the young men to do."}, {"numero": 11, "texto": "And it came to pass, when they saw him, that they brought thirty companions to be with him."}, {"numero": 12, "texto": "And Samson said unto them, I will now put forth a riddle unto you: if ye can certainly declare it me within the seven days of the feast, and find it out, then I will give you thirty sheets and thirty change of garments:"}, {"numero": 13, "texto": "But if ye cannot declare it me, then shall ye give me thirty sheets and thirty change of garments. And they said unto him, Put forth thy riddle, that we may hear it."}, {"numero": 14, "texto": "And he said unto them, Out of the eater came forth meat, and out of the strong came forth sweetness. And they could not in three days expound the riddle."}, {"numero": 15, "texto": "And it came to pass on the seventh day, that they said unto Samson''s wife, Entice thy husband, that he may declare unto us the riddle, lest we burn thee and thy father''s house with fire: have ye called us to take that we have? is it not so?"}, {"numero": 16, "texto": "And Samson''s wife wept before him, and said, Thou dost but hate me, and lovest me not: thou hast put forth a riddle unto the children of my people, and hast not told it me. And he said unto her, Behold, I have not told it my father nor my mother, and shall I tell it thee?"}, {"numero": 17, "texto": "And she wept before him the seven days, while their feast lasted: and it came to pass on the seventh day, that he told her, because she lay sore upon him: and she told the riddle to the children of her people."}, {"numero": 18, "texto": "And the men of the city said unto him on the seventh day before the sun went down, What is sweeter than honey? And what is stronger than a lion? and he said unto them, If ye had not plowed with my heifer, ye had not found out my riddle."}, {"numero": 19, "texto": "And the Spirit of the Lord came upon him, and he went down to Ashkelon, and slew thirty men of them, and took their spoil, and gave change of garments unto them which expounded the riddle. And his anger was kindled, and he went up to his father''s house."}, {"numero": 20, "texto": "But Samson''s wife was given to his companion, whom he had used as his friend."}]'::jsonb, 'King James Version'),
  ('Jz', 14, 'fr', '[{"numero": 1, "texto": "Samson descendit à Thimna, et il y vit une femme parmi les filles des Philistins."}, {"numero": 2, "texto": "Lorsqu''''il fut remonté, il le déclara à son père et à sa mère, et dit: J''''ai vu à Thimna une femme parmi les filles des Philistins; prenez-la maintenant pour ma femme."}, {"numero": 3, "texto": "Son père et sa mère lui dirent: N''''y a-t-il point de femme parmi les filles de tes frères et dans tout notre peuple, que tu ailles prendre une femme chez les Philistins, qui sont incirconcis? Et Samson dit à son père: Prends-la pour moi, car elle me plaît."}, {"numero": 4, "texto": "Son père et sa mère ne savaient pas que cela venait de l''''Eternel: car Samson cherchait une occasion de dispute de la part des Philistins. En ce temps-là, les Philistins dominaient sur Israël."}, {"numero": 5, "texto": "Samson descendit avec son père et sa mère à Thimna. Lorsqu''''ils arrivèrent aux vignes de Thimna, voici, un jeune lion rugissant vint à sa rencontre."}, {"numero": 6, "texto": "L''''esprit de l''''Eternel saisit Samson; et, sans avoir rien à la main, Samson déchira le lion comme on déchire un chevreau. Il ne dit point à son père et à sa mère ce qu''''il avait fait."}, {"numero": 7, "texto": "Il descendit et parla à la femme, et elle lui plut."}, {"numero": 8, "texto": "Quelque temps après, il se rendit de nouveau à Thimna pour la prendre, et se détourna pour voir le cadavre du lion. Et voici, il y avait un essaim d''''abeilles et du miel dans le corps du lion."}, {"numero": 9, "texto": "Il prit entre ses mains le miel, dont il mangea pendant la route; et lorsqu''''il fut arrivé près de son père et de sa mère, il leur en donna, et ils en mangèrent. Mais il ne leur dit pas qu''''il avait pris ce miel dans le corps du lion."}, {"numero": 10, "texto": "Le père de Samson descendit chez la femme. Et là, Samson fit un festin, car c''''était la coutume des jeunes gens."}, {"numero": 11, "texto": "Dès qu''''on le vit, on invita trente compagnons qui se tinrent avec lui."}, {"numero": 12, "texto": "Samson leur dit: Je vais vous proposer une énigme. Si vous me l''''expliquez pendant les sept jours du festin, et si vous la découvrez, je vous donnerai trente chemises et trente vêtements de rechange."}, {"numero": 13, "texto": "Mais si vous ne pouvez pas me l''''expliquer, ce sera vous qui me donnerez trente chemises et trente vêtements de rechange. Ils lui dirent: Propose ton énigme, et nous l''''écouterons."}, {"numero": 14, "texto": "Et il leur dit: De celui qui mange est sorti ce qui se mange, et du fort est sorti le doux. Pendant trois jours, ils ne purent expliquer l''''énigme."}, {"numero": 15, "texto": "Le septième jour, ils dirent à la femme de Samson: Persuade à ton mari de nous expliquer l''''énigme; sinon, nous te brûlerons, toi et la maison de ton père. C''''est pour nous dépouiller que vous nous avez invités, n''''est-ce pas?"}, {"numero": 16, "texto": "La femme de Samson pleurait auprès de lui, et disait: Tu n''''as pour moi que de la haine, et tu ne m''''aimes pas; tu as proposé une énigme aux enfants de mon peuple, et tu ne me l''''as point expliquée! Et il lui répondait: Je ne l''''ai expliquée ni à mon père ni à ma mère; est-ce à toi que je l''''expliquerais?"}, {"numero": 17, "texto": "Elle pleura auprès de lui pendant les sept jours que dura leur festin; et le septième jour, il la lui expliqua, car elle le tourmentait. Et elle donna l''''explication de l''''énigme aux enfants de son peuple."}, {"numero": 18, "texto": "Les gens de la ville dirent à Samson le septième jour, avant le coucher du soleil: Quoi de plus doux que le miel, et quoi de plus fort que le lion? Et il leur dit: Si vous n''''aviez pas labouré avec ma génisse, vous n''''auriez pas découvert mon énigme."}, {"numero": 19, "texto": "L''''esprit de l''''Eternel le saisit, et il descendit à Askalon. Il y tua trente hommes, prit leurs dépouilles, et donna les vêtements de rechange à ceux qui avaient expliqué l''''énigme. Il était enflammé de colère, et il monta à la maison de son père."}, {"numero": 20, "texto": "Sa femme fut donnée à l''''un de ses compagnons, avec lequel il était lié."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 14, 'es', '[{"numero": 1, "texto": "Y DESCENDIENDO Samsón á Timnah, vió en Timnah una mujer de las hijas de los Filisteos."}, {"numero": 2, "texto": "Y subió, y declarólo á su padre y á su madre, diciendo: Yo he visto en Timnah una mujer de las hijas de los Filisteos: ruégoos que me la toméis por mujer."}, {"numero": 3, "texto": "Y su padre y su madre le dijeron: ¿No hay mujer entre las hijas de tus hermanos, ni en todo mi pueblo, para que vayas tú á tomar mujer de los Filisteos incircuncisos? Y Samsón respondió á su padre: Tómamela por mujer, porque ésta agradó á mis ojos."}, {"numero": 4, "texto": "Mas su padre y su madre no sabían que esto venía de Jehová, y que él buscaba ocasión contra los Filisteos: porque en aquel tiempo los Filisteos dominaban sobre Israel."}, {"numero": 5, "texto": "Y Samsón descendió con su padre y con su madre á Timnah: y como llegaron á las viñas de Timnah, he aquí un cachorro de león que venía bramando hacia él."}, {"numero": 6, "texto": "Y el espíritu de Jehová cayó sobre él, y despedazólo como quien despedaza un cabrito, sin tener nada en su mano: y no dió á entender á su padre ni á su madre lo que había hecho."}, {"numero": 7, "texto": "Vino pues, y habló á la mujer que había agradado á Samsón."}, {"numero": 8, "texto": "Y volviendo después de algunos días para tomarla, apartóse para ver el cuerpo muerto del león, y he aquí en el cuerpo del león un enjambre de abejas, y un panal de miel."}, {"numero": 9, "texto": "Y tomándolo en sus manos, fuése comiéndolo por el camino: y llegado que hubo á su padre y á su madre, dióles también á ellos que comiesen; mas no les descubrió que había tomado aquella miel del cuerpo del león."}, {"numero": 10, "texto": "Vino pues su padre á la mujer, y Samsón hizo allí banquete; porque así solían hacer los mancebos."}, {"numero": 11, "texto": "Y como ellos le vieron, tomaron treinta compañeros que estuviesen con él;"}, {"numero": 12, "texto": "A los cuales Samsón dijo: Yo os propondré ahora un enigma, el cual si en los siete días del banquete vosotros me declarareis y descubriereis, yo os daré treinta sábanas y treinta mudas de vestidos."}, {"numero": 13, "texto": "Mas si no me lo supiereis declarar, vosotros me daréis las treinta sábanas y las treinta mudas de vestidos. Y ellos respondieron: Propónnos tu enigma, y lo oiremos."}, {"numero": 14, "texto": "Entonces les dijo: Del comedor salió comida, y del fuerte salió dulzura. Y ellos no pudieron declararle el enigma en tres días."}, {"numero": 15, "texto": "Y al séptimo día dijeron á la mujer de Samsón: Induce á tu marido á que nos declare este enigma, porque no te quememos á ti y á la casa de tu padre. ¿Habéisnos llamado aquí para poseernos?"}, {"numero": 16, "texto": "Y lloró la mujer de Samsón delante de él, y dijo: Solamente me aborreces y no me amas, pues que no me declaras el enigma que propusiste á los hijos de mi pueblo. Y él respondió: He aquí que ni á mi padre ni á mi madre lo he declarado; y ¿habíalo de declarar á ti?"}, {"numero": 17, "texto": "Y ella lloró delante de él los siete días que ellos tuvieron banquete: mas al séptimo día él se lo declaró, porque le constriñó; y ella lo declaró á los hijos de su pueblo."}, {"numero": 18, "texto": "Y al séptimo día, antes que el sol se pusiese, los de la ciudad le dijeron: ¿Qué cosa más dulce que la miel? ¿y qué cosa más fuerte que el león?"}, {"numero": 19, "texto": "Y él les respondió: Si no araseis con mi novilla, nunca hubierais descubierto mi enigma."}, {"numero": 20, "texto": "Y el espíritu de Jehová cayó sobre él, y descendió á Ascalón, é hirió treinta hombres de ellos; y tomando sus despojos, dió las mudas de vestidos á los que habían explicado el enigma: y encendido en enojo fuése á casa de su padre. Y la mujer de Samsón fué dada á su compañero, con el cual él antes se acompañaba."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 15, 'pt', '[{"numero": 1, "texto": "E aconteceu depois de dias, que no tempo da colheita do trigo, Sansão visitou à sua mulher com um cabrito, dizendo: Entrarei à minha mulher à câmara. Mas o pai dela não o deixou entrar."}, {"numero": 2, "texto": "E disse o pai dela: Persuadi-me que a aborrecias, e dei-a a teu companheiro. Mas sua irmã menor, não é mais bela que ela? Toma-a, pois, em seu lugar."}, {"numero": 3, "texto": "E Sansão lhes respondeu: Eu serei sem culpa esta vez para com os filisteus, se mal lhes fizer."}, {"numero": 4, "texto": "E foi Sansão e agarrou trezentas raposas, e tomando tochas, e segurando aquelas pelas caudas, pôs entre cada duas caudas uma tocha."}, {"numero": 5, "texto": "Depois, acendendo as tochas, lançou as raposas nas plantações dos filisteus, e queimou pilhas de cereais e cereais nos pés, e vinhas e olivais."}, {"numero": 6, "texto": "E disseram os filisteus: Quem fez isto? E foi-lhes dito: Sansão, o genro do timnateu, porque lhe tirou sua mulher e a deu a seu companheiro. E vieram os filisteus, e queimaram a fogo a ela e a seu pai."}, {"numero": 7, "texto": "Então Sansão lhes disse: Assim o havíeis de fazer? Mas eu me vingarei de vós, e depois cessarei."}, {"numero": 8, "texto": "E feriu-os perna e coxa com grande mortandade; e desceu, e ficou na caverna da penha de Etã."}, {"numero": 9, "texto": "E os filisteus subiram e puseram acampamento em Judá, e estenderam-se por Leí."}, {"numero": 10, "texto": "E os homens de Judá lhes disseram: Por que subistes contra nós? E eles responderam: A prender a Sansão subimos, para fazer-lhe como ele nos fez."}, {"numero": 11, "texto": "E vieram três mil homens de Judá à caverna da penha de Etã, e disseram a Sansão: Não sabes tu que os filisteus dominam sobre nós? Por que nos fizeste isto? E ele lhes respondeu: Eu lhes fiz como eles me fizeram."}, {"numero": 12, "texto": "Eles então lhe disseram: Nós viemos para prender-te, e entregar-te em mão dos filisteus. E Sansão lhes respondeu: Jurai-me que vós não me matareis."}, {"numero": 13, "texto": "E eles lhe responderam, dizendo: Não, somente te prenderemos, e te entregaremos em suas mãos; mas não te mataremos. Então lhe ataram com duas cordas novas, e fizeram-lhe vir da penha."}, {"numero": 14, "texto": "E assim que veio até Leí, os filisteus lhe saíram a receber com gritos de vitória: e o espírito do SENHOR caiu sobre ele, e as cordas que estavam em seus braços se tornaram como linho queimado com fogo, e as amarras se caíram de suas mãos."}, {"numero": 15, "texto": "E achando uma queixada de asno fresca, estendeu a mão e tomou-a, e feriu com ela a mil homens."}, {"numero": 16, "texto": "Então Sansão disse: Com a queixada de um asno, um amontoado, dois amontoados; Com a queixada de um asno feri mil homens."}, {"numero": 17, "texto": "E acabando de falar, lançou de sua mão a queixada, e chamou a aquele lugar Ramate-Leí."}, {"numero": 18, "texto": "E tendo grande sede, clamou logo ao SENHOR, e disse: Tu deste esta grande salvação por meio de teu servo: e morrerei eu agora de sede, e cairei em mão dos incircuncisos?"}, {"numero": 19, "texto": "Então quebrou Deus uma cavidade em Leí, e saíram dali águas, e bebeu, e recuperou seu espírito, e reanimou-se. Portanto chamou seu nome daquele lugar, En-Hacoré, o qual é em Leí, até hoje."}, {"numero": 20, "texto": "E julgou a Israel nos dias dos filisteus vinte anos."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 15, 'en', '[{"numero": 1, "texto": "But it came to pass within a while after, in the time of wheat harvest, that Samson visited his wife with a kid; and he said, I will go in to my wife into the chamber. But her father would not suffer him to go in."}, {"numero": 2, "texto": "And her father said, I verily thought that thou hadst utterly hated her; therefore I gave her to thy companion: is not her younger sister fairer than she? take her, I pray thee, instead of her."}, {"numero": 3, "texto": "And Samson said concerning them, Now shall I be more blameless than the Philistines, though I do them a displeasure."}, {"numero": 4, "texto": "And Samson went and caught three hundred foxes, and took firebrands, and turned tail to tail, and put a firebrand in the midst between two tails."}, {"numero": 5, "texto": "And when he had set the brands on fire, he let them go into the standing corn of the Philistines, and burnt up both the shocks, and also the standing corn, with the vineyards and olives."}, {"numero": 6, "texto": "Then the Philistines said, Who hath done this? And they answered, Samson, the son in law of the Timnite, because he had taken his wife, and given her to his companion. And the Philistines came up, and burnt her and her father with fire."}, {"numero": 7, "texto": "And Samson said unto them, Though ye have done this, yet will I be avenged of you, and after that I will cease."}, {"numero": 8, "texto": "And he smote them hip and thigh with a great slaughter: and he went down and dwelt in the top of the rock Etam."}, {"numero": 9, "texto": "Then the Philistines went up, and pitched in Judah, and spread themselves in Lehi."}, {"numero": 10, "texto": "And the men of Judah said, Why are ye come up against us? And they answered, To bind Samson are we come up, to do to him as he hath done to us."}, {"numero": 11, "texto": "Then three thousand men of Judah went to the top of the rock Etam, and said to Samson, Knowest thou not that the Philistines are rulers over us? what is this that thou hast done unto us? And he said unto them, As they did unto me, so have I done unto them."}, {"numero": 12, "texto": "And they said unto him, We are come down to bind thee, that we may deliver thee into the hand of the Philistines. And Samson said unto them, Swear unto me, that ye will not fall upon me yourselves."}, {"numero": 13, "texto": "And they spake unto him, saying, No; but we will bind thee fast, and deliver thee into their hand: but surely we will not kill thee. And they bound him with two new cords, and brought him up from the rock."}, {"numero": 14, "texto": "And when he came unto Lehi, the Philistines shouted against him: and the Spirit of the Lord came mightily upon him, and the cords that were upon his arms became as flax that was burnt with fire, and his bands loosed from off his hands."}, {"numero": 15, "texto": "And he found a new jawbone of an ass, and put forth his hand, and took it, and slew a thousand men therewith."}, {"numero": 16, "texto": "And Samson said, With the jawbone of an ass, heaps upon heaps, with the jaw of an ass have I slain a thousand men."}, {"numero": 17, "texto": "And it came to pass, when he had made an end of speaking, that he cast away the jawbone out of his hand, and called that place Ramathlehi."}, {"numero": 18, "texto": "And he was sore athirst, and called on the Lord, and said, Thou hast given this great deliverance into the hand of thy servant: and now shall I die for thirst, and fall into the hand of the uncircumcised?"}, {"numero": 19, "texto": "But God clave an hollow place that was in the jaw, and there came water thereout; and when he had drunk, his spirit came again, and he revived: wherefore he called the name thereof Enhakkore, which is in Lehi unto this day."}, {"numero": 20, "texto": "And he judged Israel in the days of the Philistines twenty years."}]'::jsonb, 'King James Version'),
  ('Jz', 15, 'fr', '[{"numero": 1, "texto": "Quelque temps après, à l''''époque de la moisson des blés, Samson alla voir sa femme, et lui porta un chevreau. Il dit: Je veux entrer vers ma femme dans sa chambre. Mais le père de sa femme ne lui permit pas d''''entrer."}, {"numero": 2, "texto": "J''''ai pensé dit-il, que tu avais pour elle de la haine, et je l''''ai donnée à ton compagnon. Est-ce que sa jeune soeur n''''est pas plus belle qu''''elle? Prends-la donc à sa place."}, {"numero": 3, "texto": "Samson leur dit: Cette fois je ne serai pas coupable envers les Philistins, si je leur fais du mal."}, {"numero": 4, "texto": "Samson s''''en alla. Il attrapa trois cents renards, et prit des flambeaux; puis il tourna queue contre queue, et mit un flambeau entre deux queues, au milieu."}, {"numero": 5, "texto": "Il alluma les flambeaux, lâcha les renards dans les blés des Philistins, et embrasa les tas de gerbes, le blé sur pied, et jusqu''''aux plantations d''''oliviers."}, {"numero": 6, "texto": "Les Philistins dirent: Qui a fait cela? On répondit: Samson, le gendre du Thimnien, parce que celui-ci lui a pris sa femme et l''''a donnée à son compagnon. Et les Philistins montèrent, et ils la brûlèrent, elle et son père."}, {"numero": 7, "texto": "Samson leur dit: Est-ce ainsi que vous agissez? Je ne cesserai qu''''après m''''être vengé de vous."}, {"numero": 8, "texto": "Il les battit rudement, dos et ventre; puis il descendit, et se retira dans la caverne du rocher d''''Etam."}, {"numero": 9, "texto": "Alors les Philistins se mirent en marche, campèrent en Juda, et s''''étendirent jusqu''''à Léchi."}, {"numero": 10, "texto": "Les hommes de Juda dirent: Pourquoi êtes-vous montés contre nous? Ils répondirent: Nous sommes montés pour lier Samson, afin de le traiter comme il nous a traités."}, {"numero": 11, "texto": "Sur quoi trois mille hommes de Juda descendirent à la caverne du rocher d''''Etam, et dirent à Samson: Ne sais-tu pas que les Philistins dominent sur nous? Que nous as-tu donc fait? Il leur répondit: Je les ai traités comme ils m''''ont traité."}, {"numero": 12, "texto": "Ils lui dirent: Nous sommes descendus pour te lier, afin de te livrer entre les mains des Philistins. Samson leur dit: Jurez-moi que vous ne me tuerez pas."}, {"numero": 13, "texto": "Ils lui répondirent: Non; nous voulons seulement te lier et te livrer entre leurs mains, mais nous ne te ferons pas mourir. Et ils le lièrent avec deux cordes neuves, et le firent sortir du rocher."}, {"numero": 14, "texto": "Lorsqu''''il arriva à Léchi, les Philistins poussèrent des cris à sa rencontre. Alors l''''esprit de l''''Eternel le saisit. Les cordes qu''''il avait aux bras devinrent comme du lin brûlé par le feu, et ses liens tombèrent de ses mains."}, {"numero": 15, "texto": "Il trouva une mâchoire d''''âne fraîche, il étendit sa main pour la prendre, et il en tua mille hommes."}, {"numero": 16, "texto": "Et Samson dit: Avec une mâchoire d''''âne, un monceau, deux monceaux; Avec une mâchoire d''''âne, j''''ai tué mille hommes."}, {"numero": 17, "texto": "Quand il eut achevé de parler, il jeta de sa main la mâchoire. Et l''''on appela ce lieu Ramath-Léchi."}, {"numero": 18, "texto": "Pressé par la soif, il invoqua l''''Eternel, et dit: C''''est toi qui as permis par la main de ton serviteur cette grande délivrance; et maintenant mourrais je de soif, et tomberais-je entre les mains des incirconcis?"}, {"numero": 19, "texto": "Dieu fendit la cavité du rocher qui est à Léchi, et il en sortit de l''''eau. Samson but, son esprit se ranima, et il reprit vie. C''''est de là qu''''on a appelé cette source En-Hakkoré; elle existe encore aujourd''''hui à Léchi."}, {"numero": 20, "texto": "Samson fut juge en Israël, au temps des Philistins, pendant vingt ans."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 15, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ después de días, que en el tiempo de la siega del trigo, Samsón visitó á su mujer con un cabrito, diciendo: Entraré á mi mujer á la cámara. Mas el padre de ella no lo dejó entrar."}, {"numero": 2, "texto": "Y dijo el padre de ella: Persuadíme que la aborrecías, y díla á tu compañero. Mas su hermana menor, ¿no es más hermosa que ella? tómala, pues, en su lugar."}, {"numero": 3, "texto": "Y Samsón les respondió: Yo seré sin culpa esta vez para con los Filisteos, si mal les hiciere."}, {"numero": 4, "texto": "Y fué Samsón y cogió trescientas zorras, y tomando teas, y trabando aquéllas por las colas, puso entre cada dos colas una tea."}, {"numero": 5, "texto": "Después, encendiendo las teas, echó las zorras en los sembrados de los Filisteos, y quemó hacinas y mieses, y viñas y olivares."}, {"numero": 6, "texto": "Y dijeron los Filisteos: ¿Quién hizo esto? Y fuéles dicho: Samsón, el yerno del Timnateo, porque le quitó su mujer y la dió á su compañero. Y vinieron los Filisteos, y quemaron á fuego á ella y á su padre."}, {"numero": 7, "texto": "Entonces Samsón les dijo: ¿Así lo habíais de hacer? mas yo me vengaré de vosotros, y después cesaré."}, {"numero": 8, "texto": "E hiriólos pierna y muslo con gran mortandad; y descendió, y fijóse en la cueva de la peña de Etam."}, {"numero": 9, "texto": "Y los Filisteos subieron y pusieron campo en Judá, y tendiéronse por Lehi."}, {"numero": 10, "texto": "Y los varones de Judá les dijeron: ¿Por qué habéis subido contra nosotros? Y ellos respondieron: A prender á Samsón hemos subido, para hacerle como él nos ha hecho."}, {"numero": 11, "texto": "Y vinieron tres mil hombres de Judá á la cueva de la peña de Etam, y dijeron á Samsón: ¿No sabes tú que los Filisteos dominan sobre nosotros? ¿por qué nos has hecho esto? Y él les respondió: Yo les he hecho como ellos me hicieron."}, {"numero": 12, "texto": "Ellos entonces le dijeron: Nosotros hemos venido para prenderte, y entregarte en mano de los Filisteos. Y Samsón les respondió: Juradme que vosotros no me mataréis."}, {"numero": 13, "texto": "Y ellos le respondieron, diciendo: No, solamente te prenderemos, y te entregaremos en sus manos; mas no te mataremos. Entonces le ataron con dos cuerdas nuevas, é hiciéronle venir de la peña."}, {"numero": 14, "texto": "Y así que vino hasta Lehi, los Filisteos le salieron á recibir con algazara: y el espíritu de Jehová cayó sobre él, y las cuerdas que estaban en sus brazos se tornaron como lino quemado con fuego, y las ataduras se cayeron de sus manos."}, {"numero": 15, "texto": "Y hallando una quijada de asno fresca, extendió la mano y tomóla, é hirió con ella á mil hombres."}, {"numero": 16, "texto": "Entonces Samsón dijo: con la quijada de un asno, un montón, dos montones; con la quijada de un asno herí mil hombres."}, {"numero": 17, "texto": "Y acabando de hablar, echó de su mano la quijada, y llamó á aquel lugar Ramath-lehi."}, {"numero": 18, "texto": "Y teniendo gran sed, clamó luego á Jehová, y dijo: Tú has dado esta gran salud por mano de tu siervo: ¿y moriré yo ahora de sed, y caeré en mano de los incircuncisos?"}, {"numero": 19, "texto": "Entonces quebró Dios una muela que estaba en la quijada, y salieron de allí aguas, y bebió, y recobró su espíritu, y reanimóse. Por tanto llamó su nombre de aquel lugar, En-haccore, el cual es en Lehi, hasta hoy."}, {"numero": 20, "texto": "Y juzgó á Israel en días de los Filisteos veinte años."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jz', 16, 'pt', '[{"numero": 1, "texto": "E foi Sansão a Gaza, e viu ali uma mulher prostituta, e se deitou com ela."}, {"numero": 2, "texto": "E foi dito aos de Gaza: Sansão veio aqui. E cercaram-no, e puseram-lhe espias toda aquela noite à porta da cidade: e estiveram calados toda aquela noite, dizendo: Até a luz da manhã; então o mataremos."}, {"numero": 3, "texto": "Mas Sansão dormiu até a meia noite; e à meia noite se levantou, e tomando as portas da cidade com seus dois pilares e seu ferrolho, lançou-as ao ombro, e foi-se, e subiu-se com elas ao cume do monte que está diante de Hebrom."}, {"numero": 4, "texto": "Depois disto aconteceu que se apaixonou por uma mulher no vale de Soreque, a qual se chamava Dalila."}, {"numero": 5, "texto": "E vieram a ela os príncipes dos filisteus, e disseram-lhe: Engana-o e sabe em que consiste sua grande força, e como o poderíamos vencer, para que o amarremos e o atormentemos; e cada um de nós te dará mil e cem siclos de prata."}, {"numero": 6, "texto": "E Dalila disse a Sansão: Eu te rogo que me declares em que consiste tua grande força, e como poderás ser acorrentado para ser atormentado."}, {"numero": 7, "texto": "E respondeu-lhe Sansão: Se me atarem com sete vimes verdes que ainda não estejam secos, então me debilitarei, e serei como qualquer um dos homens."}, {"numero": 8, "texto": "E os príncipes dos filisteus lhe trouxeram sete vimes verdes que ainda não se haviam secado, e atou-lhe com eles."}, {"numero": 9, "texto": "E estavam espias em casa dela em uma câmara. Então ela lhe disse: Sansão, os filisteus sobre ti! E ele rompeu os vimes, como se rompe uma corda de estopa quando sente o fogo: e não se soube sua força."}, {"numero": 10, "texto": "Então Dalila disse a Sansão: Eis que tu me enganaste, e me disseste mentiras: revela-me pois agora, eu te rogo, como poderás ser acorrentado."}, {"numero": 11, "texto": "E ele lhe disse: Se me atarem fortemente com cordas novas, com as quais nenhuma coisa se tenha feito, eu me debilitarei, e serei como qualquer um dos homens."}, {"numero": 12, "texto": "E Dalila tomou cordas novas, e atou-lhe com elas, e disse-lhe: Sansão, os filisteus sobre ti! E os espias estavam em uma câmara. Mas ele as rompeu de seus braços como um fio."}, {"numero": 13, "texto": "E Dalila disse a Sansão: Até agora me enganas, e tratas comigo com mentiras. Revela-me pois agora como poderás ser acorrentado. Ele então lhe disse: Se teceres sete tranças de minha cabeça com a teia."}, {"numero": 14, "texto": "E ela fincou a estaca, e disse-lhe: Sansão, os filisteus sobre ti! Mas despertando ele de seu sonho, arrancou a estaca do tear com a teia."}, {"numero": 15, "texto": "E ela lhe disse: Como dizes, Eu te amo, pois que teu coração não está comigo? Já me enganaste três vezes, e não me hás ainda descoberto em que está tua grande força."}, {"numero": 16, "texto": "E aconteceu que, pressionando-lhe ela cada dia com suas palavras e importunando-lhe, sua alma foi reduzida à mortal angústia."}, {"numero": 17, "texto": "Revelou-lhe, pois, todo seu coração, e disse-lhe: Nunca a minha cabeça chegou navalha; porque sou nazireu de Deus desde o ventre de minha mãe. Se for rapado, minha força se apartará de mim, e serei debilitado, e como todos os homens."}, {"numero": 18, "texto": "E vendo Dalila que ele lhe havia revelado todo seu coração, mandou chamar aos príncipes dos filisteus, dizendo: Vinde esta vez, porque ele me revelou todo seu coração. E os príncipes dos filisteus vieram a ela, trazendo em sua mão o dinheiro."}, {"numero": 19, "texto": "E ela fez que ele dormisse sobre seus joelhos; e chamado um homem, rapou-lhe sete tranças de sua cabeça, e começou a afligi-lo, pois sua força se apartou dele."}, {"numero": 20, "texto": "E disse-lhe: Sansão, os filisteus sobre ti! E logo que despertou ele de seu sonho, se disse: Esta vez sairei como as outras, e me escaparei: não sabendo que o SENHOR já se havia dele apartado."}, {"numero": 21, "texto": "Mas os filisteus lançaram mão dele, e tiraram-lhe os olhos, e o levaram a Gaza; e o ataram com correntes, para que moesse no cárcere."}, {"numero": 22, "texto": "E o cabelo de sua cabeça começou a crescer, depois que foi rapado."}, {"numero": 23, "texto": "Então os príncipes dos filisteus se juntaram para oferecer sacrifício a Dagom seu deus, e para alegrar-se; e disseram: Nosso deus entregou em nossas mãos a Sansão nosso inimigo."}, {"numero": 24, "texto": "E vendo-o o povo, louvaram a seu deus, dizendo: Nosso deus entregou em nossas mãos a nosso inimigo, e ao destruidor de nossa terra, o qual havia matado a muitos de nós."}, {"numero": 25, "texto": "E aconteceu que, indo-se alegrando o coração deles, disseram: Chamai a Sansão, para que divirta diante de nós. E chamaram a Sansão do cárcere, e fazia de joguete diante deles; e puseram-no entre as colunas."}, {"numero": 26, "texto": "E Sansão disse ao jovem que o guiava pela mão: Aproxima-me, e faze-me segurar as colunas sobre que se sustenta a casa, para que me apoie sobre elas."}, {"numero": 27, "texto": "E a casa estava cheia de homens e mulheres: e todos os príncipes dos filisteus estavam ali; e no alto piso havia como três mil homens e mulheres, que estavam olhando o escárnio de Sansão."}, {"numero": 28, "texto": "Então clamou Sansão ao SENHOR, e disse: Senhor DEUS, lembra-te agora de mim, e esforça-me, te rogo, somente esta vez, ó Deus, para que de uma vez tome vingança dos filisteus, por meus dois olhos."}, {"numero": 29, "texto": "Agarrou logo Sansão as duas colunas do meio sobre as quais se sustentava a casa, e apoiou-se nelas, a uma com a direita, e a outra com a esquerda;"}, {"numero": 30, "texto": "E disse Sansão: Morra eu com os filisteus. E apoiando com força, caiu a casa sobre os príncipes, e sobre todo aquele povo que estava nela. E foram muitos mais os que deles matou morrendo, que os que havia matado em sua vida."}, {"numero": 31, "texto": "E desceram seus irmãos e toda a casa de seu pai, e tomaram-no, e levaram-no, e o sepultaram entre Zorá e Estaol, no sepulcro de seu pai Manoá. E ele julgou a Israel vinte anos."}]'::jsonb, 'Almeida Livre'),
  ('Jz', 16, 'en', '[{"numero": 1, "texto": "Then went Samson to Gaza, and saw there an harlot, and went in unto her."}, {"numero": 2, "texto": "And it was told the Gazites, saying, Samson is come hither. And they compassed him in, and laid wait for him all night in the gate of the city, and were quiet all the night, saying, In the morning, when it is day, we shall kill him."}, {"numero": 3, "texto": "And Samson lay till midnight, and arose at midnight, and took the doors of the gate of the city, and the two posts, and went away with them, bar and all, and put them upon his shoulders, and carried them up to the top of an hill that is before Hebron."}, {"numero": 4, "texto": "And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."}, {"numero": 5, "texto": "And the lords of the Philistines came up unto her, and said unto her, Entice him, and see wherein his great strength lieth, and by what means we may prevail against him, that we may bind him to afflict him; and we will give thee every one of us eleven hundred pieces of silver."}, {"numero": 6, "texto": "And Delilah said to Samson, Tell me, I pray thee, wherein thy great strength lieth, and wherewith thou mightest be bound to afflict thee."}, {"numero": 7, "texto": "And Samson said unto her, If they bind me with seven green withs that were never dried, then shall I be weak, and be as another man."}, {"numero": 8, "texto": "Then the lords of the Philistines brought up to her seven green withs which had not been dried, and she bound him with them."}, {"numero": 9, "texto": "Now there were men lying in wait, abiding with her in the chamber. And she said unto him, The Philistines be upon thee, Samson. And he brake the withs, as a thread of tow is broken when it toucheth the fire. So his strength was not known."}, {"numero": 10, "texto": "And Delilah said unto Samson, Behold, thou hast mocked me, and told me lies: now tell me, I pray thee, wherewith thou mightest be bound."}, {"numero": 11, "texto": "And he said unto her, If they bind me fast with new ropes that never were occupied, then shall I be weak, and be as another man."}, {"numero": 12, "texto": "Delilah therefore took new ropes, and bound him therewith, and said unto him, The Philistines be upon thee, Samson. And there were liers in wait abiding in the chamber. And he brake them from off his arms like a thread."}, {"numero": 13, "texto": "And Delilah said unto Samson, Hitherto thou hast mocked me, and told me lies: tell me wherewith thou mightest be bound. And he said unto her, If thou weavest the seven locks of my head with the web."}, {"numero": 14, "texto": "And she fastened it with the pin, and said unto him, The Philistines be upon thee, Samson. And he awaked out of his sleep, and went away with the pin of the beam, and with the web."}, {"numero": 15, "texto": "And she said unto him, How canst thou say, I love thee, when thine heart is not with me? thou hast mocked me these three times, and hast not told me wherein thy great strength lieth."}, {"numero": 16, "texto": "And it came to pass, when she pressed him daily with her words, and urged him, so that his soul was vexed unto death;"}, {"numero": 17, "texto": "That he told her all his heart, and said unto her, There hath not come a razor upon mine head; for I have been a Nazarite unto God from my mother''s womb: if I be shaven, then my strength will go from me, and I shall become weak, and be like any other man."}, {"numero": 18, "texto": "And when Delilah saw that he had told her all his heart, she sent and called for the lords of the Philistines, saying, Come up this once, for he hath shewed me all his heart. Then the lords of the Philistines came up unto her, and brought money in their hand."}, {"numero": 19, "texto": "And she made him sleep upon her knees; and she called for a man, and she caused him to shave off the seven locks of his head; and she began to afflict him, and his strength went from him."}, {"numero": 20, "texto": "And she said, The Philistines be upon thee, Samson. And he awoke out of his sleep, and said, I will go out as at other times before, and shake myself. And he wist not that the Lord was departed from him."}, {"numero": 21, "texto": "But the Philistines took him, and put out his eyes, and brought him down to Gaza, and bound him with fetters of brass; and he did grind in the prison house."}, {"numero": 22, "texto": "Howbeit the hair of his head began to grow again after he was shaven."}, {"numero": 23, "texto": "Then the lords of the Philistines gathered them together for to offer a great sacrifice unto Dagon their god, and to rejoice: for they said, Our god hath delivered Samson our enemy into our hand."}, {"numero": 24, "texto": "And when the people saw him, they praised their god: for they said, Our god hath delivered into our hands our enemy, and the destroyer of our country, which slew many of us."}, {"numero": 25, "texto": "And it came to pass, when their hearts were merry, that they said, Call for Samson, that he may make us sport. And they called for Samson out of the prison house; and he made them sport: and they set him between the pillars."}, {"numero": 26, "texto": "And Samson said unto the lad that held him by the hand, Suffer me that I may feel the pillars whereupon the house standeth, that I may lean upon them."}, {"numero": 27, "texto": "Now the house was full of men and women; and all the lords of the Philistines were there; and there were upon the roof about three thousand men and women, that beheld while Samson made sport."}, {"numero": 28, "texto": "And Samson called unto the Lord, and said, O Lord God, remember me, I pray thee, and strengthen me, I pray thee, only this once, O God, that I may be at once avenged of the Philistines for my two eyes."}, {"numero": 29, "texto": "And Samson took hold of the two middle pillars upon which the house stood, and on which it was borne up, of the one with his right hand, and of the other with his left."}, {"numero": 30, "texto": "And Samson said, Let me die with the Philistines. And he bowed himself with all his might; and the house fell upon the lords, and upon all the people that were therein. So the dead which he slew at his death were more than they which he slew in his life."}, {"numero": 31, "texto": "Then his brethren and all the house of his father came down, and took him, and brought him up, and buried him between Zorah and Eshtaol in the buryingplace of Manoah his father. And he judged Israel twenty years."}]'::jsonb, 'King James Version'),
  ('Jz', 16, 'fr', '[{"numero": 1, "texto": "Samson partit pour Gaza; il y vit une femme prostituée, et il entra chez elle."}, {"numero": 2, "texto": "On dit aux gens de Gaza: Samson est arrivé ici. Et ils l''''environnèrent, et se tinrent en embuscade toute la nuit à la porte de la ville. Ils restèrent tranquilles toute la nuit, disant: Au point du jour, nous le tuerons."}, {"numero": 3, "texto": "Samson demeura couché jusqu''''à minuit. Vers minuit, il se leva; et il saisit les battants de la porte de la ville et les deux poteaux, les arracha avec la barre, les mit sur ses épaules, et les porta sur le sommet de la montagne qui est en face d''''Hébron."}, {"numero": 4, "texto": "Après cela, il aima une femme dans la vallée de Sorek. Elle se nommait Delila."}, {"numero": 5, "texto": "Les princes des Philistins montèrent vers elle, et lui dirent: Flatte-le, pour savoir d''''où lui vient sa grande force et comment nous pourrions nous rendre maîtres de lui; nous le lierons pour le dompter, et nous te donnerons chacun mille et cent sicles d''''argent."}, {"numero": 6, "texto": "Delila dit à Samson: Dis-moi, je te prie, d''''où vient ta grande force, et avec quoi il faudrait te lier pour te dompter."}, {"numero": 7, "texto": "Samson lui dit: Si on me liait avec sept cordes fraîches, qui ne fussent pas encore sèches, je deviendrais faible et je serais comme un autre homme."}, {"numero": 8, "texto": "Les princes des Philistins apportèrent à Delila sept cordes fraîches, qui n''''étaient pas encore sèches. Et elle le lia avec ces cordes."}, {"numero": 9, "texto": "Or des gens se tenaient en embuscade chez elle, dans une chambre. Elle lui dit: Les Philistins sont sur toi, Samson! Et il rompit les cordes, comme se rompt un cordon d''''étoupe quand il sent le feu. Et l''''on ne connut point d''''où venait sa force."}, {"numero": 10, "texto": "Delila dit à Samson: Voici, tu t''''es joué de moi, tu m''''as dit des mensonges. Maintenant, je te prie, indique-moi avec quoi il faut te lier."}, {"numero": 11, "texto": "Il lui dit: Si on me liait avec des cordes neuves, dont on ne se fût jamais servi, je deviendrais faible et je serais comme un autre homme."}, {"numero": 12, "texto": "Delila prit des cordes neuves, avec lesquelles elle le lia. Puis elle lui dit: Les Philistins sont sur toi, Samson! Or des gens se tenaient en embuscade dans une chambre. Et il rompit comme un fil les cordes qu''''il avait aux bras."}, {"numero": 13, "texto": "Delila dit à Samson: Jusqu''''à présent tu t''''es joué de moi, tu m''''as dit des mensonges. Déclare-moi avec quoi il faut te lier. Il lui dit: Tu n''''as qu''''à tisser les sept tresses de ma tête avec la chaîne du tissu."}, {"numero": 14, "texto": "Et elle les fixa par la cheville. Puis elle lui dit: Les Philistins sont sur toi, Samson! Et il se réveilla de son sommeil, et il arracha la cheville du tissu et le tissu."}, {"numero": 15, "texto": "Elle lui dit: Comment peux-tu dire: Je t''''aime! puisque ton coeur n''''est pas avec moi? Voilà trois fois que tu t''''es joué de moi, et tu ne m''''as pas déclaré d''''où vient ta grande force."}, {"numero": 16, "texto": "Comme elle était chaque jour à le tourmenter et à l''''importuner par ses instances, son âme s''''impatienta à la mort,"}, {"numero": 17, "texto": "il lui ouvrit tout son coeur, et lui dit: Le rasoir n''''a point passé sur ma tête, parce que je suis consacré à Dieu dès le ventre de ma mère. Si j''''étais rasé, ma force m''''abandonnerait, je deviendrais faible, et je serais comme tout autre homme."}, {"numero": 18, "texto": "Delila, voyant qu''''il lui avait ouvert tout son coeur, envoya appeler les princes des Philistins, et leur fit dire: Montez cette fois, car il m''''a ouvert tout son coeur. Et les princes des Philistins montèrent vers elle, et apportèrent l''''argent dans leurs mains."}, {"numero": 19, "texto": "Elle l''''endormit sur ses genoux. Et ayant appelé un homme, elle rasa les sept tresses de la tête de Samson, et commença ainsi à le dompter. Il perdit sa force."}, {"numero": 20, "texto": "Elle dit alors: Les Philistins sont sur toi, Samson! Et il se réveilla de son sommeil, et dit: Je m''''en tirerai comme les autres fois, et je me dégagerai. Il ne savait pas que l''''Eternel s''''était retiré de lui."}, {"numero": 21, "texto": "Les Philistins le saisirent, et lui crevèrent les yeux; ils le firent descendre à Gaza, et le lièrent avec des chaînes d''''airain. Il tournait la meule dans la prison."}, {"numero": 22, "texto": "Cependant les cheveux de sa tête recommençaient à croître, depuis qu''''il avait été rasé."}, {"numero": 23, "texto": "Or les princes des Philistins s''''assemblèrent pour offrir un grand sacrifice à Dagon, leur dieu, et pour se réjouir. Ils disaient: Notre dieu a livré entre nos mains Samson, notre ennemi."}, {"numero": 24, "texto": "Et quand le peuple le vit, ils célébrèrent leur dieu, en disant: Notre dieu a livré entre nos mains notre ennemi, celui qui ravageait notre pays, et qui multipliait nos morts."}, {"numero": 25, "texto": "Dans la joie de leur coeur, ils dirent: Qu''''on appelle Samson, et qu''''il nous divertisse! Ils firent sortir Samson de la prison, et il joua devant eux. Ils le placèrent entre les colonnes."}, {"numero": 26, "texto": "Et Samson dit au jeune homme qui le tenait par la main: Laisse-moi, afin que je puisse toucher les colonnes sur lesquelles repose la maison et m''''appuyer contre elles."}, {"numero": 27, "texto": "La maison était remplie d''''hommes et de femmes; tous les princes des Philistins étaient là, et il y avait sur le toit environ trois mille personnes, hommes et femmes, qui regardaient Samson jouer."}, {"numero": 28, "texto": "Alors Samson invoqua l''''Eternel, et dit: Seigneur Eternel! souviens-toi de moi, je te prie; ô Dieu! donne-moi de la force seulement cette fois, et que d''''un seul coup je tire vengeance des Philistins pour mes deux yeux!"}, {"numero": 29, "texto": "Et Samson embrassa les deux colonnes du milieu sur lesquelles reposait la maison, et il s''''appuya contre elles; l''''une était à sa droite, et l''''autre à sa gauche."}, {"numero": 30, "texto": "Samson dit: Que je meure avec les Philistins! Il se pencha fortement, et la maison tomba sur les princes et sur tout le peuple qui y était. Ceux qu''''il fit périr à sa mort furent plus nombreux que ceux qu''''il avait tués pendant sa vie."}, {"numero": 31, "texto": "Ses frères et toute la maison de son père descendirent, et l''''emportèrent. Lorsqu''''ils furent remontés, ils l''''enterrèrent entre Tsorea et Eschthaol dans le sépulcre de Manoach, son père. Il avait été juge en Israël pendant vingt ans."}]'::jsonb, 'Louis Segond 1910'),
  ('Jz', 16, 'es', '[{"numero": 1, "texto": "Y FUÉ Samsón á Gaza, y vió allí una mujer ramera, y entró á ella."}, {"numero": 2, "texto": "Y fué dicho á los de Gaza: Samsón es venido acá. Y cercáronlo, y pusiéronle espías toda aquella noche á la puerta de la ciudad: y estuvieron callados toda aquella noche, diciendo: Hasta la luz de la mañana; entonces lo mataremos."}, {"numero": 3, "texto": "Mas Samsón durmió hasta la media noche; y á la media noche se levantó, y tomando las puertas de la ciudad con sus dos pilares y su cerrojo, echóselas al hombro, y fuése, y subióse con ellas á la cumbre del monte que está delante de Hebrón."}, {"numero": 4, "texto": "Después de esto aconteció que se enamoró de una mujer en el valle de Sorec, la cual se llamaba Dalila."}, {"numero": 5, "texto": "Y vinieron á ella los príncipes de los Filisteos, y dijéronle: Engáñale y sabe en qué consiste su grande fuerza, y cómo lo podríamos vencer, para que lo atemos y lo atormentemos; y cada uno de nosotros te dará mil y cien siclos de plata."}, {"numero": 6, "texto": "Y Dalila dijo á Samsón: Yo te ruego que me declares en qué consiste tu grande fuerza, y cómo podrás ser atado para ser atormentado."}, {"numero": 7, "texto": "Y respondióle Samsón: Si me ataren con siete mimbres verdes que aun no estén enjutos, entonces me debilitaré, y seré como cualquiera de los hombres."}, {"numero": 8, "texto": "Y los príncipes de los Filisteos le trajeron siete mimbres verdes que aun no se habían enjugado, y atóle con ellos."}, {"numero": 9, "texto": "Y estaban espías en casa de ella en una cámara. Entonces ella le dijo: ¡Samsón, los Filisteos sobre ti! Y él rompió los mimbres, como se rompe una cuerda de estopa cuando siente el fuego: y no se supo su fuerza."}, {"numero": 10, "texto": "Entonces Dalila dijo á Samsón: He aquí tú me has engañado, y me has dicho mentiras: descúbreme pues ahora, yo te ruego, cómo podrás ser atado."}, {"numero": 11, "texto": "Y él le dijo: Si me ataren fuertemente con cuerdas nuevas, con las cuales ninguna cosa se haya hecho, yo me debilitaré, y seré como cualquiera de los hombres."}, {"numero": 12, "texto": "Y Dalila tomó cuerdas nuevas, y atóle con ellas, y díjole: ¡Samsón, los Filisteos sobre ti! Y los espías estaban en una cámara. Mas él las rompió de sus brazos como un hilo."}, {"numero": 13, "texto": "Y Dalila dijo á Samsón: Hasta ahora me engañas, y tratas conmigo con mentiras. Descúbreme pues ahora cómo podrás ser atado. El entonces le dijo: Si tejieres siete guedejas de mi cabeza con la tela."}, {"numero": 14, "texto": "Y ella hincó la estaca, y díjole: ¡Samsón, los Filisteos sobre ti! Mas despertando él de su sueño, arrancó la estaca del telar con la tela."}, {"numero": 15, "texto": "Y ella le dijo: ¿Cómo dices, Yo te amo, pues que tu corazón no está conmigo? Ya me has engañado tres veces, y no me has aún descubierto en qué está tu gran fuerza."}, {"numero": 16, "texto": "Y aconteció que, apretándole ella cada día con sus palabras é importunándole, su alma fué reducida á mortal angustia."}, {"numero": 17, "texto": "Descubrióle pues todo su corazón, y díjole: Nunca á mi cabeza llegó navaja; porque soy Nazareo de Dios desde el vientre de mi madre. Si fuere rapado, mi fuerza se apartará de mí, y seré debilitado, y como todos los hombres."}, {"numero": 18, "texto": "Y viendo Dalila que él le había descubierto todo su corazón, envió á llamar á los príncipes de los Filisteos, diciendo: Venid esta vez, porque él me ha descubierto todo su corazón. Y los príncipes de los Filisteos vinieron á ella, trayendo en su mano el dinero."}, {"numero": 19, "texto": "Y ella hizo que él se durmiese sobre sus rodillas; y llamado un hombre, rapóle siete guedejas de su cabeza, y comenzó á afligirlo, pues su fuerza se apartó de él."}, {"numero": 20, "texto": "Y díjole: ¡Samsón, los Filisteos sobre ti! Y luego que despertó él de su sueño, se dijo: Esta vez saldré como las otras, y me escaparé: no sabiendo que Jehová ya se había de él apartado."}, {"numero": 21, "texto": "Mas los Filisteos echaron mano de él, y sacáronle los ojos, y le llevaron á Gaza; y le ataron con cadenas, para que moliese en la cárcel."}, {"numero": 22, "texto": "Y el cabello de su cabeza comenzó á crecer, después que fué rapado."}, {"numero": 23, "texto": "Entonces los príncipes de los Filisteos se juntaron para ofrecer sacrificio á Dagón su dios, y para alegrarse; y dijeron: Nuestro dios entregó en nuestras manos á Samsón nuestro enemigo."}, {"numero": 24, "texto": "Y viéndolo el pueblo, loaron á su dios, diciendo: Nuestro dios entregó en nuestras manos á nuestro enemigo, y al destruidor de nuestra tierra, el cual había muerto á muchos de nosotros."}, {"numero": 25, "texto": "Y aconteció que, yéndose alegrando el corazón de ellos, dijeron: Llamad á Samsón, para que divierta delante de nosotros. Y llamaron á Samsón de la cárcel, y hacía de juguete delante de ellos; y pusiéronlo entre las columnas."}, {"numero": 26, "texto": "Y Samsón dijo al mozo que le guiaba de la mano: Acércame, y hazme tentar las columnas sobre que se sustenta la casa, para que me apoye sobre ellas."}, {"numero": 27, "texto": "Y la casa estaba llena de hombres y mujeres: y todos los príncipes de los Filisteos estaban allí; y en el alto piso había como tres mil hombres y mujeres, que estaban mirando el escarnio de Samsón."}, {"numero": 28, "texto": "Entonces clamó Samsón á Jehová, y dijo: Señor Jehová, acuérdate ahora de mí, y esfuérzame, te ruego, solamente esta vez, oh Dios, para que de una vez tome venganza de los Filisteos, por mis dos ojos."}, {"numero": 29, "texto": "Asió luego Samsón las dos columnas del medio sobre las cuales se sustentaba la casa, y estribó en ellas, la una con la mano derecha, y la otra con la izquierda;"}, {"numero": 30, "texto": "Y dijo Samsón: Muera yo con los Filisteos. Y estribando con esfuerzo, cayó la casa sobre los príncipes, y sobre todo el pueblo que estaba en ella. Y fueron muchos más los que de ellos mató muriendo, que los que había muerto en su vida."}, {"numero": 31, "texto": "Y descendieron sus hermanos y toda la casa de su padre, y tomáronle, y lleváronle, y le sepultaron entre Sora y Esthaol, en el sepulcro de su padre Manoa. Y él juzgó á Israel veinte años."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jó', 1, 'pt', '[{"numero": 1, "texto": "Havia um homem na terra de Uz, cujo nome era Jó; e este homem era íntegro e correto, temente a Deus, e que se afastava do mal."}, {"numero": 2, "texto": "E nasceram-lhe sete filhos e três filhas."}, {"numero": 3, "texto": "E seu patrimônio era sete mil ovelhas, três mil camelos, quinhentas juntas de bois, e quinhentas jumentas; ele também tinha muitíssimos servos, de maneira que este homem era o maior de todos do oriente."}, {"numero": 4, "texto": "E seus filhos iam nas casas uns dos outros para fazerem banquetes, cada um em seu dia; e mandavam convidar as suas três irmãs, para que comessem e bebessem com eles."}, {"numero": 5, "texto": "E acontecia que, acabando-se o revezamento dos dias de banquetes, Jó enviava e os santificava, e se levantava de madrugada para apresentar holocaustos[conforme] o número de todos eles. Pois Jó dizia: Talvez meus filhos tenham pecado, e tenham amaldiçoado a Deus em seus corações. Assim Jó fazia todos aqueles dias."}, {"numero": 6, "texto": "E em certo dia, os filhos de Deus vieram para se apresentarem diante do SENHOR, e Satanás também veio entre eles."}, {"numero": 7, "texto": "Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, dizendo: De rodear a terra, e de passear por ela."}, {"numero": 8, "texto": "E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há na terra semelhante a ele, homem íntegro e correto, temente a Deus, e que se afasta de mal."}, {"numero": 9, "texto": "Então Satanás respondeu ao SENHOR, dizendo: Por acaso Jó teme a Deus em troca de nada?"}, {"numero": 10, "texto": "Por acaso tu não puseste uma cerca ao redor dele, de sua casa, e de tudo quanto ele tem? Tu abençoaste o trabalho de suas mãos, e seu patrimônio tem crescido sobre a terra."}, {"numero": 11, "texto": "Mas estende agora tua mão, e toca em tudo quanto ele tem; e [verás] se ele não te amaldiçoa em tua face."}, {"numero": 12, "texto": "E o SENHOR disse a Satanás: Eis que tudo quanto ele tem está em tua mão; somente não estendas tua mão contra ele. E Satanás saiu de diante do SENHOR."}, {"numero": 13, "texto": "E sucedeu um dia que seus filhos e filhas estavam comendo e bebendo vinho na casa de seu irmão primogênito,"}, {"numero": 14, "texto": "Que veio um mensageiro a Jó, que disse: Enquanto os bois estavam arando, e as jumentas se alimentando perto deles,"}, {"numero": 15, "texto": "Eis que os sabeus atacaram, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia."}, {"numero": 16, "texto": "Enquanto este ainda estava falando, veio outro que disse: Fogo de Deus caiu do céu, que incendiou as ovelhas entre os servos, e os consumiu; somente eu escapei para te trazer-te a notícia."}, {"numero": 17, "texto": "Enquanto este ainda estava falando, veio outro que disse: Os caldeus formaram três tropas, e atacaram os camelos, e os tomaram, e feriram os servos a fio de espada; somente eu escapei para te trazer a notícia."}, {"numero": 18, "texto": "Enquanto este ainda estava falando, veio outro que disse: Teus filhos e tuas filhas estavam comendo e bebendo vinho em casa de seu irmão primogênito,"}, {"numero": 19, "texto": "E eis que veio um grande vento do deserto, e atingiu os quatro cantos da casa, que caiu sobre os jovens, e morreram; somente eu escapei para te trazer a notícia."}, {"numero": 20, "texto": "Então Jó se levantou, rasgou sua capa, rapou sua cabeça, e caindo na terra, adorou,"}, {"numero": 21, "texto": "E disse: Nu saí do ventre de minha mãe, e nu para lá voltarei. O SENHOR deu, e o SENHOR tomou; bendito seja o nome do SENHOR."}, {"numero": 22, "texto": "Em tudo isto Jó não pecou, nem atribuiu a Deus falta alguma."}]'::jsonb, 'Almeida Livre'),
  ('Jó', 1, 'en', '[{"numero": 1, "texto": "There was a man in the land of Uz, whose name was Job; and that man was perfect and upright, and one that feared God, and eschewed evil."}, {"numero": 2, "texto": "And there were born unto him seven sons and three daughters."}, {"numero": 3, "texto": "His substance also was seven thousand sheep, and three thousand camels, and five hundred yoke of oxen, and five hundred she asses, and a very great household; so that this man was the greatest of all the men of the east."}, {"numero": 4, "texto": "And his sons went and feasted in their houses, every one his day; and sent and called for their three sisters to eat and to drink with them."}, {"numero": 5, "texto": "And it was so, when the days of their feasting were gone about, that Job sent and sanctified them, and rose up early in the morning, and offered burnt offerings according to the number of them all: for Job said, It may be that my sons have sinned, and cursed God in their hearts. Thus did Job continually."}, {"numero": 6, "texto": "Now there was a day when the sons of God came to present themselves before the Lord, and Satan came also among them."}, {"numero": 7, "texto": "And the Lord said unto Satan, Whence comest thou? Then Satan answered the Lord, and said, From going to and fro in the earth, and from walking up and down in it."}, {"numero": 8, "texto": "And the Lord said unto Satan, Hast thou considered my servant Job, that there is none like him in the earth, a perfect and an upright man, one that feareth God, and escheweth evil?"}, {"numero": 9, "texto": "Then Satan answered the Lord, and said, Doth Job fear God for nought?"}, {"numero": 10, "texto": "Hast not thou made an hedge about him, and about his house, and about all that he hath on every side? thou hast blessed the work of his hands, and his substance is increased in the land."}, {"numero": 11, "texto": "But put forth thine hand now, and touch all that he hath, and he will curse thee to thy face."}, {"numero": 12, "texto": "And the Lord said unto Satan, Behold, all that he hath is in thy power; only upon himself put not forth thine hand. So Satan went forth from the presence of the Lord."}, {"numero": 13, "texto": "And there was a day when his sons and his daughters were eating and drinking wine in their eldest brother''s house:"}, {"numero": 14, "texto": "And there came a messenger unto Job, and said, The oxen were plowing, and the asses feeding beside them:"}, {"numero": 15, "texto": "And the Sabeans fell upon them, and took them away; yea, they have slain the servants with the edge of the sword; and I only am escaped alone to tell thee."}, {"numero": 16, "texto": "While he was yet speaking, there came also another, and said, The fire of God is fallen from heaven, and hath burned up the sheep, and the servants, and consumed them; and I only am escaped alone to tell thee."}, {"numero": 17, "texto": "While he was yet speaking, there came also another, and said, The Chaldeans made out three bands, and fell upon the camels, and have carried them away, yea, and slain the servants with the edge of the sword; and I only am escaped alone to tell thee."}, {"numero": 18, "texto": "While he was yet speaking, there came also another, and said, Thy sons and thy daughters were eating and drinking wine in their eldest brother''s house:"}, {"numero": 19, "texto": "And, behold, there came a great wind from the wilderness, and smote the four corners of the house, and it fell upon the young men, and they are dead; and I only am escaped alone to tell thee."}, {"numero": 20, "texto": "Then Job arose, and rent his mantle, and shaved his head, and fell down upon the ground, and worshipped,"}, {"numero": 21, "texto": "And said, Naked came I out of my mother''s womb, and naked shall I return thither: the Lord gave, and the Lord hath taken away; blessed be the name of the Lord."}, {"numero": 22, "texto": "In all this Job sinned not, nor charged God foolishly."}]'::jsonb, 'King James Version'),
  ('Jó', 1, 'fr', '[{"numero": 1, "texto": "Il y avait dans le pays d''''Uts un homme qui s''''appelait Job. Et cet homme était intègre et droit; il craignait Dieu, et se détournait du mal."}, {"numero": 2, "texto": "Il lui naquit sept fils et trois filles."}, {"numero": 3, "texto": "Il possédait sept mille brebis, trois mille chameaux, cinq cents paires de boeufs, cinq cents ânesses, et un très grand nombre de serviteurs. Et cet homme était le plus considérable de tous les fils de l''''Orient."}, {"numero": 4, "texto": "Ses fils allaient les uns chez les autres et donnaient tour à tour un festin, et ils invitaient leurs trois soeurs à manger et à boire avec eux."}, {"numero": 5, "texto": "Et quand les jours de festin étaient passés, Job appelait et sanctifiait ses fils, puis il se levait de bon matin et offrait pour chacun d''''eux un holocauste; car Job disait: Peut-être mes fils ont-ils péché et ont-ils offensé Dieu dans leur coeur. C''''est ainsi que Job avait coutume d''''agir."}, {"numero": 6, "texto": "Or, les fils de Dieu vinrent un jour se présenter devant l''''Eternel, et Satan vint aussi au milieu d''''eux."}, {"numero": 7, "texto": "L''''Eternel dit à Satan: D''''où viens-tu? Et Satan répondit à l''''Eternel: De parcourir la terre et de m''''y promener."}, {"numero": 8, "texto": "L''''Eternel dit à Satan: As-tu remarqué mon serviteur Job? Il n''''y a personne comme lui sur la terre; c''''est un homme intègre et droit, craignant Dieu, et se détournant du mal."}, {"numero": 9, "texto": "Et Satan répondit à l''''Eternel: Est-ce d''''une manière désintéressée que Job craint Dieu?"}, {"numero": 10, "texto": "Ne l''''as-tu pas protégé, lui, sa maison, et tout ce qui est à lui? Tu as béni l''''oeuvre de ses mains, et ses troupeaux couvrent le pays."}, {"numero": 11, "texto": "Mais étends ta main, touche à tout ce qui lui appartient, et je suis sûr qu''''il te maudit en face."}, {"numero": 12, "texto": "L''''Eternel dit à Satan: Voici, tout ce qui lui appartient, je te le livre; seulement, ne porte pas la main sur lui. Et Satan se retira de devant la face de l''''Eternel."}, {"numero": 13, "texto": "Un jour que les fils et les filles de Job mangeaient et buvaient du vin dans la maison de leur frère aîné,"}, {"numero": 14, "texto": "il arriva auprès de Job un messager qui dit: Les boeufs labouraient et les ânesses paissaient à côté d''''eux;"}, {"numero": 15, "texto": "des Sabéens se sont jetés dessus, les ont enlevés, et ont passé les serviteurs au fil de l''''épée. Et je me suis échappé moi seul, pour t''''en apporter la nouvelle."}, {"numero": 16, "texto": "Il parlait encore, lorsqu''''un autre vint et dit: Le feu de Dieu est tombé du ciel, a embrasé les brebis et les serviteurs, et les a consumés. Et je me suis échappé moi seul, pour t''''en apporter la nouvelle."}, {"numero": 17, "texto": "Il parlait encore, lorsqu''''un autre vint et dit: Des Chaldéens, formés en trois bandes, se sont jetés sur les chameaux, les ont enlevés, et ont passé les serviteurs au fil de l''''épée. Et je me suis échappé moi seul, pour t''''en apporter la nouvelle."}, {"numero": 18, "texto": "Il parlait encore, lorsqu''''un autre vint et dit: Tes fils et tes filles mangeaient et buvaient du vin dans la maison de leur frère aîné;"}, {"numero": 19, "texto": "et voici, un grand vent est venu de l''''autre côté du désert, et a frappé contre les quatre coins de la maison; elle s''''est écroulée sur les jeunes gens, et ils sont morts. Et je me suis échappé moi seul, pour t''''en apporter la nouvelle."}, {"numero": 20, "texto": "Alors Job se leva, déchira son manteau, et se rasa la tête; puis, se jetant par terre, il se prosterna,"}, {"numero": 21, "texto": "et dit: Je suis sorti nu du sein de ma mère, et nu je retournerai dans le sein de la terre. L''''Eternel a donné, et l''''Eternel a ôté; que le nom de l''''Eternel soit béni!"}, {"numero": 22, "texto": "En tout cela, Job ne pécha point et n''''attribua rien d''''injuste à Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Jó', 1, 'es', '[{"numero": 1, "texto": "HUBO un varón en tierra de Hus, llamado Job; y era este hombre perfecto y recto, y temeroso de Dios, y apartado del mal."}, {"numero": 2, "texto": "Y naciéronle siete hijos y tres hijas."}, {"numero": 3, "texto": "Y su hacienda era siete mil ovejas, y tres mil camellos, y quinientas yuntas de bueyes, y quinientas asnas, y muchísimos criados: y era aquel varón grande más que todos los Orientales."}, {"numero": 4, "texto": "E iban sus hijos y hacían banquetes en sus casas, cada uno en su día; y enviaban á llamar sus tres hermanas, para que comiesen y bebiesen con ellos."}, {"numero": 5, "texto": "Y acontecía que, habiendo pasado en turno los días del convite, Job enviaba y santificábalos, y levantábase de mañana y ofrecía holocaustos conforme al número de todos ellos. Porque decía Job: Quizá habrán pecado mis hijos, y habrán blasfemado á Dios en sus corazones. De esta manera hacía todos los días."}, {"numero": 6, "texto": "Y un día vinieron los hijos de Dios á presentarse delante de Jehová, entre los cuales vino también Satán."}, {"numero": 7, "texto": "Y dijo Jehová á Satán: ¿De dónde vienes? Y respondiendo Satán á Jehová, dijo: De rodear la tierra, y de andar por ella."}, {"numero": 8, "texto": "Y Jehová dijo á Satán: ¿No has considerado á mi siervo Job, que no hay otro como él en la tierra, varón perfecto y recto, temeroso de Dios, y apartado de mal?"}, {"numero": 9, "texto": "Y respondiendo Satán á Jehová, dijo: ¿Teme Job á Dios de balde?"}, {"numero": 10, "texto": "¿No le has tú cercado á él, y á su casa, y á todo lo que tiene en derredor? Al trabajo de sus manos has dado bendición; por tanto su hacienda ha crecido sobre la tierra."}, {"numero": 11, "texto": "Mas extiende ahora tu mano, y toca á todo lo que tiene, y verás si no te blasfema en tu rostro."}, {"numero": 12, "texto": "Y dijo Jehová á Satán: He aquí, todo lo que tiene está en tu mano: solamente no pongas tu mano sobre él. Y salióse Satán de delante de Jehová."}, {"numero": 13, "texto": "Y un día aconteció que sus hijos é hijas comían y bebían vino en casa de su hermano el primogénito,"}, {"numero": 14, "texto": "Y vino un mensajero á Job, que le dijo: Estando arando los bueyes, y las asnas paciendo cerca de ellos,"}, {"numero": 15, "texto": "Acometieron los Sabeos, y tomáronlos, é hirieron á los mozos á filo de espada: solamente escapé yo para traerte las nuevas."}, {"numero": 16, "texto": "Aun estaba éste hablando, y vino otro que dijo: Fuego de Dios cayó del cielo, que quemó las ovejas y los mozos, y los consumió: solamente escapé yo solo para traerte las nuevas."}, {"numero": 17, "texto": "Todavía estaba éste hablando, y vino otro que dijo: Los Caldeos hicieron tres escuadrones, y dieron sobre los camellos, y tomáronlos, é hirieron á los mozos á filo de espada; y solamente escapé yo solo para traerte las nuevas."}, {"numero": 18, "texto": "Entre tanto que éste hablaba, vino otro que dijo: Tus hijos y tus hijas estaban comiendo y bebiendo vino en casa de su hermano el primogénito;"}, {"numero": 19, "texto": "Y he aquí un gran viento que vino del lado del desierto, é hirió las cuatro esquinas de la casa, y cayó sobre los mozos, y murieron; y solamente escapé yo solo para traerte las nuevas."}, {"numero": 20, "texto": "Entonces Job se levantó, y rasgó su manto, y trasquiló su cabeza, y cayendo en tierra adoró;"}, {"numero": 21, "texto": "Y dijo: Desnudo salí del vientre de mi madre, y desnudo tornaré allá. Jehová dió, y Jehová quitó: sea el nombre de Jehová bendito."}, {"numero": 22, "texto": "En todo esto no pecó Job, ni atribuyó á Dios despropósito alguno."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jó', 2, 'pt', '[{"numero": 1, "texto": "E veio outro dia em que os filhos de Deus vieram para se apresentarem diante do SENHOR, e e Satanás também veio entre eles para se apresentar diante do SENHOR."}, {"numero": 2, "texto": "Então o SENHOR disse a Satanás: De onde vens? E Satanás respondeu ao SENHOR, e dizendo: De rodear a terra, e de passear por ela."}, {"numero": 3, "texto": "E o SENHOR disse a Satanás: Tendes visto meu servo Jó? Pois ninguém há semelhante a ele na terra, homem íntegro e correto, temente a Deus e que se afasta do mal; e que ainda mantém sua integridade, mesmo depois de teres me incitado contra ele, para o arruinar sem causa."}, {"numero": 4, "texto": "Então Satanás respondeu ao SENHOR, dizendo: Pele por pele, e tudo quanto o homem tem, dará por sua vida."}, {"numero": 5, "texto": "Mas estende agora tua mão, e toca em seus ossos e sua carne, e [verás] se ele não te amaldiçoa em tua face."}, {"numero": 6, "texto": "E o SENHOR disse a Satanás: Eis que ele está em tua mão; mas preserva sua vida."}, {"numero": 7, "texto": "Então Satanás saiu de diante do SENHOR, e feriu a Jó de chagas malignas desde a planta de seus pés até a topo de sua cabeça."}, {"numero": 8, "texto": "E [Jó] tomou um caco para se raspar com ele, e ficou sentado no meio da cinza."}, {"numero": 9, "texto": "Então sua mulher lhe disse: Ainda manténs a tua integridade? Amaldiçoa a Deus, e morre."}, {"numero": 10, "texto": "Porém ele lhe disse: Tu falas como uma tola. Receberíamos o bem de Deus, e o mal não receberíamos? Em tudo isto Jó não pecou com seus lábios."}, {"numero": 11, "texto": "Quando três amigos de Jó, Elifaz temanita, Bildade suíta, e Zofar naamita, ouviram todo este mal que lhe tinha vindo sobre ele, vieram cada um de seu lugar; porque haviam combinado de juntamente virem para se condoerem dele, e o consolarem."}, {"numero": 12, "texto": "Eles, quando levantaram seus olhos de longe, não o reconheceram; e choraram em alta voz; e cada um deles rasgou sua capa, e espalharam pó ao ar sobre suas cabeças."}, {"numero": 13, "texto": "Assim se sentaram com ele na terra durante sete dias e sete noites, e nenhum lhe falava palavra alguma, pois viam que a dor era muito grande."}]'::jsonb, 'Almeida Livre'),
  ('Jó', 2, 'en', '[{"numero": 1, "texto": "Again there was a day when the sons of God came to present themselves before the Lord, and Satan came also among them to present himself before the Lord."}, {"numero": 2, "texto": "And the Lord said unto Satan, From whence comest thou? And Satan answered the Lord, and said, From going to and fro in the earth, and from walking up and down in it."}, {"numero": 3, "texto": "And the Lord said unto Satan, Hast thou considered my servant Job, that there is none like him in the earth, a perfect and an upright man, one that feareth God, and escheweth evil? and still he holdeth fast his integrity, although thou movedst me against him, to destroy him without cause."}, {"numero": 4, "texto": "And Satan answered the Lord, and said, Skin for skin, yea, all that a man hath will he give for his life."}, {"numero": 5, "texto": "But put forth thine hand now, and touch his bone and his flesh, and he will curse thee to thy face."}, {"numero": 6, "texto": "And the Lord said unto Satan, Behold, he is in thine hand; but save his life."}, {"numero": 7, "texto": "So went Satan forth from the presence of the Lord, and smote Job with sore boils from the sole of his foot unto his crown."}, {"numero": 8, "texto": "And he took him a potsherd to scrape himself withal; and he sat down among the ashes."}, {"numero": 9, "texto": "Then said his wife unto him, Dost thou still retain thine integrity? curse God, and die."}, {"numero": 10, "texto": "But he said unto her, Thou speakest as one of the foolish women speaketh. What? shall we receive good at the hand of God, and shall we not receive evil? In all this did not Job sin with his lips."}, {"numero": 11, "texto": "Now when Job''s three friends heard of all this evil that was come upon him, they came every one from his own place; Eliphaz the Temanite, and Bildad the Shuhite, and Zophar the Naamathite: for they had made an appointment together to come to mourn with him and to comfort him."}, {"numero": 12, "texto": "And when they lifted up their eyes afar off, and knew him not, they lifted up their voice, and wept; and they rent every one his mantle, and sprinkled dust upon their heads toward heaven."}, {"numero": 13, "texto": "So they sat down with him upon the ground seven days and seven nights, and none spake a word unto him: for they saw that his grief was very great."}]'::jsonb, 'King James Version'),
  ('Jó', 2, 'fr', '[{"numero": 1, "texto": "Or, les fils de Dieu vinrent un jour se présenter devant l''''Eternel, et Satan vint aussi au milieu d''''eux se présenter devant l''''Eternel."}, {"numero": 2, "texto": "L''''Eternel dit à Satan: D''''où viens-tu? Et Satan répondit à l''''Eternel: De parcourir la terre et de m''''y promener."}, {"numero": 3, "texto": "L''''Eternel dit à Satan: As-tu remarqué mon serviteur Job? Il n''''y a personne comme lui sur la terre; c''''est un homme intègre et droit, craignant Dieu, et se détournant du mal. Il demeure ferme dans son intégrité, et tu m''''excites à le perdre sans motif."}, {"numero": 4, "texto": "Et Satan répondit à l''''Eternel: Peau pour peau! tout ce que possède un homme, il le donne pour sa vie."}, {"numero": 5, "texto": "Mais étends ta main, touche à ses os et à sa chair, et je suis sûr qu''''il te maudit en face."}, {"numero": 6, "texto": "L''''Eternel dit à Satan: Voici, je te le livre: seulement, épargne sa vie."}, {"numero": 7, "texto": "Et Satan se retira de devant la face de l''''Eternel. Puis il frappa Job d''''un ulcère malin, depuis la plante du pied jusqu''''au sommet de la tête."}, {"numero": 8, "texto": "Et Job prit un tesson pour se gratter et s''''assit sur la cendre."}, {"numero": 9, "texto": "Sa femme lui dit: Tu demeures ferme dans ton intégrité! Maudis Dieu, et meurs!"}, {"numero": 10, "texto": "Mais Job lui répondit: Tu parles comme une femme insensée. Quoi! nous recevons de Dieu le bien, et nous ne recevrions pas aussi le mal! En tout cela Job ne pécha point par ses lèvres."}, {"numero": 11, "texto": "Trois amis de Job, Eliphaz de Théman, Bildad de Schuach, et Tsophar de Naama, apprirent tous les malheurs qui lui étaient arrivés. Ils se concertèrent et partirent de chez eux pour aller le plaindre et le consoler!"}, {"numero": 12, "texto": "Ayant de loin porté les regards sur lui, ils ne le reconnurent pas, et ils élevèrent la voix et pleurèrent. Ils déchirèrent leurs manteaux, et ils jetèrent de la poussière en l''''air au-dessus de leur tête."}, {"numero": 13, "texto": "Et ils se tinrent assis à terre auprès de lui sept jours et sept nuits, sans lui dire une parole, car ils voyaient combien sa douleur était grande."}]'::jsonb, 'Louis Segond 1910'),
  ('Jó', 2, 'es', '[{"numero": 1, "texto": "Y OTRO día aconteció que vinieron los hijos de Dios para presentarse delante de Jehová, y Satán vino también entre ellos pareciendo delante de Jehová."}, {"numero": 2, "texto": "Y dijo Jehová á Satán: ¿De dónde vienes? Respondió Satán á Jehová, y dijo: De rodear la tierra, y de andar por ella."}, {"numero": 3, "texto": "Y Jehová dijo á Satán: ¿No has considerado á mi siervo Job, que no hay otro como él en la tierra, varón perfecto y recto, temeroso de Dios y apartado de mal, y que aun retiene su perfección, habiéndome tú incitado contra él, para que lo arruinara sin causa?"}, {"numero": 4, "texto": "Y respondiendo Satán dijo á Jehová: Piel por piel, todo lo que el hombre tiene dará por su vida."}, {"numero": 5, "texto": "Mas extiende ahora tu mano, y toca á su hueso y á su carne, y verás si no te blasfema en tu rostro."}, {"numero": 6, "texto": "Y Jehová dijo á Satán: He aquí, él está en tu mano; mas guarda su vida."}, {"numero": 7, "texto": "Y salió Satán de delante de Jehová, é hirió á Job de una maligna sarna desde la planta de su pie hasta la mollera de su cabeza."}, {"numero": 8, "texto": "Y tomaba una teja para rascarse con ella, y estaba sentado en medio de ceniza."}, {"numero": 9, "texto": "Díjole entonces su mujer: ¿Aun retienes tú tu simplicidad? Bendice á Dios, y muérete."}, {"numero": 10, "texto": "Y él le dijo: Como suele hablar cualquiera de las mujeres fatuas, has hablado. También recibimos el bien de Dios, ¿y el mal no recibiremos? En todo esto no pecó Job con sus labios."}, {"numero": 11, "texto": "Y tres amigos de Job, Eliphaz Temanita, y Bildad Suhita, y Sophar Naamathita, luego que oyeron todo este mal que le había sobrevenido, vinieron cada uno de su lugar; porque habían concertado de venir juntos á condolecerse de él, y á consolarle."}, {"numero": 12, "texto": "Los cuales alzando los ojos desde lejos, no lo conocieron, y lloraron á voz en grito; y cada uno de ellos rasgó su manto, y esparcieron polvo sobre sus cabezas hacia el cielo."}, {"numero": 13, "texto": "Así se sentaron con él en tierra por siete días y siete noches, y ninguno le hablaba palabra, porque veían que el dolor era muy grande."}]'::jsonb, 'Reina-Valera 1909'),
  ('Jó', 42, 'pt', '[{"numero": 1, "texto": "E Jó respondeu ao SENHOR, dizendo:"}, {"numero": 2, "texto": "Eu sei que tudo podes, e nenhum de teus pensamentos pode ser impedido."}, {"numero": 3, "texto": "[Tu dizes] : Quem é esse que obscurece o conselho sem conhecimento? Por isso eu falei do que não entendia; coisas que eram maravilhosas demais para mim, e eu não as conhecia."}, {"numero": 4, "texto": "Escuta-me, por favor, e eu falarei; eu te perguntarei, e tu me ensina."}, {"numero": 5, "texto": "Com os ouvidos eu ouvira falar de ti; mas agora meus olhos te veem."}, {"numero": 6, "texto": "Por isso [me] abomino, e me arrependo no pó e na cinza."}, {"numero": 7, "texto": "E sucedeu que, depois que o SENHOR acabou de falar essas palavras a Jó, o SENHOR disse a Elifaz, o temanita: Minha ira se acendeu contra ti e contra os teus dois amigos; porque não falastes de mim o que era correto, como o meu servo Jó."}, {"numero": 8, "texto": "Por isso tomai sete bezerros e sete carneiros, ide ao meu servo Jó, e oferecei holocaustos em vosso favor, então meu servo Jó orará por vós; pois certamente atenderei a ele para eu não vos tratar conforme a vossa insensatez; pois não falastes de mim o que era correto, como o meu servo Jó."}, {"numero": 9, "texto": "Então foram Elifaz, o temanita, Bildade, o suíta, e Zofar, o naamita, e fizeram como o SENHOR havia lhes dito; e o SENHOR atendeu a Jó."}, {"numero": 10, "texto": "E o SENHOR livrou Jó de seu infortúnio, enquanto ele orava pelos seus amigos; e o SENHOR acrescentou a Jó o dobro de tudo quanto ele[ antes] possuía."}, {"numero": 11, "texto": "Então vieram e ele todos os seus irmãos, e todas as suas irmãs, e todos os que o conheciam antes; e comeram com ele pão em sua casa, e condoeram-se dele, e o consolaram acerca de toda a calamidade que o SENHOR tinha trazido sobre ele; e cada um deles lhe deu uma peça de dinheiro, e uma argola de ouro."}, {"numero": 12, "texto": "E [assim] o SENHOR abençoou o último estado de Jó mais que o seu primeiro; porque teve catorze mil ovelhas, seis mil camelos, mil juntas de bois, e mil asnas."}, {"numero": 13, "texto": "Também teve sete filhos e três filhas."}, {"numero": 14, "texto": "E chamou o nome da uma Jemima, e o nome da segunda Quézia, e o nome da terceira Quéren-Hapuque."}, {"numero": 15, "texto": "E em toda a terra não se acharam mulheres tão belas como as filhas de Jó; e seu pai lhes deu herança entre seus irmãos."}, {"numero": 16, "texto": "E depois disto Jó viveu cento e quarenta anos; e viu seus filhos, e os filhos de seus filhos, até quatro gerações."}, {"numero": 17, "texto": "Então Jó morreu, velho, e farto de dias."}]'::jsonb, 'Almeida Livre'),
  ('Jó', 42, 'en', '[{"numero": 1, "texto": "Then Job answered the Lord, and said,"}, {"numero": 2, "texto": "I know that thou canst do every thing, and that no thought can be withholden from thee."}, {"numero": 3, "texto": "Who is he that hideth counsel without knowledge? therefore have I uttered that I understood not; things too wonderful for me, which I knew not."}, {"numero": 4, "texto": "Hear, I beseech thee, and I will speak: I will demand of thee, and declare thou unto me."}, {"numero": 5, "texto": "I have heard of thee by the hearing of the ear: but now mine eye seeth thee."}, {"numero": 6, "texto": "Wherefore I abhor myself, and repent in dust and ashes."}, {"numero": 7, "texto": "And it was so, that after the Lord had spoken these words unto Job, the Lord said to Eliphaz the Temanite, My wrath is kindled against thee, and against thy two friends: for ye have not spoken of me the thing that is right, as my servant Job hath."}, {"numero": 8, "texto": "Therefore take unto you now seven bullocks and seven rams, and go to my servant Job, and offer up for yourselves a burnt offering; and my servant Job shall pray for you: for him will I accept: lest I deal with you after your folly, in that ye have not spoken of me the thing which is right, like my servant Job."}, {"numero": 9, "texto": "So Eliphaz the Temanite and Bildad the Shuhite and Zophar the Naamathite went, and did according as the Lord commanded them: the Lord also accepted Job."}, {"numero": 10, "texto": "And the Lord turned the captivity of Job, when he prayed for his friends: also the Lord gave Job twice as much as he had before."}, {"numero": 11, "texto": "Then came there unto him all his brethren, and all his sisters, and all they that had been of his acquaintance before, and did eat bread with him in his house: and they bemoaned him, and comforted him over all the evil that the Lord had brought upon him: every man also gave him a piece of money, and every one an earring of gold."}, {"numero": 12, "texto": "So the Lord blessed the latter end of Job more than his beginning: for he had fourteen thousand sheep, and six thousand camels, and a thousand yoke of oxen, and a thousand she asses."}, {"numero": 13, "texto": "He had also seven sons and three daughters."}, {"numero": 14, "texto": "And he called the name of the first, Jemima; and the name of the second, Kezia; and the name of the third, Kerenhappuch."}, {"numero": 15, "texto": "And in all the land were no women found so fair as the daughters of Job: and their father gave them inheritance among their brethren."}, {"numero": 16, "texto": "After this lived Job an hundred and forty years, and saw his sons, and his sons'' sons, even four generations."}, {"numero": 17, "texto": "So Job died, being old and full of days."}]'::jsonb, 'King James Version'),
  ('Jó', 42, 'fr', '[{"numero": 1, "texto": "Job répondit à l''''Eternel et dit:"}, {"numero": 2, "texto": "Je reconnais que tu peux tout, Et que rien ne s''''oppose à tes pensées."}, {"numero": 3, "texto": "Quel est celui qui a la folie d''''obscurcir mes desseins? -Oui, j''''ai parlé, sans les comprendre, De merveilles qui me dépassent et que je ne conçois pas."}, {"numero": 4, "texto": "Ecoute-moi, et je parlerai; Je t''''interrogerai, et tu m''''instruiras."}, {"numero": 5, "texto": "Mon oreille avait entendu parler de toi; Mais maintenant mon oeil t''''a vu."}, {"numero": 6, "texto": "C''''est pourquoi je me condamne et je me repens Sur la poussière et sur la cendre."}, {"numero": 7, "texto": "Après que l''''Eternel eut adressé ces paroles à Job, il dit à Eliphaz de Théman: Ma colère est enflammée contre toi et contre tes deux amis, parce que vous n''''avez pas parlé de moi avec droiture comme l''''a fait mon serviteur Job."}, {"numero": 8, "texto": "Prenez maintenant sept taureaux et sept béliers, allez auprès de mon serviteur Job, et offrez pour vous un holocauste. Job, mon serviteur, priera pour vous, et c''''est par égard pour lui seul que je ne vous traiterai pas selon votre folie; car vous n''''avez pas parlé de moi avec droiture, comme l''''a fait mon serviteur Job."}, {"numero": 9, "texto": "Eliphaz de Théman, Bildad de Schuach, et Tsophar de Naama allèrent et firent comme l''''Eternel leur avait dit: et l''''Eternel eut égard à la prière de Job."}, {"numero": 10, "texto": "L''''Eternel rétablit Job dans son premier état, quand Job eut prié pour ses amis; et l''''Eternel lui accorda le double de tout ce qu''''il avait possédé."}, {"numero": 11, "texto": "Les frères, les soeurs, et les anciens amis de Job vinrent tous le visiter, et ils mangèrent avec lui dans sa maison. Ils le plaignirent et le consolèrent de tous les malheurs que l''''Eternel avait fait venir sur lui, et chacun lui donna un kesita et un anneau d''''or."}, {"numero": 12, "texto": "Pendant ses dernières années, Job reçut de l''''Eternel plus de bénédictions qu''''il n''''en avait reçu dans les premières. Il posséda quatorze mille brebis, six mille chameaux, mille paires de boeufs, et mille ânesses."}, {"numero": 13, "texto": "Il eut sept fils et trois filles:"}, {"numero": 14, "texto": "il donna à la première le nom de Jemima, à la seconde celui de Ketsia, et à la troisième celui de Kéren-Happuc."}, {"numero": 15, "texto": "Il n''''y avait pas dans tout le pays d''''aussi belles femmes que les filles de Job. Leur père leur accorda une part d''''héritage parmi leurs frères."}, {"numero": 16, "texto": "Job vécut après cela cent quarante ans, et il vit ses fils et les fils de ses fils jusqu''''à la quatrième génération."}, {"numero": 17, "texto": "Et Job mourut âgé et rassasié de jours."}]'::jsonb, 'Louis Segond 1910'),
  ('Jó', 42, 'es', '[{"numero": 1, "texto": "Y RESPONDIÓ Job á Jehová, y dijo:"}, {"numero": 2, "texto": "Yo conozco que todo lo puedes, y que no hay pensamiento que se esconda de ti."}, {"numero": 3, "texto": "¿Quién es el que oscurece el consejo sin ciencia? por tanto yo denunciaba lo que no entendía; cosas que me eran ocultas, y que no las sabía."}, {"numero": 4, "texto": "Oye, te ruego, y hablaré: te preguntaré, y tú me enseñarás."}, {"numero": 5, "texto": "De oídas te había oído; mas ahora mis ojos te ven."}, {"numero": 6, "texto": "Por tanto me aborrezco, y me arrepiento en el polvo y en la ceniza."}, {"numero": 7, "texto": "Y aconteció que después que habló Jehová estas palabras á Job, Jehová dijo á Eliphaz Temanita: Mi ira se encendió contra ti y tus dos compañeros: porque no habéis hablado por mí lo recto, como mi siervo Job."}, {"numero": 8, "texto": "Ahora pues, tomaos siete becerros y siete carneros, y andad á mi siervo Job, y ofreced holocausto por vosotros, y mi siervo Job orará por vosotros; porque de cierto á él atenderé para no trataros afrentosamente, por cuanto no habéis hablado por mí con rectitud, como mi siervo Job."}, {"numero": 9, "texto": "Fueron pues Eliphaz Temanita, y Bildad Suhita, y Sophar Naamatita, é hicieron como Jehová les dijo: y Jehová atendió á Job."}, {"numero": 10, "texto": "Y mudó Jehová la aflicción de Job, orando él por sus amigos: y aumentó al doble todas las cosas que habían sido de Job."}, {"numero": 11, "texto": "Y vinieron á él todos sus hermanos, y todas sus hermanas, y todos los que antes le habían conocido, y comieron con él pan en su casa, y condoliéronse de él, y consoláronle de todo aquel mal que sobre él había Jehová traído; y cada uno de ellos le dió una pieza de moneda, y un zarcillo de oro."}, {"numero": 12, "texto": "Y bendijo Jehová la postrimería de Job más que su principio; porque tuvo catorce mil ovejas, y seis mil camellos, y mil yuntas de bueyes, y mil asnas."}, {"numero": 13, "texto": "Y tuvo siete hijos y tres hijas."}, {"numero": 14, "texto": "Y llamó el nombre de la una, Jemimah, y el nombre de la segunda, Cesiah, y el nombre de la tercera, Keren-happuch."}, {"numero": 15, "texto": "Y no se hallaron mujeres tan hermosas como las hijas de Job en toda la tierra: y dióles su padre herencia entre sus hermanos."}, {"numero": 16, "texto": "Y después de esto vivió Job ciento y cuarenta años, y vió á sus hijos, y á los hijos de sus hijos, hasta la cuarta generación."}, {"numero": 17, "texto": "Murió pues Job viejo, y lleno de días."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 1, 'pt', '[{"numero": 1, "texto": "Como muitos empreenderam pôr em ordem o relato das coisas que entre nós se cumpriram,"}, {"numero": 2, "texto": "conforme os que [as] viram que desde o princípio, e foram servidores das palavra, nos transmitiram,"}, {"numero": 3, "texto": "pareceu-me bom que também eu, que tenho me informado com exatidão desde o princípio, escrevesse-as em ordem a ti, caríssimo Teófilo,"}, {"numero": 4, "texto": "para que conheças a certeza das coisas de que foste ensinado."}, {"numero": 5, "texto": "Houve nos dias de Herodes, rei da Judeia, um sacerdote chamado Zacarias, da ordem de Abias; sua mulher das filhas de Arão, e o seu nome era Isabel."}, {"numero": 6, "texto": "E ambos eram justos diante de Deus; andavam sem repreensão em todos os mandamentos e preceitos do Senhor."}, {"numero": 7, "texto": "Mas não tinham filho, porque Isabel era estéril, e ambos tinham idade avançada."}, {"numero": 8, "texto": "E aconteceu que, quando ele fazia o trabalho sacerdotal diante de Deus, na ordem da sua turma,"}, {"numero": 9, "texto": "conforme o costume do sacerdócio, foi sorteado a entrar no santuário do Senhor para oferecer o incenso."}, {"numero": 10, "texto": "E toda a multidão do povo estava fora orando, à hora do incenso."}, {"numero": 11, "texto": "Então um anjo do Senhor lhe apareceu em pé, à direita do altar do incenso."}, {"numero": 12, "texto": "Quando Zacarias [o] viu, perturbou-se, e o medo o tomou."}, {"numero": 13, "texto": "Mas o anjo lhe disse: Zacarias, não temas, pois a tua oração foi ouvida. E Isabel, tua mulher, dará à luz um filho, e lhe porás o nome de João."}, {"numero": 14, "texto": "E terás prazer e alegria, e muitos se alegrarão do seu nascimento;"}, {"numero": 15, "texto": "pois ele será grande diante do Senhor, e não beberá vinho nem bebida alcoólica, e será cheio do Espírito Santo, já desde o ventre da sua mãe."}, {"numero": 16, "texto": "E converterá muitos dos filhos de Israel ao Senhor seu Deus."}, {"numero": 17, "texto": "E irá adiante dele no espírito e virtude de Elias, para converter os corações dos pais aos filhos, e os rebeldes à prudência dos justos; a fim de preparar um povo pronto ao Senhor."}, {"numero": 18, "texto": "Então Zacarias disse ao anjo: Como terei certeza disso? Pois sou velho, e a minha mulher de idade avançada."}, {"numero": 19, "texto": "O anjo lhe respondeu: Eu sou Gabriel, que fico presente diante de Deus, e fui enviado para te falar e te dar estas boas notícias."}, {"numero": 20, "texto": "Eis que ficarás mudo, e não poderás falar até o dia em que essas coisas aconteçam, porque não creste nas minhas palavras, que se cumprirão no devido tempo."}, {"numero": 21, "texto": "E o povo estava esperando Zacarias, e se surpreenderam de que ele demorava no santuário."}, {"numero": 22, "texto": "Quando ele saiu, não conseguia lhes falar; e entenderam que havia tido alguma visão no santuário. Ele lhes fazia gestos, e continuou mudo."}, {"numero": 23, "texto": "E sucedeu que, terminados os dias do seu serviço, voltou à sua casa."}, {"numero": 24, "texto": "E depois daqueles dias Isabel, sua mulher, Isabel, engravidou-se, e por cinco meses se escondeu, dizendo:"}, {"numero": 25, "texto": "Pois isto o Senhor me fez nos dias em que ele [me] observou, para acabar a minha humilhação entre as pessoas."}, {"numero": 26, "texto": "E no sexto mês o anjo Gabriel foi enviado por Deus a uma cidade da Galileia, chamada Nazaré,"}, {"numero": 27, "texto": "a uma virgem prometida em casamento com um homem chamado José, da descendência de Davi; e o nome da virgem era Maria."}, {"numero": 28, "texto": "O anjo entrou onde ela estava, e disse: Alegra-te, agraciada; o Senhor [é] contigo, bendita [és] tu entre as mulheres."}, {"numero": 29, "texto": "Quando ela [o] viu, perturbou-se muito por suas palavras, e se perguntava que saudação seria esta."}, {"numero": 30, "texto": "Então o anjo lhe disse: Maria, não temas, porque encontraste graça diante de Deus."}, {"numero": 31, "texto": "E eis que em teu ventre conceberás, darás à luz um filho, e chamarás o seu nome de Jesus."}, {"numero": 32, "texto": "Ele será grande, e será chamado Filho do Altíssimo; e o Senhor Deus lhe dará o trono de Davi, seu ancestral."}, {"numero": 33, "texto": "E reinará eternamente na casa de Jacó; o seu reino não terá fim."}, {"numero": 34, "texto": "Maria disse ao anjo: Como será isso? Pois não conheço intimamente homem algum."}, {"numero": 35, "texto": "O anjo lhe respondeu: O Espírito Santo virá sobre ti, e o poder do Altíssimo te cobrirá com a sua sombra. Por isso o Santo que nascerá de ti será chamado Filho de Deus."}, {"numero": 36, "texto": "E eis que Isabel, tua prima, também está grávida de um filho na sua velhice; e este é o sexto mês para a que era chamada de estéril."}, {"numero": 37, "texto": "Pois para Deus nada será impossível."}, {"numero": 38, "texto": "Então Maria disse: Eis aqui a serva do Senhor; cumpra-se em mim conforme a tua palavra. E o anjo ausentou-se dela."}, {"numero": 39, "texto": "E naqueles dias, Maria levantou-se, e foi apressada à região montanhosa, a uma cidade de Judá."}, {"numero": 40, "texto": "Ela entrou na casa de Zacarias, e cumprimentou Isabel."}, {"numero": 41, "texto": "E aconteceu que, quando Isabel ouviu o cumprimento de Maria, a criança saltou no seu ventre, e Isabel foi cheia do Espírito Santo."}, {"numero": 42, "texto": "Então exclamou em alta voz: Bendita [és] tu entre as mulheres, e bendito [é] o fruto do teu ventre!"}, {"numero": 43, "texto": "Como me acontece isto, que a mãe de meu Senhor venha a mim?"}, {"numero": 44, "texto": "Pois eis que, quando a voz do teu cumprimento chegou aos meus ouvidos, a criança saltou de alegria no meu ventre."}, {"numero": 45, "texto": "E bendita é a que creu, pois as coisas que da parte do Senhor lhe foram ditas se cumprirão."}, {"numero": 46, "texto": "Então Maria disse: A minha alma engrandece ao Senhor,"}, {"numero": 47, "texto": "e o meu espírito se alegra em Deus meu Salvador."}, {"numero": 48, "texto": "Porque ele observou a humilde condição da sua serva; pois eis que desde agora todas as gerações me chamarão bendita."}, {"numero": 49, "texto": "Pois o Poderoso me fez grandes coisas; e santo [é] o seu nome."}, {"numero": 50, "texto": "E a sua misericórdia é de geração em geração sobre os que o temem."}, {"numero": 51, "texto": "Com o seu braço manifestou poder; dispersou os soberbos no pensamento dos seus corações."}, {"numero": 52, "texto": "Derrubou os poderosos dos tronos, e elevou os humildes."}, {"numero": 53, "texto": "Encheu de bens aos famintos, e despediu vazios os ricos."}, {"numero": 54, "texto": "Auxiliou ao seu servo Israel, lembrando-se da [sua] misericórdia,"}, {"numero": 55, "texto": "como falou aos nossos ancestrais, a Abraão, e à sua descendência, para sempre."}, {"numero": 56, "texto": "Maria esteve com ela por quase três meses; então voltou para sua casa."}, {"numero": 57, "texto": "E completou-se à Isabel o tempo de dar à luz, e teve um filho."}, {"numero": 58, "texto": "Os seus vizinhos e parentes ouviram que o Senhor havia feito a ela grande misericórdia, e alegraram-se com ela."}, {"numero": 59, "texto": "E aconteceu que ao oitavo dia vieram circuncidar o menino, e o chamavam Zacarias, do nome do seu pai."}, {"numero": 60, "texto": "E sua mãe respondeu: Não, porém será chamado João."}, {"numero": 61, "texto": "E disseram-lhe: Ninguém há entre os teus parentes que se chame deste nome."}, {"numero": 62, "texto": "E perguntaram por gestos ao seu pai como queria que lhe chamassem."}, {"numero": 63, "texto": "Ele pediu uma tábua, e escreveu: O seu nome é João. E todos se surpeenderam."}, {"numero": 64, "texto": "E logo a sua boca se abriu, e a sua língua se [soltou] ; e voltou a falar, louvando a Deus."}, {"numero": 65, "texto": "E veio temor sobre todos os seus vizinhos; e em toda a região montanhosa da Judeia todas essas coisas foram divulgadas."}, {"numero": 66, "texto": "E todos os que ouviam, guardavam em seus corações, dizendo: Quem será este menino? E a mão do Senhor estava com ele."}, {"numero": 67, "texto": "E Zacarias, seu pai, foi cheio do Espírito Santo, e profetizou, dizendo:"}, {"numero": 68, "texto": "Bendito [seja] o Senhor Deus de Israel, porque visitou e redimiu o seu povo."}, {"numero": 69, "texto": "E nos levantou uma poderosa salvação na casa de seu servo Davi,"}, {"numero": 70, "texto": "como falou pela boca dos seus santos profetas, desde o princípio do mundo;"}, {"numero": 71, "texto": "Que [nos] livraria dos nossos inimigos e da mão de todos os que nos odeiam,"}, {"numero": 72, "texto": "para manifestar misericórdia aos nossos ancestrais, e se lembrar do seu santo pacto,"}, {"numero": 73, "texto": "do juramento que fez a Abraão, nosso ancestral;"}, {"numero": 74, "texto": "de nos conceder que, libertos da mão dos nossos inimigos, o serviríamos sem temor,"}, {"numero": 75, "texto": "em santidade e justiça diante dele, todos os dias da nossa vida."}, {"numero": 76, "texto": "E tu, menino, serás chamado profeta do Altíssimo; porque irás adiante da face do Senhor, para preparar os seus caminhos,"}, {"numero": 77, "texto": "para dar a seu povo conhecimento da salvação, na remissão de seus pecados;"}, {"numero": 78, "texto": "por causa da profunda misericórdia do nosso Deus, pela qual o raiar da manhã nos visitou;"}, {"numero": 79, "texto": "para iluminar os que estão sentados nas trevas e sombra de morte; a fim de guiar os nossos pés pelo caminho da paz."}, {"numero": 80, "texto": "E o menino crescia e se fortalecia em espírito. E esteve nos desertos até o dia em que se mostrou a Israel."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 1, 'en', '[{"numero": 1, "texto": "Forasmuch as many have taken in hand to set forth in order a declaration of those things which are most surely believed among us,"}, {"numero": 2, "texto": "Even as they delivered them unto us, which from the beginning were eyewitnesses, and ministers of the word;"}, {"numero": 3, "texto": "It seemed good to me also, having had perfect understanding of all things from the very first, to write unto thee in order, most excellent Theophilus,"}, {"numero": 4, "texto": "That thou mightest know the certainty of those things, wherein thou hast been instructed."}, {"numero": 5, "texto": "There was in the days of Herod, the king of Judaea, a certain priest named Zacharias, of the course of Abia: and his wife was of the daughters of Aaron, and her name was Elisabeth."}, {"numero": 6, "texto": "And they were both righteous before God, walking in all the commandments and ordinances of the Lord blameless."}, {"numero": 7, "texto": "And they had no child, because that Elisabeth was barren, and they both were now well stricken in years."}, {"numero": 8, "texto": "And it came to pass, that while he executed the priest''s office before God in the order of his course,"}, {"numero": 9, "texto": "According to the custom of the priest''s office, his lot was to burn incense when he went into the temple of the Lord."}, {"numero": 10, "texto": "And the whole multitude of the people were praying without at the time of incense."}, {"numero": 11, "texto": "And there appeared unto him an angel of the Lord standing on the right side of the altar of incense."}, {"numero": 12, "texto": "And when Zacharias saw him, he was troubled, and fear fell upon him."}, {"numero": 13, "texto": "But the angel said unto him, Fear not, Zacharias: for thy prayer is heard; and thy wife Elisabeth shall bear thee a son, and thou shalt call his name John."}, {"numero": 14, "texto": "And thou shalt have joy and gladness; and many shall rejoice at his birth."}, {"numero": 15, "texto": "For he shall be great in the sight of the Lord, and shall drink neither wine nor strong drink; and he shall be filled with the Holy Ghost, even from his mother''s womb."}, {"numero": 16, "texto": "And many of the children of Israel shall he turn to the Lord their God."}, {"numero": 17, "texto": "And he shall go before him in the spirit and power of Elias, to turn the hearts of the fathers to the children, and the disobedient to the wisdom of the just; to make ready a people prepared for the Lord."}, {"numero": 18, "texto": "And Zacharias said unto the angel, Whereby shall I know this? for I am an old man, and my wife well stricken in years."}, {"numero": 19, "texto": "And the angel answering said unto him, I am Gabriel, that stand in the presence of God; and am sent to speak unto thee, and to shew thee these glad tidings."}, {"numero": 20, "texto": "And, behold, thou shalt be dumb, and not able to speak, until the day that these things shall be performed, because thou believest not my words, which shall be fulfilled in their season."}, {"numero": 21, "texto": "And the people waited for Zacharias, and marvelled that he tarried so long in the temple."}, {"numero": 22, "texto": "And when he came out, he could not speak unto them: and they perceived that he had seen a vision in the temple: for he beckoned unto them, and remained speechless."}, {"numero": 23, "texto": "And it came to pass, that, as soon as the days of his ministration were accomplished, he departed to his own house."}, {"numero": 24, "texto": "And after those days his wife Elisabeth conceived, and hid herself five months, saying,"}, {"numero": 25, "texto": "Thus hath the Lord dealt with me in the days wherein he looked on me, to take away my reproach among men."}, {"numero": 26, "texto": "And in the sixth month the angel Gabriel was sent from God unto a city of Galilee, named Nazareth,"}, {"numero": 27, "texto": "To a virgin espoused to a man whose name was Joseph, of the house of David; and the virgin''s name was Mary."}, {"numero": 28, "texto": "And the angel came in unto her, and said, Hail, thou that art highly favoured, the Lord is with thee: blessed art thou among women."}, {"numero": 29, "texto": "And when she saw him, she was troubled at his saying, and cast in her mind what manner of salutation this should be."}, {"numero": 30, "texto": "And the angel said unto her, Fear not, Mary: for thou hast found favour with God."}, {"numero": 31, "texto": "And, behold, thou shalt conceive in thy womb, and bring forth a son, and shalt call his name Jesus."}, {"numero": 32, "texto": "He shall be great, and shall be called the Son of the Highest: and the Lord God shall give unto him the throne of his father David:"}, {"numero": 33, "texto": "And he shall reign over the house of Jacob for ever; and of his kingdom there shall be no end."}, {"numero": 34, "texto": "Then said Mary unto the angel, How shall this be, seeing I know not a man?"}, {"numero": 35, "texto": "And the angel answered and said unto her, The Holy Ghost shall come upon thee, and the power of the Highest shall overshadow thee: therefore also that holy thing which shall be born of thee shall be called the Son of God."}, {"numero": 36, "texto": "And, behold, thy cousin Elisabeth, she hath also conceived a son in her old age: and this is the sixth month with her, who was called barren."}, {"numero": 37, "texto": "For with God nothing shall be impossible."}, {"numero": 38, "texto": "And Mary said, Behold the handmaid of the Lord; be it unto me according to thy word. And the angel departed from her."}, {"numero": 39, "texto": "And Mary arose in those days, and went into the hill country with haste, into a city of Juda;"}, {"numero": 40, "texto": "And entered into the house of Zacharias, and saluted Elisabeth."}, {"numero": 41, "texto": "And it came to pass, that, when Elisabeth heard the salutation of Mary, the babe leaped in her womb; and Elisabeth was filled with the Holy Ghost:"}, {"numero": 42, "texto": "And she spake out with a loud voice, and said, Blessed art thou among women, and blessed is the fruit of thy womb."}, {"numero": 43, "texto": "And whence is this to me, that the mother of my Lord should come to me?"}, {"numero": 44, "texto": "For, lo, as soon as the voice of thy salutation sounded in mine ears, the babe leaped in my womb for joy."}, {"numero": 45, "texto": "And blessed is she that believed: for there shall be a performance of those things which were told her from the Lord."}, {"numero": 46, "texto": "And Mary said, My soul doth magnify the Lord,"}, {"numero": 47, "texto": "And my spirit hath rejoiced in God my Saviour."}, {"numero": 48, "texto": "For he hath regarded the low estate of his handmaiden: for, behold, from henceforth all generations shall call me blessed."}, {"numero": 49, "texto": "For he that is mighty hath done to me great things; and holy is his name."}, {"numero": 50, "texto": "And his mercy is on them that fear him from generation to generation."}, {"numero": 51, "texto": "He hath shewed strength with his arm; he hath scattered the proud in the imagination of their hearts."}, {"numero": 52, "texto": "He hath put down the mighty from their seats, and exalted them of low degree."}, {"numero": 53, "texto": "He hath filled the hungry with good things; and the rich he hath sent empty away."}, {"numero": 54, "texto": "He hath helped his servant Israel, in remembrance of his mercy;"}, {"numero": 55, "texto": "As he spake to our fathers, to Abraham, and to his seed for ever."}, {"numero": 56, "texto": "And Mary abode with her about three months, and returned to her own house."}, {"numero": 57, "texto": "Now Elisabeth''s full time came that she should be delivered; and she brought forth a son."}, {"numero": 58, "texto": "And her neighbours and her cousins heard how the Lord had shewed great mercy upon her; and they rejoiced with her."}, {"numero": 59, "texto": "And it came to pass, that on the eighth day they came to circumcise the child; and they called him Zacharias, after the name of his father."}, {"numero": 60, "texto": "And his mother answered and said, Not so; but he shall be called John."}, {"numero": 61, "texto": "And they said unto her, There is none of thy kindred that is called by this name."}, {"numero": 62, "texto": "And they made signs to his father, how he would have him called."}, {"numero": 63, "texto": "And he asked for a writing table, and wrote, saying, His name is John. And they marvelled all."}, {"numero": 64, "texto": "And his mouth was opened immediately, and his tongue loosed, and he spake, and praised God."}, {"numero": 65, "texto": "And fear came on all that dwelt round about them: and all these sayings were noised abroad throughout all the hill country of Judaea."}, {"numero": 66, "texto": "And all they that heard them laid them up in their hearts, saying, What manner of child shall this be! And the hand of the Lord was with him."}, {"numero": 67, "texto": "And his father Zacharias was filled with the Holy Ghost, and prophesied, saying,"}, {"numero": 68, "texto": "Blessed be the Lord God of Israel; for he hath visited and redeemed his people,"}, {"numero": 69, "texto": "And hath raised up an horn of salvation for us in the house of his servant David;"}, {"numero": 70, "texto": "As he spake by the mouth of his holy prophets, which have been since the world began:"}, {"numero": 71, "texto": "That we should be saved from our enemies, and from the hand of all that hate us;"}, {"numero": 72, "texto": "To perform the mercy promised to our fathers, and to remember his holy covenant;"}, {"numero": 73, "texto": "The oath which he sware to our father Abraham,"}, {"numero": 74, "texto": "That he would grant unto us, that we being delivered out of the hand of our enemies might serve him without fear,"}, {"numero": 75, "texto": "In holiness and righteousness before him, all the days of our life."}, {"numero": 76, "texto": "And thou, child, shalt be called the prophet of the Highest: for thou shalt go before the face of the Lord to prepare his ways;"}, {"numero": 77, "texto": "To give knowledge of salvation unto his people by the remission of their sins,"}, {"numero": 78, "texto": "Through the tender mercy of our God; whereby the dayspring from on high hath visited us,"}, {"numero": 79, "texto": "To give light to them that sit in darkness and in the shadow of death, to guide our feet into the way of peace."}, {"numero": 80, "texto": "And the child grew, and waxed strong in spirit, and was in the deserts till the day of his shewing unto Israel."}]'::jsonb, 'King James Version'),
  ('Lc', 1, 'fr', '[{"numero": 1, "texto": "Plusieurs ayant entrepris de composer un récit des événements qui se sont accomplis parmi nous,"}, {"numero": 2, "texto": "suivant ce que nous ont transmis ceux qui ont été des témoins oculaires dès le commencement et sont devenus des ministres de la parole,"}, {"numero": 3, "texto": "il m''''a aussi semblé bon, après avoir fait des recherches exactes sur toutes ces choses depuis leur origine, de te les exposer par écrit d''''une manière suivie, excellent Théophile,"}, {"numero": 4, "texto": "afin que tu reconnaisses la certitude des enseignements que tu as reçus."}, {"numero": 5, "texto": "Du temps d''''Hérode, roi de Judée, il y avait un sacrificateur, nommé Zacharie, de la classe d''''Abia; sa femme était d''''entre les filles d''''Aaron, et s''''appelait Elisabeth."}, {"numero": 6, "texto": "Tous deux étaient justes devant Dieu, observant d''''une manière irréprochable tous les commandements et toutes les ordonnances du Seigneur."}, {"numero": 7, "texto": "Ils n''''avaient point d''''enfants, parce qu''''Elisabeth était stérile; et ils étaient l''''un et l''''autre avancés en âge."}, {"numero": 8, "texto": "Or, pendant qu''''il s''''acquittait de ses fonctions devant Dieu, selon le tour de sa classe,"}, {"numero": 9, "texto": "il fut appelé par le sort, d''''après la règle du sacerdoce, à entrer dans le temple du Seigneur pour offrir le parfum."}, {"numero": 10, "texto": "Toute la multitude du peuple était dehors en prière, à l''''heure du parfum."}, {"numero": 11, "texto": "Alors un ange du Seigneur apparut à Zacharie, et se tint debout à droite de l''''autel des parfums."}, {"numero": 12, "texto": "Zacharie fut troublé en le voyant, et la frayeur s''''empara de lui."}, {"numero": 13, "texto": "Mais l''''ange lui dit: Ne crains point, Zacharie; car ta prière a été exaucée. Ta femme Elisabeth t''''enfantera un fils, et tu lui donneras le nom de Jean."}, {"numero": 14, "texto": "Il sera pour toi un sujet de joie et d''''allégresse, et plusieurs se réjouiront de sa naissance."}, {"numero": 15, "texto": "Car il sera grand devant le Seigneur. Il ne boira ni vin, ni liqueur enivrante, et il sera rempli de l''''Esprit-Saint dès le sein de sa mère;"}, {"numero": 16, "texto": "il ramènera plusieurs des fils d''''Israël au Seigneur, leur Dieu;"}, {"numero": 17, "texto": "il marchera devant Dieu avec l''''esprit et la puissance d''''Elie, pour ramener les coeurs des pères vers les enfants, et les rebelles à la sagesse des justes, afin de préparer au Seigneur un peuple bien disposé."}, {"numero": 18, "texto": "Zacharie dit à l''''ange: A quoi reconnaîtrai-je cela? Car je suis vieux, et ma femme est avancée en âge."}, {"numero": 19, "texto": "L''''ange lui répondit: Je suis Gabriel, je me tiens devant Dieu; j''''ai été envoyé pour te parler, et pour t''''annoncer cette bonne nouvelle."}, {"numero": 20, "texto": "Et voici, tu seras muet, et tu ne pourras parler jusqu''''au jour où ces choses arriveront, parce que tu n''''as pas cru à mes paroles, qui s''''accompliront en leur temps."}, {"numero": 21, "texto": "Cependant, le peuple attendait Zacharie, s''''étonnant de ce qu''''il restait si longtemps dans le temple."}, {"numero": 22, "texto": "Quand il sortit, il ne put leur parler, et ils comprirent qu''''il avait eu une vision dans le temple; il leur faisait des signes, et il resta muet."}, {"numero": 23, "texto": "Lorsque ses jours de service furent écoulés, il s''''en alla chez lui."}, {"numero": 24, "texto": "Quelque temps après, Elisabeth, sa femme, devint enceinte. Elle se cacha pendant cinq mois, disant:"}, {"numero": 25, "texto": "C''''est la grâce que le Seigneur m''''a faite, quand il a jeté les yeux sur moi pour ôter mon opprobre parmi les hommes."}, {"numero": 26, "texto": "Au sixième mois, l''''ange Gabriel fut envoyé par Dieu dans une ville de Galilée, appelée Nazareth,"}, {"numero": 27, "texto": "auprès d''''une vierge fiancée à un homme de la maison de David, nommé Joseph. Le nom de la vierge était Marie."}, {"numero": 28, "texto": "L''''ange entra chez elle, et dit: Je te salue, toi à qui une grâce a été faite; le Seigneur est avec toi."}, {"numero": 29, "texto": "Troublée par cette parole, Marie se demandait ce que pouvait signifier une telle salutation."}, {"numero": 30, "texto": "L''''ange lui dit: Ne crains point, Marie; car tu as trouvé grâce devant Dieu."}, {"numero": 31, "texto": "Et voici, tu deviendras enceinte, et tu enfanteras un fils, et tu lui donneras le nom de Jésus."}, {"numero": 32, "texto": "Il sera grand et sera appelé Fils du Très-Haut, et le Seigneur Dieu lui donnera le trône de David, son père."}, {"numero": 33, "texto": "Il règnera sur la maison de Jacob éternellement, et son règne n''''aura point de fin."}, {"numero": 34, "texto": "Marie dit à l''''ange: Comment cela se fera-t-il, puisque je ne connais point d''''homme?"}, {"numero": 35, "texto": "L''''ange lui répondit: Le Saint-Esprit viendra sur toi, et la puissance du Très-Haut te couvrira de son ombre. C''''est pourquoi le saint enfant qui naîtra de toi sera appelé Fils de Dieu."}, {"numero": 36, "texto": "Voici, Elisabeth, ta parente, a conçu, elle aussi, un fils en sa vieillesse, et celle qui était appelée stérile est dans son sixième mois."}, {"numero": 37, "texto": "Car rien n''''est impossible à Dieu."}, {"numero": 38, "texto": "Marie dit: Je suis la servante du Seigneur; qu''''il me soit fait selon ta parole! Et l''''ange la quitta."}, {"numero": 39, "texto": "Dans ce même temps, Marie se leva, et s''''en alla en hâte vers les montagnes, dans une ville de Juda."}, {"numero": 40, "texto": "Elle entra dans la maison de Zacharie, et salua Elisabeth."}, {"numero": 41, "texto": "Dès qu''''Elisabeth entendit la salutation de Marie, son enfant tressaillit dans son sein, et elle fut remplie du Saint-Esprit."}, {"numero": 42, "texto": "Elle s''''écria d''''une voix forte: Tu es bénie entre les femmes, et le fruit de ton sein est béni."}, {"numero": 43, "texto": "Comment m''''est-il accordé que la mère de mon Seigneur vienne auprès de moi?"}, {"numero": 44, "texto": "Car voici, aussitôt que la voix de ta salutation a frappé mon oreille, l''''enfant a tressailli d''''allégresse dans mon sein."}, {"numero": 45, "texto": "Heureuse celle qui a cru, parce que les choses qui lui ont été dites de la part du Seigneur auront leur accomplissement."}, {"numero": 46, "texto": "Et Marie dit: Mon âme exalte le Seigneur,"}, {"numero": 47, "texto": "Et mon esprit se réjouit en Dieu, mon Sauveur,"}, {"numero": 48, "texto": "Parce qu''''il a jeté les yeux sur la bassesse de sa servante. Car voici, désormais toutes les générations me diront bienheureuse,"}, {"numero": 49, "texto": "Parce que le Tout-Puissant a fait pour moi de grandes choses. Son nom est saint,"}, {"numero": 50, "texto": "Et sa miséricorde s''''étend d''''âge en âge Sur ceux qui le craignent."}, {"numero": 51, "texto": "Il a déployé la force de son bras; Il a dispersé ceux qui avaient dans le coeur des pensées orgueilleuses."}, {"numero": 52, "texto": "Il a renversé les puissants de leurs trônes, Et il a élevé les humbles."}, {"numero": 53, "texto": "Il a rassasié de biens les affamés, Et il a renvoyé les riches à vide."}, {"numero": 54, "texto": "Il a secouru Israël, son serviteur, Et il s''''est souvenu de sa miséricorde, -"}, {"numero": 55, "texto": "Comme il l''''avait dit à nos pères, -Envers Abraham et sa postérité pour toujours."}, {"numero": 56, "texto": "Marie demeura avec Elisabeth environ trois mois. Puis elle retourna chez elle."}, {"numero": 57, "texto": "Le temps où Elisabeth devait accoucher arriva, et elle enfanta un fils."}, {"numero": 58, "texto": "Ses voisins et ses parents apprirent que le Seigneur avait fait éclater envers elle sa miséricorde, et ils se réjouirent avec elle."}, {"numero": 59, "texto": "Le huitième jour, ils vinrent pour circoncire l''''enfant, et ils l''''appelaient Zacharie, du nom de son père."}, {"numero": 60, "texto": "Mais sa mère prit la parole, et dit: Non, il sera appelé Jean."}, {"numero": 61, "texto": "Ils lui dirent: Il n''''y a dans ta parenté personne qui soit appelé de ce nom."}, {"numero": 62, "texto": "Et ils firent des signes à son père pour savoir comment il voulait qu''''on l''''appelle."}, {"numero": 63, "texto": "Zacharie demanda des tablettes, et il écrivit: Jean est son nom. Et tous furent dans l''''étonnement."}, {"numero": 64, "texto": "Au même instant, sa bouche s''''ouvrit, sa langue se délia, et il parlait, bénissant Dieu."}, {"numero": 65, "texto": "La crainte s''''empara de tous les habitants d''''alentour, et, dans toutes les montagnes de la Judée, on s''''entretenait de toutes ces choses."}, {"numero": 66, "texto": "Tous ceux qui les apprirent les gardèrent dans leur coeur, en disant: Que sera donc cet enfant? Et la main du Seigneur était avec lui."}, {"numero": 67, "texto": "Zacharie, son père, fut rempli du Saint-Esprit, et il prophétisa, en ces mots:"}, {"numero": 68, "texto": "Béni soit le Seigneur, le Dieu d''''Israël, De ce qu''''il a visité et racheté son peuple,"}, {"numero": 69, "texto": "Et nous a suscité un puissant Sauveur Dans la maison de David, son serviteur,"}, {"numero": 70, "texto": "Comme il l''''avait annoncé par la bouche de ses saints prophètes des temps anciens, -"}, {"numero": 71, "texto": "Un Sauveur qui nous délivre de nos ennemis et de la main de tous ceux qui nous haïssent!"}, {"numero": 72, "texto": "C''''est ainsi qu''''il manifeste sa miséricorde envers nos pères, Et se souvient de sa sainte alliance,"}, {"numero": 73, "texto": "Selon le serment par lequel il avait juré à Abraham, notre père,"}, {"numero": 74, "texto": "De nous permettre, après que nous serions délivrés de la main de nos ennemis, De le servir sans crainte,"}, {"numero": 75, "texto": "En marchant devant lui dans la sainteté et dans la justice tous les jours de notre vie."}, {"numero": 76, "texto": "Et toi, petit enfant, tu seras appelé prophète du Très-Haut; Car tu marcheras devant la face du Seigneur, pour préparer ses voies,"}, {"numero": 77, "texto": "Afin de donner à son peuple la connaissance du salut Par le pardon de ses péchés,"}, {"numero": 78, "texto": "Grâce aux entrailles de la miséricorde de notre Dieu, En vertu de laquelle le soleil levant nous a visités d''''en haut,"}, {"numero": 79, "texto": "Pour éclairer ceux qui sont assis dans les ténèbres et dans l''''ombre de la mort, Pour diriger nos pas dans le chemin de la paix."}, {"numero": 80, "texto": "Or, l''''enfant croissait, et se fortifiait en esprit. Et il demeura dans les déserts, jusqu''''au jour où il se présenta devant Israël."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 1, 'es', '[{"numero": 1, "texto": "HABIENDO muchos tentado á poner en orden la historia de las cosas que entre nosotros han sido ciertísimas,"}, {"numero": 2, "texto": "Como nos lo enseñaron los que desde el principio lo vieron por sus ojos, y fueron ministros de la palabra;"}, {"numero": 3, "texto": "Me ha parecido también á mí, después de haber entendido todas las cosas desde el principio con diligencia, escribírtelas por orden, oh muy buen Teófilo,"}, {"numero": 4, "texto": "Para que conozcas la verdad de las cosas en las cuales has sido enseñado."}, {"numero": 5, "texto": "HUBO en los días de Herodes, rey de Judea, un sacerdote llamado Zacarías, de la suerte de Abías; y su mujer, de las hijas de Aarón, llamada Elisabet."}, {"numero": 6, "texto": "Y eran ambos justos delante de Dios, andando sin reprensión en todos los mandamientos y estatutos del Señor."}, {"numero": 7, "texto": "Y no tenían hijo, porque Elisabet era estéril, y ambos eran avanzados en días."}, {"numero": 8, "texto": "Y aconteció que ejerciendo Zacarías el sacerdocio delante de Dios por el orden de su vez,"}, {"numero": 9, "texto": "Conforme á la costumbre del sacerdocio, salió en suerte á poner el incienso, entrando en el templo del Señor."}, {"numero": 10, "texto": "Y toda la multitud del pueblo estaba fuera orando á la hora del incienso."}, {"numero": 11, "texto": "Y se le apareció el ángel del Señor puesto en pie á la derecha del altar del incienso."}, {"numero": 12, "texto": "Y se turbó Zacarías viéndole, y cayó temor sobre él."}, {"numero": 13, "texto": "Mas el ángel le dijo: Zacarías, no temas; porque tu oración ha sido oída, y tu mujer Elisabet te parirá un hijo, y llamarás su nombre Juan."}, {"numero": 14, "texto": "Y tendrás gozo y alegría, y muchos se gozarán de su nacimiento."}, {"numero": 15, "texto": "Porque será grande delante de Dios, y no beberá vino ni sidra; y será lleno del Espíritu Santo, aun desde el seno de su madre."}, {"numero": 16, "texto": "Y á muchos de los hijos de Israel convertirá al Señor Dios de ellos."}, {"numero": 17, "texto": "Porque él irá delante de él con el espíritu y virtud de Elías, para convertir los corazones de los padres á los hijos, y los rebeldes á la prudencia de los justos, para aparejar al Señor un pueblo apercibido."}, {"numero": 18, "texto": "Y dijo Zacarías al ángel: ¿En qué conoceré esto? porque yo soy viejo, y mi mujer avanzada en días."}, {"numero": 19, "texto": "Y respondiendo el ángel le dijo: Yo soy Gabriel, que estoy delante de Dios; y soy enviado á hablarte, y á darte estas buenas nuevas."}, {"numero": 20, "texto": "Y he aquí estarás mudo y no podrás hablar, hasta el día que esto sea hecho, por cuanto no creíste á mis palabras, las cuales se cumplirán á su tiempo."}, {"numero": 21, "texto": "Y el pueblo estaba esperando á Zacarías, y se maravillaban de que él se detuviese en el templo."}, {"numero": 22, "texto": "Y saliendo, no les podía hablar: y entendieron que había visto visión en el templo: y él les hablaba por señas, y quedó mudo."}, {"numero": 23, "texto": "Y fué, que cumplidos los días de su oficio, se vino á su casa."}, {"numero": 24, "texto": "Y después de aquellos días concibió su mujer Elisabet, y se encubrió por cinco meses, diciendo:"}, {"numero": 25, "texto": "Porque el Señor me ha hecho así en los días en que miró para quitar mi afrenta entre los hombres."}, {"numero": 26, "texto": "Y al sexto mes, el ángel Gabriel fué enviado de Dios á una ciudad de Galilea, llamada Nazaret,"}, {"numero": 27, "texto": "A una virgen desposada con un varón que se llamaba José, de la casa de David: y el nombre de la virgen era María."}, {"numero": 28, "texto": "Y entrando el ángel á donde estaba, dijo, ¡Salve, muy favorecida! el Señor es contigo: bendita tú entre las mujeres."}, {"numero": 29, "texto": "Mas ella, cuando le vió, se turbó de sus palabras, y pensaba qué salutación fuese ésta."}, {"numero": 30, "texto": "Entonces el ángel le dijo: María, no temas, porque has hallado gracia cerca de Dios."}, {"numero": 31, "texto": "Y he aquí, concebirás en tu seno, y parirás un hijo, y llamarás su nombre JESUS."}, {"numero": 32, "texto": "Este será grande, y será llamado Hijo del Altísimo: y le dará el Señor Dios el trono de David su padre:"}, {"numero": 33, "texto": "Y reinará en la casa de Jacob por siempre; y de su reino no habrá fin."}, {"numero": 34, "texto": "Entonces María dijo al ángel: ¿Cómo será esto? porque no conozco varón."}, {"numero": 35, "texto": "Y respondiendo el ángel le dijo: El Espíritu Santo vendrá sobre ti, y la virtud del Altísimo te hará sombra; por lo cual también lo Santo que nacerá, será llamado Hijo de Dios."}, {"numero": 36, "texto": "Y he aquí, Elisabet tu parienta, también ella ha concebido hijo en su vejez; y este es el sexto mes á ella que es llamada la estéril:"}, {"numero": 37, "texto": "Porque ninguna cosa es imposible para Dios."}, {"numero": 38, "texto": "Entonces María dijo: He aquí la sierva del Señor; hágase á mí conforme á tu palabra. Y el ángel partió de ella."}, {"numero": 39, "texto": "En aquellos días levantándose María, fué á la montaña con priesa, á una ciudad de Judá;"}, {"numero": 40, "texto": "Y entró en casa de Zacarías, y saludó á Elisabet."}, {"numero": 41, "texto": "Y aconteció, que como oyó Elisabet la salutación de María, la criatura saltó en su vientre; y Elisabet fué llena del Espíritu Santo,"}, {"numero": 42, "texto": "Y exclamó á gran voz, y dijo: Bendita tú entre las mujeres, y bendito el fruto de tu vientre."}, {"numero": 43, "texto": "¿Y de dónde esto á mí, que la madre de mi Señor venga á mí?"}, {"numero": 44, "texto": "Porque he aquí, como llegó la voz de tu salutación á mis oídos, la criatura saltó de alegría en mi vientre."}, {"numero": 45, "texto": "Y bienaventurada la que creyó, porque se cumplirán las cosas que le fueron dichas de parte del Señor."}, {"numero": 46, "texto": "Entonces María dijo: engrandece mi alma al Señor;"}, {"numero": 47, "texto": "Y mi espíritu se alegró en Dios mi Salvador."}, {"numero": 48, "texto": "Porque ha mirado á la bajeza de su criada; porque he aquí, desde ahora me dirán bienaventurada todas las generaciones."}, {"numero": 49, "texto": "Porque me ha hecho grandes cosas el Poderoso; y santo es su nombre."}, {"numero": 50, "texto": "Y su misericordia de generación á generación á los que le temen."}, {"numero": 51, "texto": "Hizo valentía con su brazo: esparció los soberbios del pensamiento de su corazón."}, {"numero": 52, "texto": "Quitó los poderosos de los tronos, y levantó á los humildes."}, {"numero": 53, "texto": "A los hambrientos hinchió de bienes; y á los ricos envió vacíos."}, {"numero": 54, "texto": "Recibió á Israel su siervo, acordándose de la misericordia,"}, {"numero": 55, "texto": "Como habló á nuestros padres á Abraham y á su simiente para siempre."}, {"numero": 56, "texto": "Y se quedó María con ella como tres meses: después se volvió á su casa."}, {"numero": 57, "texto": "Y á Elisabet se le cumplió el tiempo de parir, y parió un hijo."}, {"numero": 58, "texto": "Y oyeron los vecinos y los parientes que Dios había hecho con ella grande misericordia, y se alegraron con ella."}, {"numero": 59, "texto": "Y aconteció, que al octavo día vinieron para circuncidar al niño; y le llamaban del nombre de su padre, Zacarías."}, {"numero": 60, "texto": "Y respondiendo su madre, dijo: No; sino Juan será llamado."}, {"numero": 61, "texto": "Y le dijeron: ¿Por qué? nadie hay en tu parentela que se llame de este nombre."}, {"numero": 62, "texto": "Y hablaron por señas á su padre, cómo le quería llamar."}, {"numero": 63, "texto": "Y demandando la tablilla, escribió, diciendo: Juan es su nombre. Y todos se maravillaron."}, {"numero": 64, "texto": "Y luego fué abierta su boca y su lengua, y habló bendiciendo á Dios."}, {"numero": 65, "texto": "Y fué un temor sobre todos los vecinos de ellos; y en todas las montañas de Judea fueron divulgadas todas estas cosas."}, {"numero": 66, "texto": "Y todos los que las oían, las conservaban en su corazón, diciendo: ¿Quién será este niño? Y la mano del Señor estaba con él."}, {"numero": 67, "texto": "Y Zacarías su padre fué lleno de Espíritu Santo, y profetizó, diciendo:"}, {"numero": 68, "texto": "Bendito el Señor Dios de Israel, que ha visitado y hecho redención á su pueblo,"}, {"numero": 69, "texto": "Y nos alzó un cuerno de salvación en la casa de David su siervo,"}, {"numero": 70, "texto": "Como habló por boca de sus santos profetas que fueron desde el principio:"}, {"numero": 71, "texto": "Salvación de nuestros enemigos, y de mano de todos los que nos aborrecieron;"}, {"numero": 72, "texto": "Para hacer misericordia con nuestros padres, y acordándose de su santo pacto;"}, {"numero": 73, "texto": "Del juramento que juró á Abraham nuestro padre, que nos había de dar,"}, {"numero": 74, "texto": "Que sin temor librados de nuestros enemigos, le serviríamos"}, {"numero": 75, "texto": "En santidad y en justicia delante de él, todos los días nuestros."}, {"numero": 76, "texto": "Y tú, niño, profeta del Altísimo serás llamado; porque irás ante la faz del Señor, para aparejar sus caminos;"}, {"numero": 77, "texto": "Dando conocimiento de salud á su pueblo, para remisión de sus pecados,"}, {"numero": 78, "texto": "Por las entrañas de misericordia de nuestro Dios, con que nos visitó de lo alto el Oriente,"}, {"numero": 79, "texto": "Para dar luz á los que habitan en tinieblas y en sombra de muerte; para encaminar nuestros pies por camino de paz."}, {"numero": 80, "texto": "Y el niño crecía, y se fortalecía en espíritu: y estuvo en los desiertos hasta el día que se mostró á Israel."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 2, 'pt', '[{"numero": 1, "texto": "E aconteceu naqueles dias que saiu um decreto da parte de César Augusto, para que todo a terra se registrasse."}, {"numero": 2, "texto": "(Esse primeiro censo foi feito quando Quirino era o governador da Síria.)"}, {"numero": 3, "texto": "E todos foram se registrar, cada um à sua própria cidade."}, {"numero": 4, "texto": "E José também subiu da Galileia, da cidade de Nazaré à Judeia, à cidade de Davi, que se chama Belém; (porque [ele] era da casa e família de Davi.)"}, {"numero": 5, "texto": "Para se registrar com Maria, sua mulher, com ele prometida em casamento, que estava grávida."}, {"numero": 6, "texto": "E aconteceu que, enquanto eles ali, completaram-se os dias em que ela havia de dar à luz."}, {"numero": 7, "texto": "E deu à luz seu filho primogênito, e o envolveu em panos, e o deitou numa manjedoura; porque não havia lugar para eles na hospedaria."}, {"numero": 8, "texto": "E naquela mesma localidade havia pastores que estavam no campo, e vigiavam o seu rebanho durante as vigílias da noite."}, {"numero": 9, "texto": "E eis que um anjo do Senhor lhe apareceu, e a glória do Senhor os cercou de resplendor. Então tiveram grande temor."}, {"numero": 10, "texto": "E o anjo lhes disse: Não temais; pois eis que vos dou notícias de grande alegria, que será para todo o povo:"}, {"numero": 11, "texto": "que hoje na cidade de Davi vos nasceu o Salvador, que é Cristo, o Senhor."}, {"numero": 12, "texto": "E isto vos será por sinal: achareis o menino envolto em panos, deitado numa manjedoura."}, {"numero": 13, "texto": "E no mesmo instante apareceu com o anjo uma multidão de exércitos celestiais, louvando a Deus, e dizendo:"}, {"numero": 14, "texto": "Glória nas alturas a Deus, paz na terra, [e] aos seres humanos boa vontade."}, {"numero": 15, "texto": "E aconteceu que, quando os anjos se ausentaram deles para o céu, os pastores disseram uns aos outros: Vamos, pois, até Belém, e vejamos isso que aconteceu, e o Senhor nos informou."}, {"numero": 16, "texto": "Então foram apressadamente, e acharam Maria, e José, e o menino deitado na manjedoura."}, {"numero": 17, "texto": "Quando [o] viram, contaram o que lhes havia sido dito sobre o menino."}, {"numero": 18, "texto": "E todos os que ouviram se admiraram com o que os pastores lhes diziam."}, {"numero": 19, "texto": "Mas Maria guardava todas essas palavras, considerando [-as] no seu coração."}, {"numero": 20, "texto": "Os pastores voltaram glorificando e louvando a Deus por tudo o que haviam ouvido e visto, como lhes havia sido dito."}, {"numero": 21, "texto": "Quando se completaram os oito dias para circuncidar o menino, foi chamado o seu nome Jesus, o qual havia sido posto pelo anjo antes que fosse concebido."}, {"numero": 22, "texto": "E quando se completaram os dias da purificação dela, segundo a Lei de Moisés, o levaram a Jerusalém, para o apresentarem ao Senhor,"}, {"numero": 23, "texto": "conforme o que está escrito na Lei do Senhor: Todo macho primogênito será consagrado ao Senhor."}, {"numero": 24, "texto": "E para darem a oferta segundo o que se diz na Lei do Senhor: um par de rolinhas ou dois pombinhos."}, {"numero": 25, "texto": "E eis que havia em Jerusalém um homem de nome Simeão; e esse homem era justo e devoto, e esperava a consolação de Israel; e o Espírito Santo estava sobre ele."}, {"numero": 26, "texto": "E havia lhe sido revelado pelo Espírito Santo que ele não veria a morte antes de ter visto o Cristo do Senhor."}, {"numero": 27, "texto": "E pelo Espírito foi ao Templo; e quando os pais trouxeram o menino Jesus, para fazerem com ele conforme o costume da Lei,"}, {"numero": 28, "texto": "Então ele o tomou em seus braços, louvou a Deus, e disse:"}, {"numero": 29, "texto": "Agora, Senhor, despedes o teu servo em paz, conforme a tua palavra,"}, {"numero": 30, "texto": "pois os meus olhos viram a tua salvação,"}, {"numero": 31, "texto": "a qual preparaste diante de todos os povos;"}, {"numero": 32, "texto": "Luz para iluminar as gentios, e para a glória do teu povo Israel."}, {"numero": 33, "texto": "E José e sua mãe se admiraram das coisas que se diziam sobre ele."}, {"numero": 34, "texto": "Simeão os abençoou, e disse a Maria, sua mãe: Eis que este é posto para queda e levantamento de muitos em Israel; e para sinal que terá oposição,"}, {"numero": 35, "texto": "(também uma espada atravessará a tua própria alma) para que os pensamentos de muitos corações se manifestem."}, {"numero": 36, "texto": "E estava ali a profetiza Ana, filha de Fanuel, da tribo de Aser. Ela já tinha idade avançada, e havia vivido com o marido sete anos desde sua virgindade."}, {"numero": 37, "texto": "E era viúva de cerca de oitenta e quatro anos, e não se afastava do Templo, servindo [a Deus] com jejuns e orações, de noite e de dia."}, {"numero": 38, "texto": "E ela veio na mesma hora; ela agradeci ao Senhor, e falava dele a todos os que esperavam a redenção em Jerusalém."}, {"numero": 39, "texto": "E quando acabaram de cumprir tudo, segundo a Lei do Senhor, voltaram à Galileia, para a sua cidade de Nazaré."}, {"numero": 40, "texto": "E o menino crescia e se fortalecia em espírito, e cheio de sabedoria; e a graça de Deus estava sobre ele."}, {"numero": 41, "texto": "Todos os anos, seus pais iam a Jerusalém, para a festa da Páscoa."}, {"numero": 42, "texto": "E quando [Jesus] tinha doze anos, subiram a Jerusalém, conforme o costume do festival;"}, {"numero": 43, "texto": "E quando aqueles dias terminaram, eles partiram de volta, mas o menino Jesus ficou em Jerusalém sem que José e sua mãe soubessem."}, {"numero": 44, "texto": "Porém, como pensavam que ele vinha pelo caminho entre os companheiros de viagem, eles andaram o caminho de um dia; e o procuraram entre os parentes e conhecidos."}, {"numero": 45, "texto": "E como não o acharam, voltaram a Jerusalém em busca dele."}, {"numero": 46, "texto": "E aconteceu que, três dias depois, o acharam no templo, sentado no meio dos mestres, ouvindo-os, e perguntando-lhes."}, {"numero": 47, "texto": "E todos os que o ouviam admiravam a sua inteligência e respostas;"}, {"numero": 48, "texto": "Quando eles o viram, ficarm surpresos. E sua mãe lhe disse: Filho, por que fizeste assim conosco? Eis que teu pai e eu com ansiedade te procurávamos."}, {"numero": 49, "texto": "Ele lhes disse: Por que me procuráveis? Não sabeis que devo estar nos negócios de meu Pai?"}, {"numero": 50, "texto": "E eles não entenderam as palavras que lhes dizia."}, {"numero": 51, "texto": "Então desceu com eles, e veio a Nazaré, e os obedecia. E a sua mãe guardava todas essas coisas no seu coração."}, {"numero": 52, "texto": "Jesus crescia em sabedoria, em estatura, e em graça para com Deus e as pessoas."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 2, 'en', '[{"numero": 1, "texto": "And it came to pass in those days, that there went out a decree from Caesar Augustus that all the world should be taxed."}, {"numero": 2, "texto": "(And this taxing was first made when Cyrenius was governor of Syria.)"}, {"numero": 3, "texto": "And all went to be taxed, every one into his own city."}, {"numero": 4, "texto": "And Joseph also went up from Galilee, out of the city of Nazareth, into Judaea, unto the city of David, which is called Bethlehem; (because he was of the house and lineage of David:)"}, {"numero": 5, "texto": "To be taxed with Mary his espoused wife, being great with child."}, {"numero": 6, "texto": "And so it was, that, while they were there, the days were accomplished that she should be delivered."}, {"numero": 7, "texto": "And she brought forth her firstborn son, and wrapped him in swaddling clothes, and laid him in a manger; because there was no room for them in the inn."}, {"numero": 8, "texto": "And there were in the same country shepherds abiding in the field, keeping watch over their flock by night."}, {"numero": 9, "texto": "And, lo, the angel of the Lord came upon them, and the glory of the Lord shone round about them: and they were sore afraid."}, {"numero": 10, "texto": "And the angel said unto them, Fear not: for, behold, I bring you good tidings of great joy, which shall be to all people."}, {"numero": 11, "texto": "For unto you is born this day in the city of David a Saviour, which is Christ the Lord."}, {"numero": 12, "texto": "And this shall be a sign unto you; Ye shall find the babe wrapped in swaddling clothes, lying in a manger."}, {"numero": 13, "texto": "And suddenly there was with the angel a multitude of the heavenly host praising God, and saying,"}, {"numero": 14, "texto": "Glory to God in the highest, and on earth peace, good will toward men."}, {"numero": 15, "texto": "And it came to pass, as the angels were gone away from them into heaven, the shepherds said one to another, Let us now go even unto Bethlehem, and see this thing which is come to pass, which the Lord hath made known unto us."}, {"numero": 16, "texto": "And they came with haste, and found Mary, and Joseph, and the babe lying in a manger."}, {"numero": 17, "texto": "And when they had seen it, they made known abroad the saying which was told them concerning this child."}, {"numero": 18, "texto": "And all they that heard it wondered at those things which were told them by the shepherds."}, {"numero": 19, "texto": "But Mary kept all these things, and pondered them in her heart."}, {"numero": 20, "texto": "And the shepherds returned, glorifying and praising God for all the things that they had heard and seen, as it was told unto them."}, {"numero": 21, "texto": "And when eight days were accomplished for the circumcising of the child, his name was called Jesus, which was so named of the angel before he was conceived in the womb."}, {"numero": 22, "texto": "And when the days of her purification according to the law of Moses were accomplished, they brought him to Jerusalem, to present him to the Lord;"}, {"numero": 23, "texto": "(As it is written in the law of the Lord, Every male that openeth the womb shall be called holy to the Lord;)"}, {"numero": 24, "texto": "And to offer a sacrifice according to that which is said in the law of the Lord, A pair of turtledoves, or two young pigeons."}, {"numero": 25, "texto": "And, behold, there was a man in Jerusalem, whose name was Simeon; and the same man was just and devout, waiting for the consolation of Israel: and the Holy Ghost was upon him."}, {"numero": 26, "texto": "And it was revealed unto him by the Holy Ghost, that he should not see death, before he had seen the Lord''s Christ."}, {"numero": 27, "texto": "And he came by the Spirit into the temple: and when the parents brought in the child Jesus, to do for him after the custom of the law,"}, {"numero": 28, "texto": "Then took he him up in his arms, and blessed God, and said,"}, {"numero": 29, "texto": "Lord, now lettest thou thy servant depart in peace, according to thy word:"}, {"numero": 30, "texto": "For mine eyes have seen thy salvation,"}, {"numero": 31, "texto": "Which thou hast prepared before the face of all people;"}, {"numero": 32, "texto": "A light to lighten the Gentiles, and the glory of thy people Israel."}, {"numero": 33, "texto": "And Joseph and his mother marvelled at those things which were spoken of him."}, {"numero": 34, "texto": "And Simeon blessed them, and said unto Mary his mother, Behold, this child is set for the fall and rising again of many in Israel; and for a sign which shall be spoken against;"}, {"numero": 35, "texto": "(Yea, a sword shall pierce through thy own soul also,) that the thoughts of many hearts may be revealed."}, {"numero": 36, "texto": "And there was one Anna, a prophetess, the daughter of Phanuel, of the tribe of Aser: she was of a great age, and had lived with an husband seven years from her virginity;"}, {"numero": 37, "texto": "And she was a widow of about fourscore and four years, which departed not from the temple, but served God with fastings and prayers night and day."}, {"numero": 38, "texto": "And she coming in that instant gave thanks likewise unto the Lord, and spake of him to all them that looked for redemption in Jerusalem."}, {"numero": 39, "texto": "And when they had performed all things according to the law of the Lord, they returned into Galilee, to their own city Nazareth."}, {"numero": 40, "texto": "And the child grew, and waxed strong in spirit, filled with wisdom: and the grace of God was upon him."}, {"numero": 41, "texto": "Now his parents went to Jerusalem every year at the feast of the passover."}, {"numero": 42, "texto": "And when he was twelve years old, they went up to Jerusalem after the custom of the feast."}, {"numero": 43, "texto": "And when they had fulfilled the days, as they returned, the child Jesus tarried behind in Jerusalem; and Joseph and his mother knew not of it."}, {"numero": 44, "texto": "But they, supposing him to have been in the company, went a day''s journey; and they sought him among their kinsfolk and acquaintance."}, {"numero": 45, "texto": "And when they found him not, they turned back again to Jerusalem, seeking him."}, {"numero": 46, "texto": "And it came to pass, that after three days they found him in the temple, sitting in the midst of the doctors, both hearing them, and asking them questions."}, {"numero": 47, "texto": "And all that heard him were astonished at his understanding and answers."}, {"numero": 48, "texto": "And when they saw him, they were amazed: and his mother said unto him, Son, why hast thou thus dealt with us? behold, thy father and I have sought thee sorrowing."}, {"numero": 49, "texto": "And he said unto them, How is it that ye sought me? wist ye not that I must be about my Father''s business?"}, {"numero": 50, "texto": "And they understood not the saying which he spake unto them."}, {"numero": 51, "texto": "And he went down with them, and came to Nazareth, and was subject unto them: but his mother kept all these sayings in her heart."}, {"numero": 52, "texto": "And Jesus increased in wisdom and stature, and in favour with God and man."}]'::jsonb, 'King James Version'),
  ('Lc', 2, 'fr', '[{"numero": 1, "texto": "En ce temps-là parut un édit de César Auguste, ordonnant un recensement de toute la terre."}, {"numero": 2, "texto": "Ce premier recensement eut lieu pendant que Quirinius était gouverneur de Syrie."}, {"numero": 3, "texto": "Tous allaient se faire inscrire, chacun dans sa ville."}, {"numero": 4, "texto": "Joseph aussi monta de la Galilée, de la ville de Nazareth, pour se rendre en Judée, dans la ville de David, appelée Bethléhem, parce qu''''il était de la maison et de la famille de David,"}, {"numero": 5, "texto": "afin de se faire inscrire avec Marie, sa fiancée, qui était enceinte."}, {"numero": 6, "texto": "Pendant qu''''ils étaient là, le temps où Marie devait accoucher arriva,"}, {"numero": 7, "texto": "et elle enfanta son fils premier-né. Elle l''''emmaillota, et le coucha dans une crèche, parce qu''''il n''''y avait pas de place pour eux dans l''''hôtellerie."}, {"numero": 8, "texto": "Il y avait, dans cette même contrée, des bergers qui passaient dans les champs les veilles de la nuit pour garder leurs troupeaux."}, {"numero": 9, "texto": "Et voici, un ange du Seigneur leur apparut, et la gloire du Seigneur resplendit autour d''''eux. Ils furent saisis d''''une grande frayeur."}, {"numero": 10, "texto": "Mais l''''ange leur dit: Ne craignez point; car je vous annonce une bonne nouvelle, qui sera pour tout le peuple le sujet d''''une grande joie:"}, {"numero": 11, "texto": "c''''est qu''''aujourd''''hui, dans la ville de David, il vous est né un Sauveur, qui est le Christ, le Seigneur."}, {"numero": 12, "texto": "Et voici à quel signe vous le reconnaîtrez: vous trouverez un enfant emmailloté et couché dans une crèche."}, {"numero": 13, "texto": "Et soudain il se joignit à l''''ange une multitude de l''''armée céleste, louant Dieu et disant:"}, {"numero": 14, "texto": "Gloire à Dieu dans les lieux très hauts, Et paix sur la terre parmi les hommes qu''''il agrée!"}, {"numero": 15, "texto": "Lorsque les anges les eurent quittés pour retourner au ciel, les bergers se dirent les uns aux autres: Allons jusqu''''à Bethléhem, et voyons ce qui est arrivé, ce que le Seigneur nous a fait connaître."}, {"numero": 16, "texto": "Ils y allèrent en hâte, et ils trouvèrent Marie et Joseph, et le petit enfant couché dans la crèche."}, {"numero": 17, "texto": "Après l''''avoir vu, ils racontèrent ce qui leur avait été dit au sujet de ce petit enfant."}, {"numero": 18, "texto": "Tous ceux qui les entendirent furent dans l''''étonnement de ce que leur disaient les bergers."}, {"numero": 19, "texto": "Marie gardait toutes ces choses, et les repassait dans son coeur."}, {"numero": 20, "texto": "Et les bergers s''''en retournèrent, glorifiant et louant Dieu pour tout ce qu''''ils avaient entendu et vu, et qui était conforme à ce qui leur avait été annoncé."}, {"numero": 21, "texto": "Le huitième jour, auquel l''''enfant devait être circoncis, étant arrivé, on lui donna le nom de Jésus, nom qu''''avait indiqué l''''ange avant qu''''il fût conçu dans le sein de sa mère."}, {"numero": 22, "texto": "Et, quand les jours de leur purification furent accomplis, selon la loi de Moïse, Joseph et Marie le portèrent à Jérusalem, pour le présenter au Seigneur, -"}, {"numero": 23, "texto": "suivant ce qui est écrit dans la loi du Seigneur: Tout mâle premier-né sera consacré au Seigneur, -"}, {"numero": 24, "texto": "et pour offrir en sacrifice deux tourterelles ou deux jeunes pigeons, comme cela est prescrit dans la loi du Seigneur."}, {"numero": 25, "texto": "Et voici, il y avait à Jérusalem un homme appelé Siméon. Cet homme était juste et pieux, il attendait la consolation d''''Israël, et l''''Esprit-Saint était sur lui."}, {"numero": 26, "texto": "Il avait été divinement averti par le Saint-Esprit qu''''il ne mourrait point avant d''''avoir vu le Christ du Seigneur."}, {"numero": 27, "texto": "Il vint au temple, poussé par l''''Esprit. Et, comme les parents apportaient le petit enfant Jésus pour accomplir à son égard ce qu''''ordonnait la loi,"}, {"numero": 28, "texto": "il le reçut dans ses bras, bénit Dieu, et dit:"}, {"numero": 29, "texto": "Maintenant, Seigneur, tu laisses ton serviteur S''''en aller en paix, selon ta parole."}, {"numero": 30, "texto": "Car mes yeux ont vu ton salut,"}, {"numero": 31, "texto": "Salut que tu as préparé devant tous les peuples,"}, {"numero": 32, "texto": "Lumière pour éclairer les nations, Et gloire d''''Israël, ton peuple."}, {"numero": 33, "texto": "Son père et sa mère étaient dans l''''admiration des choses qu''''on disait de lui."}, {"numero": 34, "texto": "Siméon les bénit, et dit à Marie, sa mère: Voici, cet enfant est destiné à amener la chute et le relèvement de plusieurs en Israël, et à devenir un signe qui provoquera la contradiction,"}, {"numero": 35, "texto": "et à toi-même une épée te transpercera l''''âme, afin que les pensées de beaucoup de coeurs soient dévoilées."}, {"numero": 36, "texto": "Il y avait aussi une prophétesse, Anne, fille de Phanuel, de la tribu d''''Aser. Elle était fort avancée en âge, et elle avait vécu sept ans avec son mari depuis sa virginité."}, {"numero": 37, "texto": "Restée veuve, et âgée de quatre vingt-quatre ans, elle ne quittait pas le temple, et elle servait Dieu nuit et jour dans le jeûne et dans la prière."}, {"numero": 38, "texto": "Etant survenue, elle aussi, à cette même heure, elle louait Dieu, et elle parlait de Jésus à tous ceux qui attendaient la délivrance de Jérusalem."}, {"numero": 39, "texto": "Lorsqu''''ils eurent accompli tout ce qu''''ordonnait la loi du Seigneur, Joseph et Marie retournèrent en Galilée, à Nazareth, leur ville."}, {"numero": 40, "texto": "Or, l''''enfant croissait et se fortifiait. Il était rempli de sagesse, et la grâce de Dieu était sur lui."}, {"numero": 41, "texto": "Les parents de Jésus allaient chaque année à Jérusalem, à la fête de Pâque."}, {"numero": 42, "texto": "Lorsqu''''il fut âgé de douze ans, ils y montèrent, selon la coutume de la fête."}, {"numero": 43, "texto": "Puis, quand les jours furent écoulés, et qu''''ils s''''en retournèrent, l''''enfant Jésus resta à Jérusalem. Son père et sa mère ne s''''en aperçurent pas."}, {"numero": 44, "texto": "Croyant qu''''il était avec leurs compagnons de voyage, ils firent une journée de chemin, et le cherchèrent parmi leurs parents et leurs connaissances."}, {"numero": 45, "texto": "Mais, ne l''''ayant pas trouvé, ils retournèrent à Jérusalem pour le chercher."}, {"numero": 46, "texto": "Au bout de trois jours, ils le trouvèrent dans le temple, assis au milieu des docteurs, les écoutant et les interrogeant."}, {"numero": 47, "texto": "Tous ceux qui l''''entendaient étaient frappés de son intelligence et de ses réponses."}, {"numero": 48, "texto": "Quand ses parents le virent, ils furent saisis d''''étonnement, et sa mère lui dit: Mon enfant, pourquoi as-tu agi de la sorte avec nous? Voici, ton père et moi, nous te cherchions avec angoisse."}, {"numero": 49, "texto": "Il leur dit: Pourquoi me cherchiez-vous? Ne saviez-vous pas qu''''il faut que je m''''occupe des affaires de mon Père?"}, {"numero": 50, "texto": "Mais ils ne comprirent pas ce qu''''il leur disait."}, {"numero": 51, "texto": "Puis il descendit avec eux pour aller à Nazareth, et il leur était soumis. Sa mère gardait toutes ces choses dans son coeur."}, {"numero": 52, "texto": "Et Jésus croissait en sagesse, en stature, et en grâce, devant Dieu et devant les hommes."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 2, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ en aquellos días que salió edicto de parte de Augusto César, que toda la tierra fuese empadronada."}, {"numero": 2, "texto": "Este empadronamiento primero fué hecho siendo Cirenio gobernador de la Siria."}, {"numero": 3, "texto": "E iban todos para ser empadronados, cada uno á su ciudad."}, {"numero": 4, "texto": "Y subió José de Galilea, de la ciudad de Nazaret, á Judea, á la ciudad de David, que se llama Bethlehem, por cuanto era de la casa y familia de David;"}, {"numero": 5, "texto": "Para ser empadronado con María su mujer, desposada con él, la cual estaba en cinta."}, {"numero": 6, "texto": "Y aconteció que estando ellos allí, se cumplieron los días en que ella había de parir."}, {"numero": 7, "texto": "Y parió á su hijo primogénito, y le envolvió en pañales, y acostóle en un pesebre, porque no había lugar para ellos en el mesón."}, {"numero": 8, "texto": "Y había pastores en la misma tierra, que velaban y guardaban las vigilias de la noche sobre su ganado."}, {"numero": 9, "texto": "Y he aquí el ángel del Señor vino sobre ellos, y la claridad de Dios los cercó de resplandor; y tuvieron gran temor."}, {"numero": 10, "texto": "Mas el ángel les dijo: No temáis; porque he aquí os doy nuevas de gran gozo, que será para todo el pueblo:"}, {"numero": 11, "texto": "Que os ha nacido hoy, en la ciudad de David, un Salvador, que es CRISTO el Señor."}, {"numero": 12, "texto": "Y esto os será por señal: hallaréis al niño envuelto en pañales, echado en un pesebre."}, {"numero": 13, "texto": "Y repentinamente fué con el ángel una multitud de los ejércitos celestiales, que alababan á Dios, y decían:"}, {"numero": 14, "texto": "Gloria en las alturas á Dios, y en la tierra paz, buena voluntad para con los hombres."}, {"numero": 15, "texto": "Y aconteció que como los ángeles se fueron de ellos al cielo, los pastores dijeron los unos á los otros: Pasemos pues hasta Bethlehem, y veamos esto que ha sucedido, que el Señor nos ha manifestado."}, {"numero": 16, "texto": "Y vinieron apriesa, y hallaron á María, y á José, y al niño acostado en el pesebre."}, {"numero": 17, "texto": "Y viéndolo, hicieron notorio lo que les había sido dicho del niño."}, {"numero": 18, "texto": "Y todos los que oyeron, se maravillaron de lo que los pastores les decían."}, {"numero": 19, "texto": "Mas María guardaba todas estas cosas, confiriéndolas en su corazón."}, {"numero": 20, "texto": "Y se volvieron los pastores glorificando y alabando á Dios de todas las cosas que habían oído y visto, como les había sido dicho."}, {"numero": 21, "texto": "Y pasados los ocho días para circuncidar al niño, llamaron su nombre JESÚS; el cual le fué puesto por el ángel antes que él fuese concebido en el vientre."}, {"numero": 22, "texto": "Y como se cumplieron los días de la purificación de ella, conforme á la ley de Moisés, le trajeron á Jerusalem para presentarle al Señor,"}, {"numero": 23, "texto": "(Como está escrito en la ley del Señor: Todo varón que abriere la matriz, será llamado santo al Señor),"}, {"numero": 24, "texto": "Y para dar la ofrenda, conforme á lo que está dicho en la ley del Señor: un par de tórtolas, ó dos palominos."}, {"numero": 25, "texto": "Y he aquí, había un hombre en Jerusalem, llamado Simeón, y este hombre, justo y pío, esperaba la consolación de Israel: y el Espíritu Santo era sobre él."}, {"numero": 26, "texto": "Y había recibido respuesta del Espíritu Santo, que no vería la muerte antes que viese al Cristo del Señor."}, {"numero": 27, "texto": "Y vino por Espíritu al templo. Y cuando metieron al niño Jesús sus padres en el templo, para hacer por él conforme á la costumbre de la ley,"}, {"numero": 28, "texto": "Entonces él le tomó en sus brazos, y bendijo á Dios, y dijo:"}, {"numero": 29, "texto": "Ahora despides, Señor, á tu siervo, conforme á tu palabra, en paz;"}, {"numero": 30, "texto": "Porque han visto mis ojos tu salvación,"}, {"numero": 31, "texto": "La cual has aparejado en presencia de todos los pueblos;"}, {"numero": 32, "texto": "Luz para ser revelada á los Gentiles, y la gloria de tu pueblo Israel."}, {"numero": 33, "texto": "Y José y su madre estaban maravillados de las cosas que se decían de él."}, {"numero": 34, "texto": "Y los bendijo Simeón, y dijo á su madre María: He aquí, éste es puesto para caída y para levantamiento de muchos en Israel; y para señal á la que será contradicho;"}, {"numero": 35, "texto": "Y una espada traspasará tu alma de ti misma, para que sean manifestados los pensamientos de muchos corazones."}, {"numero": 36, "texto": "Estaba también allí Ana, profetisa, hija de Phanuel, de la tribu de Aser; la cual había venido en grande edad, y había vivido con su marido siete años desde su virginidad;"}, {"numero": 37, "texto": "Y era viuda de hasta ochenta y cuatro años, que no se apartaba del templo, sirviendo de noche y de día con ayunos y oraciones."}, {"numero": 38, "texto": "Y ésta, sobreviniendo en la misma hora, juntamente confesaba al Señor, y hablaba de él á todos los que esperaban la redención en Jerusalem."}, {"numero": 39, "texto": "Mas como cumplieron todas las cosas según la ley del Señor, se volvieron á Galilea, á su ciudad de Nazaret."}, {"numero": 40, "texto": "Y el niño crecía, y fortalecíase, y se henchía de sabiduría; y la gracia de Dios era sobre él."}, {"numero": 41, "texto": "E iban sus padres todos los años á Jerusalem en la fiesta de la Pascua."}, {"numero": 42, "texto": "Y cuando fué de doce años, subieron ellos á Jerusalem conforme á la costumbre del día de la fiesta."}, {"numero": 43, "texto": "Y acabados los días, volviendo ellos, se quedó el niño Jesús en Jerusalem, sin saberlo José y su madre."}, {"numero": 44, "texto": "Y pensando que estaba en la compañía, anduvieron camino de un día; y le buscaban entre los parientes y entre los conocidos:"}, {"numero": 45, "texto": "Mas como no le hallasen, volvieron á Jerusalem buscándole."}, {"numero": 46, "texto": "Y aconteció, que tres días después le hallaron en el templo, sentado en medio de los doctores, oyéndoles y preguntándoles."}, {"numero": 47, "texto": "Y todos los que le oían, se pasmaban de su entendimiento y de sus respuestas."}, {"numero": 48, "texto": "Y cuando le vieron, se maravillaron; y díjole su madre: Hijo, ¿por qué nos has hecho así? He aquí, tu padre y yo te hemos buscado con dolor."}, {"numero": 49, "texto": "Entonces él les dice: ¿Qué hay? ¿por qué me buscabais? ¿No sabíais que en los negocios de mi Padre me conviene estar?"}, {"numero": 50, "texto": "Mas ellos no entendieron las palabras que les habló."}, {"numero": 51, "texto": "Y descendió con ellos, y vino á Nazaret, y estaba sujeto á ellos. Y su madre guardaba todas estas cosas en su corazón."}, {"numero": 52, "texto": "Y Jesús crecía en sabiduría, y en edad, y en gracia para con Dios y los hombres."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 3, 'pt', '[{"numero": 1, "texto": "No ano quinze do império de Tibério César, sendo Pôncio Pilatos o governador da Judeia, Herodes tetraca da Galileia, e seu irmão Filipe o tetrarca da Itureia e da província de Traconites, e Lisânias o tetrarca de Abilene;"}, {"numero": 2, "texto": "sendo Anás e Caifás os sumos sacerdotes, a palavra de Deus veio a João, filho de Zacarias, no deserto."}, {"numero": 3, "texto": "Ele percorreu toda a região ao redor do Jordão, pregando o batismo de arrependimento, para o perdão dos pecados;"}, {"numero": 4, "texto": "conforme o que está escrito no livro das palavras do profeta Isaías, que diz: “Voz do que clama no deserto: Preparai o caminho do Senhor, endireitai as suas veredas."}, {"numero": 5, "texto": "Todo vale se encherá, e todo monte e colina se abaixará; os tortos serão endireitados, e os caminhos ásperos se suavizarão;"}, {"numero": 6, "texto": "e todos verão a salvação de Deus.”"}, {"numero": 7, "texto": "[João] dizia às multidões que vinham ser batizadas por ele: “Raça de víboras, quem vos ensinou a fugir da ira que está para chegar?"}, {"numero": 8, "texto": "Dai, pois, frutos condizentes com o arrependimento, e não comeceis a dizer em vós mesmos: ‘Temos Abraão por pai’; pois eu vos digo que até destas pedras Deus pode produzir filhos a Abraão."}, {"numero": 9, "texto": "E também o machado já está posto à raiz das árvores; portanto, toda árvore que não dá bom fruto é cortada e lançada ao fogo."}, {"numero": 10, "texto": "E as multidões lhe perguntavam: Então o que devemos fazer?"}, {"numero": 11, "texto": "E ele lhes respondeu: Quem tiver duas túnicas, reparta com o não tem; e quem tiver comida, faça da mesma maneira."}, {"numero": 12, "texto": "E chegaram também uns publicanos, para serem batizados; e disseram-lhe: Mestre, que devemos fazer?"}, {"numero": 13, "texto": "E ele lhes disse: Não exijais mais do que vos está ordenado."}, {"numero": 14, "texto": "E uns soldados também lhe perguntaram: E nós, que devemos fazer? E ele lhes disse: Não maltrateis nem defraudeis a ninguém; e contentai-vos com vossos salários."}, {"numero": 15, "texto": "E, enquanto o povo estava em expectativa, e todos pensando em seus corações se talvez João seria o Cristo,"}, {"numero": 16, "texto": "João respondeu a todos: De fato, eu vos batizo com água, mas vem um que é mais poderoso do que eu, de quem eu não sou digno de desatar a tira das sandálias; ele vos batizará com o Espírito Santo e com fogo."}, {"numero": 17, "texto": "Sua pá está na sua mão, e limpará sua eira, e juntará o trigo no seu celeiro; porém queimará a palha com fogo que nunca se apaga."}, {"numero": 18, "texto": "Assim, exortando com muitas outras coisas, [João] anunciava a boa notícia ao povo."}, {"numero": 19, "texto": "Porém, quando Herodes, o tetrarca, foi repreendido por ele por causa de Herodias, mulher do seu irmão Filipe, e por todas as maldades que Herodes havia feito,"}, {"numero": 20, "texto": "acrescentou a todas ainda esta: encarcerou João na prisão."}, {"numero": 21, "texto": "E aconteceu que, quando todo o povo era batizado, Jesus [também] foi batizado, e enquanto orava, o céu se abriu,"}, {"numero": 22, "texto": "e o Espírito Santo desceu sobre ele em forma corpórea, como pomba; e veio do céu uma voz que dizia: Tu és o meu Filho amado, em ti me agrado."}, {"numero": 23, "texto": "E o mesmo Jesus começou quando tinha cerca de trinta anos, sendo (como se pensava) filho de José, [filho] de Eli,"}, {"numero": 24, "texto": "[filho] de Matate, [filho] de Levi, [filho] de Melqui, [filho] de Janai, [filho] de José."}, {"numero": 25, "texto": "[filho] de Matatias, [filho] de Amós, [filho] de Naum, [filho] de Esli, [filho] de Nagai."}, {"numero": 26, "texto": "[filho] de Maate, [filho] de Matatias, [filho] de Semei, [filho] de José, [filho] de Judá."}, {"numero": 27, "texto": "[filho] de Joaná, [filho] de Resa, [filho] de Zorobabel, e [filho] de Salatiel, [filho] de Neri."}, {"numero": 28, "texto": "[filho] de Melqui, [filho] de Adi, e [filho] de Cosã, [filho] de Elmodã, [filho] de Er."}, {"numero": 29, "texto": "[filho] de José,[filho] de Eliézer, [filho] de Jorim, [filho] de Matate, [filho] de Levi."}, {"numero": 30, "texto": "[filho] de Simeão, [filho] de Judá, [filho] de José, [filho] de Jonã, [filho] de Eliaquim."}, {"numero": 31, "texto": "[filho] de Meleá, [filho] de Mainã, [filho] de Matatá, [filho] de Natã, [filho] de Davi."}, {"numero": 32, "texto": "[Filho] de Jessé, [filho] de Obede, [filho] de Boaz, [filho] de Salmom, [filho] de Naassom."}, {"numero": 33, "texto": "[Filho] de Aminadabe, [filho] de Arão,[filho] de Esrom, [filho] de Peres, [filho] de Judá."}, {"numero": 34, "texto": "[filho] de Jacó, [filho] de Isaque, [filho] de Abraão, [filho] de Terá, [filho] de Naor."}, {"numero": 35, "texto": "[filho] de Serugue, [filho] de Ragaú, [filho] de Faleque, [filho] de Éber, [filho] de Salá."}, {"numero": 36, "texto": "[Filho] de Cainã, [filho] de Arfaxade, [filho] de Sem, [filho] de Noé, [filho] de Lameque."}, {"numero": 37, "texto": "[Filho] de Matusalém, [filho] de Enoque, [filho] de Jarede, [filho] de Maleleel, [filho] de Cainã."}, {"numero": 38, "texto": "[filho] de Enos, [filho] de Sete, [filho] de Adão, [e Adão] de Deus."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 3, 'en', '[{"numero": 1, "texto": "Now in the fifteenth year of the reign of Tiberius Caesar, Pontius Pilate being governor of Judaea, and Herod being tetrarch of Galilee, and his brother Philip tetrarch of Ituraea and of the region of Trachonitis, and Lysanias the tetrarch of Abilene,"}, {"numero": 2, "texto": "Annas and Caiaphas being the high priests, the word of God came unto John the son of Zacharias in the wilderness."}, {"numero": 3, "texto": "And he came into all the country about Jordan, preaching the baptism of repentance for the remission of sins;"}, {"numero": 4, "texto": "As it is written in the book of the words of Esaias the prophet, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight."}, {"numero": 5, "texto": "Every valley shall be filled, and every mountain and hill shall be brought low; and the crooked shall be made straight, and the rough ways shall be made smooth;"}, {"numero": 6, "texto": "And all flesh shall see the salvation of God."}, {"numero": 7, "texto": "Then said he to the multitude that came forth to be baptized of him, O generation of vipers, who hath warned you to flee from the wrath to come?"}, {"numero": 8, "texto": "Bring forth therefore fruits worthy of repentance, and begin not to say within yourselves, We have Abraham to our father: for I say unto you, That God is able of these stones to raise up children unto Abraham."}, {"numero": 9, "texto": "And now also the axe is laid unto the root of the trees: every tree therefore which bringeth not forth good fruit is hewn down, and cast into the fire."}, {"numero": 10, "texto": "And the people asked him, saying, What shall we do then?"}, {"numero": 11, "texto": "He answereth and saith unto them, He that hath two coats, let him impart to him that hath none; and he that hath meat, let him do likewise."}, {"numero": 12, "texto": "Then came also publicans to be baptized, and said unto him, Master, what shall we do?"}, {"numero": 13, "texto": "And he said unto them, Exact no more than that which is appointed you."}, {"numero": 14, "texto": "And the soldiers likewise demanded of him, saying, And what shall we do? And he said unto them, Do violence to no man, neither accuse any falsely; and be content with your wages."}, {"numero": 15, "texto": "And as the people were in expectation, and all men mused in their hearts of John, whether he were the Christ, or not;"}, {"numero": 16, "texto": "John answered, saying unto them all, I indeed baptize you with water; but one mightier than I cometh, the latchet of whose shoes I am not worthy to unloose: he shall baptize you with the Holy Ghost and with fire:"}, {"numero": 17, "texto": "Whose fan is in his hand, and he will throughly purge his floor, and will gather the wheat into his garner; but the chaff he will burn with fire unquenchable."}, {"numero": 18, "texto": "And many other things in his exhortation preached he unto the people."}, {"numero": 19, "texto": "But Herod the tetrarch, being reproved by him for Herodias his brother Philip''s wife, and for all the evils which Herod had done,"}, {"numero": 20, "texto": "Added yet this above all, that he shut up John in prison."}, {"numero": 21, "texto": "Now when all the people were baptized, it came to pass, that Jesus also being baptized, and praying, the heaven was opened,"}, {"numero": 22, "texto": "And the Holy Ghost descended in a bodily shape like a dove upon him, and a voice came from heaven, which said, Thou art my beloved Son; in thee I am well pleased."}, {"numero": 23, "texto": "And Jesus himself began to be about thirty years of age, being (as was supposed) the son of Joseph, which was the son of Heli,"}, {"numero": 24, "texto": "Which was the son of Matthat, which was the son of Levi, which was the son of Melchi, which was the son of Janna, which was the son of Joseph,"}, {"numero": 25, "texto": "Which was the son of Mattathias, which was the son of Amos, which was the son of Naum, which was the son of Esli, which was the son of Nagge,"}, {"numero": 26, "texto": "Which was the son of Maath, which was the son of Mattathias, which was the son of Semei, which was the son of Joseph, which was the son of Juda,"}, {"numero": 27, "texto": "Which was the son of Joanna, which was the son of Rhesa, which was the son of Zorobabel, which was the son of Salathiel, which was the son of Neri,"}, {"numero": 28, "texto": "Which was the son of Melchi, which was the son of Addi, which was the son of Cosam, which was the son of Elmodam, which was the son of Er,"}, {"numero": 29, "texto": "Which was the son of Jose, which was the son of Eliezer, which was the son of Jorim, which was the son of Matthat, which was the son of Levi,"}, {"numero": 30, "texto": "Which was the son of Simeon, which was the son of Juda, which was the son of Joseph, which was the son of Jonan, which was the son of Eliakim,"}, {"numero": 31, "texto": "Which was the son of Melea, which was the son of Menan, which was the son of Mattatha, which was the son of Nathan, which was the son of David,"}, {"numero": 32, "texto": "Which was the son of Jesse, which was the son of Obed, which was the son of Booz, which was the son of Salmon, which was the son of Naasson,"}, {"numero": 33, "texto": "Which was the son of Aminadab, which was the son of Aram, which was the son of Esrom, which was the son of Phares, which was the son of Juda,"}, {"numero": 34, "texto": "Which was the son of Jacob, which was the son of Isaac, which was the son of Abraham, which was the son of Thara, which was the son of Nachor,"}, {"numero": 35, "texto": "Which was the son of Saruch, which was the son of Ragau, which was the son of Phalec, which was the son of Heber, which was the son of Sala,"}, {"numero": 36, "texto": "Which was the son of Cainan, which was the son of Arphaxad, which was the son of Sem, which was the son of Noe, which was the son of Lamech,"}, {"numero": 37, "texto": "Which was the son of Mathusala, which was the son of Enoch, which was the son of Jared, which was the son of Maleleel, which was the son of Cainan,"}, {"numero": 38, "texto": "Which was the son of Enos, which was the son of Seth, which was the son of Adam, which was the son of God."}]'::jsonb, 'King James Version'),
  ('Lc', 3, 'fr', '[{"numero": 1, "texto": "La quinzième année du règne de Tibère César, -lorsque Ponce Pilate était gouverneur de la Judée, Hérode tétrarque de la Galilée, son frère Philippe tétrarque de l''''Iturée et du territoire de la Trachonite, Lysanias tétrarque de l''''Abilène,"}, {"numero": 2, "texto": "et du temps des souverains sacrificateurs Anne et Caïphe, -la parole de Dieu fut adressée à Jean, fils de Zacharie, dans le désert."}, {"numero": 3, "texto": "Et il alla dans tout le pays des environs du Jourdain, prêchant le baptême de repentance, pour la rémission des péchés,"}, {"numero": 4, "texto": "selon ce qui est écrit dans le livre des paroles d''''Esaïe, le prophète: C''''est la voix de celui qui crie dans le désert: Préparez le chemin du Seigneur, Aplanissez ses sentiers."}, {"numero": 5, "texto": "Toute vallée sera comblée, Toute montagne et toute colline seront abaissées; Ce qui est tortueux sera redressé, Et les chemins raboteux seront aplanis."}, {"numero": 6, "texto": "Et toute chair verra le salut de Dieu."}, {"numero": 7, "texto": "Il disait donc à ceux qui venaient en foule pour être baptisés par lui: Races de vipères, qui vous a appris à fuir la colère à venir?"}, {"numero": 8, "texto": "Produisez donc des fruits dignes de la repentance, et ne vous mettez pas à dire en vous-mêmes: Nous avons Abraham pour père! Car je vous déclare que de ces pierres Dieu peut susciter des enfants à Abraham."}, {"numero": 9, "texto": "Déjà même la cognée est mise à la racine des arbres: tout arbre donc qui ne produit pas de bons fruits sera coupé et jeté au feu."}, {"numero": 10, "texto": "La foule l''''interrogeait, disant: Que devons-nous donc faire?"}, {"numero": 11, "texto": "Il leur répondit: Que celui qui a deux tuniques partage avec celui qui n''''en a point, et que celui qui a de quoi manger agisse de même."}, {"numero": 12, "texto": "Il vint aussi des publicains pour être baptisés, et ils lui dirent: Maître, que devons-nous faire?"}, {"numero": 13, "texto": "Il leur répondit: N''''exigez rien au delà de ce qui vous a été ordonné."}, {"numero": 14, "texto": "Des soldats aussi lui demandèrent: Et nous, que devons-nous faire? Il leur répondit: Ne commettez ni extorsion ni fraude envers personne, et contentez-vous de votre solde."}, {"numero": 15, "texto": "Comme le peuple était dans l''''attente, et que tous se demandaient en eux-mêmes si Jean n''''était pas le Christ,"}, {"numero": 16, "texto": "il leur dit à tous: Moi, je vous baptise d''''eau; mais il vient, celui qui est plus puissant que moi, et je ne suis pas digne de délier la courroie de ses souliers. Lui, il vous baptisera du Saint-Esprit et de feu."}, {"numero": 17, "texto": "Il a son van à la main; il nettoiera son aire, et il amassera le blé dans son grenier, mais il brûlera la paille dans un feu qui ne s''''éteint point."}, {"numero": 18, "texto": "C''''est ainsi que Jean annonçait la bonne nouvelle au peuple, en lui adressant encore beaucoup d''''autres exhortations."}, {"numero": 19, "texto": "Mais Hérode le tétrarque, étant repris par Jean au sujet d''''Hérodias, femme de son frère, et pour toutes les mauvaises actions qu''''il avait commises,"}, {"numero": 20, "texto": "ajouta encore à toutes les autres celle d''''enfermer Jean dans la prison."}, {"numero": 21, "texto": "Tout le peuple se faisant baptiser, Jésus fut aussi baptisé; et, pendant qu''''il priait, le ciel s''''ouvrit,"}, {"numero": 22, "texto": "et le Saint-Esprit descendit sur lui sous une forme corporelle, comme une colombe. Et une voix fit entendre du ciel ces paroles: Tu es mon Fils bien-aimé; en toi j''''ai mis toute mon affection."}, {"numero": 23, "texto": "Jésus avait environ trente ans lorsqu''''il commença son ministère, étant, comme on le croyait, fils de Joseph, fils d''''Héli,"}, {"numero": 24, "texto": "fils de Matthat, fils de Lévi, fils de Melchi, fils de Jannaï, fils de Joseph,"}, {"numero": 25, "texto": "fils de Mattathias, fils d''''Amos, fils de Nahum, fils d''''Esli, fils de Naggaï,"}, {"numero": 26, "texto": "fils de Maath, fils de Mattathias, fils de Sémeï, fils de Josech, fils de Joda,"}, {"numero": 27, "texto": "fils de Joanan, fils de Rhésa, fils de Zorobabel, fils de Salathiel, fils de Néri,"}, {"numero": 28, "texto": "fils de Melchi, fils d''''Addi, fils de Kosam, fils d''''Elmadam, fils D''''Er,"}, {"numero": 29, "texto": "fils de Jésus, fils d''''Eliézer, fils de Jorim, fils de Matthat, fils de Lévi,"}, {"numero": 30, "texto": "fils de Siméon, fils de Juda, fils de Joseph, fils de Jonam, fils d''''Eliakim,"}, {"numero": 31, "texto": "fils de Méléa, fils de Menna, fils de Mattatha, fils de Nathan, fils de David,"}, {"numero": 32, "texto": "fils d''''Isaï, fils de Jobed, fils de Booz, fils de Salmon, fils de Naasson,"}, {"numero": 33, "texto": "fils d''''Aminadab, fils d''''Admin, fils d''''Arni, fils d''''Esrom, fils de Pharès, fils de Juda,"}, {"numero": 34, "texto": "fils de Jacob, fils d''''Isaac, fils d''''Abraham, fils de Thara, fils de Nachor,"}, {"numero": 35, "texto": "fils de Seruch, fils de Ragau, fils de Phalek, fils d''''Eber, fils de Sala,"}, {"numero": 36, "texto": "fils de Kaïnam, fils d''''Arphaxad, fils de Sem, fils de Noé, fils de Lamech,"}, {"numero": 37, "texto": "fils de Mathusala, fils d''''Enoch, fils de Jared, fils de Maléléel, fils de Kaïnan,"}, {"numero": 38, "texto": "fils d''''Enos, fils de Seth, fils d''''Adam, fils de Dieu."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 3, 'es', '[{"numero": 1, "texto": "Y EN el año quince del imperio de Tiberio César, siendo gobernador de Judea Poncio Pilato, y Herodes tetrarca de Galilea, y su hermano Felipe tetrarca de Iturea y de la provincia de Traconite, y Lisanias tetrarca de Abilinia,"}, {"numero": 2, "texto": "Siendo sumos sacerdotes Anás y Caifás, vino palabra del Señor sobre Juan, hijo de Zacarías, en el desierto."}, {"numero": 3, "texto": "Y él vino por toda la tierra al rededor del Jordán predicando el bautismo del arrepentimiento para la remisión de pecados;"}, {"numero": 4, "texto": "Como está escrito en el libro de las palabras del profeta Isaías que dice: Voz del que clama en el desierto: Aparejad el camino del Señor, haced derechas sus sendas."}, {"numero": 5, "texto": "Todo valle se henchirá, y bajaráse todo monte y collado; y los caminos torcidos serán enderezados, y los caminos ásperos allanados;"}, {"numero": 6, "texto": "Y verá toda carne la salvación de Dios."}, {"numero": 7, "texto": "Y decía á las gentes que salían para ser bautizadas de él: ¡Oh generación de víboras, quién os enseñó á huir de la ira que vendrá?"}, {"numero": 8, "texto": "Haced, pues, frutos dignos de arrepentimiento, y no comencéis á decir en vosotros mismos: Tenemos á Abraham por padre: porque os digo que puede Dios, aun de estas piedras, levantar hijos á Abraham."}, {"numero": 9, "texto": "Y ya también el hacha está puesta á la raíz de los árboles: todo árbol pues que no hace buen fruto, es cortado, y echado en el fuego."}, {"numero": 10, "texto": "Y las gentes le preguntaban, diciendo: ¿Pues qué haremos?"}, {"numero": 11, "texto": "Y respondiendo, les dijo: El que tiene dos túnicas, dé al que no tiene; y el que tiene qué comer, haga lo mismo."}, {"numero": 12, "texto": "Y vinieron también publicanos para ser bautizados, y le dijeron: Maestro, ¿qué haremos?"}, {"numero": 13, "texto": "Y él les dijo: No exijáis más de lo que os está ordenado."}, {"numero": 14, "texto": "Y le preguntaron también los soldados, diciendo: Y nosotros, ¿qué haremos? Y les dice: No hagáis extorsión á nadie, ni calumniéis; y contentaos con vuestras pagas."}, {"numero": 15, "texto": "Y estando el pueblo esperando, y pensando todos de Juan en sus corazones, si él fuese el Cristo,"}, {"numero": 16, "texto": "Respondió Juan, diciendo á todos: Yo, á la verdad, os bautizo en agua; mas viene quien es más poderoso que yo, de quien no soy digno de desatar la correa de sus zapatos: él os bautizará en Espíritu Santo y fuego;"}, {"numero": 17, "texto": "Cuyo bieldo está en su mano, y limpiará su era, y juntará el trigo en su alfolí, y la paja quemará en fuego que nunca se apagará."}, {"numero": 18, "texto": "Y amonestando, otras muchas cosas también anunciaba al pueblo."}, {"numero": 19, "texto": "Entonces Herodes el tetrarca, siendo reprendido por él á causa de Herodías, mujer de Felipe su hermano, y de todas las maldades que había hecho Herodes,"}, {"numero": 20, "texto": "Añadió también esto sobre todo, que encerró á Juan en la cárcel."}, {"numero": 21, "texto": "Y aconteció que, como todo el pueblo se bautizaba, también Jesús fué bautizado; y orando, el cielo se abrió,"}, {"numero": 22, "texto": "Y descendió el Espíritu Santo sobre él en forma corporal, como paloma, y fué hecha una voz del cielo que decía: Tú eres mi Hijo amado, en ti me he complacido."}, {"numero": 23, "texto": "Y el mismo Jesús comenzaba á ser como de treinta años, hijo de José, como se creía; que fué hijo de Elí,"}, {"numero": 24, "texto": "Que fué de Mathat, que fué de Leví, que fué de Melchî, que fué de Janna, que fué de José,"}, {"numero": 25, "texto": "Que fué de Mattathías, que fué de Amós, que fué de Nahum, que fué de Esli,"}, {"numero": 26, "texto": "Que fué de Naggai, que fué de Maat, que fué de Mattathías, que fué de Semei, que fué de José, que fué de Judá,"}, {"numero": 27, "texto": "Que fué de Joanna, que fué de Rhesa, que fué de Zorobabel, que fué de Salathiel,"}, {"numero": 28, "texto": "Que fué de Neri, que fué de Melchî, que fué de Abdi, que fué de Cosam, que fué de Elmodam, que fué de Er,"}, {"numero": 29, "texto": "Que fué de Josué, que fué de Eliezer, que fué de Joreim, que fué de Mathat,"}, {"numero": 30, "texto": "Que fué de Leví, que fué de Simeón, que fué de Judá, que fué de José, que fué de Jonán, que fué de Eliachîm,"}, {"numero": 31, "texto": "Que fué de Melea, que fué de Mainán, que fué de Mattatha, que fué de Nathán,"}, {"numero": 32, "texto": "Que fué de David, que fué de Jessé, que fué de Obed, que fué de Booz, que fué de Salmón, que fué de Naassón,"}, {"numero": 33, "texto": "Que fué de Aminadab, que fué de Aram, que fué de Esrom, que fué de Phares,"}, {"numero": 34, "texto": "Que fué de Judá, que fué de Jacob, que fué de Isaac, que fué de Abraham, que fué de Thara, que fué de Nachôr,"}, {"numero": 35, "texto": "Que fué de Saruch, que fué de Ragau, que fué de Phalec, que fué de Heber,"}, {"numero": 36, "texto": "Que fué de Sala, que fué de Cainán, que fué de Arphaxad, que fué de Sem, que fué de Noé, que fué de Lamech,"}, {"numero": 37, "texto": "Que fué de Mathusala, que fué de Enoch, que fué de Jared, que fué de Maleleel,"}, {"numero": 38, "texto": "Que fué de Cainán, que fué de Enós, que fué de Seth, que fué de Adam, que fué de Dios."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 4, 'pt', '[{"numero": 1, "texto": "E Jesus, cheio do Espírito Santo, voltou do Jordão, e foi levado pelo Espírito ao deserto."}, {"numero": 2, "texto": "E por quarenta dias foi tentado pelo diabo; e não comeu coisa alguma naqueles dias; e terminados eles, depois teve fome."}, {"numero": 3, "texto": "Então o diabo lhe disse: Se tu és Filho de Deus, diz a esta pedra que se transforme em pão."}, {"numero": 4, "texto": "Jesus lhe respondeu: Está escrito que não só de pão viverá o ser humano, mas de toda palavra de Deus."}, {"numero": 5, "texto": "E o diabo o levou a um alto monte, e lhe mostrou todos os reinos do mundo num instante."}, {"numero": 6, "texto": "E o diabo lhe disse: Darei a ti todo este poder e sua glória; pois a mim foram entregues, e os dou a quem quero."}, {"numero": 7, "texto": "Portanto, se tu me adorares, tudo será teu."}, {"numero": 8, "texto": "E Jesus lhe respondeu: Para trás de mim, Satanás!Porque está escrito: Adorarás ao Senhor teu Deus, e só a ele servirás."}, {"numero": 9, "texto": "Então o levou a Jerusalém, e o pôs sobre a parte mais alta do templo, e disse-lhe: Se tu és o Filho de Deus, lança-te daqui abaixo."}, {"numero": 10, "texto": "Porque está escrito que: Mandará aos seus acerca de ti que te guardem."}, {"numero": 11, "texto": "E que: te sustentarão pelas mãos, para que nunca tropeces com o teu pé em alguma pedra."}, {"numero": 12, "texto": "Jesus lhe respondeu: Dito está: Não tentes ao Senhor teu Deus."}, {"numero": 13, "texto": "E quando o diabo acabou toda a tentação, ausentou-se dele por algum tempo."}, {"numero": 14, "texto": "Então Jesus, no poder do Espírito, voltou para a Galileia, e sua fama se espalhou por toda a região ao redor."}, {"numero": 15, "texto": "Ele ensinava em suas sinagogas, e era recebido com honra por todos."}, {"numero": 16, "texto": "Ele foi a Nazaré, onde havia sido criado, e entrou, conforme o seu costume, num dia de Sábado, na sinagoga; e levantou-se para ler."}, {"numero": 17, "texto": "Foi-lhe dado o livro do profeta Isaías; e quando abriu o livro, achou o lugar onde estava escrito:"}, {"numero": 18, "texto": "O Espírito do Senhor [está] sobre mim, porque ele me ungiu para evangelizar os pobres, me enviou para curar os contritos de coração;"}, {"numero": 19, "texto": "para proclamar liberdade aos cativos e dar vista aos cegos, para pôr em liberdade os oprimidos, para proclamar o ano agradável do Senhor."}, {"numero": 20, "texto": "Ele fechou o livro, e devolveu-o ao assistente, e se sentou. Os olhos de todos na sinagoga estavam fixos nele."}, {"numero": 21, "texto": "Então ele começou a lhes dizer: Hoje esta escritura se cumpriu em vossos ouvidos."}, {"numero": 22, "texto": "E todos davam testemunho dele, e se admiravam das palavras graciosas que saíam da sua boca; e diziam: Não é este o filho de José?"}, {"numero": 23, "texto": "E ele lhes disse: Sem dúvida me direis este provérbio: Médico, cura a ti mesmo; faz também aqui na tua terra natal todas as coisas que ouvimos terem sido feitas em Cafarnaum."}, {"numero": 24, "texto": "E disse: Em verdade vos digo que nenhum profeta é bem recebido na sua terra natal."}, {"numero": 25, "texto": "Porém em verdade vos digo que hava muitas viúvas em Israel nos dias de Elias, quando o céu se fechou por três anos e seis meses, de modo que em toda [aquela] terra houve grande fome."}, {"numero": 26, "texto": "Mas a nenhuma delas Elias foi enviado, a não ser a uma mulher viúva de Sarepta de Sidom."}, {"numero": 27, "texto": "E havia muitos leprosos em Israel no tempo do profeta Eliseu; mas nenhum deles foi limpo, a não ser Naamã, o sírio."}, {"numero": 28, "texto": "E todos na sinagoga, quando ouviram essas coisas, encheram-se de ira."}, {"numero": 29, "texto": "Então se levantaram, expulsaram-no da cidade, e o levaram até o topo do monte em que sua cidade era construída, para dali o lançarem abaixo."}, {"numero": 30, "texto": "Porém ele passou por meio deles, e se retirou."}, {"numero": 31, "texto": "Ele desceu a Cafarnaum, cidade de Galileia; e [ali] os ensinava nos sábados."}, {"numero": 32, "texto": "E admiravam o seu ensino, pois a sua palavra era com autoridade."}, {"numero": 33, "texto": "E estava na sinagoga um homem que tinha um espírito de um demônio imundo, e gritou com alta voz,"}, {"numero": 34, "texto": "dizendo: Ah, que temos contigo, Jesus Nazareno? Vieste para nos destruir? Sei quem és: o Santo de Deus."}, {"numero": 35, "texto": "E Jesus o repreendeu, dizendo: Cala-te, e, sai dele. E o demônio o derrubou no meio [do povo] , e saiu dele sem lhe fazer dano algum."}, {"numero": 36, "texto": "E espanto veio sobre todos; e falavam entre si uns aos outros, dizendo: Que palavra é esta, que até aos espíritos imundos ele manda com autoridade e poder, e eles saem?"}, {"numero": 37, "texto": "E sua fama era divulgada em todos os lugares em redor daquela região."}, {"numero": 38, "texto": "[Jesus] levantou-se da sinagoga, e entrou na casa de Simão. A sogra de Simão estava doente de uma grande febre, e rogaram-lhe por ela."}, {"numero": 39, "texto": "Ele se inclinou a ela, e repreendeu a febre, que a deixou. Ela imediatamente se levantou e começou a lhes servir."}, {"numero": 40, "texto": "Quando o sol estava se pondo, troxeram-lhe todos os que estavam enfermos de varias doenças. Ele punha as mãos sobre cada um deles e os curava."}, {"numero": 41, "texto": "E também de muitos saíam demônios, gritando, e dizendo: Tu és o Cristo, o Filho de Deus. Ele os repreendia, e não os deixava falar, porque sabiam que ele era o Cristo."}, {"numero": 42, "texto": "E sendo já dia, ele saiu, e foi a um lugar deserto. As multidões o buscavam; então vieram a ele, e queriam detê-lo, para que não os deixasse."}, {"numero": 43, "texto": "Porém ele lhes disse: Também é necessário que eu anuncie a outras cidades o evangelho do Reino de Deus; pois para isso sou enviado."}, {"numero": 44, "texto": "E ele pregava nas sinagogas da Galileia."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 4, 'en', '[{"numero": 1, "texto": "And Jesus being full of the Holy Ghost returned from Jordan, and was led by the Spirit into the wilderness,"}, {"numero": 2, "texto": "Being forty days tempted of the devil. And in those days he did eat nothing: and when they were ended, he afterward hungered."}, {"numero": 3, "texto": "And the devil said unto him, If thou be the Son of God, command this stone that it be made bread."}, {"numero": 4, "texto": "And Jesus answered him, saying, It is written, That man shall not live by bread alone, but by every word of God."}, {"numero": 5, "texto": "And the devil, taking him up into an high mountain, shewed unto him all the kingdoms of the world in a moment of time."}, {"numero": 6, "texto": "And the devil said unto him, All this power will I give thee, and the glory of them: for that is delivered unto me; and to whomsoever I will I give it."}, {"numero": 7, "texto": "If thou therefore wilt worship me, all shall be thine."}, {"numero": 8, "texto": "And Jesus answered and said unto him, Get thee behind me, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve."}, {"numero": 9, "texto": "And he brought him to Jerusalem, and set him on a pinnacle of the temple, and said unto him, If thou be the Son of God, cast thyself down from hence:"}, {"numero": 10, "texto": "For it is written, He shall give his angels charge over thee, to keep thee:"}, {"numero": 11, "texto": "And in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone."}, {"numero": 12, "texto": "And Jesus answering said unto him, It is said, Thou shalt not tempt the Lord thy God."}, {"numero": 13, "texto": "And when the devil had ended all the temptation, he departed from him for a season."}, {"numero": 14, "texto": "And Jesus returned in the power of the Spirit into Galilee: and there went out a fame of him through all the region round about."}, {"numero": 15, "texto": "And he taught in their synagogues, being glorified of all."}, {"numero": 16, "texto": "And he came to Nazareth, where he had been brought up: and, as his custom was, he went into the synagogue on the sabbath day, and stood up for to read."}, {"numero": 17, "texto": "And there was delivered unto him the book of the prophet Esaias. And when he had opened the book, he found the place where it was written,"}, {"numero": 18, "texto": "The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised,"}, {"numero": 19, "texto": "To preach the acceptable year of the Lord."}, {"numero": 20, "texto": "And he closed the book, and he gave it again to the minister, and sat down. And the eyes of all them that were in the synagogue were fastened on him."}, {"numero": 21, "texto": "And he began to say unto them, This day is this scripture fulfilled in your ears."}, {"numero": 22, "texto": "And all bare him witness, and wondered at the gracious words which proceeded out of his mouth. And they said, Is not this Joseph''s son?"}, {"numero": 23, "texto": "And he said unto them, Ye will surely say unto me this proverb, Physician, heal thyself: whatsoever we have heard done in Capernaum, do also here in thy country."}, {"numero": 24, "texto": "And he said, Verily I say unto you, No prophet is accepted in his own country."}, {"numero": 25, "texto": "But I tell you of a truth, many widows were in Israel in the days of Elias, when the heaven was shut up three years and six months, when great famine was throughout all the land;"}, {"numero": 26, "texto": "But unto none of them was Elias sent, save unto Sarepta, a city of Sidon, unto a woman that was a widow."}, {"numero": 27, "texto": "And many lepers were in Israel in the time of Eliseus the prophet; and none of them was cleansed, saving Naaman the Syrian."}, {"numero": 28, "texto": "And all they in the synagogue, when they heard these things, were filled with wrath,"}, {"numero": 29, "texto": "And rose up, and thrust him out of the city, and led him unto the brow of the hill whereon their city was built, that they might cast him down headlong."}, {"numero": 30, "texto": "But he passing through the midst of them went his way,"}, {"numero": 31, "texto": "And came down to Capernaum, a city of Galilee, and taught them on the sabbath days."}, {"numero": 32, "texto": "And they were astonished at his doctrine: for his word was with power."}, {"numero": 33, "texto": "And in the synagogue there was a man, which had a spirit of an unclean devil, and cried out with a loud voice,"}, {"numero": 34, "texto": "Saying, Let us alone; what have we to do with thee, thou Jesus of Nazareth? art thou come to destroy us? I know thee who thou art; the Holy One of God."}, {"numero": 35, "texto": "And Jesus rebuked him, saying, Hold thy peace, and come out of him. And when the devil had thrown him in the midst, he came out of him, and hurt him not."}, {"numero": 36, "texto": "And they were all amazed, and spake among themselves, saying, What a word is this! for with authority and power he commandeth the unclean spirits, and they come out."}, {"numero": 37, "texto": "And the fame of him went out into every place of the country round about."}, {"numero": 38, "texto": "And he arose out of the synagogue, and entered into Simon''s house. And Simon''s wife''s mother was taken with a great fever; and they besought him for her."}, {"numero": 39, "texto": "And he stood over her, and rebuked the fever; and it left her: and immediately she arose and ministered unto them."}, {"numero": 40, "texto": "Now when the sun was setting, all they that had any sick with divers diseases brought them unto him; and he laid his hands on every one of them, and healed them."}, {"numero": 41, "texto": "And devils also came out of many, crying out, and saying, Thou art Christ the Son of God. And he rebuking them suffered them not to speak: for they knew that he was Christ."}, {"numero": 42, "texto": "And when it was day, he departed and went into a desert place: and the people sought him, and came unto him, and stayed him, that he should not depart from them."}, {"numero": 43, "texto": "And he said unto them, I must preach the kingdom of God to other cities also: for therefore am I sent."}, {"numero": 44, "texto": "And he preached in the synagogues of Galilee."}]'::jsonb, 'King James Version'),
  ('Lc', 4, 'fr', '[{"numero": 1, "texto": "Jésus, rempli du Saint-Esprit, revint du Jourdain, et il fut conduit par l''''Esprit dans le désert,"}, {"numero": 2, "texto": "où il fut tenté par le diable pendant quarante jours. Il ne mangea rien durant ces jours-là, et, après qu''''ils furent écoulés, il eut faim."}, {"numero": 3, "texto": "Le diable lui dit: Si tu es Fils de Dieu, ordonne à cette pierre qu''''elle devienne du pain."}, {"numero": 4, "texto": "Jésus lui répondit: Il est écrit: L''''Homme ne vivra pas de pain seulement."}, {"numero": 5, "texto": "Le diable, l''''ayant élevé, lui montra en un instant tous les royaumes de la terre,"}, {"numero": 6, "texto": "et lui dit: Je te donnerai toute cette puissance, et la gloire de ces royaumes; car elle m''''a été donnée, et je la donne à qui je veux."}, {"numero": 7, "texto": "Si donc tu te prosternes devant moi, elle sera toute à toi."}, {"numero": 8, "texto": "Jésus lui répondit: Il est écrit: Tu adoreras le Seigneur, ton Dieu, et tu le serviras lui seul."}, {"numero": 9, "texto": "Le diable le conduisit encore à Jérusalem, le plaça sur le haut du temple, et lui dit: Si tu es Fils de Dieu, jette-toi d''''ici en bas;"}, {"numero": 10, "texto": "car il est écrit: Il donnera des ordres à ses anges à ton sujet, Afin qu''''ils te gardent;"}, {"numero": 11, "texto": "et: Ils te porteront sur les mains, De peur que ton pied ne heurte contre une pierre."}, {"numero": 12, "texto": "Jésus lui répondit: Il est dit: Tu ne tenteras point le Seigneur, ton Dieu."}, {"numero": 13, "texto": "Après l''''avoir tenté de toutes ces manières, le diable s''''éloigna de lui jusqu''''à un moment favorable."}, {"numero": 14, "texto": "Jésus, revêtu de la puissance de l''''Esprit, retourna en Galilée, et sa renommée se répandit dans tout le pays d''''alentour."}, {"numero": 15, "texto": "Il enseignait dans les synagogues, et il était glorifié par tous."}, {"numero": 16, "texto": "Il se rendit à Nazareth, où il avait été élevé, et, selon sa coutume, il entra dans la synagogue le jour du sabbat. Il se leva pour faire la lecture,"}, {"numero": 17, "texto": "et on lui remit le livre du prophète Esaïe. L''''ayant déroulé, il trouva l''''endroit où il était écrit:"}, {"numero": 18, "texto": "L''''Esprit du Seigneur est sur moi, Parce qu''''il m''''a oint pour annoncer une bonne nouvelle aux pauvres; Il m''''a envoyé pour guérir ceux qui ont le coeur brisé, Pour proclamer aux captifs la délivrance, Et aux aveugles le recouvrement de la vue, Pour renvoyer libres les opprimés,"}, {"numero": 19, "texto": "Pour publier une année de grâce du Seigneur."}, {"numero": 20, "texto": "Ensuite, il roula le livre, le remit au serviteur, et s''''assit. Tous ceux qui se trouvaient dans la synagogue avaient les regards fixés sur lui."}, {"numero": 21, "texto": "Alors il commença à leur dire: Aujourd''''hui cette parole de l''''Ecriture, que vous venez d''''entendre, est accomplie."}, {"numero": 22, "texto": "Et tous lui rendaient témoignage; ils étaient étonnés des paroles de grâce qui sortaient de sa bouche, et ils disaient: N''''est-ce pas le fils de Joseph?"}, {"numero": 23, "texto": "Jésus leur dit: Sans doute vous m''''appliquerez ce proverbe: Médecin, guéris-toi toi-même; et vous me direz: Fais ici, dans ta patrie, tout ce que nous avons appris que tu as fait à Capernaüm."}, {"numero": 24, "texto": "Mais, ajouta-t-il, je vous le dis en vérité, aucun prophète n''''est bien reçu dans sa patrie."}, {"numero": 25, "texto": "Je vous le dis en vérité: il y avait plusieurs veuves en Israël du temps d''''Elie, lorsque le ciel fut fermé trois ans et six mois et qu''''il y eut une grande famine sur toute la terre;"}, {"numero": 26, "texto": "et cependant Elie ne fut envoyé vers aucune d''''elles, si ce n''''est vers une femme veuve, à Sarepta, dans le pays de Sidon."}, {"numero": 27, "texto": "Il y avait aussi plusieurs lépreux en Israël du temps d''''Elisée, le prophète; et cependant aucun d''''eux ne fut purifié, si ce n''''est Naaman le Syrien."}, {"numero": 28, "texto": "Ils furent tous remplis de colère dans la synagogue, lorsqu''''ils entendirent ces choses."}, {"numero": 29, "texto": "Et s''''étant levés, ils le chassèrent de la ville, et le menèrent jusqu''''au sommet de la montagne sur laquelle leur ville était bâtie, afin de le précipiter en bas."}, {"numero": 30, "texto": "Mais Jésus, passant au milieu d''''eux, s''''en alla."}, {"numero": 31, "texto": "Il descendit à Capernaüm, ville de la Galilée; et il enseignait, le jour du sabbat."}, {"numero": 32, "texto": "On était frappé de sa doctrine; car il parlait avec autorité."}, {"numero": 33, "texto": "Il se trouva dans la synagogue un homme qui avait un esprit de démon impur, et qui s''''écria d''''une voix forte:"}, {"numero": 34, "texto": "Ah! qu''''y a-t-il entre nous et toi, Jésus de Nazareth? Tu es venu pour nous perdre. Je sais qui tu es: le Saint de Dieu."}, {"numero": 35, "texto": "Jésus le menaça, disant: Tais-toi, et sors de cet homme. Et le démon le jeta au milieu de l''''assemblée, et sortit de lui, sans lui faire aucun mal."}, {"numero": 36, "texto": "Tous furent saisis de stupeur, et ils se disaient les uns aux autres: Quelle est cette parole? il commande avec autorité et puissance aux esprits impurs, et ils sortent!"}, {"numero": 37, "texto": "Et sa renommée se répandit dans tous les lieux d''''alentour."}, {"numero": 38, "texto": "En sortant de la synagogue, il se rendit à la maison de Simon. La belle-mère de Simon avait une violente fièvre, et ils le prièrent en sa faveur."}, {"numero": 39, "texto": "S''''étant penché sur elle, il menaça la fièvre, et la fièvre la quitta. A l''''instant elle se leva, et les servit."}, {"numero": 40, "texto": "Après le coucher du soleil, tous ceux qui avaient des malades atteints de diverses maladies les lui amenèrent. Il imposa les mains à chacun d''''eux, et il les guérit."}, {"numero": 41, "texto": "Des démons aussi sortirent de beaucoup de personnes, en criant et en disant: Tu es le Fils de Dieu. Mais il les menaçait et ne leur permettait pas de parler, parce qu''''ils savaient qu''''il était le Christ."}, {"numero": 42, "texto": "Dès que le jour parut, il sortit et alla dans un lieu désert. Une foule de gens se mirent à sa recherche, et arrivèrent jusqu''''à lui; ils voulaient le retenir, afin qu''''il ne les quittât point."}, {"numero": 43, "texto": "Mais il leur dit: Il faut aussi que j''''annonce aux autres villes la bonne nouvelle du royaume de Dieu; car c''''est pour cela que j''''ai été envoyé."}, {"numero": 44, "texto": "Et il prêchait dans les synagogues de la Galilée."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 4, 'es', '[{"numero": 1, "texto": "Y JESÚS, lleno del Espíritu Santo, volvió del Jordán, y fué llevado por el Espíritu al desierto"}, {"numero": 2, "texto": "Por cuarenta días, y era tentado del diablo. Y no comió cosa en aquellos días: los cuales pasados, tuvo hambre."}, {"numero": 3, "texto": "Entonces el diablo le dijo: Si eres Hijo de Dios, di á esta piedra que se haga pan."}, {"numero": 4, "texto": "Y Jesús respondiéndole, dijo: Escrito está: Que no con pan solo vivirá el hombre, mas con toda palabra de Dios."}, {"numero": 5, "texto": "Y le llevó el diablo á un alto monte, y le mostró en un momento de tiempo todos los reinos de la tierra."}, {"numero": 6, "texto": "Y le dijo el diablo: A ti te daré toda esta potestad, y la gloria de ellos; porque á mí es entregada, y á quien quiero la doy:"}, {"numero": 7, "texto": "Pues si tú adorares delante de mí, serán todos tuyos."}, {"numero": 8, "texto": "Y respondiendo Jesús, le dijo: Vete de mí, Satanás, porque escrito está: A tu Señor Dios adorarás, y á él solo servirás."}, {"numero": 9, "texto": "Y le llevó á Jerusalem, y púsole sobre las almenas del templo, y le dijo: Si eres Hijo de Dios, échate de aquí abajo:"}, {"numero": 10, "texto": "Porque escrito está: Que á sus ángeles mandará de ti, que te guarden;"}, {"numero": 11, "texto": "Y en las manos te llevarán, porque no dañes tu pie en piedra."}, {"numero": 12, "texto": "Y respondiendo Jesús, le dijo: Dicho está: No tentarás al Señor tu Dios."}, {"numero": 13, "texto": "Y acabada toda tentación, el diablo se fué de él por un tiempo."}, {"numero": 14, "texto": "Y Jesús volvió en virtud del Espíritu á Galilea, y salió la fama de él por toda la tierra de alrededor."}, {"numero": 15, "texto": "Y enseñaba en las sinagogas de ellos, y era glorificado de todos."}, {"numero": 16, "texto": "Y vino á Nazaret, donde había sido criado; y entró, conforme á su costumbre, el día del sábado en la sinagoga, y se levantó á leer."}, {"numero": 17, "texto": "Y fuéle dado el libro del profeta Isaías; y como abrió el libro, halló el lugar donde estaba escrito:"}, {"numero": 18, "texto": "El Espíritu del Señor es sobre mí, por cuanto me ha ungido para dar buenas nuevas á los pobres: me ha enviado para sanar á los quebrantados de corazón; para pregonar á los cautivos libertad, y á los ciegos vista; para poner en libertad á los quebrantados:"}, {"numero": 19, "texto": "Para predicar el año agradable del Señor."}, {"numero": 20, "texto": "Y rollando el libro, lo dió al ministro, y sentóse: y los ojos de todos en la sinagoga estaban fijos en él."}, {"numero": 21, "texto": "Y comenzó á decirles: Hoy se ha cumplido esta Escritura en vuestros oídos."}, {"numero": 22, "texto": "Y todos le daban testimonio, y estaban maravillados de las palabras de gracia que salían de su boca, y decían: ¿No es éste el hijo de José?"}, {"numero": 23, "texto": "Y les dijo: Sin duda me diréis este refrán: Médico, cúrate á ti mismo: de tantas cosas que hemos oído haber sido hechas en Capernaum, haz también aquí en tu tierra."}, {"numero": 24, "texto": "Y dijo: De cierto os digo, que ningún profeta es acepto en su tierra."}, {"numero": 25, "texto": "Mas en verdad os digo, que muchas viudas había en Israel en los días de Elías, cuando el cielo fué cerrado por tres años y seis meses, que hubo una grande hambre en toda la tierra;"}, {"numero": 26, "texto": "Pero á ninguna de ellas fué enviado Elías, sino á Sarepta de Sidón, á una mujer viuda."}, {"numero": 27, "texto": "Y muchos leprosos había en Israel en tiempo del profeta Eliseo; mas ninguno de ellos fué limpio, sino Naamán el Siro."}, {"numero": 28, "texto": "Entonces todos en la sinagoga fueron llenos de ira, oyendo estas cosas;"}, {"numero": 29, "texto": "Y levantándose, le echaron fuera de la ciudad, y le llevaron hasta la cumbre del monte sobre el cual la ciudad de ellos estaba edificada, para despeñarle."}, {"numero": 30, "texto": "Mas él, pasando por medio de ellos, se fué."}, {"numero": 31, "texto": "Y descendió á Capernaum, ciudad de Galilea. Y los enseñaba en los sábados."}, {"numero": 32, "texto": "Y se maravillaban de su doctrina, porque su palabra era con potestad."}, {"numero": 33, "texto": "Y estaba en la sinagoga un hombre que tenía un espíritu de un demonio inmundo, el cual exclamó á gran voz,"}, {"numero": 34, "texto": "Diciendo: Déjanos, ¿qué tenemos contigo, Jesús Nazareno? ¿has venido á destruirnos? Yo te conozco quién eres, el Santo de Dios."}, {"numero": 35, "texto": "Y Jesús le increpó, diciendo: Enmudece, y sal de él. Entonces el demonio, derribándole en medio, salió de él, y no le hizo daño alguno."}, {"numero": 36, "texto": "Y hubo espanto en todos, y hablaban unos á otros, diciendo: ¿Qué palabra es ésta, que con autoridad y potencia manda á los espíritus inmundos, y salen?"}, {"numero": 37, "texto": "Y la fama de él se divulgaba de todas partes por todos los lugares de la comarca."}, {"numero": 38, "texto": "Y levantándose Jesús de la sinagoga, entró en casa de Simón: y la suegra de Simón estaba con una grande fiebre; y le rogaron por ella."}, {"numero": 39, "texto": "E inclinándose hacia ella, riñó á la fiebre; y la fiebre la dejó; y ella levantándose luego, les servía."}, {"numero": 40, "texto": "Y poniéndose el sol, todos los que tenían enfermos de diversas enfermedades, los traían á él; y él, poniendo las manos sobre cada uno de ellos, los sanaba."}, {"numero": 41, "texto": "Y salían también demonios de muchos, dando voces, y diciendo: Tú eres el Hijo de Dios. Mas riñéndolos no les dejaba hablar; porque sabían que él era el Cristo."}, {"numero": 42, "texto": "Y siendo ya de día salió, y se fué á un lugar desierto: y las gentes le buscaban, y vinieron hasta él; y le detenían para que no se apartase de ellos."}, {"numero": 43, "texto": "Mas él les dijo: Que también á otras ciudades es necesario que anuncie el evangelio del reino de Dios; porque para esto soy enviado."}, {"numero": 44, "texto": "Y predicaba en las sinagogas de Galilea."}]'::jsonb, 'Reina-Valera 1909'),
  ('Lc', 5, 'pt', '[{"numero": 1, "texto": "E aconteceu que as multidões o comprimiam para ouvir a palavra de Deus, quando ele estava junto ao lago de Genesaré."}, {"numero": 2, "texto": "Então ele viu dois barcos que estavam próximos [da margem] do lago, e os pescadores haviam descido deles, e estavam lavando as redes."}, {"numero": 3, "texto": "Ele entrou num daqueles barcos, que era o de Simão, e lhe pediu que o afastasse um pouco da terra. Depois se sentou, e do barco ensinou às multidões."}, {"numero": 4, "texto": "Quando acabou de falar, disse a Simão: Vai à água profunda, e lançai as vossas redes para pescar."}, {"numero": 5, "texto": "Simão lhe respondeu: Mestre, trabalhamos toda a noite, mas nada pegamos; mas pela tua palavra lançarei a rede."}, {"numero": 6, "texto": "Eles fizeram assim, e recolheram grande quantidade de peixes, e sua rede estava se rompendo."}, {"numero": 7, "texto": "Então acenaram aos companheiros que estavam no outro barco, para que viessem os ajudar. Vieram, e encheram ambos os barcos, de tal maneira que quase afundavam."}, {"numero": 8, "texto": "Quando Simão Pedro viu[isso] , prostrou-se aos pés de Jesus, dizendo: Afasta-te de mim, Senhor, porque sou um homem pecador."}, {"numero": 9, "texto": "Pois ele estava cheio de espanto, como todos os que estavam com ele, por causa da coleta de peixes que haviam feito."}, {"numero": 10, "texto": "E semelhantemente, também, Tiago e João, filhos de Zebedeu, que eram colegas de Simão. E Jesus disse a Simão: Não temas, de agora em diante pescarás gente."}, {"numero": 11, "texto": "Eles levaram os barcos para a terra, deixaram tudo, e o seguiram."}, {"numero": 12, "texto": "E aconteceu que, quando ele estava numa daquelas cidades, eis que um homem cheio de lepra viu Jesus; então prostrou-se sobre o rosto, e lhe rogou, dizendo: Senhor, se quiseres, podes me tornar limpo."}, {"numero": 13, "texto": "Ele estendeu a mão, e o tocou, dizendo: Quero; sê limpo. E logo a lepra desapareceu dele."}, {"numero": 14, "texto": "E mandou-lhe que não o dissesse a ninguém: Mas vai, mostra-te ao sacerdote, e oferece por tua purificação, como Moisés mandou, para lhes dar testemunho."}, {"numero": 15, "texto": "Porém a sua fama se espalhava ainda mais; e ajuntavam-se muitas multidões para o ouvir, e para serem por ele curadas de suas enfermidades."}, {"numero": 16, "texto": "Porém ele se retirava para os desertos, e [ali] orava."}, {"numero": 17, "texto": "E aconteceu num daqueles dias que estava ensinando, e estavam [ali] sentados fariseus e instrutores da lei, que tinham vindo de todas as aldeias da Galileia, da Judeia, e de Jerusalém; e o poder do Senhor estava [ali] para os curar."}, {"numero": 18, "texto": "E eis que uns homens traziam numa cama um homem que estava paralítico; e procuravam levá-lo para dentro, a fim de o porem diante dele."}, {"numero": 19, "texto": "Como não acharam por onde pudessem levá-lo para dentro, por causa da multidão, subiram ao telhado, e pelas telhas o baixaram com o leito para o meio [do povo] , diante de Jesus."}, {"numero": 20, "texto": "Ele viu a fé deles, e disse-lhe: Homem, teus pecados são perdoados."}, {"numero": 21, "texto": "E os escribas e os fariseus começaram a questionar, dizendo: Quem é este que fala blasfêmias? Quem pode perdoar pecados, senão só Deus?"}, {"numero": 22, "texto": "Porém Jesus, conhecendo os seus pensamentos, respondeu-lhes: O que pensais em vossos corações?"}, {"numero": 23, "texto": "O que é mais fácil? Dizer: Teus pecados são perdoados? Ou dizer: Levanta-te, e anda?"}, {"numero": 24, "texto": "Para que saibais que o Filho do homem tem poder sobre a terra para perdoar pecados, (disse ao paralítico:) Eu te digo, levanta-te, toma o teu leito, e vai para a tua casa."}, {"numero": 25, "texto": "E ele levantou-se imediatamente diante deles, tomou o [leito] em que estava deitado, e foi para a sua casa, glorificando a Deus."}, {"numero": 26, "texto": "E todos ficaram admirados, e glorificaram a Deus; e ficaram cheios de temor, dizendo: Hoje vimos maravilhas!"}, {"numero": 27, "texto": "Depois destas coisas, ele saiu; e viu um publicano, chamado Levi, sentado na coletoria de tributos, e disse-lhe: Segue-me."}, {"numero": 28, "texto": "Ele deixou tudo, levantou-se, e o seguiu."}, {"numero": 29, "texto": "E Levi lhe fez um grande banquete em sua casa; e havia [ali] uma grande multidão de publicanos e de outros que estavam sentados com eles [à mesa] ."}, {"numero": 30, "texto": "E seus escribas e fariseus murmuravam contra os seus discípulos, dizendo: Por que comeis e bebeis com publicanos e pecadores?"}, {"numero": 31, "texto": "Jesus lhes respondeu: Os que estão sãos não precisam de médico, mas sim os que estão doentes."}, {"numero": 32, "texto": "Eu não vim para chamar os justos, mas sim, os pecadores, ao arrependimento."}, {"numero": 33, "texto": "Então eles lhe disseram: Por que os discípulos de João jejuam muitas vezes, e fazem orações, como também os dos fariseus, mas os teus comem e bebem?"}, {"numero": 34, "texto": "Mas ele lhes disse: Podeis vós fazer jejuar os convidados do casamento, enquanto o noivo está com eles?"}, {"numero": 35, "texto": "Porém virão dias em que o esposo lhes será tirado; então naqueles dias jejuarão."}, {"numero": 36, "texto": "E dizia-lhes também uma parábola: Ninguém põe remendo de pano novo em roupa velha; de outra maneira, o novo rompe, e o remendo do novo não será adequado ao velho."}, {"numero": 37, "texto": "E ninguém põe vinho novo em odres velhos; de outra maneira, o vinho novo romperá os odres, e se derramará, e os odres são destruídos."}, {"numero": 38, "texto": "Mas o vinho novo deve ser posto em odres novos, e ambos se conservam."}, {"numero": 39, "texto": "E ninguém que beber do velho quer logo o novo; porque diz: O velho é melhor."}]'::jsonb, 'Almeida Livre'),
  ('Lc', 5, 'en', '[{"numero": 1, "texto": "And it came to pass, that, as the people pressed upon him to hear the word of God, he stood by the lake of Gennesaret,"}, {"numero": 2, "texto": "And saw two ships standing by the lake: but the fishermen were gone out of them, and were washing their nets."}, {"numero": 3, "texto": "And he entered into one of the ships, which was Simon''s, and prayed him that he would thrust out a little from the land. And he sat down, and taught the people out of the ship."}, {"numero": 4, "texto": "Now when he had left speaking, he said unto Simon, Launch out into the deep, and let down your nets for a draught."}, {"numero": 5, "texto": "And Simon answering said unto him, Master, we have toiled all the night, and have taken nothing: nevertheless at thy word I will let down the net."}, {"numero": 6, "texto": "And when they had this done, they inclosed a great multitude of fishes: and their net brake."}, {"numero": 7, "texto": "And they beckoned unto their partners, which were in the other ship, that they should come and help them. And they came, and filled both the ships, so that they began to sink."}, {"numero": 8, "texto": "When Simon Peter saw it, he fell down at Jesus'' knees, saying, Depart from me; for I am a sinful man, O Lord."}, {"numero": 9, "texto": "For he was astonished, and all that were with him, at the draught of the fishes which they had taken:"}, {"numero": 10, "texto": "And so was also James, and John, the sons of Zebedee, which were partners with Simon. And Jesus said unto Simon, Fear not; from henceforth thou shalt catch men."}, {"numero": 11, "texto": "And when they had brought their ships to land, they forsook all, and followed him."}, {"numero": 12, "texto": "And it came to pass, when he was in a certain city, behold a man full of leprosy: who seeing Jesus fell on his face, and besought him, saying, Lord, if thou wilt, thou canst make me clean."}, {"numero": 13, "texto": "And he put forth his hand, and touched him, saying, I will: be thou clean. And immediately the leprosy departed from him."}, {"numero": 14, "texto": "And he charged him to tell no man: but go, and shew thyself to the priest, and offer for thy cleansing, according as Moses commanded, for a testimony unto them."}, {"numero": 15, "texto": "But so much the more went there a fame abroad of him: and great multitudes came together to hear, and to be healed by him of their infirmities."}, {"numero": 16, "texto": "And he withdrew himself into the wilderness, and prayed."}, {"numero": 17, "texto": "And it came to pass on a certain day, as he was teaching, that there were Pharisees and doctors of the law sitting by, which were come out of every town of Galilee, and Judaea, and Jerusalem: and the power of the Lord was present to heal them."}, {"numero": 18, "texto": "And, behold, men brought in a bed a man which was taken with a palsy: and they sought means to bring him in, and to lay him before him."}, {"numero": 19, "texto": "And when they could not find by what way they might bring him in because of the multitude, they went upon the housetop, and let him down through the tiling with his couch into the midst before Jesus."}, {"numero": 20, "texto": "And when he saw their faith, he said unto him, Man, thy sins are forgiven thee."}, {"numero": 21, "texto": "And the scribes and the Pharisees began to reason, saying, Who is this which speaketh blasphemies? Who can forgive sins, but God alone?"}, {"numero": 22, "texto": "But when Jesus perceived their thoughts, he answering said unto them, What reason ye in your hearts?"}, {"numero": 23, "texto": "Whether is easier, to say, Thy sins be forgiven thee; or to say, Rise up and walk?"}, {"numero": 24, "texto": "But that ye may know that the Son of man hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house."}, {"numero": 25, "texto": "And immediately he rose up before them, and took up that whereon he lay, and departed to his own house, glorifying God."}, {"numero": 26, "texto": "And they were all amazed, and they glorified God, and were filled with fear, saying, We have seen strange things to day."}, {"numero": 27, "texto": "And after these things he went forth, and saw a publican, named Levi, sitting at the receipt of custom: and he said unto him, Follow me."}, {"numero": 28, "texto": "And he left all, rose up, and followed him."}, {"numero": 29, "texto": "And Levi made him a great feast in his own house: and there was a great company of publicans and of others that sat down with them."}, {"numero": 30, "texto": "But their scribes and Pharisees murmured against his disciples, saying, Why do ye eat and drink with publicans and sinners?"}, {"numero": 31, "texto": "And Jesus answering said unto them, They that are whole need not a physician; but they that are sick."}, {"numero": 32, "texto": "I came not to call the righteous, but sinners to repentance."}, {"numero": 33, "texto": "And they said unto him, Why do the disciples of John fast often, and make prayers, and likewise the disciples of the Pharisees; but thine eat and drink?"}, {"numero": 34, "texto": "And he said unto them, Can ye make the children of the bridechamber fast, while the bridegroom is with them?"}, {"numero": 35, "texto": "But the days will come, when the bridegroom shall be taken away from them, and then shall they fast in those days."}, {"numero": 36, "texto": "And he spake also a parable unto them; No man putteth a piece of a new garment upon an old; if otherwise, then both the new maketh a rent, and the piece that was taken out of the new agreeth not with the old."}, {"numero": 37, "texto": "And no man putteth new wine into old bottles; else the new wine will burst the bottles, and be spilled, and the bottles shall perish."}, {"numero": 38, "texto": "But new wine must be put into new bottles; and both are preserved."}, {"numero": 39, "texto": "No man also having drunk old wine straightway desireth new: for he saith, The old is better."}]'::jsonb, 'King James Version'),
  ('Lc', 5, 'fr', '[{"numero": 1, "texto": "Comme Jésus se trouvait auprès du lac de Génésareth, et que la foule se pressait autour de lui pour entendre la parole de Dieu,"}, {"numero": 2, "texto": "il vit au bord du lac deux barques, d''''où les pêcheurs étaient descendus pour laver leurs filets."}, {"numero": 3, "texto": "Il monta dans l''''une de ces barques, qui était à Simon, et il le pria de s''''éloigner un peu de terre. Puis il s''''assit, et de la barque il enseignait la foule."}, {"numero": 4, "texto": "Lorsqu''''il eut cessé de parler, il dit à Simon: Avance en pleine eau, et jetez vos filets pour pêcher."}, {"numero": 5, "texto": "Simon lui répondit: Maître, nous avons travaillé toute la nuit sans rien prendre; mais, sur ta parole, je jetterai le filet."}, {"numero": 6, "texto": "L''''ayant jeté, ils prirent une grande quantité de poissons, et leur filet se rompait."}, {"numero": 7, "texto": "Ils firent signe à leurs compagnons qui étaient dans l''''autre barque de venir les aider. Ils vinrent et ils remplirent les deux barques, au point qu''''elles enfonçaient."}, {"numero": 8, "texto": "Quand il vit cela, Simon Pierre tomba aux genoux de Jésus, et dit: Seigneur, retire-toi de moi, parce que je suis un homme pécheur."}, {"numero": 9, "texto": "Car l''''épouvante l''''avait saisi, lui et tous ceux qui étaient avec lui, à cause de la pêche qu''''ils avaient faite."}, {"numero": 10, "texto": "Il en était de même de Jacques et de Jean, fils de Zébédée, les associés de Simon. Alors Jésus dit à Simon: Ne crains point; désormais tu seras pêcheur d''''hommes."}, {"numero": 11, "texto": "Et, ayant ramené les barques à terre, ils laissèrent tout, et le suivirent."}, {"numero": 12, "texto": "Jésus était dans une des villes; et voici, un homme couvert de lèpre, l''''ayant vu, tomba sur sa face, et lui fit cette prière: Seigneur, si tu le veux, tu peux me rendre pur."}, {"numero": 13, "texto": "Jésus étendit la main, le toucha, et dit: Je le veux, sois pur. Aussitôt la lèpre le quitta."}, {"numero": 14, "texto": "Puis il lui ordonna de n''''en parler à personne. Mais, dit-il, va te montrer au sacrificateur, et offre pour ta purification ce que Moïse a prescrit, afin que cela leur serve de témoignage."}, {"numero": 15, "texto": "Sa renommée se répandait de plus en plus, et les gens venaient en foule pour l''''entendre et pour être guéris de leurs maladies."}, {"numero": 16, "texto": "Et lui, il se retirait dans les déserts, et priait."}, {"numero": 17, "texto": "Un jour Jésus enseignait. Des pharisiens et des docteurs de la loi étaient là assis, venus de tous les villages de la Galilée, de la Judée et de Jérusalem; et la puissance du Seigneur se manifestait par des guérisons."}, {"numero": 18, "texto": "Et voici, des gens, portant sur un lit un homme qui était paralytique, cherchaient à le faire entrer et à le placer sous ses regards."}, {"numero": 19, "texto": "Comme ils ne savaient par où l''''introduire, à cause de la foule, ils montèrent sur le toit, et ils le descendirent par une ouverture, avec son lit, au milieu de l''''assemblée, devant Jésus."}, {"numero": 20, "texto": "Voyant leur foi, Jésus dit: Homme, tes péchés te sont pardonnés."}, {"numero": 21, "texto": "Les scribes et les pharisiens se mirent à raisonner et à dire: Qui est celui-ci, qui profère des blasphèmes? Qui peut pardonner les péchés, si ce n''''est Dieu seul?"}, {"numero": 22, "texto": "Jésus, connaissant leurs pensées, prit la parole et leur dit: Quelles pensées avez-vous dans vos coeurs?"}, {"numero": 23, "texto": "Lequel est le plus aisé, de dire: Tes péchés te sont pardonnés, ou de dire: Lève-toi, et marche?"}, {"numero": 24, "texto": "Or, afin que vous sachiez que le Fils de l''''homme a sur la terre le pouvoir de pardonner les péchés: Je te l''''ordonne, dit-il au paralytique, lève-toi, prends ton lit, et va dans ta maison."}, {"numero": 25, "texto": "Et, à l''''instant, il se leva en leur présence, prit le lit sur lequel il était couché, et s''''en alla dans sa maison, glorifiant Dieu."}, {"numero": 26, "texto": "Tous étaient dans l''''étonnement, et glorifiaient Dieu; remplis de crainte, ils disaient: Nous avons vu aujourd''''hui des choses étranges."}, {"numero": 27, "texto": "Après cela, Jésus sortit, et il vit un publicain, nommé Lévi, assis au lieu des péages. Il lui dit: Suis-moi."}, {"numero": 28, "texto": "Et, laissant tout, il se leva, et le suivit."}, {"numero": 29, "texto": "Lévi lui donna un grand festin dans sa maison, et beaucoup de publicains et d''''autres personnes étaient à table avec eux."}, {"numero": 30, "texto": "Les pharisiens et les scribes murmurèrent, et dirent à ses disciples: Pourquoi mangez-vous et buvez-vous avec les publicains et les gens de mauvaise vie?"}, {"numero": 31, "texto": "Jésus, prenant la parole, leur dit: Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais les malades."}, {"numero": 32, "texto": "Je ne suis pas venu appeler à la repentance des justes, mais des pécheurs."}, {"numero": 33, "texto": "Ils lui dirent: Les disciples de Jean, comme ceux des pharisiens, jeûnent fréquemment et font des prières, tandis que les tiens mangent et boivent."}, {"numero": 34, "texto": "Il leur répondit: Pouvez-vous faire jeûner les amis de l''''époux pendant que l''''époux est avec eux?"}, {"numero": 35, "texto": "Les jours viendront où l''''époux leur sera enlevé, alors ils jeûneront en ces jours-là."}, {"numero": 36, "texto": "Il leur dit aussi une parabole: Personne ne déchire d''''un habit neuf un morceau pour le mettre à un vieil habit; car, il déchire l''''habit neuf, et le morceau qu''''il en a pris n''''est pas assorti au vieux."}, {"numero": 37, "texto": "Et personne ne met du vin nouveau dans de vieilles outres; autrement, le vin nouveau fait rompre les outres, il se répand, et les outres sont perdues;"}, {"numero": 38, "texto": "mais il faut mettre le vin nouveau dans des outres neuves."}, {"numero": 39, "texto": "Et personne, après avoir bu du vin vieux, ne veut du nouveau, car il dit: Le vieux est bon."}]'::jsonb, 'Louis Segond 1910'),
  ('Lc', 5, 'es', '[{"numero": 1, "texto": "Y ACONTECIÓ, que estando él junto al lago de Genezaret, las gentes se agolpaban sobre él para oir la palabra de Dios."}, {"numero": 2, "texto": "Y vió dos barcos que estaban cerca de la orilla del lago: y los pescadores, habiendo descendido de ellos, lavaban sus redes."}, {"numero": 3, "texto": "Y entrado en uno de estos barcos, el cual era de Simón, le rogó que lo desviase de tierra un poco; y sentándose, enseñaba desde el barco á las gentes."}, {"numero": 4, "texto": "Y como cesó de hablar, dijo á Simón: Tira á alta mar, y echad vuestras redes para pescar."}, {"numero": 5, "texto": "Y respondiendo Simón, le dijo: Maestro, habiendo trabajado toda la noche, nada hemos tomado; mas en tu palabra echaré la red."}, {"numero": 6, "texto": "Y habiéndolo hecho, encerraron gran multitud de pescado, que su red se rompía."}, {"numero": 7, "texto": "E hicieron señas á los compañeros que estaban en el otro barco, que viniesen á ayudarles; y vinieron, y llenaron ambos barcos, de tal manera que se anegaban."}, {"numero": 8, "texto": "Lo cual viendo Simón Pedro, se derribó de rodillas á Jesús, diciendo: Apártate de mí, Señor, porque soy hombre pecador."}, {"numero": 9, "texto": "Porque temor le había rodeado, y á todos los que estaban con él, de la presa de los peces que habían tomado;"}, {"numero": 10, "texto": "Y asimismo á Jacobo y á Juan, hijos de Zebedeo, que eran compañeros de Simón. Y Jesús dijo á Simón: No temas: desde ahora pescarás hombres."}, {"numero": 11, "texto": "Y como llegaron á tierra los barcos, dejándolo todo, le siguieron."}, {"numero": 12, "texto": "Y aconteció que estando en una ciudad, he aquí un hombre lleno de lepra, el cual viendo á Jesús, postrándose sobre el rostro, le rogó, diciendo: Señor, si quieres, puedes limpiarme."}, {"numero": 13, "texto": "Entonces, extendiendo la mano, le tocó diciendo: Quiero: sé limpio. Y luego la lepra se fué de él."}, {"numero": 14, "texto": "Y él le mandó que no lo dijese á nadie: Mas ve, díjole, muéstrate al sacerdote, y ofrece por tu limpieza, como mandó Moisés, para testimonio á ellos."}, {"numero": 15, "texto": "Empero tanto más se extendía su fama: y se juntaban muchas gentes á oir y ser sanadas de sus enfermedades."}, {"numero": 16, "texto": "Mas él se apartaba á los desiertos, y oraba."}, {"numero": 17, "texto": "Y aconteció un día, que él estaba enseñando, y los Fariseos y doctores de la ley estaban sentados, los cuales habían venido de todas las aldeas de Galilea, y de Judea y Jerusalem: y la virtud del Señor estaba allí para sanarlos."}, {"numero": 18, "texto": "Y he aquí unos hombres, que traían sobre un lecho un hombre que estaba paralítico; y buscaban meterle, y ponerle delante de él."}, {"numero": 19, "texto": "Y no hallando por donde meterle á causa de la multitud, subieron encima de la casa, y por el tejado le bajaron con el lecho en medio, delante de Jesús;"}, {"numero": 20, "texto": "El cual, viendo la fe de ellos, le dice: Hombre, tus pecados te son perdonados."}, {"numero": 21, "texto": "Entonces los escribas y los Fariseos comenzaron á pensar, diciendo: ¿Quién es éste que habla blasfemias? ¿Quién puede perdonar pecados sino sólo Dios?"}, {"numero": 22, "texto": "Jesús entonces, conociendo los pensamientos de ellos, respondiendo les dijo: ¿Qué pensáis en vuestros corazones?"}, {"numero": 23, "texto": "¿Qué es más fácil, decir: Tus pecados te son perdonados, ó decir: Levántate y anda?"}, {"numero": 24, "texto": "Pues para que sepáis que el Hijo del hombre tiene potestad en la tierra de perdonar pecados, (dice al paralítico): A ti digo, levántate, toma tu lecho, y vete á tu casa."}, {"numero": 25, "texto": "Y luego, levantándose en presencia de ellos, y tomando aquel en que estaba echado, se fué á su casa, glorificando á Dios."}, {"numero": 26, "texto": "Y tomó espanto á todos, y glorificaban á Dios; y fueron llenos de temor, diciendo: Hemos visto maravillas hoy."}, {"numero": 27, "texto": "Y después de estas cosas salió, y vió á un publicano llamado Leví, sentado al banco de los públicos tributos, y le dijo: Sígueme."}, {"numero": 28, "texto": "Y dejadas todas las cosas, levantándose, le siguió."}, {"numero": 29, "texto": "E hizo Leví gran banquete en su casa; y había mucha compañía de publicanos y de otros, los cuales estaban á la mesa con ellos."}, {"numero": 30, "texto": "Y los escribas y los Fariseos murmuraban contra sus discípulos, diciendo: ¿Por qué coméis y bebéis con los publicanos y pecadores?"}, {"numero": 31, "texto": "Y respondiendo Jesús, les dijo: Los que están sanos no necesitan médico, sino los que están enfermos."}, {"numero": 32, "texto": "No he venido á llamar justos, sino pecadores á arrepentimiento."}, {"numero": 33, "texto": "Entonces ellos le dijeron: ¿Por qué los discípulos de Juan ayunan muchas veces y hacen oraciones, y asimismo los de los Fariseos, y tus discípulos comen y beben?"}, {"numero": 34, "texto": "Y él les dijo: ¿Podéis hacer que los que están de bodas ayunen, entre tanto que el esposo está con ellos?"}, {"numero": 35, "texto": "Empero vendrán días cuando el esposo les será quitado: entonces ayunarán en aquellos días."}, {"numero": 36, "texto": "Y les decía también una parábola: Nadie mete remiendo de paño nuevo en vestido viejo; de otra manera el nuevo rompe, y al viejo no conviene remiendo nuevo."}, {"numero": 37, "texto": "Y nadie echa vino nuevo en cueros viejos; de otra manera el vino nuevo romperá los cueros, y el vino se derramará, y los cueros se perderán."}, {"numero": 38, "texto": "Mas el vino nuevo en cueros nuevos se ha de echar; y lo uno y lo otro se conserva."}, {"numero": 39, "texto": "Y ninguno que bebiere del añejo, quiere luego el nuevo; porque dice: El añejo es mejor."}]'::jsonb, 'Reina-Valera 1909')
